#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_SINGLE_SHOT 0x8000  // Single-shot mode
#define CONFIG_AIN0_SINGLE_ENDED 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000     // PGA = +/- 4.096V
#define CONFIG_128SPS 0x0000       // 128 samples per second

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int handle, uint16_t value)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    int result = i2cWriteI2CBlockData(handle, buf[0], buf + 1, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int read_ads1115(int handle, uint16_t *value)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteI2CBlockData(handle, buf[0], NULL, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 for read: %d\n", result);
        return -1;
    }

    result = i2cReadI2CBlockData(handle, buf[0], (char *)value, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to convert the raw ADC value to current
float convert_to_current(uint16_t adc_value)
{
    // Convert ADC value to voltage (assuming +/- 4.096V range)
    float voltage = (float)adc_value * 4.096 / 32768.0;

    // Convert voltage to current (40mV/A sensitivity)
    float current = voltage * 1000.0 / 40.0; // Convert to A

    return current;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (write_ads1115(i2c_handle, CONFIG_SINGLE_SHOT | CONFIG_AIN0_SINGLE_ENDED | CONFIG_PGA_4_096V | CONFIG_128SPS) != 0) {
        fprintf(stderr, "Error configuring ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        uint16_t adc_value;
        if (read_ads1115(i2c_handle, &adc_value) == 0) {
            float current = convert_to_current(adc_value);
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

