#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADC_CHANNEL 0
#define ADC_RANGE 4.096
#define ADC_SENSITIVITY 0.0048828125
#define ADC_VREF 3.3
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_DELAY 50000 // 50ms in microseconds
#define LOG_FILE "fire_log.txt"
#define POLLING_INTERVAL_MS 100

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int initialize_gpio();
int configure_ads1115();
int read_ads1115();
