#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FAN_GPIO 18
#define DEFAULT_SENSITIVITY 0.100 // 100 mV/A
#define DEFAULT_THRESHOLD 5.0 // 5.0 A
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
int fan_state = 0; // 0 = OFF, 1 = ON
int sensitivity = DEFAULT_SENSITIVITY;
float threshold = DEFAULT_THRESHOLD;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_read_adc(int fd, int channel);
float adc_to_current(int adc_value, float sensitivity);
void control_fan(int gpio_pin, int state);
void log_data(const char *filename, float current);
void signal_handler(int signal);

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Convert ADC value to current
float adc_to_current(int adc_value, float sensitivity) {
    return (adc_value * sensitivity) / 1000.0; // mV to A
}

// Control fan state
void control_fan(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    fan_state = state;
}

// Log data to file
void log_data(const char *filename, float current) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.3f\n", timestamp, current);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO resources
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin for fan control as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            // Attempt to recover (e.g., re-initialize SPI)
            close(spi_fd);
            spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
            if (spi_fd < 0) {
                fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
                break; // Exit loop if SPI fails repeatedly
            }
            sleep(1); // Wait before retrying
            continue;
        }

        // Check for sensor-absent condition
        if (adc_value == 0 || adc_value == 0xFF) {
            fprintf(stderr, "Sensor-absent condition detected. Skipping fan control.\n");
        } else {
            // Convert ADC value to current
            float current = adc_to_current(adc_value, sensitivity);

            // Control fan
            if (current > threshold) {
                control_fan(FAN_GPIO, 1); // Turn on fan
            } else {
                control_fan(FAN_GPIO, 0); // Turn off fan
            }

            // Log data
            log_data(LOG_FILE, current);

            printf("Current: %.3f A\n", current);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    close(spi_fd);
    gpioTerminate();
    return 0;
}

