int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t mic1_data;
    int16_t mic2_data;
} microphone_data_t;

// Function prototypes
int read_mic1();
int read_mic2();
double calculate_sound_pressure(int16_t raw_data, double sensitivity, double reference_pressure);
void log_data(double avg_sound_pressure);
void signal_handler(int signal);
int setup();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Setup function to initialize pigpio and I2C
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDRESS, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for MIC1: %d\n", i2c_handle1);
        gpioTerminate();
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDRESS, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for MIC2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

// Function to read data from MIC1
int read_mic1() {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle1, 0x00, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading MIC1: %d\n", bytes_read);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to read data from MIC2
int read_mic2() {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle2, 0x00, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading MIC2: %d\n", bytes_read);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to calculate sound pressure level
double calculate_sound_pressure(int16_t raw_data, double sensitivity, double reference_pressure) {
    return 20 * log10(raw_data / (1000.0 * sensitivity));
}

// Function to log data to file
void log_data(double avg_sound_pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, avg_sound_pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    microphone_data_t mic1_data, mic2_data;
    double avg_sound_pressure;

    printf("Starting acoustic leak detection...\n");

    while (!terminate) {
        mic1_data.mic1_data = read_mic1();
        mic2_data.mic2_data = read_mic2();

        if (mic1_data.mic1_data == -1 || mic2_data.mic2_data == -1) {
            avg_sound_pressure = -999.0; // Indicate error
        } else {
            avg_sound_pressure = calculate_sound_pressure(mic1_data.mic1_data, 0.001, 2e-6); // Example sensitivity and reference pressure
        }

        log_data(avg_sound_pressure);
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 100ms
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

