#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_1 0
#define MCP3008_CHANNEL_2 1
#define LED_GPIO 27
#define RMS_THRESHOLD 0.7
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_MS 1
#define NUM_SAMPLES 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float calculate_rms(int *samples, int num_samples);
void control_led(int on);
void log_data(float mic1_rms, float mic2_rms);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel1;
    int mcp3008_channel2;
    int led_gpio;
    float rms_threshold;
    int sample_window_ms;
    int sample_interval_ms;
    int num_samples;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL_1,
    MCP3008_CHANNEL_2,
    LED_GPIO,
    RMS_THRESHOLD,
    SAMPLE_WINDOW_MS,
    SAMPLE_INTERVAL_MS,
    NUM_SAMPLES
};

int main() {
    int mic1_samples[config.num_samples];
    int mic2_samples[config.num_samples];
    float mic1_rms, mic2_rms;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone 1 samples
        for (i = 0; i < config.num_samples; i++) {
            mic1_samples[i] = read_mcp3008(config.mcp3008_channel1);
        }

        // Read microphone 2 samples
        for (i = 0; i < config.num_samples; i++) {
            mic2_samples[i] = read_mcp3008(config.mcp3008_channel2);
        }

        // Calculate RMS values
        mic1_rms = calculate_rms(mic1_samples, config.num_samples);
        mic2_rms = calculate_rms(mic2_samples, config.num_samples);

        // Check for threshold exceedance
        if (mic1_rms > config.rms_threshold || mic2_rms > config.rms_threshold) {
            control_led(1); // Turn on LED
            gpioDelay(500);  // Wait 500 ms
            control_led(0); // Turn off LED
        }

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Wait for the next sample window
        gpioDelay(config.sample_interval_ms * 1000); // Convert ms to us
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Calculate RMS value
float calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Control LED
void control_led(int on) {
    gpioWrite(config.led_gpio, on);
}

// Log data to CSV file
void log_data(float mic1_rms, float mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

