#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define CIRCULAR_BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_circular_buffer(CircularBuffer *cb, float value);
float calculate_average_current(CircularBuffer *cb);
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    int16_t value;

    // Configure for single-ended A0, 4.096V, 128 SPS, disable comparator
    config[0] = CONFIG_REG;
    config[1] = 0x44; // 0b01000100
    config[2] = 0x83; // 10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return -1;
    }

    value = (data[0] << 8) | data[1];
    *raw_value = value;

    return 0;
}

// Convert raw value to current (A)
float convert_to_current(int16_t raw_value) {
    float voltage = (float)raw_value / 32768.0 * 4.096; // Assuming 16-bit ADC, 5V supply
    float current = (voltage - 0.5) / 0.4; // 0.5V to 4.5V range
    return current;
}

// Add value to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (cb->count < CIRCULAR_BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average current from circular buffer
float calculate_average_current(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    int16_t raw_value;
    float current;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&current_buffer);

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        if (read_ads1115(&raw_value) == 0) {
            // Convert raw value to current
            current = convert_to_current(raw_value);

            // Add current to circular buffer
            add_to_circular_buffer(&current_buffer, current);

            // Calculate average current
            float average_current = calculate_average_current(&current_buffer);

            // Control LED
            control_led(average_current);

            // Print current and average current
            printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

