#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x29
#define SENSOR2_ADDR 0x2A
#define SENSOR3_ADDR 0x2B

// Define registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Define error codes
#define I2C_ERROR -1
#define SENSOR_ERROR -2
#define FILE_ERROR -3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
int i2c_handle3 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_color_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    // Check sensor ID
    int id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return SENSOR_ERROR;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return SENSOR_ERROR;
    }

    // Enable power and ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x01 | 0x02) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return I2C_ERROR;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return I2C_ERROR;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return I2C_ERROR;
    }

    return 0;
}

// Function to read color data from the sensor
int read_color_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int c, r, g, b;

    c = i2cReadByteData(i2c_handle, TCS34725_CDATA);
    if (c < 0) {
        fprintf(stderr, "Error reading clear data: %s\n", strerror(errno));
        return I2C_ERROR;
    }
    *clear = (uint16_t)c;

    r = i2cReadByteData(i2c_handle, TCS34725_RDATA);
    if (r < 0) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return I2C_ERROR;
    }
    *red = (uint16_t)r;

    g = i2cReadByteData(i2c_handle, TCS34725_GDATA);
    if (g < 0) {
        fprintf(stderr, "Error reading green data: %s\n", strerror(errno));
        return I2C_ERROR;
    }
    *green = (uint16_t)g;

    b = i2cReadByteData(i2c_handle, TCS34725_BDATA);
    if (b < 0) {
        fprintf(stderr, "Error reading blue data: %s\n", strerror(errno));
        return I2C_ERROR;
    }
    *blue = (uint16_t)b;

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus for each sensor
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle3 = i2cOpen(1, SENSOR3_ADDR, 0);
    if (i2c_handle3 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 3: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Error initializing sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        i2cClose(i2c_handle3);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error initializing sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        i2cClose(i2c_handle3);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle3) != 0) {
        fprintf(stderr, "Error initializing sensor 3\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        i2cClose(i2c_handle3);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        i2cClose(i2c_handle3);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t clear, red, green, blue;

        // Read data from sensor 1
        if (read_color_data(i2c_handle1, &clear, &red, &green, &blue) == 0) {
            log_data(log_file, clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading data from sensor 1, retrying...\n");
        }

        // Read data from sensor 2
        if (read_color_data(i2c_handle2, &clear, &red, &green, &blue) == 0) {
