#include <errno.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_1 0
#define MCP3008_CHANNEL_2 1
#define LOG_FILE "moisture_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int channel1_value;
    int channel2_value;
    float moisture1;
    float moisture2;
} sensor_data_t;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008_channel(int fd, int channel);
float map_adc_to_moisture(int adc_value);
void log_data(FILE *fp, time_t timestamp, float moisture1, float moisture2);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read MCP3008 channel
int read_mcp3008_channel(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading MCP3008 channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    // Assuming ADC range is 0-1023, corresponding to 0-100% moisture
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to CSV file
void log_data(FILE *fp, time_t timestamp, float moisture1, float moisture2) {
    struct tm *timeinfo = localtime(&timestamp);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp_str, moisture1, moisture2);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        int adc_value1 = read_mcp3008_channel(spi_fd, MCP3008_CHANNEL_1);
        int adc_value2 = read_mcp3008_channel(spi_fd, MCP3008_CHANNEL_2);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue; // Skip to the next iteration
        }

        // Map ADC values to moisture percentages
        float moisture1 = map_adc_to_moisture(adc_value1);
        float moisture2 = map_adc_to_moisture(adc_value2);

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        log_data(log_file, current_time, moisture1, moisture2);

        // Print data to console
        printf("Timestamp: %ld, Moisture1: %.2f%%, Moisture2: %.2f%%\n", current_time, moisture1, moisture2);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Clean up resources
    close(spi_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

