#define LOG_FILE "pressure_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and configuration
typedef struct {
    int i2c_handle;
    FILE *log_file;
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} sensor_config_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C connection
int init_i2c(sensor_config_t *config) {
    config->i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (config->i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read pressure data from the sensor
int read_pressure(sensor_config_t *config, int *raw_value) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(config->i2c_handle, PRESSURE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw value to pressure in kPa
float convert_to_kPa(int raw_value) {
    return (float)raw_value / 65535.0 * 500.0;
}

// Function to log the pressure data to a file
int log_data(FILE *log_file, float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to create the log file with a header row
int create_log_file(FILE **log_file, const char *filename) {
    *log_file = fopen(filename, "a");
    if (*log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Write header row if the file is newly created
    fseek(*log_file, 0, SEEK_END);
    long file_size = ftell(*log_file);
    if (file_size == 0) {
        fprintf(*log_file, "timestamp,pressure_kPa\n");
    }
    fflush(*log_file);
    return 0;
}

// Function to close the I2C connection and log file
void cleanup(sensor_config_t *config) {
    if (config->i2c_handle >= 0) {
        i2cClose(config->i2c_handle);
    }
    if (config->log_file != NULL) {
        fclose(config->log_file);
    }
    gpioTerminate();
}

