    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX90817_ADDR,
        .log_file_name = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c(&config) != 0) {
        cleanup(&config);
        return 1;
    }

    // Create the log file
    if (create_log_file(&config.log_file, config.log_file_name) != 0) {
        cleanup(&config);
        return 1;
    }

    int raw_value;
    float pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&config, &raw_value) == 0) {
            pressure_kPa = convert_to_kPa(raw_value);
            log_data(config.log_file, pressure_kPa);
            printf("Pressure: %.2f kPa\n", pressure_kPa);
        } else {
            // Log the error to the log file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(config.log_file, "%s,I2C read error\n", timestamp);
            fflush(config.log_file);
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup(&config);
    return 0;
}

