#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int *pressure, int *temperature);
float convert_pressure(int adc_value);
float convert_temperature(int adc_value);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended AIN0 and AIN1, gain 2/3, 128 SPS
int configure_ads1115() {
    // Configuration register value: 0x4003 (Single-ended AIN0, Single-ended AIN1, Gain 2/3, 128 SPS, Single-shot mode)
    unsigned short config_value = 0x4003;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config_value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error configuring ADS1115 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to configure ADS1115 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read pressure and temperature data from ADS1115
int read_ads1115(int *pressure, int *temperature) {
    unsigned char buffer[3];
    int16_t adc_value;

    // Start a single conversion
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error starting conversion.\n");
        return -1;
    }

    gpioDelay(10000); // Wait for conversion (at least 8.33ms for 128 SPS)

    // Read the conversion result
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, (char *)buffer, 3) != 3) {
        fprintf(stderr, "Error reading conversion data.\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    adc_value = (buffer[0] << 8) | buffer[1];

    *pressure = convert_pressure(adc_value);
    *temperature = convert_temperature(adc_value);

    return 0;
}

// Convert ADC value to pressure (kPa)
float convert_pressure(int adc_value) {
    return (float)adc_value * 400.0 / 1023.0;
