#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VCC 3.3 // Supply voltage
#define ZERO_CURRENT_VOLTAGE 1.65 // Volts
#define SENSITIVITY 0.066 // mV/A
#define OVERCURRENT_THRESHOLD 10.0 // Amps
#define SHUTDOWN_GPIO 27
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_from_adc(int adc_value);
float current_from_voltage(float voltage);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float voltage_from_adc(int adc_value) {
    return ((float)adc_value / 1023.0) * VCC;
}

// Function to convert voltage to current
float current_from_voltage(float voltage) {
    return (voltage - ZERO_CURRENT_VOLTAGE) / SENSITIVITY;
}

// Function to log current reading with timestamp
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.3f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to check for overcurrent condition
void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        fprintf(stderr, "Overcurrent detected! Current: %.3f A\n", current);
        fprintf(log_file, "OVERCURRENT DETECTED! Current: %.3f A\n", current);
        fflush(log_file);

        // Trigger motor shutdown (simulated)
        gpioWrite(SHUTDOWN_GPIO, 1); // Set GPIO HIGH
        printf("Motor shutdown triggered!\n");
        fprintf(log_file, "Motor shutdown triggered!\n");
        fflush(log_file);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds

        // Reset GPIO to LOW
        gpioWrite(SHUTDOWN_GPIO, 0); // Set GPIO LOW
        printf("Motor shutdown released!\n");
        fprintf(log_file, "Motor shutdown released!\n");
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    fprintf(log_file, "Caught signal %d, terminating...\n", signal);
    fflush(log_file);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT);
    gpioWrite(SHUTDOWN_GPIO, 0); // Ensure it starts LOW

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            fprintf(log_file, "Error: Failed to read ADC value\n");
            fflush(log_file);
            gpioDelay(100); // Small delay before next read
            continue;
        }

        // Convert ADC value to voltage
        float voltage = voltage_from_adc(adc_value);

        // Convert voltage to current
        float current = current_from_voltage(voltage);

        // Log current reading
        log_current(current);

        // Check for overcurrent condition
        check_overcurrent(current);

        // Delay
        gpioDelay(100); // 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fprintf(log_file, "Cleaning up...\n");
    fflush(log_file);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Reset GPIO
    gpioWrite(SHUTDOWN_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

