    spi_handle = spiOpen(config.spi_ce0, config.spi_baud, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm pin as output
    gpioSetMode(config.alarm_pin, PI_OUTPUT);
    gpioWrite(config.alarm_pin, 0); // Initially turn off the alarm

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
