        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

float voltage_conversion(int adc_value) {
    float voltage = (float)adc_value * 3.3 / 1023.0;
    return voltage;
}

void control_alarm(float voltage) {
    if (voltage > config.co_threshold) {
        gpioWrite(config.alarm_pin, 1); // Turn on alarm
    } else {
        gpioWrite(config.alarm_pin, 0); // Turn off alarm
    }
}

void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
