#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define SAMPLE_RATE 1.0 // Hz

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for ADS1115 configuration
typedef struct {
    int16_t config_value;
} ads1115_config_t;

// Function prototypes
int initialize_i2c();
ads1115_config_t configure_ads1115();
int read_adc();
float convert_to_voltage(int16_t adc_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended AIN0, 16-bit, continuous conversion mode
ads1115_config_t configure_ads1115() {
    ads1115_config_t config;
    config.config_value = 0x4003; // 0b0100000000000011
    return config;
}

// Read ADC value from ADS1115
int read_adc() {
    char buf[2];
    int16_t adc_value;

    // Write configuration register address to read from
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONVERT, ADS1115_REG_CONFIG) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Read 2 bytes from the conversion register
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    adc_value = (buf[0] << 8) | buf[1];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int16_t adc_value) {
    return ((float)adc_value / 32767.0) * 4.096; // ADS1115 range: 4.096V
}

// Convert voltage to pressure in kPa
float convert_to_pressure(float voltage) {
    return (voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

// Log pressure reading to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
        fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    ads1115_config_t config = configure_ads1115();

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t adc_value = read_adc();
        if (adc_value >= 0) {
            float voltage = convert_to_voltage(adc_value);
            float pressure = convert_to_pressure(voltage);

            if (log_pressure(pressure) == 0) {
                printf("Pressure: %.2f kPa\n", pressure);
            } else {
                fprintf(stderr, "Failed to log pressure reading\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

