#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0 // Humidity sensor connected to channel 0
#define HUMIDITY_THRESHOLD 80.0
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int spi_read_adc(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);

// Function to read from MCP3208 ADC via SPI
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate relative humidity
float calculate_humidity(int adc_value) {
    // Transfer function: Vout = 0.824 + 0.0315 * RH
    // Rearrange to solve for RH: RH = (Vout - 0.824) / 0.0315
    float voltage = (float)adc_value / 1023.0 * 5.0; // Assuming 5V supply
    float humidity = (voltage - 0.824) / 0.0315;
    return humidity;
}

// Function to calculate temperature from thermistor
float calculate_temperature(int adc_value) {
    // Beta parameter equation: Beta = 3950K
    // R0 = 10kΩ
    // T = Beta / (ln(R/R0) + 1)
    float voltage = (float)adc_value / 1023.0 * 5.0; // Assuming 5V supply
    float temperature = 3950.0 / (log(voltage / 10000.0) + 1);
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
