#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CS 4
#define VREF 3.3
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.0
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_MS 1000 // 1 Hz

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_ioctl(int fd, int cmd, void *arg);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int spi_close(int fd);
int read_adc(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_temperature(float voltage);
void log_temperature(float temperature);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, SPI_MODE) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error performing SPI transfer");
        return -1;
    }
    return 0;
}

// SPI close function
int spi_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing SPI device");
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3208 channel
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading ADC channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0) * vref;
}

// Convert voltage to temperature (Celsius)
float voltage_to_temperature(float voltage) {
    return (voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
}

// Log temperature to file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return;
        }
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as output for CS
    gpioSetMode(GPIO_CS, PI_OUTPUT);
    gpioWrite(GPIO_CS, 1); // Set CS high initially

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to temperature
        float temperature = voltage_to_temperature(voltage);

        // Validate temperature
        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        } else {
            // Log temperature
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        }

        gpioDelay(READ_INTERVAL_MS); // Wait 1000ms
    }

    // Clean up
    spi_close(spi_fd);
    gpioWrite(GPIO_CS, 1); // Set CS high
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

