#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)
#define IMPACT_THRESHOLD 2.0 // g
#define VOLTAGE_RANGE 3.3
#define SENSITIVITY 0.3 // V/g
#define ZERO_G_VOLTAGE 1.65 // V

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int16_t adc_value);
float convert_to_g(float voltage);
int log_data(accelerometer_data_t data);
void detect_impact(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int16_t adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int16_t adc_value) {
    return ((float)adc_value / 1023.0) * VOLTAGE_RANGE;
}

// Function to convert voltage to g
float convert_to_g(float voltage) {
    return (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
}

// Function to log data to file
int log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f\n",
            timestamp, data.x, data.y, data.z,
            convert_to_voltage(data.x), convert_to_voltage(data.y), convert_to_voltage(data.z));
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to detect impacts
void detect_impact(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "IMPACT DETECTED: X=%.3f, Y=%.3f, Z=%.3f, Magnitude=%.3f\n", x, y, z, magnitude);
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
