    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data;

        // Read ADC values
        data.x = read_mcp3008(ADC_CHANNEL_X);
        data.y = read_mcp3008(ADC_CHANNEL_Y);
        data.z = read_mcp3008(ADC_CHANNEL_Z);

        if (data.x == -1 || data.y == -1 || data.z == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Validate ADC readings
        if (data.x < 0 || data.x > 1023 || data.y < 0 || data.y > 1023 || data.z < 0 || data.z > 1023) {
            fprintf(stderr, "Invalid ADC reading, skipping sample.\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Convert to voltage and g
        float voltage_x = convert_to_voltage(data.x);
        float voltage_y = convert_to_voltage(data.y);
        float voltage_z = convert_to_voltage(data.z);
        float g_x = convert_to_g(voltage_x);
        float g_y = convert_to_g(voltage_y);
        float g_z = convert_to_g(voltage_z);

        // Log data
        log_data(data);

        // Detect impacts
        detect_impact(g_x, g_y, g_z);

