    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row to the log file
    fprintf(log_file, "Timestamp,HR,SpO2,Error Flag\n");

    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    int ir_data, red_data;
    sensor_data_t sensor_data;

    while (!terminate) {
        // Trigger a measurement
        char cmd[2] = {MEASUREMENT_COMMAND, 0};
        if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
            fprintf(stderr, "Error triggering measurement.\n");
            sensor_data.error_flag = 2; // Indicate sensor absent/uninitialized
            log_data(sensor_data);
            continue; // Skip to the next iteration
        }

        // Wait for a short period (e.g., 100ms)
        gpioDelay(100000); // 100ms

        // Read sensor data
        if (read_sensor_data(&ir_data, &red_data) == 0) {
            // Process the sensor data
            sensor_data = process_sensor_data(ir_data, red_data);

            // Log the data
            log_data(sensor_data);
        } else {
            // Log an error if the read fails
            sensor_data.error_flag = 1; // Indicate read error
            log_data(sensor_data);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close the I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close the log file
    fclose(log_file);

    return 0;
}

