#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to the sensor
#define VREF 3.3 // Reference voltage
#define FLOW_MIN 0.0 // Minimum flow rate (L/min)
#define FLOW_MAX 5.0 // Maximum flow rate (L/min)
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float adc_to_flow_rate(int adc_value);
void log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    float flow_min;
    float flow_max;
    char *log_file;
} Config;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi SPI
    if ((spi_handle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "wiringPi SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "YYYY-MM-DD HH:MM:SS.uuuuuu,flow_rate\n");
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to convert ADC value to flow rate
float adc_to_flow_rate(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float flow_rate = (voltage / VREF) * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;

    // Validate flow rate
    if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
        fprintf(stderr, "Error: Flow rate out of range: %.2f L/min\n", flow_rate);
        return -1.0; // Indicate an error
    }

    return flow_rate;
}

// Function to log data to file
void log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk
