#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define SAMPLE_RATE 10000 // 10 kHz
#define GAIN_CONTROL_THRESHOLD 0.5
#define GAIN_CONTROL_OFFSET 0.1
#define NUM_SAMPLES 1024

// Global variables
static volatile int running = 1;
static int spi_handle;
static int gain = 1.0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float apply_gain(float voltage);
float subtract_audio_streams(float audio1, float audio2);
void print_csv(float audio1, float audio2, float processed_audio);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Function to apply gain to the audio signal
float apply_gain(float voltage) {
    return voltage * gain;
}

// Function to subtract the second audio stream from the first
float subtract_audio_streams(float audio1, float audio2) {
    return audio1 - audio2;
}

// Function to print CSV data
void print_csv(float audio1, float audio2, float processed_audio) {
    printf("%.2f,%.2f,%.2f\n", audio1, audio2, processed_audio);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments for gain control
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0) {
            fprintf(stderr, "Invalid gain value. Using default gain of 1.0.\n");
            gain = 1.0;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure SPI
    spi_handle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle == -1) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read audio streams
        int adc_value_0 = read_mcp3008(MCP3008_CHANNEL_0);
        int adc_value_1 = read_mcp3008(MCP3008_CHANNEL_1);

        // Convert to voltage
        float voltage_0 = adc_to_voltage(adc_value_0);
        float voltage_1 = adc_to_voltage(adc_value_1);

        // Apply gain
        float audio_0 = apply_gain(voltage_0);
        float audio_1 = apply_gain(voltage_1);

        // Subtract audio streams
        float processed_audio = subtract_audio_streams(audio_0, audio_1);

        // Apply noise cancellation threshold
        if (fabs(processed_audio) > GAIN_CONTROL_THRESHOLD) {
            gain = 1.0 - (GAIN_CONTROL_OFFSET * (float)gain); // Reduce gain if above threshold
        } else {
            gain = 1.0; // Increase gain if below threshold
        }

        // Print CSV data
        print_csv(audio_0, audio_1, processed_audio);

        // Delay for sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // microseconds
    }

    // Clean up
    gpioTerminate();
    return 0;
}

