        // Read audio streams
        int adc_value_0 = read_mcp3008(MCP3008_CHANNEL_0);
        int adc_value_1 = read_mcp3008(MCP3008_CHANNEL_1);

        // Convert to voltage
        float voltage_0 = adc_to_voltage(adc_value_0);
