        // Apply gain
        float audio_0 = apply_gain(voltage_0);
        float audio_1 = apply_gain(voltage_1);

        // Subtract audio streams
        float processed_audio = subtract_audio_streams(audio_0, audio_1);

        // Apply noise cancellation threshold
        if (fabs(processed_audio) > GAIN_CONTROL_THRESHOLD) {
