#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_fd;
    int buzzer_gpio;
    float flame_threshold;
    char *temperature_file;
    char *log_file;
    int sample_interval_ms;
} Config;

// Function prototypes
int spi_init(const char *device);
int read_mcp3008(int channel);
float read_temperature(const char *filename);
float compensate_voltage(int adc_value, float temperature);
int log_data(const char *filename, int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int gpio_pin, int state);
void signal_handler(int signal);

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to read ambient temperature from file
float read_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return 25.0; // Default temperature
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return 25.0; // Default temperature
    }

    float temperature = atof(line);
    fclose(fp);
    return temperature;
}

// Function to compensate voltage
float compensate_voltage(int adc_value, float temperature) {
    float voltage = (adc_value / 1023.0) * 3.3;
    float compensated_voltage = voltage + (temperature - 25.0) * 0.001;
    return compensated_voltage;
}

// Function to log data to file
int log_data(const char *filename, int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to control the buzzer
void control_buzzer(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize configuration
    Config config = {
        .spi_fd = -1,
        .buzzer_gpio = BUZZER_GPIO,
        .flame_threshold = FLAME_THRESHOLD,
        .temperature_file = TEMPERATURE_FILE,
        .log_file = LOG_FILE,
        .sample_interval_ms = SAMPLE_INTERVAL_MS
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    config.spi_fd = spi_init(SPI_DEVICE);
    if (config.spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize buzzer GPIO
    gpioSetMode(config.buzzer_gpio, PI_OUTPUT);
    control_buzzer(config.buzzer_gpio, 0); // Turn off buzzer initially

    // Open log file
    config.log_file = fopen(config.log_file, "a");
    if (config.log_file == NULL) {
        perror("Error opening log file");
        close(config.spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int adc_value, flame_detected;
    float temperature, compensated_voltage;

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            log_data(config.log_file, -1, -1.0, -1.0, -1, -1); // Log error
            sleep(1); // Wait before retrying
            continue;
        }

        // Read temperature from file
        temperature = read_temperature(config.temperature_file);

        // Compensate voltage
        compensated_voltage = compensate_voltage(adc_value, temperature);

        // Flame detection
        flame_detected = (compensated_voltage > config.flame_threshold);

        // Log data
        log_data(config.log_file, adc_value, compensated_voltage, compensated_voltage, temperature, flame_detected);

        // Control buzzer
        control_buzzer(config.buzzer_gpio, flame_detected);

        // Wait for the next sample
        usleep(config.sample_interval_ms * 1000); // Convert ms to microseconds
    }

    // Cleanup
    close(config.spi_fd);
    fclose(config.log_file);
    control_buzzer(config.buzzer_gpio, 0); // Turn off buzzer
    gpioTerminate();

    return 0;
}

