#include <pigpio.h>
#include <jansson.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define LED_ON_DURATION 5 // seconds

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_data(float water_level_percentage);
void control_led(float water_level_percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008): %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to JSON file
void log_data(float water_level_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03dZ", timeinfo);

    json_t *root = json_array();
    json_t *entry = json_object();

    json_object_set_new(entry, "timestamp", json_string(timestamp));
    json_object_set_new(entry, "water_level_percentage", json_real(water_level_percentage));

    json_array_append_new(root, entry);

    // Flush the JSON array to the file
    json_dump_file(root, json_file, JSON_INDENT(4));

    json_decref(root);
}

// Function to control the LED based on water level
void control_led(float water_level_percentage) {
    if (water_level_percentage > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED ON
        gpioDelay(LED_ON_DURATION * 1000); // Delay for 5 seconds
        gpioWrite(LED_GPIO, 0); // Turn LED OFF
    } else if (water_level_percentage < WATER_LEVEL_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 1); // Turn LED ON
        gpioDelay(LED_ON_DURATION * 1000); // Delay for 5 seconds
        gpioWrite(LED_GPIO, 0); // Turn LED OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open JSON file for appending
    json_file = fopen("water_levels.json", "a");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Failed to open water_levels.json\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float water_level_percentage = convert_to_percentage(adc_value);
            printf("Water level: %.2f%%\n", water_level_percentage);
            log_data(water_level_percentage);
            control_led(water_level_percentage);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(json_file);

    return 0;
}

