#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define AWM7300V_SENSITIVITY 0.064 // LPM/ADC unit
#define AWM7300V_OFFSET 0.0 // ADC units
#define LOG_FILE "airflow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float sensitivity;
    float offset;
    char *log_file_name;
} config_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int baud);
int read_mcp3008(int channel);
float convert_to_flow_rate(int adc_value, float sensitivity, float offset);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to flow rate
float convert_to_flow_rate(int adc_value, float sensitivity, float offset) {
    return (adc_value - offset) * sensitivity;
}

// Function to log data to file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        fprintf(log_file, "Timestamp,FlowRate(LPM)\n"); // Write header if file is newly created
    }

    fprintf(log_file, "%s,%.4f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(SPI_CHANNEL, SPI_BAUD);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value, AWM7300V_SENSITIVITY, AWM7300V_OFFSET);

        // Log data
        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print flow rate to console
        printf("Flow Rate: %.4f LPM\n", flow_rate);

        // Wait 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

