#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int logging_interval;
    char recipient_email[256];
    char msmtp_config_path[256];
} Config;

// Global variables
int spi_handle;
FILE *log_file;
Config config;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int raw_value);
void log_data(float moisture_percentage);
void send_alert(float moisture_percentage);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int raw_value) {
    float moisture_percentage = 100.0 - ((float)(raw_value - config.min_raw) / (float)(config.max_raw - config.min_raw) * 100.0);
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }
    return moisture_percentage;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_alert(float moisture_percentage) {
    char command[512];
    char body[256];

    snprintf(body, sizeof(body), "Moisture level is below threshold (%.2f%%).", moisture_percentage);

    // Construct msmtp command
    snprintf(command, sizeof(command), "msmtp -t -a default -C %s", config.msmtp_config_path);

    int status = system(command);

    if (status == -1) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;

    // Default values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_raw = 300;
    config.max_raw = 700;
    config.moisture_threshold = 30.0;
    config.logging_interval = 60;
    strncpy(config.recipient_email, "recipient@example.com", sizeof(config.recipient_email) - 1);
    config.recipient_email[sizeof(config.recipient_email) - 1] = '\0';
    strncpy(config.msmtp_config_path, "/etc/mail/mail.conf", sizeof(config.msmtp_config_path) - 1);
    config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0';

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:c:m:t:i:e:a:")) != -1) {
        switch (opt) {
            case 's':
                config.spi_channel = atoi(optarg);
                break;
            case 'c':
                config.adc_channel = atoi(optarg);
                break;
            case 'm':
                config.min_raw = atoi(optarg);
                break;
            case 't':
