        // Print log buffer
        print_log_buffer();

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

