#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MAX30102 I2C address
#define MAX30102_ADDR 0x57

// MAX30102 register addresses
#define REG_PART_ID 0xFF
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_FIFO_DATA 0x07

// SpO2 and HR thresholds
#define MIN_SPO2 95.0
#define MAX_SPO2 100.0
#define MIN_HR 100.0
#define MAX_HR 150.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_fifo_data(uint16_t *red, uint16_t *ir);
float calculate_spo2(uint16_t red, uint16_t ir);
int detect_peaks(uint16_t *ir, int *peak_count);
int log_health_data(float spo2, int hr);
void signal_handler(int signal);

// Function to initialize the MAX30102 sensor
int init_max30102() {
    int status;

    // Verify sensor presence
    char part_id;
    status = i2cReadI2CBlockData(i2c_handle, REG_PART_ID, &part_id, 1);
    if (status != 1) {
        fprintf(stderr, "Error reading Part ID: %d\n", status);
        return -1;
    }

    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the sensor
    status = i2cWriteI2CBlockData(i2c_handle, REG_MODE_CONFIG, 0x40, 1);
    if (status != 1) {
        fprintf(stderr, "Error resetting sensor: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Clear interrupts
    status = i2cWriteI2CBlockData(i2c_handle, 0x00, 0x00, 1); // Clear FIFO
    if (status != 1) {
        fprintf(stderr, "Error clearing interrupts: %d\n", status);
        return -1;
    }

    // Configure SpO2 mode
    status = i2cWriteI2CBlockData(i2c_handle, REG_MODE_CONFIG, 0x03, 1);
    if (status != 1) {
        fprintf(stderr, "Error configuring SpO2 mode: %d\n", status);
        return -1;
    }

    // Configure SPO2_CONFIG
    status = i2cWriteI2CBlockData(i2c_handle, REG_SPO2_CONFIG, 0x27, 1);
    if (status != 1) {
        fprintf(stderr, "Error configuring SPO2_CONFIG: %d\n", status);
        return -1;
    }

    // Set LED pulse amplitudes
    status = i2cWriteI2CBlockData(i2c_handle, REG_LED1_PA, 0x24, 1);
    if (status != 1) {
        fprintf(stderr, "Error setting LED1_PA: %d\n", status);
        return -1;
    }
    status = i2cWriteI2CBlockData(i2c_handle, REG_LED2_PA, 0x24, 1);
    if (status != 1) {
        fprintf(stderr, "Error setting LED2_PA: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read FIFO data from the MAX30102
int read_fifo_data(uint16_t *red, uint16_t *ir) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", status);
        return -1;
    }

    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Function to calculate SpO2 using the ratio-of-ratios method
float calculate_spo2(uint16_t red, uint16_t ir) {
    float ratio_red = (float)ir / (float)red;
    float ratio_ir = (float)ir / (float)red;

    if (ratio_ir == 0.0) {
        return 0.0; // Avoid division by zero
    }

    return ratio_red / ratio_ir;
}

// Function to detect peaks in the IR signal
int detect_peaks(uint16_t *ir, int *peak_count) {
    int i;
    int peak_index = -1;
    int current_index = 0;
    int peak_width = 0;

    for (i = 1; i < 100; i++) { // Check for peaks within a reasonable range
        if (ir[current_index] > ir[i]) {
            if (peak_width < (i - current_index)) {
                peak_width = i - current_index;
                peak_index = i;
            }
        }
        current_index++;
    }

    if (peak_index != -1) {
        *peak_count = peak_width;
        return 0; // Success
    } else {
        return -1; // No peak detected
    }
}

// Function to log health data to a file
int log_health_data(float spo2, int hr) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (hr < MIN_HR || hr > MAX_HR || spo2 < MIN_SPO2 || spo2 > MAX_SPO2) {
        fprintf(log_file, "%s, ERROR: Invalid health data: SpO2=%.2f, HR=%d\n", timestamp, spo2, hr);
        fflush(log_file);
        fprintf(stderr, "%s, ERROR: Invalid health data: SpO2=%.2f, HR=%d\n", timestamp, spo2, hr);
        return -1;
    }

    fprintf(log_file, "%s, SpO2=%.2f, HR=%d\n", timestamp, spo2, hr);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    uint16_t red, ir;
    int peak_count;
    float spo2;
    int hr;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the MAX30102 sensor
    if (init_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read FIFO data
        if (read_fifo_data(&red, &ir) == 0) {
            // Calculate SpO2
            spo2 = calculate_spo2(red, ir);

            // Detect peaks in the IR signal
            peak_count = 0;
            if (detect_peaks(&ir, &peak_count) == 0) {
                hr = peak_count; // Assign peak width as HR
                if (hr > 100) {
                    hr = 100; // Cap HR at 100 BPM
                }
            } else {
                hr = 0; // Assign a default value if no peak is detected
            }

            // Log health data
            if (log_health_data(spo2, hr) != 0) {
                fprintf(stderr, "Error logging health data\n");
            }
        } else {
            fprintf(stderr, "Error reading FIFO data\n");
        }

        gpioDelay(1000000); // Sample every 1 second
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

