#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 parameters
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define MCP3008_CHANNEL_2 2

// Define VREF
#define VREF 3.3

// Define retry count
#define MAX_RETRIES 3

// Define log file name
#define LOG_FILE "analog_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Function prototypes
int spi_transfer(int channel, int *rx_buf, int count);
float calculate_voltage(int adc_value, float vref);
void log_data(int channel, float voltage);
void signal_handler(int signal);

// SPI transfer function
int spi_transfer(int channel, int *rx_buf, int count) {
    char tx_buf[3];
    int result;

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    // Retry loop
    for (int i = 0; i < MAX_RETRIES; ++i) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, count);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to calculate voltage
float calculate_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to log data to CSV file
void log_data(int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write to log file
    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    int adc_value;
    float voltage;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_config_t spi_config = {SPI_CHANNEL, SPI_SPEED, SPI_MODE};
    spi_handle = spiOpen(spi_config.channel, spi_config.speed, spi_config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        adc_value = spi_transfer(MCP3008_CHANNEL_0, NULL, 3);
        if (adc_value >= 0) {
            voltage = calculate_voltage(adc_value, VREF);
            log_data(MCP3008_CHANNEL_0, voltage);
        }

        adc_value = spi_transfer(MCP3008_CHANNEL_1, NULL, 3);
        if (adc_value >= 0) {
            voltage = calculate_voltage(adc_value, VREF);
            log_data(MCP3008_CHANNEL_1, voltage);
        }

        adc_value = spi_transfer(MCP3008_CHANNEL_2, NULL, 3);
        if (adc_value >= 0) {
            voltage = calculate_voltage(adc_value, VREF);
            log_data(MCP3008_CHANNEL_2, voltage);
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

