#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define GPIO_RELAY 17
#define GPIO_REED 27
#define DISTANCE_THRESHOLD_PERCENTAGE 80
#define DISTANCE_THRESHOLD_MULTIPLIER 1.0 - DISTANCE_THRESHOLD_PERCENTAGE / 100.0
#define POLLING_INTERVAL_MS 200
#define LOG_FILE "/var/log/door_events.log"
#define NUM_BASELINE_SAMPLES 10
#define SAMPLE_DELAY_MS 50

// Global variables
int i2c_fd;
int relay_state = 0; // 0 = de-energized, 1 = energized
int reed_state = 0; // 0 = closed, 1 = open

// Function prototypes
int read_distance();
int set_relay_state(int state);
int read_reed_sensor();
void log_event(const char *event);
void signal_handler(int signal);
int initialize_i2c();
void cleanup();

// Function to read distance from ADS1115
int read_distance() {
    unsigned char config[3];
    unsigned char data[2];
    int16_t raw_value;
    float distance;

    // Configure ADS1115 for single-shot mode, AIN0, +/- 3.3V, 128 SPS
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-shot, AIN0, +/-3.3V, 128 SPS)
    config[2] = 0x83; // LSB: 10000011 (Start single conversion)

    if (write(i2c_fd, config, 3) != 3) {
        perror("Failed to configure ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    config[0] = 0x00; // Conversion register address
    if (write(i2c_fd, config, 1) != 1) {
        perror("Failed to set conversion register");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read conversion data");
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];

    // Convert raw value to distance (example formula, adjust as needed)
    distance = (float)raw_value * 0.1; // Example: 0.1V/ADC unit

    return (int)distance;
}

// Function to set the relay state
int set_relay_state(int state) {
    gpioWrite(GPIO_RELAY, state);
    relay_state = state;
    return 0;
}

// Function to read the reed sensor
int read_reed_sensor() {
    int value = gpioRead(GPIO_REED);
    return value;
}

// Function to log events with timestamps
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_relay_state(0); // De-energize relay
    cleanup();
    exit(0);
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    set_relay_state(0); // De-energize relay
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_REED, PI_INPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Take baseline samples
    int baseline_samples[NUM_BASELINE_SAMPLES];
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance during baseline sample %d\n", i + 1);
            continue; // Skip to the next sample
        }
        baseline_samples[i] = distance;
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Calculate average baseline distance
    float baseline_sum = 0.0;
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        baseline_sum += baseline_samples[i];
    }
    float baseline_average = baseline_sum / NUM_BASELINE_SAMPLES;

    // Calculate threshold
    int threshold = (int)(baseline_average * DISTANCE_THRESHOLD_MULTIPLIER);

    // Set initial relay state
    set_relay_state(0); // De-energize relay

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        // Check if distance is below threshold
        if (distance < threshold) {
            set_relay_state(1); // Energize relay
            log_event("Door lock released");
            gpioDelay(3000000); // Energize for 3 seconds
            set_relay_state(0); // De-energize relay
            log_event("Door lock de-energized");

            // Read reed sensor
            reed_state = read_reed_sensor();
            if (reed_state == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        } else {
            log_event("No action");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    return 0;
}

