#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CE0 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 30
#define PUMP_DURATION 10 // seconds
#define SLEEP_INTERVAL 60 // seconds
#define MAX_SPI_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int activate);
void log_data(int adc_value, float moisture, int pump_state);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int count = 0;
    while (count < MAX_SPI_RETRIES) {
        char tx_buf[3];
        char rx_buf[3];

        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
        tx_buf[2] = 0x00;

        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 0) {
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read error, retrying...\n");
            count++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    fprintf(stderr, "Failed to read MCP3008 after %d retries.\n", MAX_SPI_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    float dry_value = 200.0;
    float wet_value = 800.0;
    float moisture_percentage = 100.0 - ((float)(adc_value - 2048) / (float)(2047 - 2048) * 100.0);

    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    if (moisture_percentage < dry_value || moisture_percentage > wet_value) {
        fprintf(stderr, "Moisture percentage out of range: %.2f\n", moisture_percentage);
        return -1.0; // Indicate error
    }

    return moisture_percentage;
}

// Function to control the water pump
void control_pump(int activate) {
    if (activate) {
        gpioWrite(PUMP_GPIO, 1); // Activate pump
        printf("Pump activated\n");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Deactivate pump
        printf("Pump deactivated\n");
    }
}

// Function to log data to a file
void log_data(int adc_value, float moisture, int pump_state) {
    FILE *fp = fopen("irrigation.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ADC: %d, Moisture: %.2f%%, Pump: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            adc_value, moisture, pump_state ? "ON" : "OFF");

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

// Setup function to initialize pigpio and SPI
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = MOISTURE_THRESHOLD;
    int duration = PUMP_DURATION;
    int sleep_interval = SLEEP_INTERVAL;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup()) {
        return 1;
    }

    printf("Irrigation system started. Threshold: %d%%, Duration: %d s, Sleep: %d s\n", threshold, duration, sleep_interval);

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(SPI_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping irrigation cycle.\n");
            gpioDelay(sleep_interval * 1000000); // Sleep for sleep_interval seconds
            continue;
        }

        float moisture = calculate_moisture(adc_value);
        if (moisture < 0) {
            fprintf(stderr, "Failed to calculate moisture, skipping irrigation cycle.\n");
            gpioDelay(sleep_interval * 1000000); // Sleep for sleep_interval seconds
            continue;
        }

        control_pump(moisture < threshold);
        log_data(adc_value, moisture, gpioRead(PUMP_GPIO));

        gpioDelay(sleep_interval * 1000000); // Sleep for sleep_interval seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

