// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define EMA_ALPHA 0.2
#define THRESHOLD_MULTIPLIER 1.2
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_MS 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    double ema_alpha;
    double threshold_multiplier;
    char *log_file;
    int sample_interval_ms;
} Config;

// Function prototypes
int initialize_spi(int channel, int speed);
int read_mcp3008(int channel);
double calculate_ema(double new_value, double *ema, double alpha);
int detect_peak(double raw_value, double ema, double threshold_multiplier);
int log_event(double raw_value, double ema, int peak_detected);
void signal_handler(int signal);

// EMA calculation function
double calculate_ema(double new_value, double *ema, double alpha) {
    *ema = alpha * new_value + (1 - alpha) * *ema;
    return *ema;
}

// Peak detection function
int detect_peak(double raw_value, double ema, double threshold_multiplier) {
    double threshold = ema * threshold_multiplier;
    return (raw_value > threshold);
}

// Logging function
int log_event(double raw_value, double ema, int peak_detected) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, raw_value, ema, peak_detected);
    fclose(fp);
    return 0;
}

// SPI initialization function
int initialize_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// MCP3008 reading function
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

