#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Define the control byte for single-ended AIN0
#define PCF8591_CONTROL_AIN0 0x40

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to write a byte to the PCF8591
int write_pcf8591(int fd, uint8_t control_byte) {
    uint8_t data[2];
    data[0] = control_byte & 0x0F; // Mask the control byte to write only the first byte
    data[1] = (control_byte >> 4) & 0xFF; // Write the second byte

    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from the PCF8591
int read_pcf8591(int fd, uint8_t *data) {
    if (write(fd, NULL, 0) != 0) {
        perror("Error writing to I2C device for reading");
        return -1;
    }

    if (read(fd, data, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop to continuously read and print the ADC value
    while (1) {
        uint8_t data[2];
        int adc_value;

        // Write the control byte to enable single-ended AIN0
        if (write_pcf8591(i2c_fd, PCF8591_CONTROL_AIN0) < 0) {
            fprintf(stderr, "Error writing to PCF8591. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        // Dummy read to clear the previous data
        if (read_pcf8591(i2c_fd, data) < 0) {
            fprintf(stderr, "Error reading from PCF8591. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        // Read the ADC value (0-255)
        if (read_pcf8591(i2c_fd, data) < 0) {
            fprintf(stderr, "Error reading ADC value. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        // Combine the two bytes to get the ADC value
        adc_value = (data[0] << 4) | (data[1] >> 4);

        // Print the ADC value to stdout
        printf("ADC Value: %d\n", adc_value);

        // Wait for 100 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Close the I2C file descriptor (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

