#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_SHUTDOWN 27
#define THRESHOLD 500.0 // Gauss
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1
#define VCC 3.3 // Volts
#define SENSITIVITY 0.0014 // V/Gauss
#define ZERO_FIELD_OUTPUT 2.5 // Volts

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float voltage_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int read_ads1115(float *voltage);
float convert_to_gauss(float voltage);
void add_to_buffer(float voltage);
float calculate_rolling_average();
void log_message(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Configure ADS1115
int configure_ads1115() {
    // Configure for single-ended AIN0, 4.096V range, 128 SPS, single conversion
    uint16_t config_value = 0x4003; //0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        log_message(LOG_ERR, "Failed to configure ADS1115");
        return -1;
    }
    return 0;
}

// Read ADS1115
int read_ads1115(float *voltage) {
    char buf[1];
    char read_buf[2];

    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        log_message(LOG_ERR, "Failed to set ADS1115 for conversion");
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        log_message(LOG_ERR, "Failed to read ADS1115 conversion");
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    *voltage = (float)raw_value * VCC / 32768.0; // Convert to voltage

    return 0;
}

// Convert voltage to Gauss
float convert_to_gauss(float voltage) {
    return (voltage - ZERO_FIELD_OUTPUT) / SENSITIVITY;
}

// Add voltage to circular buffer
void add_to_buffer(float voltage) {
    voltage_buffer[buffer_index] = voltage;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += voltage_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Log message to syslog
void log_message(int priority, const char *message) {
    openlog("magnetometer", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Cleanup function
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    i2cClose(i2c_handle);
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Initialize to LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float voltage, gauss;
    float rolling_average;

    log_message(LOG_INFO, "Starting magnetometer program");

    while (!terminate) {
        if (read_ads1115(&voltage) == 0) {
            add_to_buffer(voltage);
            rolling_average = calculate_rolling_average();
            log_message(LOG_INFO, "Voltage: %.2f V, Gauss: %.2f, Rolling Average: %.2f", voltage, convert_to_gauss(voltage), rolling_average);

            if (rolling_average > THRESHOLD) {
                log_message(LOG_WARNING, "Threshold exceeded, shutting down motor!");
                gpioWrite(GPIO_SHUTDOWN, 1); // Set GPIO HIGH
            }
        } else {
            log_message(LOG_WARNING, "Failed to read sensor data. Skipping.");
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay for 1 Hz sampling
    }

    cleanup();
    return 0;
}

