#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MCP3008_CE 8
#define MCP3008_CLK 11
#define MCP3008_MISO 9
#define MCP3008_MOSI 10
#define MOTOR_PIN 18

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// PWM configuration
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1024

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
int set_pwm_duty_cycle(int duty_cycle);
void cleanup();
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int clk_pin;
    int miso_pin;
    int mosi_pin;
    int speed;
    int mode;
} spi_config_t;

// Structure to hold GPIO configuration
typedef struct {
    int motor_pin;
    int pwm_range;
    int pwm_frequency;
} gpio_config_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure GPIO for PWM
    gpioSetMode(MOTOR_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_PIN, PWM_RANGE);

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            gpioDelay(10000); // 10 ms delay
            continue;
        }

        // Set PWM duty cycle based on ADC value
        int duty_cycle = (int)(((float)adc_value / PWM_RANGE) * PWM_RANGE);
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle. Retrying.\n");
            gpioDelay(10000); // 10 ms delay
            continue;
        }

        // Print ADC value and duty cycle
        printf("ADC Value: %d, Duty Cycle: %d\n", adc_value, duty_cycle);

        // Delay for 100 ms
        gpioDelay(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return 1;
    }

    gpioPWM(MOTOR_PIN, duty_cycle);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up and exiting...\n");
    gpioPWM(MOTOR_PIN, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

