#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define DEFAULT_SENSITIVITY 0.001

// Global variables
int i2c_handle;
double sensitivity;
double threshold;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_ads1115(int *adc_value);
double convert_to_gauss(int adc_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    int config_reg;
} ads1115_config_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration from file (or default values)
    FILE *fp = fopen("ads1115_config.txt", "r");
    if (fp != NULL) {
        char line[256];
        while (fgets(line, sizeof(line), fp)) {
            if (strncmp(line, "config_reg", 11) == 0) {
                sensitivity = atof(line + 11);
                break;
            }
        }
        fclose(fp);
        printf("Configuration read from file: sensitivity = %f\n", sensitivity);
    } else {
        printf("Configuration file not found. Using default sensitivity: %f\n", DEFAULT_SENSITIVITY);
        sensitivity = DEFAULT_SENSITIVITY;
    }

    // Configure ADS1115 (single-ended, gain 4.096V, continuous conversion)
    ads1115_config_t config = {0x4003}; // 0b0100000000000011
    config.config_reg = 0x01; // Configuration register address

    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config.config_reg) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    return 0;
}

