int read_ads1115(int *adc_value) {
    char buf[2];
    int16_t raw_value;

    // Read conversion register
    if (i2cWriteByte(i2c_handle, ADS1115_REG_CONVERT) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return 1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return 1;
    }

    raw_value = (buf[0] << 8) | buf[1];
    *adc_value = raw_value;

    return 0;
}

// Function to convert ADC value to Gauss
double convert_to_gauss(int adc_value) {
    return (adc_value * sensitivity) / 4096.0;
}

// Function to blink the LED
void blink_led(int duration_ms) {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for duration_ms ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for duration_ms ms
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    int adc_value;
    double gauss_value;

    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
    } else {
        threshold = DEFAULT_THRESHOLD;
    }

    // Initialize the system
    if (initialize()) {
        return 1;
    }

    printf("Monitoring magnetic field strength...\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&adc_value) == 0) {
            // Convert to Gauss
            gauss_value = convert_to_gauss(adc_value);

            // Print magnetic field strength
            printf("Gauss: %.2f\n", gauss_value);

            // Check if threshold is exceeded
            if (fabs(gauss_value) > threshold) {
                printf("Threshold exceeded! Blinking LED...\n");
                blink_led(1000); // Blink for 1 second (1000 ms)
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100 * 1000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

