#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_COMMAND_TOPIC "pump_control"
#define MOISTURE_THRESHOLD_LOW 30.0
#define MOISTURE_THRESHOLD_HIGH 35.0
#define PUMP_DURATION 5 // seconds
#define PUMP_INTERVAL 60 // seconds
#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(float moisture);
void publish_moisture(float moisture);
void handle_mqtt_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);
int setup_mqtt();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int count = 0;
    while (count < MAX_RETRIES) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            syslog(LOG_ERR, "SPI transfer failed (attempt %d): %d", count + 1, -1);
            count++;
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
        }
    }

    syslog(LOG_ERR, "SPI transfer failed after %d retries", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate error
    }

    // Assuming a linear relationship between ADC value and moisture percentage
    // You'll need to calibrate this based on your sensor and environment
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(float moisture) {
    static int pump_state = 0; // 0 = off, 1 = on
    static time_t pump_start_time = 0;
    time_t current_time;

    if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
        syslog(LOG_INFO, "Moisture below threshold (%.2f%%), turning pump ON", moisture);
        pump_state = 1;
        if (pump_start_time == 0) {
            pump_start_time = time(NULL);
        }
    } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
        syslog(LOG_INFO, "Moisture above threshold (%.2f%%), turning pump OFF", moisture);
        pump_state = 0;
    }

    if (pump_state == 1) {
        current_time = time(NULL);
        if (difftime(current_time, pump_start_time) >= PUMP_DURATION) {
            syslog(LOG_INFO, "Pump duration exceeded, turning pump OFF");
            pump_state = 0;
        }
    }
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    }
}

// MQTT message callback function
void handle_mqtt_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_COMMAND_TOPIC) == 0) {
            if (strcmp(message->payload, "ON") == 0) {
                syslog(LOG_INFO, "Received command: Pump ON");
                control_pump(calculate_moisture(read_mcp3008(MCP3008_CHANNEL)));
            } else if (strcmp(message->payload, "OFF") == 0) {
                syslog(LOG_INFO, "Received command: Pump OFF");
                control_pump(0.0); // Turn off the pump
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// MQTT setup function
int setup_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_message_callback_set(mosq, handle_mqtt_message);

    int ret = mosquitto_loop_start(mosq);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel, baud rate, flags
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Setup MQTT
    if (setup_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT setup failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        float moisture = calculate_moisture(adc_value);
        if (moisture < 0.0) {
            syslog(LOG_ERR, "Failed to calculate moisture");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Control the pump
        control_pump(moisture);

        // Publish moisture data
        publish_moisture(moisture);

        // Wait for the next interval
        gpioDelay(60000); // 60 seconds
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    control_pump(0.0); // Turn off the pump
    spiClose(spi_handle);
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    gpioTerminate();
    closelog();

    return 0;
}

