            pump_state = 0;
        }
    }
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    }
}

// MQTT message callback function
void handle_mqtt_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_COMMAND_TOPIC) == 0) {
            if (strcmp(message->payload, "ON") == 0) {
                syslog(LOG_INFO, "Received command: Pump ON");
                control_pump(calculate_moisture(read_mcp3008(MCP3008_CHANNEL)));
            } else if (strcmp(message->payload, "OFF") == 0) {
                syslog(LOG_INFO, "Received command: Pump OFF");
                control_pump(0.0); // Turn off the pump
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// MQTT setup function
int setup_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_message_callback_set(mosq, handle_mqtt_message);

    int ret = mosquitto_loop_start(mosq);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel, baud rate, flags
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Setup MQTT
    if (setup_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT setup failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        float moisture = calculate_moisture(adc_value);
        if (moisture < 0.0) {
            syslog(LOG_ERR, "Failed to calculate moisture");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Control the pump
        control_pump(moisture);

        // Publish moisture data
        publish_moisture(moisture);

        // Wait for the next interval
        gpioDelay(60000); // 60 seconds
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    control_pump(0.0); // Turn off the pump
    spiClose(spi_handle);
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    gpioTerminate();
    closelog();

    return 0;
}

