#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNELS 3

// Define VREF
#define VREF 3.3

// Define CSV filename
#define CSV_FILENAME "sensor_data.csv"

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channels;
    float vref;
    char *csv_filename;
} config_t;

// Function prototypes
int initialize_pigpio();
int open_spi(int channel, int speed);
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value, float vref);
int log_data(FILE *file, int channel, float voltage);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open SPI channel
int open_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // SPI_MODE_0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to log data to CSV file
int log_data(FILE *file, int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(file, "%s,%d,%.3f\n", timestamp, channel, voltage) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .mcp3008_channels = MCP3008_CHANNELS,
        .vref = VREF,
        .csv_filename = CSV_FILENAME
    };

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    spi_handle = open_spi(config.spi_channel, config.spi_speed);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(config.csv_filename, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", config.csv_filename);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < config.mcp3008_channels; channel++) {
            // Read ADC value
            int adc_value = read_mcp3008(channel);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC value from channel %d\n", channel);
                continue; // Skip to the next channel
            }

            // Convert to voltage
            float voltage = convert_to_voltage(adc_value, config.vref);

            // Log data
            if (log_data(csv_file, channel, voltage) != 0) {
                fprintf(stderr, "Error logging data for channel %d\n", channel);
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

