#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x11
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define LOG_FILE "tamper_log.csv"

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int read_bh1750(float *light_level);
float adc_to_db(int adc_value);
float lux_to_light_level(int raw_value);
int log_data(time_t timestamp, float sound_level_db, float light_level_lux, int adc_error, int i2c_error);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_fd, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to read light level from BH1750 sensor
int read_bh1750(float *light_level) {
    char cmd[1] = {BH1750_CONTINUOUS_HIGH_RES_MODE};
    char rx_buf[2];
    int i2c_error = -1;

    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        if (i2cWriteDevice(i2c_fd, cmd, 1) == 0) {
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            if (i2cReadDevice(i2c_fd, rx_buf, 2) == 2) {
                // Combine the two bytes into a 16-bit value
                int raw_value = (rx_buf[0] << 8) | rx_buf[1];
                *light_level = (float)raw_value / 1.2; // Convert to lux
                return 0; // Success
            } else {
                fprintf(stderr, "Error: I2C read failed (attempt %d)\n", i + 1);
            }
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d)\n", i + 1);
        }
        gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: BH1750 read failed after %d retries\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// Function to convert ADC value to sound level (dB)
float adc_to_db(int adc_value) {
    // Assuming a linear relationship between ADC value and sound level
    // You'll need to calibrate this based on your specific setup
    float db_level = (float)adc_value / 1023.0 * 80.0; // Example: 0-1023 -> 80 dB
    return db_level;
}

// Function to convert raw BH1750 value to lux
float lux_to_light_level(int raw_value) {
    // BH1750 datasheet formula
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Function to log data to CSV file
int log_data(time_t timestamp, float sound_level_db, float light_level_lux, int adc_error, int i2c_error) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp_str, sound_level_db, light_level_lux, adc_error, i2c_error);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, BH1750_ADDR, 0); // I2C bus 1, address 0x23, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,adc_error,i2c_error\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            adc_error = -1; // Indicate ADC read error
        } else {
            float sound_level_db = adc_to_db(adc_value);
            int i2c_result = read_bh1750(&light_level_lux);
            if (i2c_result != 0) {
                fprintf(stderr, "Error: Failed to read BH1750 value\n");
                i2c_error = -1; // Indicate I2C read error
            } else {
                light_level_lux = lux_to_light_level(light_level_lux);
            }
        }

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        if (log_data(current_time, sound_level_db, light_level_lux, adc_error, i2c_error) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

