#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float moisture_threshold;
    char *log_file;
} config_t;

// Function to read from MCP3008
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage >= 0.0) {
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);

                if (moisture_percentage < MOISTURE_THRESHOLD) {
                    fprintf(stderr, "Low moisture detected! (%.2f%% < %.2f%%)\n", moisture_percentage, MOISTURE_THRESHOLD);
                }
            } else {
                fprintf(stderr, "Invalid moisture percentage: %.2f%%\n", moisture_percentage);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

