#define ADC_READ_TIMEOUT_MS 100

// Global variables
int spi_handle;
int socket_desc;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_adc(int channel);
float adc_to_ppm(int adc_value);
char *classify_alcohol_level(float ppm);
void log_data(float ppm, char *classification);
void send_data(float ppm, char *classification);
