#define MAX_SPEED 255

// Define motion profile parameters
#define ACCELERATION_TIME 2 // seconds
#define HOLD_TIME 2 // seconds
#define DECELERATION_TIME 2 // seconds
#define PAUSE_TIME 5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float map_to_speed(int adc_value);
void set_motor_speed(int motor_number, int speed);
void forward(int motor_number);
void backward(int motor_number);
void stop_motor(int motor_number);
void motion_profile(int motor1_speed, int motor2_speed);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to map ADC value to speed using a logarithmic function
float map_to_speed(int adc_value) {
    // Ensure ADC value is within the valid range
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    // Use a logarithmic mapping for finer control at low speeds
    float log_speed = log10(adc_value + 1) / log10(1024) * 255.0; // Scale to 0-255
    return (int)log_speed;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_number, int speed) {
    int enable_pin, dir_pin;

    if (motor_number == 1) {
        enable_pin = MOTOR1_ENABLE;
        dir_pin = MOTOR1_DIR;
    } else if (motor_number == 2) {
        enable_pin = MOTOR2_ENABLE;
        dir_pin = MOTOR2_DIR;
    } else {
