        return;
    }

    gpioPWM(enable_pin, 128); // Enable the motor (50%)
    gpioWrite(dir_pin, (speed > 0) ? 1 : 0); // Set direction (1 for forward, 0 for backward)
    gpioPWM(dir_pin, speed); // Set speed (0-255)
