#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define CS_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration parameters
#define CALIBRATION_TIME 5 // seconds
#define DEBOUNCE_DELAY 10 // milliseconds

// Global variables
int spi_handle;
int ambient_level = 0;
int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int channel);
void calibrate_ambient_level();
void check_sound_level(int current_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1; // Indicate an error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate the ambient sound level
void calibrate_ambient_level() {
    printf("Calibrating ambient level for %d seconds...\n", CALIBRATION_TIME);
    ambient_level = 0; // Reset the ambient level
    for (int i = 0; i < CALIBRATION_TIME * 100; ++i) {
        int level = read_mcp3008(0);
        if (level == -1) {
            fprintf(stderr, "Error reading MCP3008 during calibration. Exiting.\n");
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
        ambient_level += level;
        gpioDelay(1000); // 1 ms delay
    }
    printf("Calibration complete. Average ambient level: %d\n", ambient_level / (CALIBRATION_TIME * 100));
}

// Function to check the sound level against the ambient level
void check_sound_level(int current_level) {
    if (current_level > (ambient_level * 1.1)) {
        // Check for debounce
        if (led_state == 0) {
            gpioWrite(LED_PIN, 1); // Turn LED on
            led_state = 1;
            gpioDelay(DEBOUNCE_DELAY); // Debounce
            gpioWrite(LED_PIN, 0); // Turn LED off
            led_state = 0;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle); // Close SPI handle
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Calibrate the ambient level
    calibrate_ambient_level();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int current_level = read_mcp3008(0);
        if (current_level == -1) {
            fprintf(stderr, "Error reading sound level. Retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        check_sound_level(current_level);

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

