#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define SLPM_MIN 0
#define SLPM_MAX 200
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(int adc_value);
void log_data(float airflow);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "ERROR: SPI read/write failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert voltage to airflow (SLPM)
float voltage_to_airflow(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float airflow = (voltage - 0.5) / (4.5 - 0.5) * SLPM_MAX;
    return airflow;
}

// Function to log data to file
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
