#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8           // GPIO8 (CE0)
#define MCP3008_CHANNEL 0
#define LOG_FILE "audio_log.txt"
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE) // 100ms

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device, int mode, int bits, int speed);
int spi_ioctl(int fd, int cmd);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_request(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int gpio_release(int pin);
int read_mcp3008(int channel);
void log_data(const char *timestamp, int adc_value);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) == -1) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error getting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO request function
int gpio_request(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    return gpioSetMode(pin, PI_OUTPUT);
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    if (gpio_request(pin) < 0) return -1;
    return gpioSetMode(pin, PI_OUTPUT);
}

// GPIO write function
int gpio_write(int pin, int value) {
    if (gpio_set_direction(pin, "out") < 0) return -1;
    gpioWrite(pin, value);
    return 0;
}

// GPIO release function
int gpio_release(int pin) {
    if (gpio_set_direction(pin, "input") < 0) return -1;
    gpioSetMode(pin, PI_INPUT);
    return 0;
}

// MCP3008 read function
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Start bit
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    gpio_write(CS_PIN, 0); // Select the MCP3008
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        gpio_write(CS_PIN, 1); // Deselect the MCP3008
        return -1;
    }
    gpio_write(CS_PIN, 1); // Deselect the MCP3008

    // Extract the 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Log data function
void log_data(const char *timestamp, int adc_value) {
    if (log_file != NULL) {
        fprintf(log_file, "%s|%d\n", timestamp, adc_value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

        // Log data
        log_data(timestamp_ns, adc_value);

        // Sleep for the sample period
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD_NS;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_release(CS_PIN);

    return 0;
}

