#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3 // Reference voltage
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_ppm(float voltage);
void log_data(float voltage, float ppm);
void print_data(float voltage, float ppm);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_adc): %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0) * vref;
}

// Function to convert voltage to PPM (placeholder)
float voltage_to_ppm(float voltage) {
    return voltage * 1000.0;
}

// Function to log data to file
void log_data(float voltage, float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(log_file, "%s, %.3f, %.3f\n", timestamp, voltage, ppm);
    fclose(log_file);
}

// Function to print data to console
void print_data(float voltage, float ppm) {
    printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int adc_value = -1;
        int retry_count = 0;

        // Retry reading ADC value if it fails
        while (adc_value == -1 && retry_count < 3) {
            adc_value = spi_read_adc(MCP3008_CHANNEL);
            if (adc_value == -1) {
                fprintf(stderr, "Error: SPI read failed, retrying (%d/%d)...\n", retry_count + 1, 3);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry_count++;
            }
        }

        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC after multiple retries. Exiting.\n");
            break; // Exit the loop if reading fails repeatedly
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to PPM
        float ppm = voltage_to_ppm(voltage);

        // Log data
        log_data(voltage, ppm);

        // Print data to console
        print_data(voltage, ppm);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

