#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define MCP3008_CHANNELS 8
#define SAMPLE_RATE 10 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

// ADXL335 Sensitivity (mV/g)
#define ADXL335_SENSITIVITY 300.0

// Kalman Filter Parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1
#define INITIAL_PROCESS_COVARIANCE 1.0
#define INITIAL_MEASUREMENT_COVARIANCE 1.0

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman Filter States
typedef struct {
    float x;
    float v;
} kalman_state_t;

// Kalman Filter Covariances
typedef struct {
    float P;
} kalman_covariance_t;

// Function Prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float kalman_filter(kalman_state_t *state, kalman_covariance_t *covariance, float measurement);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read MCP3008 Channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC Value to Voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 3.3;
}

// Convert Voltage to Acceleration (g)
float voltage_to_acceleration(float voltage) {
    return (voltage - 1.5) / ADXL335_SENSITIVITY;
}

// Kalman Filter
float kalman_filter(kalman_state_t *state, kalman_covariance_t *covariance, float measurement) {
    // Prediction step
    state->x = state->x + 0.1; // Process noise
    state->v = state->v + 0.1; // Process noise
    kalman_covariance_t temp = *covariance;
    *covariance = temp + PROCESS_NOISE;

    // Update step
    float kalman_gain = state->v / (state->v + MEASUREMENT_NOISE);
    state->x = state->x + kalman_gain * (measurement - state->x);
    state->v = (1 - kalman_gain) * state->v;
    *covariance = *covariance + MEASUREMENT_NOISE;

    return state->x;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman Filter States and Covariances
    kalman_state_t state = {0.0, 0.0};
    kalman_covariance_t covariance = {1.0};

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read ADC values from MCP3008
        int adc_values[MCP3008_CHANNELS];
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC channel %d\n", i);
                continue; // Skip to the next channel
            }
            adc_values[i] = adc_value;
        }

        // Convert ADC values to voltages
        float voltages[MCP3008_CHANNELS];
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            voltages[i] = adc_to_voltage(adc_values[i]);
        }

        // Convert voltages to accelerations
        float accelerations[MCP3008_CHANNELS];
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            accelerations[i] = voltage_to_acceleration(voltages[i]);
        }

        // Apply Kalman filter
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            accelerations[i] = kalman_filter(&state, &covariance, voltages[i]);
        }

        // Print acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", accelerations[0], accelerations[1], accelerations[2]);

        gpioDelay(SAMPLE_PERIOD_US); // Delay for 10 Hz sampling
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

