#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the quiescent voltage (V_quiescent)
#define V_QUIESCENT 1.65

// Define the sensitivity (V/mT)
#define SENSITIVITY 0.025

// Define the supply voltage (V)
#define VCC 3.3

// Define the magnetic field range (mT)
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Define the sampling interval (ms)
#define SAMPLING_INTERVAL 100

// Global variables for GPIO lines and file pointer
static int sensor1_line = -1;
static int sensor2_line = -1;
static int sensor3_line = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(int pin);
int read_sensor(int line);
float calculate_magnetic_field(float voltage);
void log_data(float sensor1_magnetic_field, float sensor2_magnetic_field, float sensor3_magnetic_field);
void signal_handler(int signal);
void cleanup();

// Function to initialize a GPIO line for input
int initialize_gpio(int pin) {
    int line = gpioSetMode(pin, PI_INPUT);
    if (line < 0) {
        fprintf(stderr, "Error setting GPIO %d as input: %s\n", pin, strerror(errno));
        return -1;
    }
    return line;
}

// Function to read the digital value from a sensor
int read_sensor(int line) {
    int value = gpioRead(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", line, strerror(errno));
        return -1;
    }
    return value;
}

// Function to calculate the magnetic field strength in mT
float calculate_magnetic_field(float voltage) {
    float magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field;
}

// Function to log the sensor data to a file
void log_data(float sensor1_magnetic_field, float sensor2_magnetic_field, float sensor3_magnetic_field) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_magnetic_field, sensor2_magnetic_field, sensor3_magnetic_field);
    fflush(log_file); // Flush the file to ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release GPIO resources and close the log file
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (sensor1_line >= 0) {
        gpioSetMode(sensor1_line, PI_INPUT); // Set back to input
        gpioTerminate(sensor1_line);
    }
    if (sensor2_line >= 0) {
        gpioSetMode(sensor2_line, PI_INPUT); // Set back to input
        gpioTerminate(sensor2_line);
    }
    if (sensor3_line >= 0) {
        gpioSetMode(sensor3_line, PI_INPUT); // Set back to input
        gpioTerminate(sensor3_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO lines
    sensor1_line = initialize_gpio(SENSOR1_PIN);
    sensor2_line = initialize_gpio(SENSOR2_PIN);
    sensor3_line = initialize_gpio(SENSOR3_PIN);

    if (sensor1_line < 0 || sensor2_line < 0 || sensor3_line < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);
        int sensor3_value = read_sensor(sensor3_line);

        // Check for errors during sensor reading
        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor values. Skipping logging.\n");
            continue; // Skip logging and continue to the next iteration
        }

        // Calculate voltage (assuming 3.3V is HIGH)
        float voltage1 = (sensor1_value == 1) ? VCC : 0.0;
        float voltage2 = (sensor2_value == 1) ? VCC : 0.0;
        float voltage3 = (sensor3_value == 1) ? VCC : 0.0;

        // Calculate magnetic field strength
        float magnetic_field1 = calculate_magnetic_field(voltage1);
        float magnetic_field2 = calculate_magnetic_field(voltage2);
        float magnetic_field3 = calculate_magnetic_field(voltage3);

        // Log the data
        log_data(magnetic_field1, magnetic_field2, magnetic_field3);

        // Check for out-of-range magnetic field values
        if (magnetic_field1 < MIN_MAGNETIC_FIELD || magnetic_field1 > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Sensor 1 magnetic field out of range: %.2f mT\n", magnetic_field1);
        }
        if (magnetic_field2 < MIN_MAGNETIC_FIELD || magnetic_field2 > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Sensor 2 magnetic field out of range: %.2f mT\n", magnetic_field2);
        }
        if (magnetic_field3 < MIN_MAGNETIC_FIELD || magnetic_field3 > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Sensor 3 magnetic field out of range: %.2f mT\n", magnetic_field3);
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

