    // Initialize GPIO lines
    sensor1_line = initialize_gpio(SENSOR1_PIN);
    sensor2_line = initialize_gpio(SENSOR2_PIN);
    sensor3_line = initialize_gpio(SENSOR3_PIN);

    if (sensor1_line < 0 || sensor2_line < 0 || sensor3_line < 0) {
        cleanup();
        return 1;
    }

