// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define SLEEP_SECONDS 60

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(float moisture_level);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture level (0-100%)
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_event("Error: Invalid ADC value.");
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(float moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        log_event("Pump ON");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        log_event("Pump OFF");
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    program_running = 0;
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Initially turn pump OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error: Failed to read ADC value.");
        } else {
            float moisture_level = calculate_moisture(adc_value);
            if (moisture_level >= 0.0) {
                control_pump(moisture_level);
                log_event("Moisture level: " + moisture_level + "%");
            } else {
                log_event("Error: Failed to calculate moisture level.");
            }
        }

        gpioDelay(SLEEP_SECONDS * 1000); // Sleep for 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

