#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define MCP3008 channel numbers
#define CHANNEL_0 0
#define CHANNEL_1 1
#define CHANNEL_2 2

// Define CSV filename
#define CSV_FILENAME "sensor_data.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *csv_file = NULL;

// Structure to hold SPI configuration
typedef struct {
    int fd;
    int mode;
    unsigned int bits_per_word;
    unsigned int speed_hz;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int spi_read_adc(int channel);
int csv_write_data(FILE *fp, int channel0, int channel1, int channel2);
void signal_handler(int signal);

// SPI initialization function
int spi_init(spi_config_t *config) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &config->mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed hz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->speed_hz) == -1) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Build SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(1, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// CSV write data function
int csv_write_data(FILE *fp, int channel0, int channel1, int channel2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0, channel1, channel2) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    if (spi_fd > 0) {
        close(spi_fd);
    }

    exit(0);
}

int main() {
    spi_config_t spi_config = {0};
    spi_config.fd = -1; // Initialize to an invalid file descriptor
    spi_config.mode = SPI_MODE;
    spi_config.bits_per_word = 8;
    spi_config.speed_hz = 1000000; // 1 MHz

    // Initialize SPI
    spi_fd = spi_init(&spi_config);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(spi_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    rewind(csv_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC values
        int channel0_value = spi_read_adc(CHANNEL_0);
        int channel1_value = spi_read_adc(CHANNEL_1);
        int channel2_value = spi_read_adc(CHANNEL_2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Write data to CSV file
        if (csv_write_data(csv_file, channel0_value, channel1_value, channel2_value) != 0) {
            fprintf(stderr, "Error writing data to CSV file. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close CSV file and SPI device
    fclose(csv_file);
    close(spi_fd);

    return 0;
}

