#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Function prototypes
int read_sound_sensor(int gpio_pin);
void control_alarm_led(int gpio_pin, int state, int duration_ms);
void cleanup_gpio(int gpio_pin);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Function to read the sound sensor
int read_sound_sensor(int gpio_pin) {
    int sound_level = gpioRead(gpio_pin);
    if (sound_level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, sound_level);
        return -1; // Indicate an error
    }
    return sound_level;
}

// Function to control the alarm LED
void control_alarm_led(int gpio_pin, int state, int duration_ms) {
    gpioWrite(gpio_pin, state);
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
    gpioWrite(gpio_pin, 0); // Turn off the LED after the duration
}

// Function to cleanup GPIO resources
void cleanup_gpio(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_INPUT); // Set to input to release resources
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor(SOUND_SENSOR_PIN);
        if (sound_level == -1) {
            // Error reading sensor, exit loop
            break;
        }

        if (sound_level == 0) { // Sound detected (LOW)
            printf("Sound detected!\n");
            control_alarm_led(ALARM_LED_PIN, 1, 1000); // Turn on LED for 1 second
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio(SOUND_SENSOR_PIN);
    cleanup_gpio(ALARM_LED_PIN);

    printf("Program terminated.\n");
    return 0;
}

