#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_CHIP 0
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;
static int log_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Signal received, exiting gracefully.\n");
        terminate = 1;
    }
}

int open_log_file() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

int close_log_file() {
    if (log_fd != -1) {
        close(log_fd);
        log_fd = -1;
        return 0;
    }
    return -1;
}

int log_event(const char *message) {
    if (log_fd == -1) {
        fprintf(stderr, "Log file not open.\n");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fd, "%s: %s\n", timestamp, message);
    fflush(log_fd); // Ensure immediate write to disk
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LINE, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_LINE);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_LINE, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", GPIO_LINE);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(GPIO_LINE, log_event, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", GPIO_LINE);
        gpioTerminate();
        return 1;
    }

    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        sleep(1); // Reduce CPU usage
    }

    printf("Exiting...\n");

    if (log_fd != -1) {
        close_log_file();
    }

    gpioTerminate();
    return 0;
}

