#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3 // Reference voltage
#define LM35_SENSITIVITY 0.01 // 10mV/°C
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void add_to_circular_buffer(CircularBuffer *cb, float value);
void log_circular_buffer_to_file(CircularBuffer *cb);
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Log circular buffer to file
void log_circular_buffer_to_file(CircularBuffer *cb) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening log file for writing");
        return;
    }

    size_t bytes_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (bytes_written != cb->count) {
        fprintf(stderr, "Error writing to log file. Wrote %zu bytes, expected %d\n", bytes_written, cb->count);
    }

    fclose(fp);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0; // Assuming 10-bit ADC
    float temperature = voltage / LM35_SENSITIVITY;
    return temperature;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer cb;
    init_circular_buffer(&cb);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping.\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Add to circular buffer
        add_to_circular_buffer(&cb, temperature);

        // Log to file
        log_circular_buffer_to_file(&cb);

        // Print to console
        printf("Temperature: %.2f °C\n", temperature);

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

