    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed hz
    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int main() {
    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (setup_i2c() < 0) {
        fprintf(stderr, "I2C setup failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (setup_spi() < 0) {
        fprintf(stderr, "SPI setup failed, exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char bh1750_data[2];
        int adc_value;
        float lux;

        // Read BH1750 light sensor
        if (i2c_read_sensor(i2c_fd, bh1750_data) == 0) {
            unsigned int raw_value = (bh1750_data[0] << 8) | bh1750_data[1];
            lux = (float)raw_value / 1.2; // BH1750 lux calculation
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor, using default value.\n");
            lux = 0.0; // Default value
        }

        // Read MCP3008 sound sensor
        adc_value = spi_read_sensor(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008 sensor, using default value.\n");
            adc_value = 0; // Default value
        }

        // Log data
        if (log_data(log_file, lux, adc_value) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

