#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_events.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, cleaning up...\n");
}

// Function to initialize GPIO
int initialize_gpio() {
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line, "flame_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_LINE, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor state
int read_flame_sensor() {
    int ret;
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

// Function to log flame events
int log_flame_event(int pin, int state) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, pin, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print alarm message
void print_alarm_message() {
    printf("ALARM: Flame detected!\n");
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    int ret;

    if (line) {
        ret = gpiod_line_release(line);
        if (ret < 0) {
            fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(-ret));
        }
    }

    if (chip) {
        ret = gpiod_chip_close(chip);
        if (ret < 0) {
            fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(-ret));
        }
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int flame_detected;
    int pull_down_enabled = 1; // Set to 0 to disable pull-down

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (flame_detected == 1) {
            print_alarm_message();
            log_flame_event(GPIO_LINE, 1);
        } else if (flame_detected == 0) {
            log_flame_event(GPIO_LINE, 0);
        }

        sleep(1); // Check every 1 second
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return EXIT_SUCCESS;
}

