#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP3008_CHANNEL 0
#define MCP4725_ADDRESS 0x62
#define DAC_VREF 3.3
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define DAC_MIN 0.0
#define DAC_MAX 3.3
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
float temperature_to_dac_voltage(float temperature);
int write_dac_value(int i2c_handle, float voltage);
void log_data(float temperature, float dac_voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008): %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value * DAC_VREF) / 1024.0;
    float temperature = (voltage - TEMP_MIN) * (TEMP_MAX - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
    return temperature;
}

// Function to convert temperature to DAC voltage
float temperature_to_dac_voltage(float temperature) {
    float voltage = (temperature / TEMP_MAX) * DAC_MAX;
    return voltage;
}

// Function to write DAC voltage to MCP4725
int write_dac_value(int i2c_handle, float voltage) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Construct I2C message (MCP4725 datasheet)
    tx_buffer[0] = 0x40; // Write DAC command
    tx_buffer[1] = (uint8_t)(voltage * 1000000.0); // Voltage in microvolts

    int result = i2cWriteDevice(i2c_handle, tx_buffer, 2);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed (write_dac_value): %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to file and stdout
void log_data(float temperature, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stdout, "%s, %.2f, %.2f\n", timestamp, temperature, dac_voltage);
    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, dac_voltage);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MCP4725_ADDRESS, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float temperature = adc_to_temperature(adc_value);
        float dac_voltage = temperature_to_dac_voltage(temperature);

        if (write_dac_value(i2c_handle, dac_voltage) != 0) {
            fprintf(stderr, "Error: Failed to write DAC value\n");
        }

        log_data(temperature, dac_voltage);

        gpioDelay(500000); // 0.5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

