#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int initialize_gpio(void);
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio(void);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate and deactivate relays sequentially
        activate_relay(RELAY1_PIN);
        deactivate_relay(RELAY1_PIN);
        gpioDelay(1000); // 1 second delay

        activate_relay(RELAY2_PIN);
        deactivate_relay(RELAY2_PIN);
        gpioDelay(1000);

        activate_relay(RELAY3_PIN);
        deactivate_relay(RELAY3_PIN);
        gpioDelay(1000);

        activate_relay(RELAY4_PIN);
        deactivate_relay(RELAY4_PIN);
        gpioDelay(1000);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Relay sequencer stopped.\n");
    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RELAY1_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RELAY2_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RELAY3_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RELAY4_PIN);
        return 1;
    }

    // Request GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to request mode for GPIO %d\n", RELAY1_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to request mode for GPIO %d\n", RELAY2_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to request mode for GPIO %d\n", RELAY3_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to request mode for GPIO %d\n", RELAY4_PIN);
        return 1;
    }

    return 0;
}

// Function to activate a relay
