#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_handle;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_rain_level(int adc_value);
void control_motor(int direction, int speed);
void log_rain_data(float rain_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value = -1; // Initialize to an error value

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed. Error code: %d\n", errno);
        return -1;
    }

    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to rain level (0-10)
float adc_to_rain_level(int adc_value) {
    // Invert the rain level based on the ADC value
    return 10.0 - (float)adc_value / 1023.0 * 10.0;
}

// Function to control the DC motor
void control_motor(int direction, int speed) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, speed);
    } else if (direction == 0) { // Reverse
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor direction.\n");
    }
}

// Function to log rain data to a file
void log_rain_data(float rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Rain Level: %.2f\n", timestamp, rain_level);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Could not open log file for writing.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motor and exiting...\n", signal);

    // Stop the motor
    control_motor(0, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int adc_value;
    float rain_level;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file for appending\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to rain level
        rain_level = adc_to_rain_level(adc_value);

        // Log rain data
        log_rain_data(rain_level);

        printf("Rain Level: %.2f\n", rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            control_motor(1, 150); // Close window
            sleep(3);
            control_motor(0, 150); // Open window
            sleep(3);
        } else {
            control_motor(0, 150); // Open window
            sleep(3);
            control_motor(1, 150); // Close window
            sleep(3);
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(0, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

