#include <sys/stat.h>
#include <sys/types.h>

// Constants
#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17"
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200 // mm

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float voltage_to_distance(float voltage);
int log_distance(float distance);
void feeder_control(float distance);
void signal_handler(int signal);

// Function to export the GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;
    int len;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;
    int len;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value (0 or 1)
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to convert voltage to distance (mm) using a linear approximation
float voltage_to_distance(float voltage) {
    return 26.0 / voltage + 6.0;
}

// Function to log the distance reading with a timestamp
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, %.2f mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to control the feeder based on distance
void feeder_control(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    int gpio_value;
    float voltage;
    float distance;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read GPIO value
        gpio_value = gpio_read(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value\n", GPIO_PIN);
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert GPIO value to voltage (0V = low, 3.3V = high)
        voltage = (float)gpio_value / 3.3; // Assuming 3.3V is the reference voltage

        // Convert voltage to distance
        distance = voltage_to_distance(voltage);

        // Log distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance\n");
        }

        // Control feeder
        feeder_control(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin
    if (gpio_unexport(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    return 0;
}

