#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"
#define PUMP_DURATION 5 // seconds

// Global variables
int spi_fd;
FILE *log_file;
bool pump_active = false;

// Function prototypes
int read_mcp3008(int channel);
float calibrate_adc(int adc_value);
void control_pump(float moisture_level);
void log_data(float moisture_level, bool pump_status);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calibrate ADC value to moisture percentage
float calibrate_adc(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    float moisture_level = 100.0 - ((float)(adc_value - 3276) / (float)(1023 - 3276)) * 100.0;
    return moisture_level;
}

// Function to control the water pump
void control_pump(float moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD && !pump_active) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        pump_active = true;
        printf("Pump turned ON\n");
    } else if (moisture_level >= MOISTURE_THRESHOLD && pump_active) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        pump_active = false;
        printf("Pump turned OFF\n");
    }
}

// Function to log data to file
void log_data(float moisture_level, bool pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f%%, %s\n", timestamp, moisture_level, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);

    // Turn off the pump
    gpioWrite(PUMP_GPIO, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpioTerminate();
        return 1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Configure SPI bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            // Log the error to the file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, ADC read error, %s\n", timestamp, (adc_value < 0) ? "ERROR" : "OK");
            fflush(log_file);
            sleep(1); // Wait before retrying
            continue;
        }

        // Calibrate ADC value to moisture percentage
        float moisture_level = calibrate_adc(adc_value);
        if (moisture_level < 0) {
            fprintf(stderr, "Error calibrating ADC value\n");
            // Log the error to the file
