int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Select the MCP3008
    gpioWrite(CS_PIN, 0);

    // Transfer data
    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading MCP3008 channel %d\n", channel);
        gpioWrite(CS_PIN, 1);
        return -1;
    }

    // Deselect the MCP3008
    gpioWrite(CS_PIN, 1);

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

