        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(config.cs_pin, PI_OUTPUT);
    gpioWrite(config.cs_pin, 1); // Deselect MCP3008 initially

    // Initialize SPI
    spi_fd = spi_init(config.spi_device, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(spi_fd, 0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample\n");
            gpioDelay(config.sample_interval_ms);
