        float voltage = (float)adc_value * (5.0 / 1023.0);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current reading
        if (log_current(log_file, current) < 0) {
            fprintf(stderr, "Error logging current reading\n");
        }

        printf("Current: %.2f A, Voltage: %.2f V\n", current, voltage);

        // Wait for the specified interval
        sleep(SAMPLING_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

