        // Determine sensor states
        int sensor1_state_debounced = sensor1_debounced == 0 ? 0 : 1;
        int sensor2_state_debounced = sensor2_debounced == 0 ? 0 : 1;

        // Update sensor states if the debounced values are different
        if (sensor1_state_debounced != sensor1_state) {
            sensor1_state = sensor1_state_debounced;
        }
        if (sensor2_state_debounced != sensor2_state) {
            sensor2_state = sensor2_state_debounced;
        }

        // Log sensor data
        log_sensor_data(sensor1_state, sensor2_state);

        // Check for alert condition
        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpioTerminate();
    return 0;
}

