#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

int spi_setup(spi_config_t config) {
    int handle = spiOpen(config.channel, config.baud, config.flags);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, handle);
        return -1;
    }
    return handle;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) {
        moisture_level = 0.0;
    }
    if (moisture_level > 100.0) {
        moisture_level = 100.0;
    }
    return moisture_level;
}

int log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_config_t spi_config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .flags = 0
    };

    spi_handle = spi_setup(spi_config);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Moisture level: %.2f%%\n", moisture_level);

        sleep(READ_DELAY);
    }

    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

