#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define TIMESTAMP_FORMAT "%Y%m%d_%H%M%S"
#define TIMESTAMP_SIZE 20

volatile sig_atomic_t program_running = 1;

// Function to generate a timestamp string
char* generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(TIMESTAMP_SIZE);
    if (timestamp == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for timestamp.");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, TIMESTAMP_SIZE, TIMESTAMP_FORMAT, timeinfo);
    return timestamp;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 1280 --height 720 --format jpeg --timeout 1000", filename);
    int status = system(command);
    if (status == -1) {
        syslog(LOG_ERR, "Failed to execute libcamera-still: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log events to syslog
void log_event(const char *event) {
    syslog(LOG_INFO, "%s", event);
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Function to read GPIO state
int read_gpio_state() {
    return gpioRead(GPIO_PIN);
}

// Function to debounce the GPIO state
int debounce_gpio(int current_state) {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    return read_gpio_state();
}

// Function to capture an image if motion is detected
void capture_image_if_motion() {
    int current_state = read_gpio_state();
    if (current_state == 1) {
        char *timestamp = generate_timestamp();
        if (timestamp != NULL) {
            char filename[64];
            snprintf(filename, sizeof(filename), "%s%s.jpg", CAPTURE_DIR, timestamp);
            free(timestamp);

            if (access(CAPTURE_DIR, F_OK) == -1) {
                // Directory doesn't exist, create it
                if (mkdir(CAPTURE_DIR, 0777) == -1) {
                    syslog(LOG_ERR, "Failed to create directory %s: %s", CAPTURE_DIR, strerror(errno));
                    return;
                }
            }

            if (capture_image(filename) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Motion detected, image captured: %s", filename);
                log_event(log_message);
            } else {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Failed to capture image: %s", filename);
                log_event(log_message);
            }
        }
    }
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_event("Motion detector started");

    // Main loop
    while (program_running) {
        int current_state = read_gpio_state();
        if (current_state == 1) {
            capture_image_if_motion();
        }
        gpioDelay(50 * 1000); // Poll every 50 ms
    }

    // Cleanup
    gpioTerminate();
    closelog();
    return 0;
}

