#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define BUFFER_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2) // 2 bytes per pixel (RGB24)
#define LOG_FILE "frame_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int fd = -1;
FILE *log_file = NULL;

// Structure to hold video buffer information
typedef struct {
    void *start;
    size_t length;
} buffer_t;

// Function prototypes
int open_device(const char *device_name);
int configure_device(int fd);
int capture_frame(int fd, buffer_t *buffers, int num_buffers);
void log_timestamp(buffer_t buffer);
void cleanup(int fd, buffer_t buffers, int num_buffers);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to configure the video device
int configure_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(int fd, buffer_t *buffers, int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Error: Not enough memory on the device\n");
        return -1;
    }

    for (int i = 0; i < num_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    // Use select() to wait for a buffer to become ready
    fd_set readfds;
    struct timeval timeout;
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 1; // Timeout after 1 second
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select()");
        cleanup(fd, buffers, num_buffers);
        return -1;
    } else if (retval == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        cleanup(fd, buffers, num_buffers);
        return -1;
    }

    // Read the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        cleanup(fd, buffers, num_buffers);
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        cleanup(fd, buffers, num_buffers);
        return -1;
    }

    return 0;
}

// Function to log the timestamp
void log_timestamp(buffer_t buffer) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_us = (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;

    fprintf(log_file, "%lld\n", timestamp_us);
    fflush(log_file);
}

// Function to clean up resources
void cleanup(int fd, buffer_t buffers, int num_buffers) {
    for (int i = 0; i < num_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
        }
    }

    if (close(fd) == -1) {
        perror("Error closing device");
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Configure the device
    if (configure_device(fd) == -1) {
        cleanup(fd, NULL, 0);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup(fd, NULL, 0);
        return EXIT_FAILURE;
    }

    // Allocate memory for buffers
    buffer_t buffers[10]; // Adjust size as needed
    for (int i = 0; i < 10; ++i) {
        buffers[i].length = 0;
        buffers[i].start = NULL;
    }

    // Main loop
    while (program_running) {
        if (capture_frame(fd, buffers, 10) == -1) {
            fprintf(stderr, "Error capturing frame, exiting.\n");
            break;
        }

        for (int i = 0; i < 10; ++i) {
            if (buffers[i].length > 0) {
                log_timestamp(buffers[i]);
            }
        }
    }

    // Clean up and exit
    cleanup(fd, buffers, 10);
    return EXIT_SUCCESS;
}

