#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG
#define IMAGE_FIELD V4L2_FIELD_NONE
#define NUM_BUFFERS 4

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;

// Structure to hold camera configuration
typedef struct {
    int fd;
    void **buffers;
    size_t buffer_count;
    size_t buffer_size;
    unsigned int *buffer_addresses;
} camera_config_t;

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, stopping streaming...\n", sig);
        stop_flag = 1;
    }
}

// Function to initialize the camera
int init_camera(camera_config_t *config) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    config->fd = fd;

    // Query device capabilities
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    enum v4l2_fmt fmt = IMAGE_FORMAT;
    enum v4l2_field field = IMAGE_FIELD;

    if (ioctl(fd, VIDIOC_ENUM_FMT, &type) < 0) {
        perror("Error enumerating formats");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_G_FMT, &fmt) < 0) {
        perror("Error getting format");
        close(fd);
        return -1;
    }

    if (!(fmt & V4L2_FMT_MJPEG)) {
        fprintf(stderr, "Error: %s is not a MJPEG camera\n", VIDEO_FMT_MJPEG_STRING);
        close(fd);
        return -1;
    }

    if (!(field & V4L2_FIELD_NONE)) {
        fprintf(stderr, "Error: %s is a field sequential camera\n", VIDEO_FMT_MJPEG_STRING);
        close(fd);
        return -1;
    }

    // Request 4 buffers
    if (ioctl(fd, VIDIOC_REQBUFS, &4) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    config->buffer_count = 4;

    // Allocate memory for buffer addresses
    config->buffer_addresses = (unsigned int *)malloc(config->buffer_count * sizeof(unsigned int));
    if (!config->buffer_addresses) {
        perror("Error allocating memory for buffer addresses");
        close(fd);
        return -1;
    }

    // Map buffers
    for (int i = 0; i < config->buffer_count; i++) {
        struct v4l2_buffer buf;
