// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// PWM parameters
#define PWM_PERIOD_US 20000 // 50 Hz (20 ms period)
#define PWM_DUTY_CYCLE_MIN 50
#define PWM_DUTY_CYCLE_MAX 100
#define DUTY_CYCLE_INCREMENT 5
#define DUTY_CYCLE_DECREMENT 5
#define DUTY_CYCLE_RANGE 100

// Global variables
static volatile int running = 1;
static int pan_position = 75;
static int tilt_position = 75;

// Function prototypes
int initialize_gpio();
int set_servo_position(int servo_pin, int position);
int read_button_state(int button_pin);
int map_duty_cycle(int position);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initializes the pigpio library and sets the GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs for PWM
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    return 0;
}

// Sets the position of a servo motor using PWM
int set_servo_position(int servo_pin, int position) {
    // Map the position (25-125) to a duty cycle (50-100)
    int duty_cycle = map_duty_cycle(position);

    // Set the PWM duty cycle
    gpioPWM(servo_pin, duty_cycle);

    printf("Servo %d set to position %d, duty cycle: %d\n", servo_pin, position, duty_cycle);
    return 0;
}

// Reads the state of a button
int read_button_state(int button_pin) {
    return gpioRead(button_pin);
}

// Maps a position (25-125) to a duty cycle (50-100)
int map_duty_cycle(int position) {
    // Clamp the position to the range [25, 125]
    if (position < 25) {
        position = 25;
    } else if (position > 125) {
        position = 125;
    }

    // Map the position to the duty cycle range
    return (int)(((float)(position - 25) / 100.0) * (PWM_DUTY_CYCLE_MAX - PWM_DUTY_CYCLE_MIN) + PWM_DUTY_CYCLE_MIN);
}

// Cleans up GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Read button states
        int tilt_up_pressed = read_button_state(TILT_UP_BUTTON);
        int tilt_down_pressed = read_button_state(TILT_DOWN_BUTTON);
        int pan_left_pressed = read_button_state(PAN_LEFT_BUTTON);
        int pan_right_pressed = read_button_state(PAN_RIGHT_BUTTON);

        // Update servo positions based on button presses
        if (tilt_up_pressed) {
            tilt_position += DUTY_CYCLE_INCREMENT;
            if (tilt_position > 125) {
                tilt_position = 125;
            }
        } else if (tilt_down_pressed) {
            tilt_position -= DUTY_CYCLE_INCREMENT;
            if (tilt_position < 25) {
                tilt_position = 25;
            }
        }

        if (pan_left_pressed) {
            pan_position += DUTY_CYCLE_INCREMENT;
            if (pan_position > 125) {
                pan_position = 125;
            }
        } else if (pan_right_pressed) {
            pan_position -= DUTY_CYCLE_INCREMENT;
            if (pan_position < 25) {
                pan_position = 25;
            }
        }

        // Set servo positions
        set_servo_position(PAN_SERVO_PIN, pan_position);
        set_servo_position(TILT_SERVO_PIN, tilt_position);

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

