#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <math.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
static int  fd = -1;
static buffer_t *buffers = NULL;
static int  num_buffers = 0;
static FILE *jpeg_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_camera(void);
int capture_frame(void);
void apply_box_blur(unsigned char *frame, unsigned char *output, int width, int height, int radius);
int save_jpeg(unsigned char *rgb24_frame, int width, int height, const char *filename);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);

    if (jpeg_file != NULL) {
        fclose(jpeg_file);
    }

    if (buffers != NULL) {
        for (int i = 0; i < num_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
    }

    if (fd != -1) {
        close(fd);
    }

    exit(0);
}

// Initialize the camera
int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_streamparm st;
    struct v4l2_streamparm_info info;

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    // Queue buffers
    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBITS, &buf) < 0) {
            perror("Error queuing buffers");
            close(fd);
            free(buffers);
            return -1;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_OUTPUT;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffers");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    // Stream on
    memset(&st, 0, sizeof(st));
