    memset(&st, 0, sizeof(st));
    st.type = V4L2_BUF_TYPE_OUTPUT;
    st.memory = V4L2_MEMORY_MMAP;
    st.index = 0;

    if (ioctl(fd, VIDIOC_STREAMON, &st) < 0) {
        perror("Error starting stream");
        close(fd);
        free(buffers);
        return -1;
    }

    // Get buffer information
    memset(&info, 0, sizeof(info));
    info.type = V4L2_BUF_TYPE_OUTPUT;
    info.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_GSTREAM_INFO, &info) < 0) {
        perror("Error getting stream info");
        close(fd);
        free(buffers);
        return -1;
    }

    num_buffers = info.bytesused / info.elemsize;
    printf("Camera initialized. Number of buffers: %d\n", num_buffers);

