#define DEVICE_PATH "/dev/video0"
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x39

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int main() {
    int fd, i2c_fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frms;
    struct v4l2_frameintervalenum frame;
    struct v4l2_queryctrl ctrl;
    unsigned int i;
    unsigned char buf[2];
    unsigned int autofocus_supported;

    signal(SIGINT, int_handler);

    if (access(DEVICE_PATH, F_OK) == -1) {
        fprintf(stderr, "Error: Device node %s does not exist.\n", DEVICE_PATH);
        return 1;
    }

    fd = open(DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open device %s: %s\n", DEVICE_PATH, strerror(errno));
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error: Could not query capabilities: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Device capabilities:\n");
    printf("  Device type: %s\n", cap.card);
    printf("  Bus info: %s\n", cap.bus_info);
    printf("  Driver: %s\n", cap.driver);
    printf("  Version: %u.%u.%u\n", cap.version_major, cap.version_minor, cap.version_subminor);
    printf("  Supported formats: %s\n", cap.capabilities);

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frms) < 0) {
        fprintf(stderr, "Error: Could not enumerate frame sizes: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("\nSupported frame sizes:\n");
    for (i = 0; i < frms.count; i++) {
        printf("  %d: %d x %d\n", i, frms.sizes[i].width, frms.sizes[i].height);
    }

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frame) < 0) {
        fprintf(stderr, "Error: Could not enumerate frame intervals: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("\nSupported frame intervals:\n");
    for (i = 0; i < frame.count; i++) {
        printf("  %d: %d ms\n", i, frame.intervals[i].interval);
    }

    if (ioctl(fd, V4L2_CID_FOCUS_AUTO, &buf[0]) < 0) {
        fprintf(stderr, "Error: Could not query autofocus control: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    autofocus_supported = (buf[0] != 0);

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        fprintf(stderr, "Error: Could not query control: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("\nAutofocus support: %s\n", autofocus_supported ? "Yes" : "No");

    if (ioctl(fd, VIDIOC_S_CTRL, (unsigned64)autofocus_supported) < 0) {
        fprintf(stderr, "Error: Could not set autofocus control: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device %s: %s\n", I2C_BUS, strerror(errno));
        close(fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        close(fd);
        return 1;
