#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define center position for servos (50% duty cycle)
#define CENTER_PULSE_WIDTH 1500 // microseconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, stopping servos and cleaning up...\n");
        program_running = 0;
    }
}

// Function to initialize servos
int initialize_servos() {
    // Set servo pins as outputs
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting PAN_SERVO_PIN as output\n");
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting TILT_SERVO_PIN as output\n");
        return -1;
    }

    // Set PWM frequency to 50 Hz
    if (gpioSetPWMfrequency(PAN_SERVO_PIN, 50) != 0) {
        fprintf(stderr, "Error setting PWM frequency for PAN_SERVO_PIN\n");
