#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 2000 // milliseconds
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define CAPTURE_DIR "motion_captures"

// Global variables
volatile sig_atomic_t program_running = 1;
int server_port = SERVER_PORT;

// Structure to hold the image data
typedef struct {
    char *filename;
    char timestamp[32];
} image_data_t;

// Function prototypes
int initialize_gpio();
int configure_gpio(int pin, int mode, int pull_up_down);
int capture_image(const char *filename);
int send_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure a GPIO pin
int configure_gpio(int pin, int mode, int pull_up_down) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", pin);
        return -1;
    }
    if (pull_up_down != 0) {
        gpioSetPullUpDown(pin, pull_up_down);
    }
    return 0;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -w %d -h %d -q %d", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
    int status = system(command);
    if (status != 0) {
        fprintf(stderr, "Failed to capture image: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to send a JSON payload using libcurl
int send_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    char json_payload[256];

    // Create JSON payload
    snprintf(json_payload, sizeof(json_payload), 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://%s:%d/upload", SERVER_IP, server_port);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        // Set Content-Type header
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers); /* free the header list */
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioTerminate();
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "p:")) != -1) {
        switch (opt) {
            case 'p':
                server_port = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-p server_port]\n", argv[0]);
                return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    if (configure_gpio(GPIO_PIN, PI_INPUT, 0) != 0) {
        cleanup();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Poll the GPIO pin
        int motion_detected = gpioRead(GPIO_PIN);

        if (motion_detected == 1) {
            printf("Motion detected!\n");

            // Capture image
            if (capture_image("motion_capture.jpg") == 0) {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp_str[32];
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%03dZ", timeinfo);

                // Send JSON payload
                if (send_json_payload("motion_capture.jpg", timestamp_str, 1, GPIO_PIN) != 0) {
                    fprintf(stderr, "Failed to send JSON payload\n");
                }
            } else {
                fprintf(stderr, "Failed to capture image\n");
            }

            // Debounce
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
        }

        gpioDelay(100 * 1000); // Poll every 100 milliseconds
    }

    cleanup();
    return 0;
}

