#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define FIELD_NONE 0
#define FRAME_RATE 30

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
static int  fd = -1;
static buffer_t buffer;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int vid_ioctl(int fd, int request, void *arg);
int vid_ioctl_set_format(int fd, int width, int height, int pix_format);
int vid_ioctl_set_field(int fd, int field);
int vid_ioctl_start(int fd);
int vid_ioctl_stop(int fd);
int vid_ioctl_dequeue(int fd, buffer_t *buf);
int vid_ioctl_queue(int fd, buffer_t *buf);
int vid_ioctl_request_buffers(int fd, int n_buffers, buffer_t *buffers);
int vid_ioctl_dequeue_buffers(int fd, buffer_t *buffers, int n_buffers);
int vid_ioctl_prepare(int fd);
int vid_ioctl_rele(int fd, buffer_t buffer);
int vid_ioctl_release(int fd, buffer_t buffer);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, exiting...\n", sig);
        keep_running = 0;
    }
}

// V4L2 ioctl wrapper
int vid_ioctl(int fd, int request, void *arg) {
    int ret;
    void *ptr;

    switch (request) {
        case V4L2_BUF_TYPE_VIDEO_CAPTURE:
            ptr = (void *)arg;
            ret = ioctl(fd, VIDIOC_DQBUF, ptr);
            break;
        case V4L2_BUF_TYPE_VIDEO_CAPTURE:
            ptr = (void *)arg;
            ret = ioctl(fd, VIDIOC_QBUF, ptr);
            break;
        case V4L2_BUF_TYPE_VIDEO_CAPTURE:
            ptr = (void *)arg;
            ret = ioctl(fd, VIDIOC_STREAMON, ptr);
            break;
        case V4L2_BUF_TYPE_VIDEO_CAPTURE:
            ptr = (void *)arg;
            ret = ioctl(fd, VIDIOC_STREAMOFF, ptr);
            break;
        default:
            fprintf(stderr, "Error: Invalid ioctl request\n");
            return -1;
    }
    return ret;
}

// Set camera format
int vid_ioctl_set_format(int fd, int width, int height, int pix_format) {
    int ret;
    unsigned char buf[10];

    ret = vid_ioctl(fd, VIDIOC_S_FMT, &width);
    if (ret < 0) return ret;
    ret = vid_ioctl(fd, VIDIOC_S_FMT, &height);
    if (ret < 0) return ret;
    ret = vid_ioctl(fd, VIDIOC_S_PARM, &pix_format);
    if (ret < 0) return ret;

    return 0;
}

// Set field
int vid_ioctl_set_field(int fd, int field) {
    int ret;
    unsigned char buf[2];

    ret = vid_ioctl(fd, V4L2_SW_FIELD_NONE, &field);
    if (ret < 0) return ret;

    return 0;
}

// Start streaming
int vid_ioctl_start(int fd) {
    int ret;
    unsigned char buf[10];

    ret = vid_ioctl(fd, V4L2_STREAMON, &buf);
    if (ret < 0) return ret;

    return 0;
}

// Stop streaming
int vid_ioctl_stop(int fd) {
    int ret;
    unsigned char buf[10];

    ret = vid_ioctl(fd, V4L2_STREAMOFF, &buf);
    if (ret < 0) return ret;

    return 0;
}

// Dequeue buffer
int vid_ioctl_dequeue(int fd, buffer_t *buf) {
    int ret;
    unsigned char buf_type[10];
    unsigned char buf_type_val = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    ret = vid_ioctl(fd, VIDIOC_DQBUF, buf_type);
    if (ret < 0) return ret;

    buf->length = buf->length; // Copy the length
    buf->start = madvise(buf->start, buf->length, MADV_FREE);
    if (buf->start == MAP_FAILED) {
        perror("madvise");
        return -1;
    }

    return 0;
}

// Queue buffer
int vid_ioctl_queue(int fd, buffer_t *buf) {
    int ret;
    unsigned char buf_type[10];
    unsigned char buf_type_val = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    ret = vid_ioctl(fd, VIDIOC_QBUF, buf_type);
    if (ret < 0) return ret;

    return 0;
}

// Request buffers
int vid_ioctl_request_buffers(int fd, int n_buffers, buffer_t *buffers) {
    int ret;
    unsigned char buf_type[10];
    unsigned char buf_type_val = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    ret = vid_ioctl(fd, V4L2_BUF_TYPE_VIDEO_CAPTURE, &buf_type_val);
    if (ret < 0) return ret;

    for (int i = 0; i < n_buffers; i++) {
        ret = vid_ioctl(fd, V4L2_BUF_TYPE_VIDEO_CAPTURE, &buf_type);
        if (ret < 0) return ret;
        buffers[i].length = 0; // Initialize length
        buffers[i].start = NULL; // Initialize start
    }

    return 0;
}

// Dequeue buffers
int vid_ioctl_dequeue_buffers(int fd, buffer_t *buffers, int n_buffers) {
    int ret;
    unsigned char buf_type[10];
    unsigned char buf_type_val = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    ret = vid_ioctl(fd, V4L2_BUF_TYPE_VIDEO_CAPTURE, &buf_type_val);
    if (ret < 0) return ret;

    for (int i = 0; i < n_buffers; i++) {
        ret = vid_ioctl(fd, V4L2_BUF_TYPE_VIDEO_CAPTURE, &buf_type);
        if (ret < 0) return ret;
        buffers[i].length = 0; // Initialize length
        buffers[i].start = NULL; // Initialize start
    }

    return 0;
}

// Prepare device
int vid_ioctl_prepare(int fd) {
    int ret;
    unsigned char buf[10];

    ret = vid_ioctl(fd, V4L2_PREPARE, &buf);
    if (ret < 0) return ret;

    return 0;
}

// Release device
int vid_ioctl_release(int fd, buffer_t buffer) {
    int ret;
    unsigned char buf[10];

    ret = vid_ioctl(fd, V4L2_RELE, &buf);
    if (ret < 0) return ret;

    return 0;
}

// Release buffer
int vid_ioctl_rele(int fd, buffer_t buffer) {
    int ret;
    unsigned char buf[10];

    ret = vid_ioctl(fd, V4L2_RELE, &buf);
    if (ret < 0) return ret;

    return 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    // Query capabilities
    struct v4l2_capability cap;
    if (vid_ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set format
    if (vid_ioctl_set_format(fd, WIDTH, HEIGHT, PIXEL_FORMAT) < 0) {
        fprintf(stderr, "Error setting format\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set field
    if (vid_ioctl_set_field(fd, FIELD_NONE) < 0) {
        fprintf(stderr, "Error setting field\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (vid_ioctl_start(fd) < 0) {
        fprintf(stderr, "Error starting streaming\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (vid_ioctl_request_buffers(fd, 1, &buffer) < 0) {
        fprintf(stderr, "Error requesting buffers\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Prepare device
    if (vid_ioctl_prepare(fd) < 0) {
        fprintf(stderr, "Error preparing device\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for buffer
    buffer.length = buffer.length; // Copy the length
    buffer.start = madvise(buffer.start, buffer.length, MADV_WONCE);
    if (buffer.start == MAP_FAILED) {
        perror("madvise");
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Select timeout
        fd_set readfds;
        struct timeval tv;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);
        tv.tv_sec = 2; // 2 seconds
        tv.tv_usec = 0;

        int retval = select(fd + 1, &readfds, NULL, NULL, &tv);

        if (retval == -1) {
            perror("select");
            break;
        } else if (retval) {
            // Frame is ready
            if (vid_ioctl_dequeue(&buffer) < 0) {
                fprintf(stderr, "Error dequeueing buffer\n");
                break;
            }

            // Verify frame size
            if (buffer.length != WIDTH * HEIGHT * 2) {
                fprintf(stderr, "Error: Frame size mismatch. Expected %d, got %d\n", WIDTH * HEIGHT * 2, buffer.length);
                break;
            }

            // Crop the frame
            int y_start = 100;
            int y_end = 100 + 200;
            int u_start = 0;
            int u_end = 0;
            int v_start = 50;
            int v_end = 50 + 150;

            for (int y = y_start; y < y_end; y++) {
                for (int u = u_start; u < u_end; u += 2) {
                    for (int v = v_start; v < v_end; v += 2) {
                        // YUYV format: Y0, U, Y1, V
                        unsigned char *y0 = &buffer.start[y * WIDTH * 2 + u];
                        unsigned char *y1 = &buffer.start[y * WIDTH * 2 + u + 1];
                        unsigned char *v = &buffer.start[y * WIDTH * 2 + u + 2];
                        unsigned char *u = &buffer.start[y * WIDTH * 2 + u + 3];

                        // Copy YUYV macroblock
                        memcpy(&buffer.start[y * WIDTH * 2 + u], y0, 2);
                        memcpy(&buffer.start[y * WIDTH * 2 + u + 1], y1, 2);
                        memcpy(&buffer.start[y * WIDTH * 2 + u + 3], v, 2);
                    }
                }
            }

            // Save cropped frame to file
            FILE *fp = fopen("cropped.yuv", "wb");
            if (fp == NULL) {
                perror("Error opening cropped.yuv");
                break;
            }

            fwrite(&buffer.start, 1, buffer.length, fp);
            fclose(fp);

            printf("Cropped frame saved to cropped.yuv\n");
        } else {
            // Timeout
            printf("Timeout waiting for frame\n");
        }
    }

    // Stop streaming
    if (vid_ioctl_stop(fd) < 0) {
        fprintf(stderr, "Error stopping streaming\n");
    }

    // Release buffers
    for (int i = 0; i < 1; i++) {
        vid_ioctl_rele(fd, buffer);
    }

    // Unmap buffers
    munmap(buffer.start, buffer.length);

    // Close device
    close(fd);

    printf("Exiting cleanly\n");
    return EXIT_SUCCESS;
}

