#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define PWM range (microseconds)
#define PWM_MIN 500
#define PWM_MAX 2500

// Define angle increment
#define ANGLE_INCREMENT 5

// Define initial angles
#define INITIAL_PAN_ANGLE 90
#define INITIAL_TILT_ANGLE 90

// Define delay between commands (milliseconds)
#define DELAY_MS 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int gpio, int angle);
int handle_input(int key);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold servo data
typedef struct {
    int pan_angle;
    int tilt_angle;
} ServoData;

ServoData current_servo_data = {INITIAL_PAN_ANGLE, INITIAL_TILT_ANGLE};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        int key = handle_input(0); // Assuming 0 is the key input

        if (key != -1) {
            if (key == 4) { // Up arrow
                current_servo_data.pan_angle -= ANGLE_INCREMENT;
                if (current_servo_data.pan_angle < 0) {
                    current_servo_data.pan_angle = 0;
                }
                set_servo_angle(PAN_GPIO, current_servo_data.pan_angle);
            } else if (key == 6) { // Down arrow
                current_servo_data.pan_angle += ANGLE_INCREMENT;
                if (current_servo_data.pan_angle > 180) {
                    current_servo_data.pan_angle = 180;
                }
                set_servo_angle(PAN_GPIO, current_servo_data.pan_angle);
            } else if (key == 8) { // Left arrow
                current_servo_data.tilt_angle -= ANGLE_INCREMENT;
                if (current_servo_data.tilt_angle < 0) {
                    current_servo_data.tilt_angle = 0;
                }
                set_servo_angle(TILT_GPIO, current_servo_data.tilt_angle);
            } else if (key == 2) { // Right arrow
                current_servo_data.tilt_angle += ANGLE_INCREMENT;
                if (current_servo_data.tilt_angle > 180) {
                    current_servo_data.tilt_angle = 180;
                }
                set_servo_angle(TILT_GPIO, current_servo_data.tilt_angle);
            } else if (key == 10) { // q
                program_running = 0; // Exit loop on 'q' input
                set_servo_angle(PAN_GPIO, current_servo_data.pan_angle);
                set_servo_angle(TILT_GPIO, current_servo_data.tilt_angle);
                cleanup_gpio();
                return 0;
            }
        }

        gpioDelay(DELAY_MS * 1000); // Delay for 100ms
    }

    return 0;
}

// Function to initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    return 0;
}

// Function to set servo angle
int set_servo_angle(int gpio, int angle) {
    // Validate angle
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return 1;
    }

    // Calculate pulse width
    int pulse_width = PWM_MIN + (int)(((float)angle / 180.0) * (PWM_MAX - PWM_MIN));

    // Set PWM duty cycle
    gpioPWM(gpio, pulse_width);

    return 0;
}

// Function to handle user input
int handle_input(int key) {
    switch (key) {
        case 4: // Up arrow
            return 4;
        case 6: // Down arrow
            return 6;
        case 8: // Left arrow
            return 8;
        case 2: // Right arrow
            return 2;
        case 10: // 'q'
            return 10;
        default:
            return -1; // Invalid key
    }
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

