        SSD1306_SET_DISPLAY_OFFSET, 0x00,   // 0x00
        SSD1306_SET_START_LINE, 0x00,       // 0x00
        SSD1306_CHARGE_PUMP, 0x14,       // 0x14
        SSD1306_MEMORY_MODE, 0x00,       // 0x00
        SSD1306_COLUMN_ADDR, 0x00,       // 0x00
        SSD1306_PAGE_ADDR, 0x00,       // 0x00
        SSD1306_COM_SCAN_DIR, 0x00,       // 0x00
        SSD1306_COM_PATTERNS, 0x12,       // 0x12
        SSD1306_SET_MEMORY_MODE, 0x00,       // 0x00
        SSD1306_SET_DISPLAY_CONFIG, 0x00,   // 0x00
        SSD1306_DISPLAY_ALLON, 0x04,       // 0x04
        SSD1306_NORMAL_DISPLAY, 0x00,       // 0x00
        SSD1306_DISPLAY_ALLON_RESUME, 0x00,   // 0x00
        SSD1306_SET_CONTRAST, 0xCF,       // 0xCF
        SSD1306_SET_PRECHARGE, 0xF1,       // 0xF1
        SSD1306_SET_VCOM_DETECT, 0x40,     // 0x40
        SSD1306_SET_VCOM_DESELECT, 0x10,    // 0x10
        SSD1306_DISPLAY_ALLON, 0x04,       // 0x04
        SSD1306_NORMAL_DISPLAY, 0x00,       // 0x00
        SSD1306_DISPLAY_OFF, 0xAE         // 0xAE
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (write_i2c_device(i2c_fd, 0, &init_commands[i], 1) != 0) {
            fprintf(stderr, "Error: Failed to write initialization command %d\n", i);
            oled_clear();
            exit(1);
        }
    }
    oled_clear();
}

// Function to clear the OLED display
void oled_clear() {
    for (int i = 0; i < 8 * SSD1306_WIDTH * SSD1306_HEIGHT / 8; i++) {
        write_i2c_device(i2c_fd, 0, 0x00, 1);
    }
}

// Function to draw a pixel on the OLED display
void oled_draw_pixel(int x, int y, unsigned char color) {
    if (x < 0 || x >= SSD1306_WIDTH || y < 0 || y >= SSD1306_HEIGHT) return;

    int page = y / 8;
    int bit = y % 8;
    int page_addr = 0x40 + page;
    int bit_addr = 0x80 + bit;

    unsigned char page_value = 0;
    if (color) {
        page_value |= (1 << bit);
    }

    write_i2c_device(i2c_fd, 0, &page_value, 1);
    write_i2c_device(i2c_fd, 0, &bit_addr, 1);
}

// Function to draw a string on the OLED display
void oled_draw_string(int x, int y, const char *str) {
    int i = 0;
    while (str[i] != '\0') {
        unsigned char c = str[i];
        if (c >= ' ' && c <= '~') {
            // Find the font index for the character
            int font_index = c - ' ';
            if (font_index < 0 || font_index >= 128) {
                fprintf(stderr, "Error: Invalid character '%c'\n", c);
                oled_clear();
                return;
            }

            // Calculate the starting position for the character
            int page = y / 8;
            int bit = y % 8;
            int page_addr = 0x40 + page;
            int bit_addr = 0x80 + bit;

            // Set the page and bit address
            write_i2c_device(i2c_fd, 0, page_addr, 1);
            write_i2c_device(i2c_fd, 0, bit_addr, 1);

            // Draw the character
            for (int j = 0; j < 5; j++) {
                oled_draw_pixel(x + j, y, font[font_index][j]);
            }
        } else {
            // Draw a space if the character is not a printable character
            oled_draw_pixel(x, y, 0);
        }
        x += 6; // Move to the next character position
        i++;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read OLED address from EEPROM
    unsigned char oled_address_data[2];
    if (read_i2c_device("/dev/i2c-1", 0x00, oled_address_data, 2) != 0) {
        fprintf(stderr, "Error: Could not read OLED address from EEPROM\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    oled_address = oled_address_data[1] << 8 | oled_address_data[0];

    // Initialize the OLED display
    oled_init();

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read CPU temperature
        int temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error: Could not read CPU temperature. Displaying error string.\n");
            oled_draw_string(0, 0, "TEMP ERROR");
        } else {
            // Read CPU usage
            int usage = read_cpu_usage();
            if (usage == -1) {
                fprintf(stderr, "Error: Could not read CPU usage. Displaying error string.\n");
                oled_draw_string(0, 0, "USAGE ERROR");
            } else {
                // Display temperature and usage on the OLED
                char temp_str[10];
                char usage_str[10];

                snprintf(temp_str, sizeof(temp_str), "Temp: %d C", temp);
                snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", usage);

                oled_draw_string(0, 0, temp_str);
                oled_draw_string(0, 16, usage_str);
            }
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // This part is never reached due to the infinite loop, but included for completeness
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

