#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pins for the water flow sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 22

// Define the I2C address for the LCD
#define LCD_ADDR 0x27

// Define the LCD command to turn on the LCD (optional, depends on your LCD module)
#define LCD_ENABLE_PIN 25 // Example: GPIO pin for LCD enable

// Define the number of pulses per liter for the YF-S201 sensor
#define PULSES_PER_LITER 450

// Global variables for pulse counts and total volume
volatile int sensor1_pulse_count = 0;
volatile int sensor2_pulse_count = 0;
volatile int sensor3_pulse_count = 0;
float total_volume = 0.0;

// Global variable for the I2C handle
int i2c_handle = -1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulse_count);
void update_lcd(float flow_rate);
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Disable the LCD enable pin
    gpioWrite(LCD_ENABLE_PIN, 1); // Assuming 1 enables the LCD

    // Close the I2C connection if it's open
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to calculate the flow rate in liters per minute
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / PULSES_PER_LITER / 60.0;
}

// Function to update the LCD display
void update_lcd(float flow_rate) {
    char buffer[20];

    // Format the data to be displayed on the LCD
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f LPM, Total Volume: %.2f L", flow_rate, total_volume);

    // Send the data to the LCD via I2C
    int result = i2cWriteDevice(i2c_handle, buffer, strlen(buffer));
    if (result != strlen(buffer)) {
        fprintf(stderr, "Error writing to LCD: %d\n", result);
    } else {
        printf("%s\n", buffer);
    }
}

// Interrupt handler for the water flow sensors
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        if (gpio == SENSOR1_GPIO) {
            sensor1_pulse_count++;
        } else if (gpio == SENSOR2_GPIO) {
            sensor2_pulse_count++;
        } else if (gpio == SENSOR3_GPIO) {
            sensor3_pulse_count++;
        }
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Set up interrupt handlers for the sensor pins
    gpioSetISRFuncEx(SENSOR1_GPIO, RISING_EDGE, 0, pulse_counter, NULL);
    gpioSetISRFuncEx(SENSOR2_GPIO, RISING_EDGE, 0, pulse_counter, NULL);
    gpioSetISRFuncEx(SENSOR3_GPIO, RISING_EDGE, 0, pulse_counter, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate the flow rates for each sensor
        float flow_rate1 = calculate_flow_rate(sensor1_pulse_count);
        float flow_rate2 = calculate_flow_rate(sensor2_pulse_count);
        float flow_rate3 = calculate_flow_rate(sensor3_pulse_count);

        // Update the total volume
        total_volume += (flow_rate1 + flow_rate2 + flow_rate3) * 60.0; // Convert LPM to L/min * 60 seconds

        // Print the current flow rates and total volume to the console
        printf("Sensor 1: %.2f LPM, Sensor 2: %.2f LPM, Sensor 3: %.2f LPM, Total Volume: %.2f L\n",
               flow_rate1, flow_rate2, flow_rate3, total_volume);

        // Update the LCD display
        update_lcd(flow_rate1);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

