#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD1602_I2C_ADDR 0x27
#define LCD_WIDTH 160
#define LCD_HEIGHT 20
#define PULSES_PER_LITER 7.5
#define PULSES_THRESHOLD 1000 // Pulses per second
#define SENSOR_PRESENT_TIMEOUT 60 // Seconds

// Global variables
static volatile int pulse_count = 0;
static volatile int sensor_present = 0;
static int lcd_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulses);
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int col, int row);
void lcd_write_string(const char *str);
void log_message(const char *message);
void signal_handler(int signal);
void sensor_check();

// Pulse counter function
void pulse_counter(int gpio, int level, uint32_t tick)
{
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate
double calculate_flow_rate(int pulses)
{
    return (double)pulses / PULSES_PER_LITER / (1.0 / 1.0) / 60.0; // L/min
}

// LCD initialization function
void lcd_init()
{
    // Initialization sequence (adjust as needed for your LCD1602)
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x33); // Function set: 8-bit mode, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x32); // Function set: 8-bit mode, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x06); // Display on, cursor off, blink off
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x0C); // Display on, cursor off, blink off
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x28); // Data length, number of lines, font size
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    delay(5); // Short delay after clear display
}

// Function to clear the LCD
void lcd_clear()
{
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01);
    delay(2); // Clear display command requires 2ms
}

// Function to set the cursor position
void lcd_set_cursor(int col, int row)
{
    int address;
    if (col == 0) {
        address = 0x80 + row;
    } else {
        address = 0xC0 + row;
    }
    wiringPiI2CWriteReg8(lcd_fd, 0x00, address);
}

// Function to write a string to the LCD
void lcd_write_string(const char *str)
{
    int i = 0;
    while (str[i] != 0) {
        wiringPiI2CWriteReg8(lcd_fd, 0x00, str[i]);
        i++;
    }
}

// Function to log messages with timestamps
void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    terminate = 1;
    log_message("Received signal, shutting down...");
}

// Function to check sensor presence
void sensor_check()
{
    static int last_pulse_count = 0;
    static time_t last_pulse_time = 0;
    time_t current_time = time(NULL);

    if (pulse_count > last_pulse_count * 10) { // Check for significant increase in pulses
        if (current_time - last_pulse_time > SENSOR_PRESENT_TIMEOUT) {
            sensor_present = 1;
            log_message("Sensor detected!");
        }
    } else {
        sensor_present = 0;
        log_message("Sensor absent for extended period.");
    }

    last_pulse_count = pulse_count;
    last_pulse_time = current_time;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi I2C
    lcd_fd = wiringPiI2CSetup(LCD1602_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();
    lcd_clear();

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO mode and alert
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_counter);

    // Main loop
    while (!terminate) {
        sensor_check();

        if (sensor_present) {
            // Calculate flow rate
            int pulses = pulse_count;
            pulse_count = 0; // Reset pulse count for the next interval

            double flow_rate = calculate_flow_rate(pulses);

            // Display flow rate on LCD
            char flow_rate_str[20];
            snprintf(flow_rate_str, sizeof(flow_rate_str), "Flow Rate: %.2f L/min", flow_rate);
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_write_string(flow_rate_str);

            // Log flow rate
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Flow Rate: %.2f L/min", flow_rate);
            log_message(log_message_buffer);
        } else {
            log_message("No sensor detected, flow rate not available.");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);
    return 0;
}

