    lcd_init();
    lcd_clear();

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO mode and alert
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_counter);

    // Main loop
    while (!terminate) {
        sensor_check();

        if (sensor_present) {
            // Calculate flow rate
            int pulses = pulse_count;
            pulse_count = 0; // Reset pulse count for the next interval

            double flow_rate = calculate_flow_rate(pulses);

            // Display flow rate on LCD
            char flow_rate_str[20];
            snprintf(flow_rate_str, sizeof(flow_rate_str), "Flow Rate: %.2f L/min", flow_rate);
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_write_string(flow_rate_str);

            // Log flow rate
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Flow Rate: %.2f L/min", flow_rate);
