#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COLUMN_PINS {14, 15, 18, 23, 24, 25, 8, 7}

// Define the number of rows and columns
#define NUM_ROWS 8
#define NUM_COLS 8

// Define the delay between columns (in milliseconds)
#define COLUMN_DELAY 150

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set row pins as outputs
    for (size_t i = 0; i < NUM_ROWS; ++i) {
        gpioSetMode(ROW_PINS[i], PI_OUTPUT);
        gpioWrite(ROW_PINS[i], 1); // Set row pins HIGH initially
    }

    // Set column pins as outputs
    for (size_t i = 0; i < NUM_COLS; ++i) {
        gpioSetMode(COLUMN_PINS[i], PI_OUTPUT);
        gpioWrite(COLUMN_PINS[i], 1); // Set column pins HIGH initially
    }

    return 0;
}

// Function to clear the matrix
void clear_matrix() {
    for (size_t i = 0; i < NUM_ROWS; ++i) {
        gpioWrite(ROW_PINS[i], 1); // Set row pins HIGH
    }
    for (size_t i = 0; i < NUM_COLS; ++i) {
        gpioWrite(COLUMN_PINS[i], 1); // Set column pins HIGH
    }
}

// Function to light up a column
void light_up_column(int column) {
    gpioWrite(COLUMN_PINS[column], 0); // Set column pin LOW
    for (size_t i = 0; i < NUM_ROWS; ++i) {
        gpioWrite(ROW_PINS[i], 1); // Set row pin HIGH
    }
}

// Function to animate the matrix
void animate_matrix() {
    for (int col = 0; col < NUM_COLS && program_running; ++col) {
        light_up_column(col);
        gpioDelay(COLUMN_DELAY * 1000); // Delay in microseconds
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Matrix animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        animate_matrix();
    }

    // Clean up GPIO before exiting
    clear_matrix();
    gpioTerminate();

    fprintf(stderr, "Matrix animation stopped.\n");

    return 0;
}

