#include <errno.h>

// Define the I2C address of the MLX75031 sensor
#define MLX75031_I2C_ADDR 0x4C

// Define the register address for the distance data
#define DISTANCE_REG 0x0D

// Define the log file name
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} config_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int bus, int addr);
int read_distance(int handle);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C connection
int open_i2c_connection(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read the distance from the sensor
int read_distance(int handle) {
    char reg_addr = DISTANCE_REG;
    char buffer[2];
    int distance;

    // Write the register address
    if (i2cWriteByteData(handle, reg_addr, reg_addr) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read the distance data (2 bytes)
    if (i2cReadI2CBlockData(handle, reg_addr, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

