    int distance;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the I2C connection
    i2c_handle = open_i2c_connection(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_data(log_file, distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
            // Attempt to re-open the I2C connection
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_connection(config.i2c_bus, config.i2c_address);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-opening fails
            }
        }
        gpioDelay(100); // Sample every 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

