#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define SI1145_PART_ID 0x00
#define SI1145_ALS_VIS_DATA0 0x22
#define SI1145_ALS_VIS_DATA1 0x23
#define SI1145_ALS_IR_DATA0 0x24
#define SI1145_ALS_IR_DATA1 0x25
#define SI1145_PS_LED21_SELECT 0x13
#define SI1145_MEAS_RATE0 0x08
#define SI1145_MEAS_RATE1 0x09
#define SI1145_COMMAND 0x18
#define SI1145_RESET 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int si1145_read_data(uint16_t *als_vis, uint16_t *als_ir, uint16_t *prox);
void log_data(uint16_t als_vis, uint16_t als_ir, uint16_t prox);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1145: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rates
    if (i2cWriteByteData(i2c_handle, SI1145_MEAS_RATE0, 0x07) < 0) { // Example: 7 samples per second
        fprintf(stderr, "Error writing to MEAS_RATE0: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1145_MEAS_RATE1, 0x00) < 0) { // Example: 0 samples per second
        fprintf(stderr, "Error writing to MEAS_RATE1: %s\n", strerror(errno));
        return -1;
    }

    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Si1145 sensor initialized successfully.\n");
    return 0;
}

// Read data from the Si1145 sensor
int si1145_read_data(uint16_t *als_vis, uint16_t *als_ir, uint16_t *prox) {
    int result;

    result = i2cReadWordData(i2c_handle, SI1145_ALS_VIS_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0: %s\n", strerror(errno));
        return -1;
    }
    *als_vis = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, SI1145_ALS_VIS_DATA1);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1: %s\n", strerror(errno));
        return -1;
    }
    *als_ir = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, SI1145_PS_LED21_SELECT);
    if (result < 0) {
        fprintf(stderr, "Error reading PS_LED21_SELECT: %s\n", strerror(errno));
        return -1;
    }
    *prox = (uint16_t)result;

    return 0;
}

// Log data to file
void log_data(uint16_t als_vis, uint16_t als_ir, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u\n", timestamp, als_vis, als_ir, prox);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t als_vis, als_ir, prox;
    while (!terminate) {
        if (si1145_read_data(&als_vis, &als_ir, &prox) == 0) {
            log_data(als_vis, als_ir, prox);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        gpioDelay(500); // Sample every 500 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

