#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define PART_ID 0x00
#define HW_KEY 0x07
#define CH_LIST 0x4F
#define COMMAND 0x30
#define PS1_DATA_LSB 0x18
#define PS1_DATA_MSB 0x19
#define ALS_VIS_DATA_LSB 0x22
#define ALS_VIS_DATA_MSB 0x23

// Measurement configuration
#define MEASUREMENT_RATE_PS 0x07
#define MEASUREMENT_RATE_ALS 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_si1145_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    int status;

    // Verify PART_ID register
    int part_id = i2cReadByteData(i2c_handle, PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY register
    status = i2cWriteByteData(i2c_handle, HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    // Set channel list
    status = i2cWriteByteData(i2c_handle, CH_LIST, 0x03); // Enable PS1 and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing CH_LIST: %s\n", strerror(errno));
        return -1;
    }

    // Configure measurement rates
    status = i2cWriteByteData(i2c_handle, COMMAND, MEASUREMENT_RATE_PS | (MEASUREMENT_RATE_ALS << 1));
    if (status < 0) {
        fprintf(stderr, "Error writing COMMAND: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int status;

    // Read proximity data
    int prox_lsb = i2cReadByteData(i2c_handle, PS1_DATA_LSB);
    int prox_msb = i2cReadByteData(i2c_handle, PS1_DATA_MSB);
    if (prox_lsb < 0 || prox_msb < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    *proximity = (prox_msb << 8) | prox_lsb;

    // Read ambient light data
    int als_lsb = i2cReadByteData(i2c_handle, ALS_VIS_DATA_LSB);
    int als_msb = i2cReadByteData(i2c_handle, ALS_VIS_DATA_MSB);
    if (als_lsb < 0 || als_msb < 0) {
        fprintf(stderr, "Error reading ambient light data: %s\n", strerror(errno));
        return -1;
    }
    *ambient_light = (als_msb << 8) | als_lsb;

    return 0;
}

// Function to log the sensor data to a CSV file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Flush the file to ensure data is written immediately
}

int main() {
    int proximity, ambient_light;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0); // I2C bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_si1145_data(&proximity, &ambient_light);
        if (status == 0) {
            // Log the data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function in milliseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

