#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000        // 30 ms timeout
#define MIN_DISTANCE 15.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    double distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(uint32_t pulse_width);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for ECHO_PIN
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for ECHO_PIN
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static int echo_rising = 0;
    static int echo_falling = 0;
    static int echo_timeout = 0;

    if (level == 1) {
        echo_rising = 1;
        start_tick = tick;
    } else if (level == 0) {
        echo_falling = 1;
    }

    if (echo_rising && !echo_falling) {
        echo_timeout = 0; // Reset timeout if rising edge is valid
    } else if (echo_falling && !echo_rising) {
        echo_timeout++;
        if (echo_timeout > TIMEOUT_US) {
            fprintf(stderr, "Echo timeout on GPIO %d\n", gpio);
            echo_timeout = 0; // Reset timeout after timeout
        }
    } else if (echo_rising && echo_falling) {
        echo_timeout = 0; // Reset timeout if both edges are valid
    }

    if (echo_timeout > TIMEOUT_US) {
        fprintf(stderr, "Echo timeout on GPIO %d\n", gpio);
        echo_timeout = 0; // Reset timeout after timeout
    }
}

// Function to calculate distance from pulse width
double calculate_distance(uint32_t pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Error: %s, Timeout: %d\n",
            timestamp, data.distance, (data.distance < MIN_DISTANCE || data.distance > MAX_DISTANCE) ? "Invalid" : "Valid", echo_timeout);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Plant watering reminder system started. Logging to %s\n", LOG_FILE);

    while (running) {
        sensor_data_t data;
        data.timestamp = time(NULL);

        trigger_sensor();

        gpioDelay(50); // Wait for echo

        uint32_t pulse_width = 0;
        if (echo_rising) {
            pulse_width = gpioTick() - start_tick;
        }

        data.distance = calculate_distance(pulse_width);

        if (data.distance < MIN_DISTANCE || data.distance > MAX_DISTANCE) {
            data.distance = -1.0; // Indicate invalid reading
        }

        log_data(data);

        if (data.distance >= 0 && data.distance < 15) {
            fprintf(log_file, "%s, Time to water the plant!\n", __TIME__);
            fflush(log_file);
        }

        sleep(60); // Poll every 60 seconds
    }

    cleanup();
    return 0;
}

