#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define MEAS_RATE0 0x08
#define COMMAND 0x47
#define PS_DATA0 0x24
#define PS_DATA1 0x25
#define BPM_THRESHOLD 60
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int init_sensor();
int read_register(int reg);
int write_register(int reg, int value);
int read_proximity_data(uint16_t *proximity);
float calculate_bpm(uint16_t proximity);
int log_data(float bpm);
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    int meas_rate;
    int bpm_threshold;
} sensor_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1182 sensor
int init_sensor() {
    // Check PART_ID register
    int part_id = read_register(0x00);
    if (part_id != 0x5A) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02X). Expected 0x5A.\n", part_id);
        return -1;
    }

    // Configure MEAS_RATE0 register
    if (write_register(MEAS_RATE0, 0x0A) != 0) {
        fprintf(stderr, "Error writing to MEAS_RATE0 register.\n");
        return -1;
    }

    // Reset/Start the sensor
    if (write_register(COMMAND, 0x01) != 0) {
        fprintf(stderr, "Error writing to COMMAND register.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset/start to complete

    return 0;
}

// Function to read a register from the sensor
int read_register(int reg) {
    int value = i2cReadByteData(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a register to the sensor
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read proximity data from the sensor
int read_proximity_data(uint16_t *proximity) {
    int data0 = read_register(PS_DATA0);
    int data1 = read_register(PS_DATA1);

    if (data0 < 0 || data1 < 0) {
        fprintf(stderr, "Error reading proximity data.\n");
        return -1;
    }

    *proximity = (data1 << 8) | data0; // Combine little-endian
    return 0;
}

// Function to calculate BPM from proximity data (placeholder)
float calculate_bpm(uint16_t proximity) {
    // This is a placeholder.  A real implementation would
    // analyze the proximity data to detect heartbeats.
    // For example, it might look for a rising edge followed by a falling edge.
    // It would also need to filter out noise and spurious readings.
    // This example just returns a constant BPM.
    return 70.0; // Placeholder BPM
}

// Function to log data to a CSV file
int log_data(float bpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file != NULL) {
        fprintf(csv_file, "%s,%.2f\n", timestamp, bpm);
        fflush(csv_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: CSV file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("heartrate.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t proximity;
    float bpm;
    while (running) {
        if (read_proximity_data(&proximity) == 0) {
            bpm = calculate_bpm(proximity);

            if (log_data(bpm) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            if (bpm > BPM_THRESHOLD) {
                printf("BPM: %.2f\n", bpm);
            }
        } else {
            fprintf(stderr, "Error reading proximity data, skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

