int read_proximity_data(uint16_t *proximity) {
    int data0 = read_register(PS_DATA0);
    int data1 = read_register(PS_DATA1);

    if (data0 < 0 || data1 < 0) {
        fprintf(stderr, "Error reading proximity data.\n");
        return -1;
    }

    *proximity = (data1 << 8) | data0; // Combine little-endian
    return 0;
}

