// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    // Check if the sensor is present by reading the presence bit (register 0x0000)
    char buf[1];
    buf[0] = 0x0000;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    char presence_reg = 0x0000;
    int presence_value = i2cReadByteData(i2c_handle, presence_reg);
    if (presence_value < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (presence_value != 0x01) {
        fprintf(stderr, "VL53L0X not present at address 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }

    // Configure the sensor for single measurement mode
    buf[0] = VL53L0X_REG_SYSRANGE_START;
    result = i2cWriteByteData(i2c_handle, buf[0], 0x01);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Clear interrupt
    buf[0] = VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR;
    result = i2cWriteByteData(i2c_handle, buf[0], 0x01);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance() {
    char buf[1];
    char range_status_reg = VL53L0X_REG_RESULT_RANGE_STATUS;
    int result;

    // Read the range status
    result = i2cWriteDevice(i2c_handle, &range_status_reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    char range_status = i2cReadByteData(i2c_handle, range_status_reg);
    if (range_status < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the interrupt to be set
    int timeout_counter = 0;
    while (range_status & 0x01) {
        gpioDelay(1); // Wait 1 ms
        timeout_counter++;
        if (timeout_counter > 100) {
            fprintf(stderr, "Timeout waiting for interrupt\n");
            return -1;
        }
    }

    // Read the 14-byte result block
    buf[0] = VL53L0X_REG_RESULT_RANGE_STATUS;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    char result_block[14];
    result = i2cReadDevice(i2c_handle, result_block, 14);
    if (result != 14) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Extract the distance from bytes 10 and 11
    int distance = (result_block[10] << 8) | result_block[11];

    // Clear the interrupt
    buf[0] = VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR;
    result = i2cWriteByteData(i2c_handle, buf[0], 0x01);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

// Function to log the distance to a file
void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    fprintf(log_file, "%s,%d\n", buf, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

