#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20 // cm
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int init_gpio(int gpio_pin);
int read_distance(int i2c_handle);
void log_distance(FILE *fp, int distance);
void control_led(int gpio_pin, int state);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_address;
    int led_pin;
    int distance_threshold;
} sensor_config_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Initialize GPIO pin
int init_gpio(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0); // Initially turn the LED off
    return 0;
}

// Read distance from the sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int distance = -1;
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            distance = (buf[0] << 8) | buf[1];
            return distance;
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Indicate error
}

// Log distance to file with ISO-8601 timestamp
void log_distance(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s, Distance: %d cm\n", timestamp, distance);
    fflush(fp); // Ensure data is written to file immediately
}

// Control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, ICU20201_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(LED_GPIO) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(log_file, distance);

            if (distance < DISTANCE_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read distance, skipping logging.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

