#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the Si1182-GMR sensor
#define SI1182_I2C_ADDR 0x60

// Define the proximity data register address
#define PROXIMITY_REG 0x18

// Define the ambient light data register address
#define AMBIENT_LIGHT_REG 0x16

// Define the log file name
#define LOG_FILE "biometric_log.txt"

// Global variables for I2C handle and log file pointer
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c();
int read_proximity_data(int *proximity_value);
int read_ambient_light_data(int *ambient_light_value);
int log_data(int proximity_value, int ambient_light_value);
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SI1182_I2C_ADDR, 0); // Open I2C bus 1 with the sensor's address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity data from the sensor
int read_proximity_data(int *proximity_value) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG, buf, 2);
        if (result == 2) {
            *proximity_value = (buf[1] << 8) | buf[0]; // Combine the two bytes into a 16-bit value
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading proximity data: %d, retries remaining: %d\n", result, retries);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
    return -1; // Failure
}

// Function to read ambient light data from the sensor
int read_ambient_light_data(int *ambient_light_value) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, AMBIENT_LIGHT_REG, buf, 2);
        if (result == 2) {
            *ambient_light_value = (buf[1] << 8) | buf[0]; // Combine the two bytes into a 16-bit value
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading ambient light data: %d, retries remaining: %d\n", result, retries);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read ambient light data after multiple retries.\n");
    return -1; // Failure
}

// Function to log the sensor data to a file
int log_data(int proximity_value, int ambient_light_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity_value, ambient_light_value);
    fclose(log_file);
    return 0;
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to clean up resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int proximity_value, ambient_light_value;

        // Read proximity data
        if (read_proximity_data(&proximity_value) == 0) {
            // Read ambient light data
            if (read_ambient_light_data(&ambient_light_value) == 0) {
                // Log the data
                if (log_data(proximity_value, ambient_light_value) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error reading ambient light data.\n");
            }
        } else {
            fprintf(stderr, "Error reading proximity data.\n");
        }

        gpioDelay(500000); // Wait 500 ms
    }

    return 0;
}

