#define I2C_ADDR 0x6A
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 100 // mm
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x41
#define RETRY_COUNT 3

// Global variables
