volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_distance(int i2c_handle);
void log_data(int distance);
void control_led(int distance, int threshold);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    int result;
    int who_am_i;

    // Verify WHO_AM_I register
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (result >= 0) {
            who_am_i = (int)result;
            if (who_am_i == WHO_AM_I_VALUE) {
                printf("Sensor WHO_AM_I check passed.\n");
                return 0; // Success
            } else {
                fprintf(stderr, "Error: WHO_AM_I check failed. Expected 0x%02X, got 0x%02X. Retrying...\n", WHO_AM_I_VALUE, who_am_i);
                gpioDelay(100000); // 100ms delay
            }
        } else {
            fprintf(stderr, "Error: I2C read failed (WHO_AM_I). Retrying...\n");
            gpioDelay(100000); // 100ms delay
        }
    }

    fprintf(stderr, "Error: Sensor initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    int distance;
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, 0x00); // Read distance register
        if (result >= 0) {
            distance = (int)result;
            return distance;
        } else {
            fprintf(stderr, "Error: I2C read failed. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "Error: I2C read failed after multiple retries.\n");
    return -1; // Indicate error
}

