#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50

// Define the command to request a distance measurement
#define MEASUREMENT_COMMAND 0x500A0001

// Define the distance threshold (1000 mm)
#define DISTANCE_THRESHOLD 1000

// Define the log file name
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Structure to hold sensor data
typedef struct {
    int distance;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int i2c_write_command(int fd, uint8_t command);
int i2c_read_data(int fd, uint8_t *data, int count);
int validate_header(const uint8_t *data, int count);
int read_distance(int fd, sensor_data_t *data);
int log_intrusion(const sensor_data_t *data);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write command function
int i2c_write_command(int fd, uint8_t command) {
    uint8_t data[2];
    data[0] = command >> 8;
    data[1] = command & 0xFF;

    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C read data function
int i2c_read_data(int fd, uint8_t *data, int count) {
    if (write(fd, &count, 2) != 2) {
        perror("Error writing number of bytes to read");
        return -1;
    }

    if (read(fd, data, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Validate header function
int validate_header(const uint8_t *data, int count) {
    if (count != 2) {
        fprintf(stderr, "Error: Invalid header length: %d\n", count);
        return -1;
    }

    if (data[0] != 0x50) {
        fprintf(stderr, "Error: Invalid header value: 0x%02X\n", data[0]);
        return -1;
    }

    return 0;
}

// Read distance function
int read_distance(int fd, sensor_data_t *data) {
    uint8_t response[15];
    if (i2c_read_data(fd, response, 15) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    if (validate_header(response, 2) != 0) {
        fprintf(stderr, "Error: Invalid header in response\n");
        return -1;
    }

    data->distance = (response[11] << 8) | response[12];
    return 0;
}

// Log intrusion function
int log_intrusion(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %d mm\n", timestamp, data->distance);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("%s, Distance: %d mm\n", timestamp, data->distance);
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SENSOR_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed, exiting...\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Request distance measurement
        if (i2c_write_command(i2c_fd, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Error requesting distance measurement\n");
            continue; // Try again
        }

        // Wait for at least 10 ms
        usleep(10000); // 10 ms

        // Read distance
        if (read_distance(i2c_fd, &sensor_data) != 0) {
            fprintf(stderr, "Error reading distance\n");
            continue; // Try again
        }

        // Check if distance is within threshold
        if (sensor_data.distance < DISTANCE_THRESHOLD) {
            log_intrusion(&sensor_data);
        }

        // Delay for 100 ms
        usleep(100000); // 100 ms
    }

    // Close I2C device
    close(i2c_fd);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program finished.\n");
    return 0;
}

