// VL53L0X register addresses
#define VL53L0X_ADDR 0x29
#define VL53L0X_REG_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read a single byte from the VL53L0X sensor
int read_byte(int handle, uint8_t reg) {
    int data = i2cReadByteData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading byte from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return data;
}

// Function to write a single byte to the VL53L0X sensor
int write_byte(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing byte 0x%02X to register 0x%02X: %s\n", data, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the model ID from the VL53L0X sensor
