#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_IRQ_ENABLE 0x04
#define REG_IRQ_STATUS 0x05
#define REG_ALS_VIS_DATA0 0x2A
#define REG_ALS_VIS_DATA1 0x2B
#define REG_PS1_DATA0 0x22
#define REG_PS1_DATA1 0x23
#define REG_PS2_DATA0 0x24
#define REG_PS2_DATA1 0x25
#define REG_PS3_DATA0 0x26
#define REG_PS3_DATA1 0x27
#define REG_PS4_DATA0 0x28
#define REG_PS4_DATA1 0x29
