#define REG_PS6_DATA0 0x2C
#define REG_PS6_DATA1 0x2D
#define REG_PS7_DATA0 0x2E
#define REG_PS7_DATA1 0x2F
#define REG_COMMAND 0x30
#define REG_CONFIG 0x18

