int si1182_init() {
    // Check if the sensor is present by reading the Part ID register
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    printf("Si1182 Part ID: 0x%02X\n", part_id);

    // Initialize the sensor (example: enable proximity mode)
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    // Enable interrupts
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x03) < 0) {
        fprintf(stderr, "Error writing to INT_CFG register\n");
        return -1;
    }

