            printf("Proximity Value: %d\n", proximity_value);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

