#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C

// Define the distance register address
#define DISTANCE_REG 0x00

// Define the distance conversion factor
#define DISTANCE_FACTOR 0.125

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, uint8_t address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to read the distance data from the sensor
int read_distance(int fd, uint16_t *distance) {
    uint8_t buffer[2];
    int bytes_read = read(fd, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert the raw distance value to millimeters
float convert_distance(uint16_t raw_distance) {
    return (float)raw_distance * DISTANCE_FACTOR;
}

// Function to log the distance data to stdout
void log_distance(float distance) {
    printf("Distance: %.2f mm\n", distance);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set the I2C slave address
    if (set_i2c_slave(i2c_fd, MLX75030_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t raw_distance;
        float distance_mm;

        // Read the distance data
        if (read_distance(i2c_fd, &raw_distance) == 0) {
            // Convert the raw distance value to millimeters
            distance_mm = convert_distance(raw_distance);

            // Log the distance data
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance data. Retrying in 500ms...\n");
        }

        // Wait for 500 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Close the I2C file descriptor (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

