#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_RISING 200000 // Timeout for rising edge (microseconds)
#define TIMEOUT_FALLING 200000 // Timeout for falling edge (microseconds)
#define MAX_PULSE_DURATION 38000 // Maximum valid pulse duration (microseconds)

// Global variables
volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO pin configurations
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_RISING) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_RISING) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_FALLING) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_FALLING) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Invalid pulse duration
    }
    return (pulse_width * 0.0343) / 2.0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Get the current timestamp
        char timestamp[20];
        get_timestamp(timestamp);

        // Log the reading
        if (distance >= 0) {
            printf("%s Distance: %.2f cm\n", timestamp, distance);
        } else {
            fprintf(stderr, "%s Error: Invalid pulse duration\n", timestamp);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second delay
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

