        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read radar data from the UART
int read_radar_data(int fd, RadarData *data) {
    unsigned char magic_word[MAGIC_WORD_SIZE];
    unsigned char range_data[128];
    ssize_t bytes_read;

    // Read the magic word
    bytes_read = read(fd, magic_word, MAGIC_WORD_SIZE);
    if (bytes_read != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error reading magic word: %s\n", strerror(errno));
        return -1;
    }

    // Validate the magic word
    if (magic_word[0] != 0x02 || magic_word[1] != 0x01 || magic_word[2] != 0x04 ||
        magic_word[3] != 0x03 || magic_word[4] != 0x06 || magic_word[5] != 0x05 ||
        magic_word[6] != 0x08 || magic_word[7] != 0x07) {
        fprintf(stderr, "Invalid magic word: 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X\n",
                magic_word[0], magic_word[1], magic_word[2], magic_word[3],
                magic_word[4], magic_word[5], magic_word[6], magic_word[7]);
        return -1;
    }

    // Read the range profile data
    bytes_read = read(fd, range_data, 128);
    if (bytes_read != 128) {
        fprintf(stderr, "Error reading range profile data: %s\n", strerror(errno));
        return -1;
    }

    // Convert the range profile data to little-endian integers
    for (int i = 0; i < RANGE_BINS; i++) {
        data->range_bins[i] = (int16_t)((range_data[i * 2] << 8) | range_data[i * 2 + 1]);
    }

    return 0;
}

// Function to detect intrusion
int detect_intrusion(const RadarData *data, float threshold) {
    for (int i = 0; i < RANGE_BINS; i++) {
        if (data->range_bins[i] < 0) {
            fprintf(stderr, "Error: Negative range value at index %d\n", i);
            return 0; // No intrusion detected
        }
        if (data->range_bins[i] < threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Function to log intrusion event
void log_intrusion(float distance, float range_resolution) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    RadarData radar_data;
    int init_result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    init_result = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (init_result == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }
    uart_fd = init_result; // Store the file descriptor for later cleanup

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed. Exiting.\n");
        close(uart_fd);
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read radar data
        if (read_radar_data(uart_fd, &radar_data) == 0) {
            // Detect intrusion
            if (detect_intrusion(&radar_data, INTRUSION_THRESHOLD)) {
                // Activate LED
                gpioWrite(LED_GPIO, 1);
                gpioDelay(2000); // 2 seconds
                gpioWrite(LED_GPIO, 0);

                // Log intrusion event
                log_intrusion(INTRUSION_THRESHOLD, RANGE_RESOLUTION);
            }
        } else {
            fprintf(stderr, "Error reading radar data. Retrying.\n");
        }

        gpioDelay(100); // Delay to avoid overwhelming the system
    }

    // Cleanup
    close(uart_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

