#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define GPIO_ALERT 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int read_distance(int handle);
void log_distance(FILE *fp, int distance);
void trigger_alert(int gpio_pin, int distance);
void cleanup(int signum);

// Signal handler
void cleanup(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    terminate = 1;

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Release GPIO resources
    gpioSetMode(GPIO_ALERT, PI_INPUT); // Set to input to release
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C connection
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read distance from the sensor
int read_distance(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, 0x31, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Log distance to file
void log_distance(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fflush(fp); // Ensure data is written to disk immediately
}

// Trigger alert if distance is below threshold
void trigger_alert(int gpio_pin, int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(gpio_pin, 1); // Set GPIO HIGH
        gpioDelay(1000);        // Wait for 1 second
        gpioWrite(gpio_pin, 0); // Set GPIO LOW
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance monitoring...\n");

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log distance
        log_distance(log_file, distance);

        // Trigger alert
        trigger_alert(GPIO_ALERT, distance);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

