// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE_START 0x007
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void log_distance(int distance);
void print_parking_guidance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the VL53L1X sensor
int vl53l1x_init() {
    // Check if the sensor is present by reading the model ID register
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_MODEL_ID);
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: VL53L1X sensor not found (Model ID: 0x%02X)\n", model_id);
        return -1;
    }

    // Perform a software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X sensor\n");
        return -1;
    }
    gpioDelay(2000); // Wait 2 ms

    // Start continuous back-to-back ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start VL53L1X sensor\n");
        return -1;
    }

    return 0;
}

// Reads the distance from the VL53L1X sensor
int vl53l1x_read_distance() {
    // Wait for the interrupt to be clear
    int timeout_count = 0;
    while (i2cReadByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START) & 0x01) {
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 100) {
            fprintf(stderr, "Error: Timeout waiting for interrupt clear\n");
            return -1; // Indicate timeout error
        }
    }

    // Read the distance from the range status register
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance from VL53L1X sensor\n");
        return -1;
    }

    // Clear the interrupt
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to clear VL53L1X interrupt\n");
        return -1;
    }

    return distance;
}

// Logs the distance to a CSV file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("distance_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Could not open distance_log.csv for writing\n");
            return;
        }
        fprintf(log_file, "timestamp,distance_mm\n");
    }

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Prints a parking guidance message based on the distance
void print_parking_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance >= 300 && distance < 600) {
        printf("APPROACH\n");
    } else if (distance >= 600 && distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            log_distance(distance);
            print_parking_guidance(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        gpioDelay(100); // Wait 100 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

