// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define BLINK_FREQ_MIN 1.0
#define BLINK_FREQ_MAX 50.0
#define MAX_DISTANCE 500.0
#define MIN_DISTANCE 50.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 10000 // 10 ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
void set_led_blink_frequency(float distance);
void log_data(float distance, float frequency);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    float distance;
    float frequency;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(float *distance) {
    char buf[2];
    int result;
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int16_t raw_distance = (buf[0] << 8) | buf[1];
            // Convert raw distance to millimeters (adjust as needed)
            *distance = (float)raw_distance * 0.1; // Example conversion
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(I2C_RETRY_DELAY);
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Set LED blink frequency based on distance
void set_led_blink_frequency(float distance) {
    float frequency;

    if (distance < MIN_DISTANCE) {
        frequency = BLINK_FREQ_MAX;
    } else if (distance > MAX_DISTANCE) {
        frequency = BLINK_FREQ_MIN;
    } else {
        frequency = BLINK_FREQ_MIN + (distance - MIN_DISTANCE) * (BLINK_FREQ_MAX - BLINK_FREQ_MIN) / (MAX_DISTANCE - MIN_DISTANCE);
        if (frequency < BLINK_FREQ_MIN) {
            frequency = BLINK_FREQ_MIN;
        } else if (frequency > BLINK_FREQ_MAX) {
            frequency = BLINK_FREQ_MAX;
        }
    }

    // Calculate the period of the blink (in seconds)
    float period = 1.0 / frequency;

    // Calculate the on/off time (in seconds)
    float on_time = period / 2.0;
    float off_time = period / 2.0;

    // Calculate the duty cycle (in seconds)
    float duty_cycle = on_time;

    // Calculate the delay between blinks (in seconds)
    float delay = (1.0 / frequency) - duty_cycle;

    // Calculate the on and off durations in milliseconds
    int on_ms = (int)(on_time * 1000);
    int off_ms = (int)(off_time * 1000);
    int delay_ms = (int)(delay * 1000);

    // Blink the LED
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(on_ms);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(off_ms);
}

