    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %.2f mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Signal handler for clean shutdown
