    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;
    float frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            set_led_blink_frequency(distance);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

