#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASUREMENT_CMD 0x01 // Example command, check datasheet
#define READ_DELAY_US 10000 // 10 ms
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance_cm;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_distance(int *distance);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the MLX75030
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, 0x00, MEASUREMENT_CMD); // Assuming register 0x00 is the command register
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance data from the sensor
int read_distance(int *distance) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2); // Assuming register 0x00 is the data register
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (buffer[0] << 8) | buffer[1];

    return 0;
}

