    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        int distance;
        int retries = 0;

        // Trigger measurement with retries
        while (retries < MAX_RETRIES) {
            if (trigger_measurement() == 0) {
                break; // Measurement triggered successfully
            } else {
                fprintf(stderr, "Measurement trigger failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Measurement trigger failed after %d retries.\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        gpioDelay(READ_DELAY_US * 1000); // Delay for measurement completion

        // Read distance with retries
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_distance(&distance) == 0) {
                break; // Read successful
            } else {
                fprintf(stderr, "Distance read failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Distance read failed after %d retries.\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Get current timestamp
        data.timestamp = time(NULL);
        data.distance_cm = distance;

        // Log the data
        log_data(data);

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

