        int sensor1_debounced_state = read_sensor(SENSOR_1_GPIO);
        if (sensor1_debounced_state < 0) {
            program_running = 0; // Exit on error
            break;
        }

        // Check for state transition
        if (sensor1_last_state != sensor1_debounced_state) {
            if (sensor1_last_state == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            sensor1_last_state = sensor1_debounced_state;
        }

        // Read sensor 2
        int sensor2_current_state = read_sensor(SENSOR_2_GPIO);
        if (sensor2_current_state < 0) {
            program_running = 0; // Exit on error
            break;
        }

        // Debounce sensor 2
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
        int sensor2_debounced_state = read_sensor(SENSOR_2_GPIO);
        if (sensor2_debounced_state < 0) {
            program_running = 0; // Exit on error
            break;
        }

        // Check for state transition
        if (sensor2_last_state != sensor2_debounced_state) {
            if (sensor2_last_state == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            sensor2_last_state = sensor2_debounced_state;
        }

        // Update last states
        sensor1_last_state = sensor1_debounced_state;
        sensor2_last_state = sensor2_debounced_state;

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms
    }

    // Clean up and exit
    cleanup();
    return 0;
}

