#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <stdint.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int distance_mm;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int read_distance(int fd);
void log_data(sensor_data_t data);
void signal_handler(int sig);

// Helper function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Helper function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (for read) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int fd) {
    uint8_t status;
    uint8_t high, low;
    int distance;

    // Trigger a single range measurement
    if (i2c_write_reg(fd, MEAS_TRIGGER, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for data-ready bit to be set (with timeout)
    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = TIMEOUT_MS * 1000000; // Convert ms to ns

    int start_time = time(NULL);
    while (1) {
        if (i2c_read_reg(fd, MEAS_STATUS, &status) == 0) {
            if ((status & 0x01) && (time(NULL) - start_time >= timeout.tv_sec)) {
                // Timeout occurred
                fprintf(stderr, "Timeout waiting for data-ready\n");
                return -1;
            }
            break; // Exit loop if data is ready
        } else {
            fprintf(stderr, "Error reading MEAS_STATUS\n");
            return -1;
        }
        nanosleep(&timeout, NULL);
    }

    // Read the distance data
    if (i2c_read_reg(fd, DIST_HIGH, &high) != 0) {
        fprintf(stderr, "Error reading DIST_HIGH\n");
        return -1;
    }
    if (i2c_read_reg(fd, DIST_LOW, &low) != 0) {
        fprintf(stderr, "Error reading DIST_LOW\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit distance value
    distance = (high << 8) | low;

    return distance;
}

// Function to log the data to a CSV file
void log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp[20];

    timeinfo = gmtime(&data.timestamp);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, data.distance_mm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set the slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        sensor_data_t data;
        data.timestamp = time(NULL);

        // Read the distance
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            data.distance_mm = distance;
            log_data(data);
        } else {
            fprintf(stderr, "Error reading distance, skipping sample\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

