// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// Register addresses (Example - adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L5CX_REG_SYSTEM_START 0x0000
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB 0x001E
#define VL53L5CX_REG_RESULT_SIGNAL_RATE 0x0020
#define VL53L5CX_REG_RESULT_AMBIENT_RATE 0x0022
#define VL53L5CX_REG_RESULT_DISTANCE 0x001A

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx() {
    // Check sensor ID (Example - adjust based on datasheet)
    unsigned char model_id;
    if (read(i2c_fd, &model_id, 1) != 1) {
        perror("Failed to read model ID");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Start continuous ranging (Example - adjust based on datasheet)
    unsigned char start_cmd[2] = {VL53L5CX_REG_SYSTEM_START, 0x01};
    if (write(i2c_fd, start_cmd, 2) != 2) {
        perror("Failed to start sensor");
        return -1;
    }

    return 0;
