#define MLX75030_REG_STATUS 0x00
#define MLX75030_REG_DISTANCE 0x01

// Global variables for I2C handle and program state
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance from the MLX75030 sensor
int read_distance(int *distance) {
    int status;
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, MLX75030_REG_DISTANCE);
        if (status >= 0) {
            *distance = status; // Assuming status is the distance value
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, status);
            retries--;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure after retries
}

