void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %d mm\n", timestamp, distance);
}

// Function to close the I2C connection and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio and I2C
    if (initialize() != 0) {
        return 1;
    }

    int distance;

    // Main loop
    while (program_running) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100 * 1000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

