int init_sensor(int handle) {
    // Soft reset
    if (write_register(handle, VL53L4CX_REG_SYSTEM_START, 0x01) != 0) {
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Start ranging
    if (write_register(handle, VL53L4CX_REG_SYSTEM_START, 0x04) != 0) {
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    return 0;
}

