#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_NAME "/distance_queue"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 5000

// VL53L1X Registers
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_RESET 0x0000
#define VL53L1X_REG_TIMING_BUDGET 0x0080
#define VL53L1X_REG_START_RANGING 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

// Global variables
int i2c_handle;
int socket_desc;
struct sockaddr_in server_addr;

// Function prototypes
int vl53l1x_init();
int vl53l1x_get_distance();
void activate_buzzer();
void log_distance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (socket_desc > 0) {
        close(socket_desc);
    }
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate();
    exit(0);
}

// VL53L1X Initialization
int vl53l1x_init() {
    int status;

    // Check model ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (status != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", status);
        return -1;
    }

    // Software reset
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESET, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing reset command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESET, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing reset command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure timing budget
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, 50); // 50ms
    if (status < 0) {
        fprintf(stderr, "Error writing timing budget command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Start ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_START_RANGING, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing start ranging command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    return 0;
}

// VL53L1X Distance Reading
int vl53l1x_get_distance() {
    int distance = -1;
    int status;

    // Check data ready bit
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading range status: %s\n", strerror(errno));
        return -1;
    }

    if (status & 0x01) {
        // Read distance
        status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE);
        if (status < 0) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            return -1;
        }
        distance = (int)status;
    }

    return distance;
}

// Buzzer Control
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
    gpioDelay(100000);         // Wait 100ms
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
}

// Message Queue Logging
void log_distance(int distance) {
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10;
    attr.mq_msgsize = 10;
    attr.mq_curmsgs = 0;

    if (mq_getattr(mq_desc, &attr) == -1) {
        fprintf(stderr, "mq_getattr failed: %s\n", strerror(errno));
        return;
    }

    char buffer[10];
    snprintf(buffer, sizeof(buffer), "%d", distance);

    if (mq_send(mq_desc, buffer, strlen(buffer), 0) == -1) {
        fprintf(stderr, "mq_send failed: %s\n", strerror(errno));
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create message queue
    mqd_t mq_desc = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_WRONLY, 0644, NULL);
    if (mq_desc == (mqd_t)-1) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        mq_close(mq_desc);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", SERVER_IP);
        close(socket_desc);
        mq_close(mq_desc);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to server
    if (connect(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error connecting to server: %s\n", strerror(errno));
        close(socket_desc);
        mq_close(mq_desc);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Connected to server. Logging distance to %s\n", MESSAGE_QUEUE_NAME);

    // Main loop
    while (1) {
        fd_set readfds;
        struct timeval tv;

        FD_ZERO(&readfds);
        FD_SET(socket_desc, &readfds);

        tv.tv_sec = 0;
        tv.tv_usec = 50000; // 50ms

        int select_result = select(socket_desc + 1, &readfds, NULL, NULL, &tv);

        if (select_result > 0) {
            if (FD_ISSET(socket_desc, &readfds)) {
                // Receive data from server
                ssize_t bytes_received = recv(socket_desc, buffer, sizeof(buffer) - 1, 0);
                if (bytes_received > 0) {
                    buffer[bytes_received] = '\0';
                    printf("Received from server: %s\n", buffer);
                } else if (bytes_received == 0) {
                    printf("Server disconnected\n");
                } else {
                    fprintf(stderr, "Error receiving data: %s\n", strerror(errno));
                }
            } else {
                // Data ready bit is set
                int distance = vl53l1x_get_distance();
                if (distance >= 0) {
                    log_distance(distance);
                    printf("Distance: %d mm\n", distance);

                    if (distance < DISTANCE_THRESHOLD) {
                        activate_buzzer();
                    }
                }
            }
        } else if (select_result == -1) {
            fprintf(stderr, "Select error: %s\n", strerror(errno));
            break;
        }
    }

    // Cleanup (should not reach here normally due to signal handler)
    close(socket_desc);
    mq_close(mq_desc);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

