#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 1000000      // 1 second timeout
#define BUZZER_DURATION_MS 500
#define DISTANCE_THRESHOLD 30.0 // cm

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor(int triggerPin);
void echoCallback(int gpio, int level, uint32_t tick, void *user);
void buzzerControl(int buzzerPin, int state);
void distanceCalculation(uint32_t start, uint32_t end, float speedOfSound, float *distance);
void distanceValidation(float distance);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor(int triggerPin) {
    gpioWrite(triggerPin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(triggerPin, 0);
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that echo has started
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 0; // Reset echo_received
    }
}

// Function to control the buzzer
void buzzerControl(int buzzerPin, int state) {
    gpioWrite(buzzerPin, state);
}

// Function to calculate distance
void distanceCalculation(uint32_t start, uint32_t end, float speedOfSound, float *distance) {
    uint32_t pulse_width = end - start;
    if (pulse_width < 0) pulse_width += 0xFFFFFFFF; // Handle tick wraparound
    *distance = (float)pulse_width * speedOfSound / 2.0;
}

// Function to validate distance
void distanceValidation(float distance) {
    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
    }
}

// Signal handler for clean shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    buzzerControl(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signalHandler);

    // Set up interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        triggerSensor(TRIGGER_PIN);
        gpioDelay(50); // Wait for echo

        if (echo_end_tick > echo_start_tick) {
            float distance;
            distanceCalculation(echo_start_tick, echo_end_tick, SPEED_OF_SOUND, &distance);
            distanceValidation(distance);

            if (distance < DISTANCE_THRESHOLD) {
                buzzerControl(BUZZER_PIN, 1); // Turn on buzzer
            } else {
                buzzerControl(BUZZER_PIN, 0); // Turn off buzzer
            }

            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Sensor timeout\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

