#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_THRESHOLD 30000 // microseconds
#define MIN_PULSE_WIDTH 100     // microseconds
#define MAX_PULSE_WIDTH 30000  // microseconds
#define TIMEOUT_TIMEOUT 60      // milliseconds
#define MEASUREMENT_INTERVAL 200 // milliseconds

// Global variables
static volatile int pulse_width = 0;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 microsecond pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for ECHO pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_valid = 0; // Reset valid flag
        } else if (level == 0) {
            echo_end_tick = tick;
            echo_valid = 1; // Set valid flag
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to stdout and file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    FILE *fp = fopen("distance_log.txt", "a");
    if (fp != NULL) {
        fprintf(fp, "%s Distance: %.2f cm\n", timestamp, distance);
        fclose(fp);
    } else {
        perror("Error opening distance_log.txt");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();

        if (echo_valid) {
            uint32_t pulse_width_raw = echo_end_tick - echo_start_tick;
            if (pulse_width_raw < 0) {
                pulse_width_raw += 0xFFFFFFFF; // Handle tick wraparound
            }
            pulse_width = pulse_width_raw;

            if (pulse_width >= MIN_PULSE_WIDTH && pulse_width <= MAX_PULSE_WIDTH) {
                log_distance(calculate_distance(pulse_width));
            } else {
                if (pulse_width < MIN_PULSE_WIDTH) {
                    fprintf(stderr, "Warning: Invalid pulse width: %d us\n", pulse_width);
                } else if (pulse_width > MAX_PULSE_WIDTH) {
                    fprintf(stderr, "Warning: Timeout or no object detected: %d us\n", pulse_width);
                }
            }
        } else {
            // No valid echo received within timeout
            fprintf(stderr, "Warning: No valid echo received within timeout.\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

