        fprintf(stderr, "Error triggering measurement.\n");
        return -1;
    }

    // Wait for measurement to be ready (example - adjust based on datasheet)
    int ready = 0;
    int timeout = 100; // Timeout after 100 attempts
    while (!ready && timeout > 0) {
        if (read_register(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &ready) != 0) {
            fprintf(stderr, "Error reading data ready status.\n");
            return -1;
        }
        gpioDelay(10); // Small delay
        timeout--;
