// VL53L1X Initialization
int vl53l1x_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X reset failed (soft). Error code: %d\n", errno);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Check device ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error: VL53L1X reset failed (soft). Error reading model ID. Error code: %d\n", errno);
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Error: VL53L1X reset failed (soft). Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure timing budget
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X timing budget setup failed. Error code: %d\n", errno);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X timing budget setup failed. Error code: %d\n", errno);
        return -1;
    }

    // Start ranging
    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X ranging setup failed. Error code: %d\n", errno);
        return -1;
    }

    return 0;
}

