    int status = i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP_CONTROL, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed. Error code: %d\n", errno);
        return -1;
    }
    return 0;
}

