    int distance = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error: VL53L1X read distance failed. Error code: %d\n", errno);
        return -1;
    }
    return distance;
}

