    fprintf(log_file, "%s,%s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
