#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define MPR121 I2C address
#define MPR121_ADDR 0x5A

// Define GPIO pins for LEDs
#define LED1_PIN 17
#define LED2_PIN 18
#define LED3_PIN 27
#define LED4_PIN 22

// Define proximity patterns
#define PATTERN_0 0x0F
#define PATTERN_1 0x00
#define PATTERN_2 0x1F
#define PATTERN_3 0x00

// Define proximity thresholds
#define THRESHOLD_LOW 0x01
#define THRESHOLD_MED 0x02
#define THRESHOLD_HIGH 0x03

// Define I2C file descriptor
int i2c_fd;

// Function prototypes
int mpr121_init(int i2c_fd);
int read_touch_status(int i2c_fd);
void set_led_pattern(int led_pin, int pattern);
void log_event(int electrode, int pattern);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize the MPR121 sensor
int mpr121_init(int i2c_fd) {
    // Soft reset
    if (i2cWriteByteData(i2c_fd, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Verify sensor presence by reading a known register
    int status = i2cReadByteData(i2c_fd, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read status register after reset\n");
        return -1;
    }
    if (status != 0x00) {
        fprintf(stderr, "Error: MPR121 not found or reset failed. Status: 0x%02X\n", status);
        return -1;
    }

    // Stop mode
    if (i2cWriteByteData(i2c_fd, 0x5E, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set stop mode\n");
        return -1;
    }

    // Baseline filtering
    if (i2cWriteByteData(i2c_fd, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHDR\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5C, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHDR\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5D, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCLR\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5F, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set FDLR\n");
        return -1;
    }

    // Auto-configuration thresholds
    if (i2cWriteByteData(i2c_fd, 0x5A, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to set threshold_low\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5D, 0xC8) < 0) {
        fprintf(stderr, "Error: Failed to set threshold_med\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5E, 0x82) < 0) {
        fprintf(stderr, "Error: Failed to set threshold_high\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5F, 0xB4) < 0) {
        fprintf(stderr, "Error: Failed to set auto_config_mode\n");
        return -1;
    }

    // Enable all electrodes in run mode
    if (i2cWriteByteData(i2c_fd, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHDR for run mode\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5C, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHDR for run mode\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5D, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCLR for run mode\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, 0x5F, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set FDLR for run mode\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(int i2c_fd) {
    int status = i2cReadByteData(i2c_fd, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return status;
}

// Function to set the LED pattern
void set_led_pattern(int led_pin, int pattern) {
    gpioWrite(led_pin, (pattern >> 3) & 0x01); // Bit 3
    gpioWrite(led_pin, (pattern >> 2) & 0x01); // Bit 2
    gpioWrite(led_pin, (pattern >> 1) & 0x01); // Bit 1
    gpioWrite(led_pin, (pattern >> 0) & 0x01); // Bit 0
}

// Function to log the event
void log_event(int electrode, int pattern) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Electrode: %d, Pattern: 0x%02X\n", timestamp, electrode, pattern);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);
    gpioSetMode(LED3_PIN, PI_OUTPUT);
    gpioSetMode(LED4_PIN, PI_OUTPUT);

    // Open I2C device
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-1");
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", filename);
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status, exiting...\n");
            break;
        }

        // Check if any electrode is active
        if (touch_status > 0) {
            // Determine LED pattern based on the highest active electrode
            int highest_active_electrode = 0;
            for (int i = 0; i < 12; i++) {
                if ((touch_status & (1 << i)) && (i > highest_active_electrode)) {
                    highest_active_electrode = i;
                }
            }

            // Set LED patterns
            set_led_pattern(LED1_PIN, PATTERN_0);
            set_led_pattern(LED2_PIN, PATTERN_1);
            set_led_pattern(LED3_PIN, PATTERN_2);
            set_led_pattern(LED4_PIN, PATTERN_3);

            // Log the event
            log_event(highest_active_electrode, touch_status);
        } else {
            // No electrode is active
            set_led_pattern(LED1_PIN, 0);
            set_led_pattern(LED2_PIN, 0);
            set_led_pattern(LED3_PIN, 0);
            set_led_pattern(LED4_PIN, 0);
            log_event(-1, 0); // Log no active electrode
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

