#define RELEASE_THRESHOLD 0x05
#define LED_ON_TIME_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_mpr121_register(int i2c_handle, unsigned char reg);
int write_mpr121_register(int i2c_handle, unsigned char reg, unsigned char value);
int verify_mpr121_device(int i2c_handle);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Verify device ID
    if (verify_mpr121_device(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 not found.\n");
        return -1;
    }

    // Configure touch and release thresholds for electrode 0
    if (write_mpr121_register(i2c_handle, THRESHOLD_REG, PROXIMITY_THRESHOLD) != 0) {
        fprintf(stderr, "Error writing proximity threshold.\n");
        return -1;
    }
    if (write_mpr121_register(i2c_handle, THRESHOLD_REG + 1, RELEASE_THRESHOLD) != 0) {
        fprintf(stderr, "Error writing release threshold.\n");
        return -1;
    }

    // Configure debounce settings
    if (write_mpr121_register(i2c_handle, DEBOUNCE_REG, 0x01) != 0) {
        fprintf(stderr, "Error writing debounce register.\n");
        return -1;
    }

    // Configure AFE settings
    if (write_mpr121_register(i2c_handle, AFE_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing AFE register.\n");
        return -1;
    }

    // Configure baseline filtering settings
    if (write_mpr121_register(i2c_handle, BASELINE_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing baseline register.\n");
        return -1;
    }

    return 0;
}

