int verify_mpr121_device(int i2c_handle) {
    int device_id = read_mpr121_register(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID.\n");
        return -1;
    }

    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID. Expected 0x%02X, got 0x%02X\n", DEVICE_ID, device_id);
        return -1;
    }

    printf("MPR121 device ID verified: 0x%02X\n", device_id);
    return 0;
}

