    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read proximity status from electrode 0
        int proximity_status = read_mpr121_register(i2c_handle, 0x00);
        if (proximity_status < 0) {
            fprintf(stderr, "Error reading proximity status.\n");
            break; // Exit loop on error
        }

        // Check if proximity is detected
        if (proximity_status & 0x01) { // Check bit 0 of the status register
            printf("Proximity detected!\n");
            log_event("Proximity detected!");

            // Turn on LED
            gpioWrite(LED_GPIO, 1);

            // Wait for 1 second
            gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to microseconds

