#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000 // 30 ms
#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;

// Structure to hold GPIO and SPI configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
    int spi_fd;
} Config;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int hc_sr04_measure(int trigger_pin, int echo_pin, int spi_fd);
float calculate_distance(int pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// HC-SR04 measurement function
int hc_sr04_measure(int trigger_pin, int echo_pin, int spi_fd) {
    gpioWrite(trigger_pin, 0); // Ensure trigger is low
    gpioDelay(TRIGGER_PULSE_US); // Trigger pulse
    gpioWrite(trigger_pin, 1);
    gpioDelay(TRIGGER_PULSE_US); // Trigger pulse
    gpioWrite(trigger_pin, 0);

    unsigned char tx_buf[3] = {0x01, 0x00, 0x00}; // Start bit, single-ended mode, 10-bit resolution
    unsigned char rx_buf[3];

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int pulse_width = ((rx_buf[1] & 0x03) << 8) + rx_buf[2]; // Extract pulse width

    if (pulse_width < 0 || pulse_width > ECHO_TIMEOUT_US) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return -1;
    }

    return pulse_width;
}

// Distance calculation function
float calculate_distance(int pulse_width) {
    return (pulse_width * 0.0343) / 2.0;
}

// Logging function
void log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, distance);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_INPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int pulse_width = hc_sr04_measure(17, 18, spi_fd);
        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
                log_distance(-1.0); // Log an error
            }
        } else {
            fprintf(stderr, "HC-SR04 measurement failed\n");
            log_distance(-1.0); // Log an error
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    close(spi_fd);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

