#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_PULSE_WIDTH 25000   // Maximum pulse width in microseconds (25ms)
#define MIN_PULSE_WIDTH 58      // Minimum pulse width in microseconds (58us)
#define MAX_DISTANCE 4.0        // Maximum measurable distance in meters
#define MIN_DISTANCE 1.0        // Minimum measurable distance in meters

// Global variables
static volatile int pulse_width = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void log_distance(float distance);
void signal_handler(int signal);

// Function to trigger a pulse on the TRIG pin
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 microsecond pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        pulse_width = tick;
        echo_received = 1;
    } else if (level == 0) {
        // Falling edge
        if (pulse_width > 0 && pulse_width < MAX_PULSE_WIDTH) {
            // Valid pulse received
            float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0;
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Warning: Distance out of range: %.2f m\n", distance);
            }
        } else {
            fprintf(stderr, "Error: Invalid pulse width: %d us\n", pulse_width);
        }
        pulse_width = 0; // Reset pulse_width
    }
}

// Function to log distance to file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Disable ISR
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set ISR for ECHO_PIN
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(500000); // Wait 0.5 seconds
    }

    return 0;
}

