#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0010
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0018
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0018

// GPIO pin for active-low trigger
#define TRIGGER_PIN 27

// I2C handle
int i2c_handle;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void log_data(uint16_t distance, uint8_t status);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int trigger_pin;
    int i2c_handle;
} sensor_config_t;

// Global sensor configuration
sensor_config_t sensor_config = {
    .i2c_address = VL53L1X_ADDR,
    .trigger_pin = TRIGGER_PIN,
    .i2c_handle = -1 // Initialize to -1 to indicate not opened
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t distance;
        uint8_t status;

        if (read_distance(&distance) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Open I2C bus
    i2c_handle = i2cOpen(1, sensor_config.i2c_address, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        return -1;
    }

    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        syslog(LOG_ERR, "Failed to read sensor ID");
        i2cClose(i2c_handle);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect sensor ID: 0x%02X", sensor_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure continuous mode, no timeout, start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to system start register");
        i2cClose(i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to range status register");
        i2cClose(i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to final range register");
        i2cClose(i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to interrupt clear register");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(uint16_t *distance) {
    int result;

    result = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (result < 0) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    *distance = (uint16_t)result;
    return 0;
}

// Log data to the systemd journal
void log_data(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s - Distance: %d mm, Status: 0x%02X", timestamp, distance, status);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);

    // Close I2C bus
    if (sensor_config.i2c_handle >= 0) {
        i2cClose(sensor_config.i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    exit(0);
}

