#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 200 // mm
#define BUFFER_SIZE 10

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MM_SD0 0x0015
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MM_SD0 0x001E
#define VL53L1X_REG_START_STOP_CONTROL 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_SPAD_NB 0x0090
#define VL53L1X_REG_RESULT_SIGNAL_RATE 0x0092
#define VL53L1X_REG_RESULT_AMBIENT_RATE 0x0094
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle, int *distance);
void add_to_buffer(CircularBuffer *cb, int value);
int get_from_buffer(CircularBuffer *cb, int index);
void check_distance_and_control_led(int distance);
void signal_handler(int signal);

// Circular buffer functions
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

int get_from_buffer(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return -1; // Indicate error
    }
    int value = cb->buffer[cb->head + index];
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->count--;
    return value;
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Example initialization sequence (adjust based on datasheet)
    // This is a simplified example and may need adjustments
    char data[2];
    int status;

    // Check device ID
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Model ID): %d\n", status);
        return -1;
    }
    char model_id;
    status = i2cReadDevice(i2c_handle, &model_id, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading VL53L1X Model ID: %d\n", status);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect VL53L1X Model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Enable signal rate check
    data[0] = VL53L1X_REG_PRE_RANGE_CONFIG_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Pre-range config): %d\n", status);
        return -1;
    }
    data[0] = 0x01; // Enable signal rate check
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Signal rate config): %d\n", status);
        return -1;
    }

    // Configure cross-talk compensation
    data[0] = VL53L1X_REG_FINAL_RANGE_CONFIG_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Final range config): %d\n", status);
        return -1;
    }
    data[0] = 0x00; // No cross-talk compensation
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Final range config): %d\n", status);
        return -1;
    }

    // Start ranging
    data[0] = VL53L1X_REG_START_STOP_CONTROL;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Start ranging): %d\n", status);
        return -1;
    }
    data[0] = 0x04; // Start ranging
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Start ranging): %d\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int i2c_handle, int *distance) {
    char data[2];
    int status;
    uint16_t range;

    // Read distance
    data[0] = VL53L1X_REG_RESULT_DISTANCE;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to VL53L1X (Distance read): %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, (char *) &range, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading VL53L1X distance: %d\n", status);
        return -1;
    }

    *distance = (int)range; // Distance is in mm
    return 0;
}

// Distance check and LED control function
void check_distance_and_control_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int distance;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize circular buffer
    init_circular_buffer(&circular_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read distance
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            // Add to circular buffer
            add_to_buffer(&circular_buffer, distance);

            // Check distance and control LED
            check_distance_and_control_led(distance);

            // Print distance (optional)
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

