    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read distance from the ultrasonic sensor
float read_distance() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2); // Wait 2 us
    gpioWrite(TRIGGER_PIN, 1); // Send a 10 us pulse
    gpioDelay(10); // Wait for echo
    gpioWrite(TRIGGER_PIN, 0);

    int start_tick = 0;
    int end_tick = 0;

    // Wait for echo to go high
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
