        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse not received (timeout)\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse not received (timeout)\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    int diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    float pulse_width = (float)diff / 1000000.0; // Convert to seconds
    float distance = pulse_width * 34300.0 / 2.0; // Speed of sound in cm/s

    return distance;
}

