    int duty_cycle = (int)((float)range * (1.0 - (float)last_valid_distance / MAX_DIST) / 2.0); // Map distance to duty cycle

    gpioHardwarePWM(BUZZER_PIN, 0, range); // Set range
    gpioPWM(BUZZER_PIN, duty_cycle); // Set duty cycle
    last_valid_distance = distance; // Update last valid distance
}

