    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(BUZZER_PIN, 1000000); // Set PWM range to 1,000,000

