    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI write register function
int spi_write_register(int reg, int value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg << 1) | 0x80; // Set MSB for write
    tx_buf[1] = value & 0xFF;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI write error: %d\n", errno);
        return -1;
    }
    return 0;
}

// SPI read register function
int spi_read_register(int reg, int *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg << 1) & 0x7F; // Clear MSB for read
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI read error: %d\n", errno);
        return -1;
    }

    *value = (rx_buf[1] << 8) | rx_buf[0];
    return 0;
}

