        return -1;
    }
    if (spi_read_register(ICU20201_REG_DISTANCE_HIGH, &high) != 0) {
        fprintf(stderr, "Error reading distance_high\n");
        return -1;
    }

    *distance = (high << 8) | low;
    return 0;
}

