#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C device address
#define I2C_DEVICE "/dev/i2c-1"

// Define the Si1175 register addresses
#define SI1175_ALS_VIS_DATA0 0x22
#define SI1175_ALS_VIS_DATA1 0x23

// Define the log file name
#define LOG_FILE "proximity_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    uint16_t visible_light;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *device);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_close(int fd);
int read_visible_light(int fd, sensor_data_t *data);
char* get_iso8601_timestamp();
int log_data(FILE *fp, const char *timestamp, uint16_t visible_light);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }
    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;

    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Read visible light function
int read_visible_light(int fd, sensor_data_t *data) {
    uint8_t buffer[2];

    if (i2c_read_bytes(fd, SI1175_ALS_VIS_DATA0, buffer, 2) != 0) {
        fprintf(stderr, "Error reading visible light data\n");
        return -1;
    }

    data->visible_light = (buffer[1] << 8) | buffer[0];
    return 0;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data function
int log_data(FILE *fp, const char *timestamp, uint16_t visible_light) {
    if (fprintf(fp, "%s,%u\n", timestamp, visible_light) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write the header row to the log file
    fprintf(log_file, "timestamp,als_visible\n");
    fflush(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read visible light
        if (read_visible_light(i2c_fd, &sensor_data) == 0) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log data
                if (log_data(log_file, timestamp, sensor_data.visible_light) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading visible light\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C device and log file
    i2c_close(i2c_fd);
    fclose(log_file);

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

