#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_REG_RESET 0x30

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int si1120_read_als();
int si1120_read_proximity();
void log_data(int als_value, int proximity_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int als_value;
    int proximity_value;
} sensor_data_t;

// Function to initialize the Si1120 sensor
int si1120_init() {
    int result;
    int retries = 3;

    while (retries > 0) {
        // Reset the sensor
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, 0x01);
        if (result != 0) {
            fprintf(stderr, "Error resetting Si1120: %d\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait for reset to complete (10 ms)

        // Verify part ID
        int part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (part_id != 0x41) {
            fprintf(stderr, "Error: Incorrect part ID (0x%02X). Expected 0x41.\n", part_id);
            log_data(-1, -1); // Log error values
            gpioDelay(10000); // 10 ms delay
            retries--;
            continue;
        }

