#define SI1182_ADDR 0x39
#define MEASUREMENT_RATE_REG 0x08
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24
#define LOG_FILE "biometric_log.txt"
#define READ_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;

// Function prototypes
int init_sensor(int i2c_fd);
int read_sensor_data(int i2c_fd, int *ambient_light, int *proximity);
float convert_lux(int raw_value);
void log_data(float lux, int proximity);
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    int measurement_rate;
} sensor_config_t;

// Function to initialize the sensor
int init_sensor(int i2c_fd) {
    int part_id;

    // Verify part ID
    if (i2cReadByteData(i2c_fd, 0x00) < 0) {
        fprintf(stderr, "Error reading part ID. Check I2C connection.\n");
        return -1;
    }
    part_id = i2cReadByteData(i2c_fd, 0x00);
    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rate
    if (i2cWriteByteData(i2c_fd, MEASUREMENT_RATE_REG, 0x07) < 0) {
        fprintf(stderr, "Error writing to measurement rate register.\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_fd, int *ambient_light, int *proximity) {
    int raw_ambient, raw_proximity;

    // Read ambient light data
    raw_ambient = i2cReadWordData(i2c_fd, AMBIENT_LIGHT_REG);
    if (raw_ambient < 0) {
        fprintf(stderr, "Error reading ambient light data.\n");
        return -1;
    }

    // Read proximity data
    raw_proximity = i2cReadWordData(i2c_fd, PROXIMITY_REG);
    if (raw_proximity < 0) {
        fprintf(stderr, "Error reading proximity data.\n");
        return -1;
    }

    *ambient_light = raw_ambient;
    *proximity = raw_proximity;

    return 0;
}

// Function to convert raw ambient light to lux
float convert_lux(int raw_value) {
    return (float)raw_value * 0.1;
}

// Function to log data to file
void log_data(float lux, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_fp, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(log_fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    int ambient_light, proximity;
    float lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            // Convert ambient light to lux
            lux = convert_lux(ambient_light);

            // Log data
            log_data(lux, proximity);

            // Print to stdout
            printf("Lux: %.2f, Proximity: %d\n", lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for the next reading
        gpioDelay(READ_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (should not reach here in normal execution due to signal handler)
    i2cClose(i2c_fd);
    fclose(log_fp);
    gpioTerminate();

    return 0;
}

