// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define SI1145_REG_PS_DATA0 0x16
#define SI1145_REG_PS_DATA1 0x17
#define SI1145_REG_COMMAND 0x80
#define SI1145_REG_MEAS_RATE 0x06
#define SI1145_REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define SI1145_REG_ALS_VIS_ADC_GAIN 0x24
#define SI1145_REG_PS_ADC_GAIN 0x22
#define SI1145_REG_PS_LED21 0x0C
#define SI1145_REG_PS_LED3 0x0D
#define SI1145_REG_PS_ADC_MISC 0x11
#define SI1145_REG_COMMAND_PS_FORCE 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_write_register(int handle, int reg, int value);
int si1145_read_register(int handle, int reg);
int si1145_read_proximity(int handle);
void log_data(unsigned int proximity);
void signal_handler(int signal);

// Function to write to a Si1145 register
int si1145_write_register(int handle, int reg, int value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %d. Retrying...\n", reg, result);
            log_data(-1); // Log the error
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read from a Si1145 register
int si1145_read_register(int handle, int reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "Error reading from register 0x%02X: %d. Retrying...\n", reg, result);
            log_data(-1); // Log the error
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read from register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read the proximity value from the Si1145
int si1145_read_proximity(int handle) {
    int low_byte, high_byte;
    int result;

    low_byte = si1145_read_register(handle, SI1145_REG_PS_DATA0);
    if (low_byte < 0) return -1;

    high_byte = si1145_read_register(handle, SI1145_REG_PS_DATA1);
    if (high_byte < 0) return -1;

    return (high_byte << 8) | low_byte;
}

