int si1145_write_register(int handle, int reg, int value);
int si1145_read_register(int handle, int reg);
int si1145_read_proximity(int handle);
void log_data(unsigned int proximity);
void signal_handler(int signal);

// Function to write to a Si1145 register
int si1145_write_register(int handle, int reg, int value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %d. Retrying...\n", reg, result);
            log_data(-1); // Log the error
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read from a Si1145 register
int si1145_read_register(int handle, int reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "Error reading from register 0x%02X: %d. Retrying...\n", reg, result);
            log_data(-1); // Log the error
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read from register 0x%02X after multiple retries.\n", reg);
