#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
volatile static unsigned int start_tick, end_tick;
volatile static int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
void buzzer_control(int state);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that a rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset the flag after receiving the falling edge
    }
}

// Function to control the buzzer
void buzzer_control(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    buzzer_control(0); // Turn off the buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set up interrupt handler for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(50); // Delay to allow sensor to settle

        if (echo_received) {
            unsigned int pulse_width = end_tick - start_tick;
            if (pulse_width > 0) {
                float distance = (pulse_width * SPEED_OF_SOUND) / 2.0;
                printf("Distance: %.2f cm\n", distance);

                if (distance < DISTANCE_THRESHOLD) {
                    buzzer_control(1); // Turn on the buzzer
                } else {
                    buzzer_control(0); // Turn off the buzzer
                }
            } else {
                fprintf(stderr, "Error: Invalid pulse width: %u\n", pulse_width);
            }
        } else {
            fprintf(stderr, "Error: No echo received.\n");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    return 0;
}

