#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_timeout = 0;

// Function prototypes
void triggerSensor();
float getDistance();
void setServoAngle(float distance);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float getDistance() {
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_timeout = 0;

    triggerSensor();

    // Wait for echo to start
    int timeout_count = 0;
    while (echo_start_tick == 0 && timeout_count < 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (echo_start_tick == 0) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout error
    }

    // Wait for echo to end
    timeout_count = 0;
    while (echo_end_tick == 0 && timeout_count < 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (echo_end_tick == 0) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout error
    }

    // Calculate pulse width in microseconds
    int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    return distance;
}

// Function to set the servo angle based on distance
void setServoAngle(float distance) {
    // Map distance to pulse width (0-2500 us)
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (distance - SERVO_MIN_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (SERVO_MAX_DISTANCE - SERVO_MIN_DISTANCE));

    // Ensure pulse width is within valid range
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    }
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set servo to initial position (90 degrees)
    gpioServo(SERVO_PIN, 1500);
    gpioDelay(500); // Allow servo to settle

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        float distance = getDistance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            setServoAngle(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(100); // Update every 100 ms
    }

    return 0;
}

