#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate distance from pulse width
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate timeout
    return (pulse_width * 0.0343) / 2.0;
}

// Function to map distance to servo angle
int mapDistanceToAngle(float distance) {
    if (distance < 20.0) {
        return 0; // 0 degrees
    } else if (distance > 200.0) {
        return 180; // 180 degrees
    } else {
        return (int)(((distance - 20.0) / (200.0 - 20.0)) * 180.0); // Linear mapping
    }
}

// Function to set the servo angle
void setServoAngle(int angle) {
    int pulse_width = 0;
    if (angle == 0) {
        pulse_width = 500; // 0 degrees
    } else if (angle == 180) {
        pulse_width = 2500; // 180 degrees
    } else {
        pulse_width = (int)(500 + (pulse_width * (180.0 / 180.0))); // Linear mapping
    }
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulse_width = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to an angle
        int angle = mapDistanceToAngle(distance);

        // Set the servo angle
        setServoAngle(angle);

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Stop the servo and terminate pigpio
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();

    return 0;
}

