#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

int i2c_handle;

void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor (disable heater, set internal temperature)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10); // Wait for conversion

    while (1) {
        int raw_temperature = i2cReadWordData(i2c_handle, TEMP_REG);
        int raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);

        if (raw_temperature < 0 || raw_humidity < 0) {
            fprintf(stderr, "Failed to read temperature or humidity\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait before retrying
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            gpioDelay(1000); // Wait before retrying
            continue; // Retry the loop
        }

        float temperature = (175.72 * raw_temperature) / 65536.0 - 46.85;
        float humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        sleep(2);
    }

    return 0;
}

