#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I = 0x%02X\n", who_am_i);
        return -1;
    }

    // Reset the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error resetting MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range to ±250 deg/s
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring gyroscope range\n");
        return -1;
    }

    // Set sample rate divider to 7 for 125 Hz output
    if (i2cWriteByteData(i2c_handle, 0x19, 0x07) < 0) {
        fprintf(stderr, "Error setting sample rate divider\n");
        return -1;
    }

    // Clear sleep bit
    if (i2cWriteByteData(i2c_handle, 0x06, 0x00) < 0) {
        fprintf(stderr, "Error clearing sleep bit\n");
        return -1;
    }

    return 0;
