#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from the sensor
int read_temperature(int i2c_fd, int reg, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_fd, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert raw temperature to Celsius (example formula, adjust as needed)
    *temperature = (float)raw_temp * 0.02 - 273.15; // Example conversion

    return 0; // Indicate success
}

// Function to log temperature data to a file
int log_temperature(FILE *log_file, float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate error
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0; // Indicate success
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float ambient_temp, object_temp;

        // Read ambient temperature
        if (read_temperature(i2c_fd, AMBIENT_TEMP_REG, &ambient_temp) != 0) {
            fprintf(stderr, "Error reading ambient temperature\n");
            ambient_temp = -999.0; // Indicate error
        }

        // Read object temperature
        if (read_temperature(i2c_fd, OBJECT_TEMP_REG, &object_temp) != 0) {
            fprintf(stderr, "Error reading object temperature\n");
            object_temp = -999.0; // Indicate error
        }

        // Log temperature data
        if (log_temperature(log_file, ambient_temp, object_temp) != 0) {
            fprintf(stderr, "Error logging temperature data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

