#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define MEASUREMENT_COMMAND 0x2196
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow.log"

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_handle;
FILE *log_file;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
int convert_data(uint8_t *raw_data, sensor_data_t *sensor_data);
int log_data(sensor_data_t sensor_data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    int result = i2cWriteDevice(i2c_handle, (char[]){0x21, 0x96}, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
int convert_data(uint8_t *raw_data, sensor_data_t *sensor_data) {
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    sensor_data->pressure_pa = (float)raw_pressure / 60.0;
    sensor_data->temperature_c = (float)raw_temperature / 200.0;

    return 0;
}

// Log data to file
int log_data(sensor_data_t sensor_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data.pressure_pa, sensor_data.temperature_c);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t raw_data[6];
    sensor_data_t sensor_data;
    int retry_count;

    while (program_running) {
        retry_count = 0;
        while (retry_count < RETRY_COUNT) {
            if (send_measurement_command() == 0) {
                gpioDelay(1000); // Wait 1 ms
                if (read_sensor_data(raw_data) == 0) {
                    if (convert_data(raw_data, &sensor_data) == 0) {
                        log_data(sensor_data);
                        break; // Exit retry loop on success
                    }
                }
            }
            retry_count++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Exponential backoff
        }

        if (retry_count == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Sample every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

