#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <stdbool.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25

// Define the measurement command
#define MEASURE_CMD 0x362F

// Define the data structure
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t scale_factor;
} sdp800_data_t;

// Define the log file name
#define LOG_FILE "airflow_data.txt"

// Define the CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int init_i2c(const char *bus, int addr);
int send_command(int fd, uint16_t command);
int read_data(int fd, sdp800_data_t *data);
int validate_crc(const uint8_t *data, int len);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to send a command to the SDP800 sensor
int send_command(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read data from the SDP800 sensor
int read_data(int fd, sdp800_data_t *data) {
    uint8_t buf[9];
    int bytes_read = read(fd, buf, 9);

    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %d bytes read\n", bytes_read);
        return -1;
    }

    // Validate CRC for pressure
    if (!validate_crc(buf, 2)) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    // Validate CRC for temperature
    if (!validate_crc(buf + 3, 2)) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Validate CRC for scale factor
    if (!validate_crc(buf + 6, 2)) {
        fprintf(stderr, "CRC error for scale factor data\n");
        return -1;
    }

    // Assign the data to the struct
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = (uint8_t)buf[6];

    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Function to convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 240.0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return ((float)raw_temperature / 200.0) - 45.0;
}

// Function to log the data to a file
void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = false;
    printf("Caught signal %d, exiting gracefully...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write the header row to the log file
    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    fflush(log_file);

    sdp800_data_t data;

    // Main loop
    while (running) {
        // Trigger continuous measurement
        if (send_command(i2c_fd, MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Wait for approximately 45 ms
        usleep(50000); // 50 ms

        // Read the data
        if (read_data(i2c_fd, &data) < 0) {
            fprintf(stderr, "Failed to read data. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert the data
        float pressure = convert_pressure(data.pressure);
        float temperature = convert_temperature(data.temperature);

        // Log the data
        log_data(log_file, pressure, temperature);

        // Wait for 100 ms
        usleep(100000); // 100 ms
    }

    // Close the log file
    fclose(log_file);

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

