#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASUREMENT_COMMAND 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_THRESHOLD 1000
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log_file"

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    int error_code;
} sensor_data_t;

// CRC-8-ATM-32 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS30-DIS sensor
sensor_data_t read_temperature() {
    sensor_data_t data = {0.0, 0};
    uint8_t buffer[3];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(error_log_file, "%s I2C write error: %d\n", __TIME__, result);
        fflush(error_log_file);
        return data; // Return error code
    }

    // Wait for conversion (at least 15 ms)
    gpioDelay(15000); // 15 ms

    // Read 3 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 3);
    if (result != 3) {
        fprintf(error_log_file, "%s I2C read error: %d\n", __TIME__, result);
        fflush(error_log_file);
        return data; // Return error code
    }

    // Validate CRC checksum
    uint8_t crc = crc8(buffer, 2);
    if (crc != buffer[2]) {
        fprintf(error_log_file, "%s CRC mismatch: calculated 0x%02X, received 0x%02X\n", __TIME__, crc, buffer[2]);
        fflush(error_log_file);
        return data; // Return error code
    }

    // Convert raw data to temperature
    int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    data.temperature = -45 + 175.0 * (float)raw_temperature / 65535.0;

    return data;
}

// Function to log temperature data
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "%s Received signal %d, terminating...\n", __TIME__, signal);
    fflush(log_file);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_temperature();

        if (sensor_data.error_code == 0) {
            log_temperature(sensor_data.temperature);
        } else {
            fprintf(error_log_file, "%s Error reading temperature: %d\n", __TIME__, sensor_data.error_code);
            fflush(error_log_file);
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    fclose(log_file);
    fclose(error_log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

