#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "airflow_data.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_write_cmd(int fd, unsigned short command);
int i2c_read_data(int fd, unsigned char *data, int count);
int validate_crc(unsigned char data[], int len);
int convert_pressure(int raw_pressure);
int convert_temperature(int raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Function to write a command to the SDP800 sensor
int i2c_write_cmd(int fd, unsigned short command) {
    unsigned char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the SDP800 sensor
int i2c_read_data(int fd, unsigned char *data, int count) {
    if (read(fd, data, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Function to convert raw pressure to Pascals
int convert_pressure(int raw_pressure) {
    return (raw_pressure / 240.0);
}

// Function to convert raw temperature to Celsius
int convert_temperature(int raw_temperature) {
    return (raw_temperature / 200.0) - 45.0;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    unsigned char data[6];
    int raw_pressure, raw_temperature;
    float pressure, temperature;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Send continuous measurement command
        if (i2c_write_cmd(i2c_fd, MEASURE_CMD) < 0) {
            fprintf(stderr, "Error sending measurement command. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Wait for at least 1 ms
        usleep(1000);

        // Read 6 bytes of data
        if (i2c_read_data(i2c_fd, data, 6) < 0) {
            fprintf(stderr, "Error reading data. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(data, 2)) {
            fprintf(stderr, "CRC error for pressure data.\n");
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(data + 3, 2)) {
            fprintf(stderr, "CRC error for temperature data.\n");
            continue;
        }

        // Convert raw data to physical units
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Log the data
        if (log_data(pressure, temperature) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device and log file
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

