#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xEC05

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_command(int handle, unsigned short command);
int read_measurement(int handle, unsigned char *data, int bytes);
int verify_crc(unsigned char *data, int bytes);
sensor_data_t process_data(unsigned char *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // I2C bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(int handle, unsigned short command) {
    unsigned char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read measurement data from SCD40
int read_measurement(int handle, unsigned char *data, int bytes) {
    int result = i2cReadDevice(handle, (char *)data, bytes);
    if (result != bytes) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify CRC checksum
int verify_crc(unsigned char *data, int bytes) {
    for (int i = 0; i < bytes - 1; i++) {
        unsigned char crc = data[i + 1];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
        if (crc != data[i]) {
            fprintf(stderr, "CRC check failed at byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Process raw data and convert to CO2, temperature, and humidity
sensor_data_t process_data(unsigned char *data) {
    sensor_data_t sensor_data;
    int co2_raw = (data[0] << 8) | data[1];
    int temp_raw = (data[2] << 8) | data[3];
    int hum_raw = (data[4] << 8) | data[5];

    sensor_data.co2 = co2_raw;
    sensor_data.temperature = -45 + 175 * (float)temp_raw / 65535.0;
    sensor_data.humidity = 100 * (float)hum_raw / 65535.0;

    return sensor_data;
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Send Start Periodic Measurement command
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }

    // Wait for at least 1 second
    gpioDelay(1000); // 1000 ms = 1 second

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        unsigned char data[9];
        int data_ready = 0;

        // Poll the data-ready flag
        while (!data_ready && program_running) {
            if (send_command(i2c_handle, 0xE4B8) != 0) {
                fprintf(stderr, "Failed to send data-ready command\n");
                program_running = 0; // Exit loop if command fails
                break;
            }
            gpioDelay(10); // Small delay to avoid busy-waiting
            if (send_command(i2c_handle, 0xE4B8) != 0) {
                fprintf(stderr, "Failed to send data-ready command\n");
                program_running = 0; // Exit loop if command fails
                break;
            }
            if (read_measurement(i2c_handle, data, 9) == 0) {
                data_ready = 1;
            } else {
                fprintf(stderr, "Failed to read measurement data\n");
                program_running = 0; // Exit loop if read fails
                break;
            }
        }

        if (data_ready) {
            // Verify CRC for each 2-byte word
            if (verify_crc(data, 9) != 0) {
                fprintf(stderr, "CRC check failed\n");
                program_running = 0; // Exit loop if CRC check fails
                break;
            }

            // Process data
            sensor_data_t sensor_data = process_data(data);

            // Log data
            log_data(log_file, sensor_data);

            printf("CO2: %.2f ppm, Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.co2, sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Data not ready yet\n");
        }

        // Send Stop Periodic Measurement command after 5 seconds
        gpioDelay(5000); // 5000 ms = 5 seconds
        if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
            fprintf(stderr, "Failed to send stop command\n");
            program_running = 0; // Exit loop if stop command fails
            break;
        }
    }

    // Cleanup resources before exiting
    cleanup();
    return 0;
}

