int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int start_periodic_measurement() {
    uint8_t command[2] = {(START_PERIODIC_MEASUREMENT >> 8) & 0xFF, START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t command[2] = {(READ_MEASUREMENT >> 8) & 0xFF, READ_MEASUREMENT & 0xFF};
    char buffer[9];
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after write

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // Validate CRC for CO2
    if (!validate_crc((uint8_t*)buffer, 2)) {
        fprintf(stderr, "CO2 CRC validation failed\n");
        return -1;
    }

    // Validate CRC for Temperature
    if (!validate_crc((uint8_t*)(buffer + 3), 2)) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Validate CRC for Humidity
    if (!validate_crc((uint8_t*)(buffer + 6), 2)) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *humidity = (buffer[6] << 8) | buffer[7];

    return 0;
}

int stop_periodic_measurement() {
    uint8_t command[2] = {(STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, STOP_PERIODIC_MEASUREMENT & 0xFF};
