        if (data_ready_status & 0x01) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Validate CRC
                if (validate_crc((uint8_t*)&co2, 2) &&
                    validate_crc((uint8_t*)(buffer.data + (buffer.head - buffer.count + 1) % BUFFER_SIZE), 2) &&
                    validate_crc((uint8_t*)(buffer.data + (buffer.head - buffer.count + 2) % BUFFER_SIZE), 2)) {

