#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds
#define TIMEOUT_MS 50

static volatile int pulse_width = 0;
static volatile int total_cycle_width = 0;
static volatile int sensor_malfunction = 0;
static volatile int consecutive_failures = 0;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to log messages to the log file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to read temperature from the TMP05 sensor
float read_temperature() {
    int start_tick, end_tick;
    int edge_count = 0;
    int edge_width;
    int i;

    // Wait for the start of a new cycle
    while (gpioTick() < 0) {
        // Timeout after TIMEOUT_MS milliseconds
        if (sensor_malfunction || consecutive_failures > 3) {
            return -999.0; // Indicate sensor malfunction
        }
        if (log_file != NULL) {
            log_message("Timeout waiting for edge.");
        }
        gpioDelay(1000); // Wait 1ms
    }

    // Measure the total cycle width
    start_tick = gpioTick();
    while (gpioTick() < (start_tick + TIMEOUT_MS * 1000)) {
        // Timeout after TIMEOUT_MS milliseconds
        if (sensor_malfunction || consecutive_failures > 3) {
            return -999.0; // Indicate sensor malfunction
        }
        if (log_file != NULL) {
            log_message("Timeout waiting for end of cycle.");
        }
        gpioDelay(1000); // Wait 1ms
    }
    end_tick = gpioTick();
    total_cycle_width = end_tick - start_tick;

    // Measure the high pulse width
    start_tick = gpioTick();
    edge_count = 0;
    while (gpioTick() < (start_tick + TIMEOUT_MS * 1000)) {
        // Timeout after TIMEOUT_MS milliseconds
        if (sensor_malfunction || consecutive_failures > 3) {
            return -999.0; // Indicate sensor malfunction
        }
        if (log_file != NULL) {
            log_message("Timeout waiting for end of pulse.");
        }
        gpioDelay(1000); // Wait 1ms
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;

    // Validate sensor readings
    if (total_cycle_width == 0) {
        log_message("Error: Total cycle width is zero, invalid sensor reading.");
        return -999.0; // Indicate invalid reading
    }

    // Calculate temperature
    float temperature = 4215 - (2143 * pulse_width / total_cycle_width);

    // Check for out-of-range temperatures
    if (temperature < -40.0 || temperature > 150.0) {
        log_message("Error: Temperature reading out of range.");
        return -999.0; // Indicate out-of-range reading
    }

    return temperature;
}

// Function to log temperature readings to a file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s Temperature: %.2f °C\n", timestamp, temperature);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    consecutive_failures = 0;
    sensor_malfunction = 0; // Initialize sensor malfunction flag

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature != -999.0) {
            log_temperature(temperature);
        } else {
            log_message("Error: Failed to read temperature.");
        }

        consecutive_failures = 0; // Reset failure count on successful read
        if (temperature == -999.0) {
            sensor_malfunction = 1; // Set sensor malfunction flag
        }

        gpioDelay(SAMPLE_INTERVAL); // Wait for the next sample
    }

    // The following lines will never be reached in normal execution
    fclose(log_file);
    gpioTerminate();
    return 0;
}

