FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_fd, sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_fd, 0x00, MEASURE_CMD); // Register address 0x00
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (approx. 45ms)
    gpioDelay(50); // Wait 50ms

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_fd, 0x00, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    // Extract raw data
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t raw_scale_factor = (buffer[6] << 8) | buffer[7];

    // Convert raw data to physical units
    data->pressure = (float)raw_pressure / 240.0; // Pa
    data->temperature = (float)raw_temperature / 200.0; // °C

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *file, float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sdp810(i2c_fd, &sensor_data);
        if (result == 0) {
            // Log data to CSV file
            log_data(csv_file, sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000ms = 1 second
    }

    // Close I2C device and CSV file
    i2cClose(i2c_fd);
    fclose(csv_file);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

