        return -1;
    }
    gpioDelay(10); // Wait for reset to complete
    return 0;
}

// Function to read temperature from the sensor
int read_temperature(float *temperature) {
    unsigned char data[2];
    int result;

    result = i2cWriteByteData(i2c_fd, 0x00, TEMP_MEASURE_HOLD);
    if (result < 0) {
