                crc_calculated = (crc_calculated << 1) ^ CRC8_POLY;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    if (crc_calculated != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    *temperature = (float)((data[0] << 8) | data[1]) / 16.0;
    return 0;
}

