    unsigned char data[2];
    int result;

    result = i2cWriteByteData(i2c_fd, 0x00, HUMID_MEASURE_HOLD);
    if (result < 0) {
        fprintf(stderr, "Failed to write humidity measurement command\n");
        return -1;
    }
    gpioDelay(50); // Wait for measurement (datasheet says 50ms)

    result = i2cReadI2CBlockData(i2c_fd, 0x00, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }

    // CRC check for humidity
    unsigned char humidity_data[2] = {data[0], data[1]};
    unsigned char crc_calculated = 0;
    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC8_POLY;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    if (crc_calculated != data[2]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 16.0;
    return 0;
}

// Function to log data to a CSV file
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    reset_sensor();

    while (1) {
        float temperature, humidity;

        if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Logging ERROR values.\n");
            log_data(-999.0, -999.0); // Log error values
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    return 0;
}

