#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "airflow.dat"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send continuous measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion time (datasheet recommends 20ms)
    gpioDelay(20000); // 20ms

    // Read 9 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // Scale factor extraction
    uint8_t scale_factor_msb = buffer[6];
    uint8_t scale_factor_lsb1 = buffer[7];
    uint8_t scale_factor_lsb2 = buffer[8];

    // Combine scale factor bytes into a 16-bit value
    uint16_t scale_factor = (scale_factor_msb << 8) | scale_factor_lsb1;
    scale_factor |= (scale_factor_lsb2 & 0xF0) >> 4; // Shift and combine LSB2

    // Convert raw values to physical units
    data->pressure = (float)raw_pressure / scale_factor - 1000.0;
    data->temperature = (float)raw_temperature / 200.0 - 45.0;

    return 0;
}

// Function to log data to a file
int log_data(FILE *file, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Error writing pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp810(i2c_handle, &sensor_data) == 0) {
            // Log data to file
            if (log_data(log_file, sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

