#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // Hz
#define LOG_FILE "flow_log.txt"

// Sensor calibration parameters (from datasheet)
#define ZERO_PRESSURE_FLOW 0.0 // SLPM
#define MAX_PRESSURE_FLOW 10.0 // SLPM

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int16_t *raw_flow);
float calculate_flow_rate(int16_t raw_flow);
int set_fan_speed(float flow_rate);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    float flow_rate;
} sensor_data_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO to output mode
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *raw_flow) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }

    // Combine the two bytes into a 16-bit word
    *raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);

    // Mask off status bits
    *raw_flow = (*raw_flow >> 2) & 0x3FFF; // Keep only 14 bits

    return 0;
}

// Function to calculate flow rate
float calculate_flow_rate(int16_t raw_flow) {
    float flow_rate = (float)raw_flow / 14745.0 * MAX_PRESSURE_FLOW;
    return flow_rate;
}

// Function to set fan speed
int set_fan_speed(float flow_rate) {
    // Map flow rate to PWM duty cycle (0-100%)
    int duty_cycle = (int)(flow_rate / MAX_PRESSURE_FLOW * 100.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    // Set PWM duty cycle
    gpioPWM(FAN_GPIO, duty_cycle);

    return 0;
}

// Function to log data
int log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    // Stop the fan
    gpioPWM(FAN_GPIO, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    int16_t raw_flow;
    float flow_rate;

    while (!terminate) {
        if (read_sensor_data(&raw_flow) == 0) {
            flow_rate = calculate_flow_rate(raw_flow);
            set_fan_speed(flow_rate);
            log_data(flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    cleanup();
    return 0;
}

