#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int32_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int check_who_am_i();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Check WHO_AM_I register
int check_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xB1, got 0x%02X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed.\n");
    return 0;
}

// Configure the LPS33HW sensor
int configure_sensor() {
    // Set CTRL_REG1 to 0xB0 (Block data update, 10 Hz, active mode)
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
