#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
float read_temperature();
void update_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int stlm75_address;
    int led_gpio;
    float temperature_threshold;
} Config;

Config config = {I2C_BUS, STLM75_ADDR, LED_GPIO, TEMP_THRESHOLD};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature != -1000.0) { // Assuming -1000.0 indicates an error
            update_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping iteration.\n");
        }
        gpioDelay(1000); // 1 second delay
    }

    // Cleanup
    gpioWrite(config.led_gpio, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.stlm75_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from STLM75
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1000.0; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Swap bytes (pigpio returns little-endian)
    raw_temp = (raw_temp >> 8) | (raw_temp << 8);

    // Extract the 9-bit temperature value
    int16_t temp_value = raw_temp & 0x3FFF; // Mask to get the 9-bit value

    // Convert to Celsius (2^9 = 512, so each bit is 0.0625 degrees C)
    float temperature = temp_value * 0.0625;

    return temperature;
}

// Update circular buffer
void update_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate running average
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average temperature
void control_led(float average_temperature) {
    if (average_temperature > config.temperature_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn on LED
    } else {
        gpioWrite(config.led_gpio, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating program...\n");
    terminate = 1;
}

