#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
int verify_checksum(uint8_t *data, int len);
int convert_raw_to_pressure(uint8_t raw_pressure);
int convert_raw_to_temperature(uint8_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SDP32
int send_command(int handle, uint16_t command) {
    uint8_t cmd[2];
    cmd[0] = (command >> 8) & 0xFF;
    cmd[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP32
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify the CRC-8 checksum
int verify_checksum(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Convert raw pressure to Pascals
int convert_raw_to_pressure(uint8_t raw_pressure) {
    return (int16_t)raw_pressure;
}

// Convert raw temperature to Celsius
int convert_raw_to_temperature(uint8_t raw_temperature) {
    return (int16_t)raw_temperature;
}

// Log the pressure and temperature data with a timestamp
void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
}

int main(int argc, char *argv[]) {
    int sample_interval_ms = SAMPLE_INTERVAL_MS;

    // Parse command-line argument for sample interval
    if (argc > 1) {
        sample_interval_ms = atoi(argv[1]);
        if (sample_interval_ms <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default value: %d ms\n", SAMPLE_INTERVAL_MS);
            sample_interval_ms = SAMPLE_INTERVAL_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[9];
    int raw_pressure, raw_temperature;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data, 9) == 0) {
            // Verify checksums
            if (verify_checksum(sensor_data, 3) &&
                verify_checksum(sensor_data + 3, 3) &&
                verify_checksum(sensor_data + 6, 3)) {

                // Convert raw data to pressure and temperature
                raw_pressure = (sensor_data[0] << 8) | sensor_data[1];
                raw_temperature = (sensor_data[3] << 8) | sensor_data[4];

                pressure = convert_raw_to_pressure(raw_pressure);
                temperature = convert_raw_to_temperature(raw_temperature);

                // Log the data
                log_data(pressure, temperature);
            } else {
                fprintf(stderr, "Checksum verification failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(sample_interval_ms * 1000); // Delay in microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

