#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_CONTINUOUS 0x3615
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_INIT_2 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, sensor_data_t *data) {
    uint8_t cmd[2] = {(CMD_CONTINUOUS >> 8) & 0xFF, CMD_CONTINUOUS & 0xFF};
    uint8_t buffer[9];
    int result;

    // Send continuous measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 45 ms
    gpioDelay(50000); // 50 ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    for (int i = 0; i < 3; i++) {
        uint8_t crc = crc8(buffer + 2 * i, 2);
        if (crc != buffer[2 + 2 * i]) {
            fprintf(stderr, "CRC mismatch in pressure data at byte %d\n", i);
            return -1;
        }
    }

    for (int i = 3; i < 6; i++) {
        uint8_t crc = crc8(buffer + 5 + 2 * i, 2);
        if (crc != buffer[5 + 2 * i]) {
            fprintf(stderr, "CRC mismatch in temperature data at byte %d\n", i);
            return -1;
        }
    }

    for (int i = 6; i < 9; i++) {
        uint8_t crc = crc8(buffer + 8 + 2 * i, 2);
        if (crc != buffer[8 + 2 * i]) {
            fprintf(stderr, "CRC mismatch in scale factor data at byte %d\n", i);
            return -1;
        }
    }

    // Convert raw values to physical units
    data->pressure = (float)((int16_t)(buffer[0] << 8 | buffer[1])) / 60.0f;
    data->temperature = (float)((int16_t)(buffer[3] << 8 | buffer[4])) / 200.0f;

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp810(i2c_handle, &sensor_data) == 0) {
            // Log data to stdout
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

