#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 registers
#define CONFIG_REG 0x02
#define TEMP_REG 0x00

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_setup(int bus, int addr);
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int i2c_read_data(int fd, uint8_t reg, uint8_t *data, int len);
int hdc1000_init(int fd);
int hdc1000_read_data(int fd, sensor_data_t *data);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// I2C setup function
int i2c_setup(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t data[1];
    data[0] = reg;
    if (write(fd, data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return data[0];
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;
    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read data function
int i2c_read_data(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }
    return 0;
}

// HDC1000 initialization function
int hdc1000_init(int fd) {
    // Configure the HDC1000 for temperature and humidity measurement
    if (i2c_write_register(fd, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }
    return 0;
}

// HDC1000 read data function
int hdc1000_read_data(int fd, sensor_data_t *data) {
    uint8_t raw_data[4];
    if (i2c_read_data(fd, TEMP_REG, raw_data, 4) < 0) {
        fprintf(stderr, "Error reading data from HDC1000\n");
        return -1;
    }

    // Combine the two bytes for temperature and humidity
    int16_t raw_temperature = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_humidity = (raw_data[2] << 8) | raw_data[3];

    // Convert the raw data to temperature and humidity
    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_setup(1, HDC1000_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Initialize HDC1000 sensor
    if (hdc1000_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize HDC1000 sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity data
        if (hdc1000_read_data(i2c_fd, &sensor_data) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

