#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor I2C address
#define ICP10101_ADDR 0x63

// Define measurement command
#define MEASURE_CMD 0x40

// Define measurement delay
#define MEASURE_DELAY 7

// Define scale_factor_lut size
#define SCALE_FACTOR_LUT_SIZE 8

// Define calibration coefficients
int16_t scale_factor_lut[SCALE_FACTOR_LUT_SIZE];
int16_t scale_factor_h[SCALE_FACTOR_LUT_SIZE];
int16_t scale_factor_p[SCALE_FACTOR_LUT_SIZE];

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration data
typedef struct {
    int16_t scale_factor_lut_val;
    int16_t scale_factor_h_val;
    int16_t scale_factor_p_val;
} calibration_data_t;

calibration_data_t calibration_data;

// Function prototypes
int read_calibration_coefficients();
int trigger_measurement();
int read_raw_data(int16_t *raw_temperature, int16_t *raw_pressure);
double calculate_temperature(int16_t raw_temperature);
double calculate_pressure(int16_t raw_pressure, double temperature);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read calibration coefficients from the sensor
int read_calibration_coefficients() {
    char buf[8];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x50, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    // Extract calibration coefficients from the buffer
    calibration_data.scale_factor_lut_val = (buf[0] << 8) | buf[1];
    calibration_data.scale_factor_h_val = (buf[2] << 8) | buf[3];
    calibration_data.scale_factor_p_val = (buf[4] << 8) | buf[5];

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement() {
    char buf[1];
    int result;

    buf[0] = MEASURE_CMD;

    result = i2cWriteI2CBlockData(i2c_handle, 0x00, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    gpioDelay(MEASURE_DELAY * 1000); // Delay in microseconds
    return 0;
}

// Function to read raw temperature and pressure data from the sensor
int read_raw_data(int16_t *raw_temperature, int16_t *raw_pressure) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    *raw_pressure = (buf[2] << 24) | (buf[3] << 16) | (buf[4] << 8) | buf[5];

    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int16_t raw_temperature) {
    double temp = (double)raw_temperature / 100.0;
    return temp;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int16_t raw_pressure, double temperature) {
    double pressure = (double)raw_pressure / 100.0;
    return pressure;
}

// Function to log the temperature and pressure data with an ISO-8601 timestamp
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    int result;
    int16_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            gpioDelay(5000000); // Wait 5 seconds
            continue;
        }

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw data. Retrying in 5 seconds.\n");
            gpioDelay(5000000); // Wait 5 seconds
            continue;
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, temperature);

        // Log the data
        log_data(temperature, pressure);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

