    terminate = 1;
}

// Function to read pressure data from the MLX90819 sensor
int read_pressure(int i2c_handle) {
    char buf[2];
    int result;

    // Trigger a measurement (replace with actual trigger command if needed)
    // For MLX90819, no trigger is needed, it's a continuous measurement mode
    // gpioWrite(TRIGGER_PIN, 1); // Example trigger pin
    gpioDelay(100); // Wait for measurement to complete (adjust as needed)

    // Read the pressure data
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_MSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the MSB and LSB to get the raw pressure value
    int raw_pressure = (buf[0] << 8) | buf[1];

    return raw_pressure;
}

// Function to convert raw pressure to kPa
float convert_to_kPa(int raw_pressure) {
    return raw_pressure * SCALING_FACTOR;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

