    gpioDelay(100); // Wait for measurement to complete (adjust as needed)

    // Read the pressure data
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_MSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the MSB and LSB to get the raw pressure value
    int raw_pressure = (buf[0] << 8) | buf[1];

    return raw_pressure;
}

// Function to convert raw pressure to kPa
float convert_to_kPa(int raw_pressure) {
    return raw_pressure * SCALING_FACTOR;
}

// Function to get the current timestamp
