    i2c_handle = i2cOpen(I2C_BUS, MLX90819_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the pressure value
        int raw_pressure = read_pressure(i2c_handle);
        if (raw_pressure < 0) {
            fprintf(stderr, "Error reading pressure, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert the raw pressure to kPa
        float pressure_kPa = convert_to_kPa(raw_pressure);

        // Get the current timestamp
        char timestamp[20];
        get_timestamp(timestamp);

        // Log the pressure reading to stdout
        printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // Close the I2C device
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

