    int16_t temperature;
    uint8_t crc_pressure;
    uint8_t crc_temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buf[9];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 9);

    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    // Validate CRC for pressure
    uint8_t pressure_data[2] = {buf[0], buf[1]};
    uint8_t pressure_crc = buf[2];
    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temperature_data[2] = {buf[3], buf[4]};
    uint8_t temperature_crc = buf[5];
    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Populate the sensor data struct
    data->pressure = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
