    signal(SIGTERM, signal_handler);

    // Send continuous measurement command
    char cmd[2] = {(CMD_CONTINUOUS >> 8) & 0xFF, CMD_CONTINUOUS & 0xFF};
    int bytes_written = i2cWriteI2CBlockData(i2c_handle, 0x00, cmd, 2);
    if (bytes_written != 2) {
        fprintf(stderr, "Error sending continuous measurement command: %d\n", bytes_written);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            if (log_data(log_file, sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }
        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

