// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01
#define SAFETY_MIN 200.0
#define SAFETY_MAX 250.0
#define LOG_FILE "pressure_log.csv"
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int read_pressure(float *pressure);
void log_pressure(float pressure);
void check_safety(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int mlx90821_address;
    char *log_file_name;
    float safety_min;
    float safety_max;
} config_t;

config_t config = {
    I2C_BUS,
    MLX90821_ADDR,
    LOG_FILE,
    SAFETY_MIN,
    SAFETY_MAX
};

int main() {
    float pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
            check_safety(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying in 1 second.\n");
        }
        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

