#include <errno.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASUREMENT_COMMAND 0x00
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_MAX_SIZE 1048576 // 1 MB
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_sensor_data(uint8_t *data);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the HIH6130
int read_sensor_data(uint8_t *data) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Check status bits (bit 7 of byte 0)
    if (buf[0] & 0x80) {
        fprintf(stderr, "Sensor not present or busy\n");
        return -1;
    }

    data[0] = buf[0];
    data[1] = buf[1];
    data[2] = buf[2];
    data[3] = buf[3];

    return 0;
}

// Validate sensor data
int validate_sensor_data(uint8_t *data) {
    if ((data[0] & 0x07) != 0) {
        fprintf(stderr, "Invalid sensor data: Status bits are not 0\n");
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int raw_T = (data[0] << 8) | data[1];
    int raw_H = (data[2] << 8) | data[3];

    sensor_data.temperature = raw_T * 165.0 / 16383.0 - 40.0;
    sensor_data.humidity = raw_H * 100.0 / 16383.0;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

