#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define SENT_DATA_PIN 4
#define SENT_CLOCK_PIN 17
#define SENT_ENABLE_PIN 27

// Define constants
#define SENT_SYNC_PULSE_US 56
#define SENT_STATUS_NIBBLE_US 4
#define SENT_DATA_NIBBLE_US 4
#define SENT_CHECKSUM_NIBBLE_US 4
#define MAX_PULSE_WIDTH_US 271
#define CHECKSUM_MODULO 16
#define PRESSURE_SCALE 0.1 // Pa/raw unit
#define PRESSURE_OFFSET 0.0 // Pa

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data;
    unsigned int checksum;
} SENT_Data;

// Function prototypes
int initialize_gpio();
SENT_Data read_sent_data();
float convert_raw_to_pressure(unsigned int raw_value);
int validate_checksum(SENT_Data data);
int detect_sensor_absence();
int log_pressure_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_DATA_PIN, PI_INPUT);
    gpioSetMode(SENT_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SENT_ENABLE_PIN, PI_OUTPUT);

    gpioWrite(SENT_ENABLE_PIN, 0); // Disable sensor initially

    return 0;
}

// Function to read SENT data
SENT_Data read_sent_data() {
    SENT_Data data = {0, 0, 0};
    unsigned int pulse_width;
    unsigned int status, data_value, checksum;

    // Wait for synchronization pulse
    int timeout = 0;
    while (gpioRead(SENT_DATA_PIN) == 0 && timeout < 1000) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }
    if (timeout >= 1000) {
        fprintf(stderr, "Timeout waiting for synchronization pulse\n");
        data.status = 0; // Indicate error
        return data;
    }

    // Read status nibble
    gpioWrite(SENT_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay
    pulse_width = gpioRead(SENT_DATA_PIN);
    if (pulse_width < 12 || pulse_width > MAX_PULSE_WIDTH_US) {
        fprintf(stderr, "Invalid status nibble pulse width: %d\n", pulse_width);
        data.status = 0; // Indicate error
        return data;
    }
    data.status = pulse_width;

    // Read data nibbles
    for (int i = 0; i < 3; i++) {
        gpioWrite(SENT_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
        pulse_width = gpioRead(SENT_DATA_PIN);
        if (pulse_width < 12 || pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid data nibble pulse width: %d\n", pulse_width);
            data.data = 0; // Indicate error
            return data;
        }
        data.data = (data.data << 1) | pulse_width;
    }

    // Read checksum nibble
    for (int i = 0; i < 3; i++) {
        gpioWrite(SENT_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
        pulse_width = gpioRead(SENT_DATA_PIN);
        if (pulse_width < 12 || pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid checksum nibble pulse width: %d\n", pulse_width);
            data.checksum = 0; // Indicate error
            return data;
        }
        data.checksum = (data.checksum << 1) | pulse_width;
    }

    return data;
}

// Function to convert raw value to pressure
float convert_raw_to_pressure(unsigned int raw_value) {
    return (float)raw_value * PRESSURE_SCALE + PRESSURE_OFFSET;
}

// Function to validate checksum
int validate_checksum(SENT_Data data) {
    unsigned int calculated_checksum = 0;
    for (int i = 0; i < 4; i++) {
        calculated_checksum += data.status;
        calculated_checksum += data.data;
        calculated_checksum += data.checksum;
    }
    return (calculated_checksum % CHECKSUM_MODULO) == 0;
}

// Function to detect sensor absence
int detect_sensor_absence() {
    return gpioRead(SENT_DATA_PIN); // Check if data pin is low
}

// Function to log pressure data
int log_pressure_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(SENT_ENABLE_PIN, 1); // Disable sensor
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Brake pressure monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read SENT data
        SENT_Data sent_data = read_sent_data();

        // Check for errors
        if (sent_data.status == 0 || !validate_checksum(sent_data) || detect_sensor_absence()) {
            fprintf(stderr, "Error: SENT data invalid or sensor absent\n");
        } else {
            // Convert raw value to pressure
            unsigned int raw_value = (sent_data.data >> 12) & 0x3FFF; // Extract 12-bit data
            if (raw_value & 0x2000) {
                raw_value |= 0xC000; // Sign extend if negative
            }
            float pressure = convert_raw_to_pressure(raw_value);

            // Log pressure data
            log_pressure_data(pressure);

            printf("Pressure: %.2f Pa\n", pressure);
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

