        gpioWrite(SENT_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
        pulse_width = gpioRead(SENT_DATA_PIN);
        if (pulse_width < 12 || pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid data nibble pulse width: %d\n", pulse_width);
            data.data = 0; // Indicate error
            return data;
        }
        data.data = (data.data << 1) | pulse_width;
    }

    // Read checksum nibble
    for (int i = 0; i < 3; i++) {
        gpioWrite(SENT_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
        pulse_width = gpioRead(SENT_DATA_PIN);
        if (pulse_width < 12 || pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid checksum nibble pulse width: %d\n", pulse_width);
            data.checksum = 0; // Indicate error
            return data;
        }
        data.checksum = (data.checksum << 1) | pulse_width;
    }

    return data;
}

// Function to convert raw value to pressure
float convert_raw_to_pressure(unsigned int raw_value) {
    return (float)raw_value * PRESSURE_SCALE + PRESSURE_OFFSET;
}

// Function to validate checksum
int validate_checksum(SENT_Data data) {
    unsigned int calculated_checksum = 0;
    for (int i = 0; i < 4; i++) {
        calculated_checksum += data.status;
        calculated_checksum += data.data;
        calculated_checksum += data.checksum;
    }
    return (calculated_checksum % CHECKSUM_MODULO) == 0;
}

// Function to detect sensor absence
int detect_sensor_absence() {
    return gpioRead(SENT_DATA_PIN); // Check if data pin is low
}

// Function to log pressure data
int log_pressure_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(SENT_ENABLE_PIN, 1); // Disable sensor
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Brake pressure monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read SENT data
        SENT_Data sent_data = read_sent_data();

        // Check for errors
        if (sent_data.status == 0 || !validate_checksum(sent_data) || detect_sensor_absence()) {
            fprintf(stderr, "Error: SENT data invalid or sensor absent\n");
        } else {
            // Convert raw value to pressure
            unsigned int raw_value = (sent_data.data >> 12) & 0x3FFF; // Extract 12-bit data
            if (raw_value & 0x2000) {
                raw_value |= 0xC000; // Sign extend if negative
            }
            float pressure = convert_raw_to_pressure(raw_value);

            // Log pressure data
            log_pressure_data(pressure);

            printf("Pressure: %.2f Pa\n", pressure);
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

