#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define FILENAME "greenhouse_temps.dat"

static volatile int running = 1;
static int i2c_handle;

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;
    int device_id;
    float temperature;
    char buffer[4];
    FILE *fp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    result = i2cReadByteData(i2c_handle, 0x01);
    if (result < 0) {
        fprintf(stderr, "Failed to read device ID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    device_id = i2cReadByteData(i2c_handle, 0x01);
    if (device_id != 0x0117) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("TMP117 device ID verified: 0x%02X\n", device_id);

    // Open data file for appending
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        result = i2cReadWordData(i2c_handle, TEMP_REG);
        if (result < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            continue; // Try again
        }
        temperature = (float)result;

        // Convert to little-endian
        buffer[0] = (temperature >> 24) & 0xFF;
        buffer[1] = (temperature >> 16) & 0xFF;
        buffer[2] = (temperature >> 8) & 0xFF;
        buffer[3] = temperature & 0xFF;

        // Write to file
        if (fwrite(buffer, 1, 4, fp) != 4) {
            fprintf(stderr, "Failed to write to data file: %s\n", strerror(errno));
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

