#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASUREMENT_COMMAND 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "environmental_data.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8-H2F checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(data, 2) != data[2] || crc8(data + 3, 1) != data[4]) {
        fprintf(stderr, "CRC checksum validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_hum = (data[3] << 8) | data[4];

    *temperature = -45 + 175 * (raw_temp / 65535.0);
    *humidity = -6 + 125 * (raw_hum / 65535.0) % 100;

    return 0;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_sht40(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

