#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for the circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float value);
void save_to_file(const CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a temperature reading to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Save the contents of the circular buffer to a file
void save_to_file(const CircularBuffer *cb) {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        perror("Error opening temperature_log.dat for writing");
        return;
    }

    fwrite(cb->buffer, sizeof(float), cb->count, fp);
    fclose(fp);
}

// Initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read the temperature from the TMP117 sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate an error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert the raw temperature to Celsius
    float temperature = (float)raw_temp * 0.0078125;

    return temperature;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize the circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the temperature
        float temperature = read_temperature();
        if (temperature > -999.0) {
            // Add the temperature to the circular buffer
            add_to_buffer(&temp_buffer, temperature);

            // Save the buffer to the file
            save_to_file(&temp_buffer);

            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

