        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate an error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert the raw temperature to Celsius
    float temperature = (float)raw_temp * 0.0078125;

    return temperature;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
