    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    uint8_t temp_data[2] = {data[0], data[1]};
    uint8_t hum_data[2] = {data[3], data[4]};

    uint8_t temp_crc = crc8(temp_data, 2);
    uint8_t hum_crc = crc8(hum_data, 2);

    if (temp_crc != data[2] || hum_crc != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[3] << 8) | data[4];

