        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_shtc3(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Validate data
            if (temperature >= -40.0 && temperature <= 125.0 && humidity >= 0.0 && humidity <= 100.0) {
                // Log data
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                // Print data
                print_data(temperature, humidity);
            } else {
                fprintf(stderr, "Invalid sensor data: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SLEEP_SECONDS * 1000000); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

