#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_REG 0x00
#define TEMP_REG 0x01
#define MAG_TEMP_LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float magnetic_field;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *magnetic_field_raw, int16_t *temperature_raw);
sensor_data_t convert_sensor_data(int16_t raw_mag, int16_t raw_temp);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data from the Si7202
int read_sensor_data(int16_t *magnetic_field_raw, int16_t *temperature_raw) {
    char buf[4];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, MAG_REG, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    *magnetic_field_raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature_raw = (int16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Convert raw sensor data to magnetic field (Gauss) and temperature (Celsius)
sensor_data_t convert_sensor_data(int16_t raw_mag, int16_t raw_temp) {
    sensor_data_t data;
    data.magnetic_field = (float)raw_mag * 0.1;
    data.temperature = (float)raw_temp * 0.01 - 25.0;
    return data;
}

// Log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(MAG_TEMP_LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", MAG_TEMP_LOG_FILE);
            return -1;
        }
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.magnetic_field, data.temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (!terminate) {
        int16_t magnetic_field_raw, temperature_raw;

        if (read_sensor_data(&magnetic_field_raw, &temperature_raw) == 0) {
            sensor_data_t data = convert_sensor_data(magnetic_field_raw, temperature_raw);
            if (isnan(data.magnetic_field) || isnan(data.temperature)) {
                fprintf(stderr, "Error: Invalid sensor data, logging NaN values.\n");
            } else {
                if (log_data(data) != 0) {
                    fprintf(stderr, "Error: Failed to log data.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Logging NaN values.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    cleanup();
    return 0;
}

