#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define RETRY_COUNT 3

int i2c_handle;

// Function to handle errors
void error_handler(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_FAILURE);
}

// Function to read temperature from TMP117
float read_temperature() {
    int raw_temp;
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, TEMP_REG);
        if (result >= 0) {
            raw_temp = (int16_t)result;
            // Check for negative temperatures
            if (raw_temp & 0x8000) {
                raw_temp |= 0xF000; // Sign extend
            }
            return (float)raw_temp * 0.0078125;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -273.15; // Return absolute zero as error indicator
}

// Function to log temperature to file
void log_temperature(float temperature) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        error_handler("Failed to open temperature_log.txt");
    }

    fprintf(fp, "%s, Temperature: %.4f C\n", timestamp, temperature);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        error_handler("pigpio initialisation failed");
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        error_handler("Failed to open I2C bus");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        temperature = read_temperature();

        if (temperature != -273.15) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Logging error.\n");
