    exit(EXIT_FAILURE);
}

// Function to read temperature from TMP117
float read_temperature() {
    int raw_temp;
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, TEMP_REG);
        if (result >= 0) {
            raw_temp = (int16_t)result;
            // Check for negative temperatures
            if (raw_temp & 0x8000) {
                raw_temp |= 0xF000; // Sign extend
            }
            return (float)raw_temp * 0.0078125;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -273.15; // Return absolute zero as error indicator
}

