    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    // Combine the bytes to form the raw flow and temperature values
    int raw_flow = (buffer[0] << 8) | buffer[1];
    int raw_temp = (buffer[2] << 8) | buffer[3];

    // Validate the raw data
    if (raw_flow < 0 || raw_flow > 65535) {
        fprintf(stderr, "Error: Invalid raw flow value: %d\n", raw_flow);
        return -1;
    }

    if (raw_temp < 0 || raw_temp > 65535) {
        fprintf(stderr, "Error: Invalid raw temperature value: %d\n", raw_temp);
        return -1;
    }

    data->flow_rate = convert_flow(raw_flow);
    data->temperature = convert_temp(raw_temp);

    return 0;
}

// Function to convert raw flow data to SLPM
float convert_flow(int raw_flow) {
    return ((float)raw_flow / 16384.0) - 0.1 / 0.8 * 25.0;
}

