#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define DHT11_PIN 4
#define START_PIN 17
#define DATA_PIN 27

// Define constants
#define START_PULSE_MIN 18000  // 18 ms
#define START_PULSE_MAX 22000  // 22 ms
#define DATA_HIGH_MIN 80000   // 80 us
#define DATA_HIGH_MAX 120000  // 120 us
#define DATA_LOW_MIN 50000    // 50 us
#define DATA_LOW_MAX 150000   // 150 us
#define CHECKSUM_MIN 40000    // 40 us
#define CHECKSUM_MAX 160000   // 160 us
#define CHECKSUM_THRESHOLD 10000 // 10 ms
#define TIMEOUT_START 1000000 // 1 ms
#define TIMEOUT_DATA 10000000 // 10 ms
#define TIMEOUT_CHECKSUM 1000000 // 10 ms
#define TIMEOUT_TOTAL 2000000  // 20 ms

// Global variables
static volatile int timeout_start = 0;
static volatile int timeout_data = 0;
static volatile int timeout_checksum = 0;
static volatile int timeout_total = 0;
static volatile int timeout_start_flag = 0;
static volatile int timeout_data_flag = 0;
static volatile int timeout_checksum_flag = 0;
static volatile int timeout_total_flag = 0;
static FILE *log_file = NULL;
static int dht11_present = 0;

// Function prototypes
int gpio_init();
int gpio_set_mode(int pin, int mode);
int gpio_write(int pin, int value);
int gpio_read(int pin);
int dht11_start_pulse();
int dht11_check_response();
int dht11_read_data(unsigned char *data);
int dht11_validate_checksum(const unsigned char *data);
int dht11_read_sensor(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold DHT11 data
typedef struct {
    float temperature;
    float humidity;
} DHT11Data;

int main() {
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        DHT11Data data;
        if (dht11_read_sensor(&data.temperature, &data.humidity) == 0) {
            log_data(data.temperature, data.humidity);
        } else {
            fprintf(stderr, "DHT11 read failed. Retrying in 2 seconds.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(DHT11_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set DHT11_PIN mode\n");
        return 1;
    }
    if (gpioSetMode(START_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set START_PIN mode\n");
        return 1;
    }
    if (gpioSetMode(DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set DATA_PIN mode\n");
        return 1;
    }

    return 0;
}

int gpio_set_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", pin);
        return 1;
    }
    return 0;
}

int gpio_write(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "Failed to write value %d to GPIO %d\n", value, pin);
        return 1;
    }
    return 0;
}

int gpio_read(int pin) {
    return gpioRead(pin);
}

int dht11_start_pulse() {
    gpioWrite(START_PIN, 0);
    gpioDelay(START_PULSE_MIN);
    gpioWrite(START_PIN, 1);
    gpioDelay(START_PULSE_MAX);
    return 0;
}

int dht11_check_response() {
    timeout_start = 0;
    timeout_data = 0;
    timeout_checksum = 0;
    timeout_total = 0;
    timeout_start_flag = 0;
    timeout_data_flag = 0;
    timeout_checksum_flag = 0;
    timeout_total_flag = 0;

    // Check for start pulse
    if (gpio_read(DHT11_PIN) != 0) {
        fprintf(stderr, "DHT11 start pulse check failed: No start pulse detected.\n");
        return 1;
    }

    gpioDelay(1000); // Wait 1 ms

    // Check for response
    if (gpio_read(DHT11_PIN) != 1) {
        fprintf(stderr, "DHT11 response check failed: No response detected.\n");
        return 1;
    }

    gpioDelay(1000); // Wait 1 ms

    // Check for data bits
    if (dht11_read_data((unsigned char *)NULL) != 0) {
        fprintf(stderr, "DHT11 data check failed: No data bits detected.\n");
        return 1;
    }

    return 0;
}

int dht11_read_data(unsigned char *data) {
    int i;
    unsigned char bit;

    for (i = 0; i < 32; i++) {
        if (gpio_read(DHT11_PIN) == 0) {
            bit = 1;
        } else {
            bit = 0;
        }

        if (gpio_read(DHT11_PIN) == 1) {
            data[i] = bit;
        } else {
            data[i] = 0;
        }

        gpioDelay(1000); // Wait 1 ms
    }

    return 0;
}

int dht11_validate_checksum(const unsigned char *data) {
    unsigned int calculated_checksum = 0;
    unsigned int received_checksum = 0;

    // Calculate checksum
    for (int i = 0; i < 4; i++) {
        calculated_checksum += data[i];
    }

    // Check received checksum
    for (int i = 0; i < 4; i++) {
        received_checksum += data[i];
    }

    // Validate checksum
    if (calculated_checksum != received_checksum) {
        fprintf(stderr, "DHT11 checksum validation failed: Calculated %u, Received %u\n", calculated_checksum, received_checksum);
        return 1;
    }

    return 0;
}

int dht11_read_sensor(float *temperature, float *humidity) {
    unsigned char data[5];
    int i;

    if (!dht11_start_pulse()) {
        return 1;
    }

    if (!dht11_check_response()) {
        return 1;
    }

    if (!dht11_read_data(data)) {
        return 1;
    }

    if (!dht11_validate_checksum(data)) {
        return 1;
    }

    // Extract temperature and humidity
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    // Validate sensor presence
    if (gpio_read(DHT11_PIN) == 1) {
        dht11_present = 1;
    } else {
        dht11_present = 0;
    }

    return 0;
}

void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.1f,%.1f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

