#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_DEVICE_ID_REG 0x00
#define ADPD105_RED_REG 0x64
#define ADPD105_GREEN_REG 0x66
#define ADPD105_BLUE_REG 0x68
#define ADPD105_DATA_LENGTH 2
#define CCT_THRESHOLD 500
#define MAX_RETRIES 3

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int i2c_handle, sensor_data_t *data);
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
int log_cct(float avg_cct);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Reads sensor data from the ADPD105
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buffer[ADPD105_DATA_LENGTH];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, ADPD105_RED_REG, buffer, ADPD105_DATA_LENGTH);
        if (bytes_read == ADPD105_DATA_LENGTH) {
            // Convert little-endian to big-endian
            data->red = (buffer[1] << 8) | buffer[0];
            data->green = (buffer[3] << 8) | buffer[2];
            data->blue = (buffer[5] << 8) | buffer[4];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculates the Correlated Color Temperature (CCT) using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float x = (float)red / (float)green;
    float y = (float)red / (float)blue;
    float cct = 449.0 * powf(x, 1/3.0) * powf(y, 1/3.0) + 551.0;
    return cct;
}

// Logs the average CCT value to a CSV file
int log_cct(float avg_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("cct_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, avg_cct);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle_1 = initialize_i2c(I2C_BUS, ADPD105_ADDR_1);
    if (i2c_handle_1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = initialize_i2c(I2C_BUS, ADPD105_ADDR_2);
    if (i2c_handle_2 < 0) {
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    char device_id_reg = ADPD105_DEVICE_ID_REG;
    char device_id = 0x2A;
    int result_1 = i2cWriteI2CBlockData(i2c_handle_1, device_id_reg, &device_id, 1);
    int result_2 = i2cWriteI2CBlockData(i2c_handle_2, device_id_reg, &device_id, 1);

    if (result_1 < 0 || result_2 < 0) {
        fprintf(stderr, "Error writing to device ID register: %s\n", strerror(errno));
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    // Read sensor data
    sensor_data_t sensor1_data, sensor2_data;
    if (read_sensor_data(i2c_handle_1, &sensor1_data) != 0) {
        fprintf(stderr, "Error reading sensor 1 data.\n");
    }
    if (read_sensor_data(i2c_handle_2, &sensor2_data) != 0) {
        fprintf(stderr, "Error reading sensor 2 data.\n");
    }

    // Calculate CCT and log average
    float avg_cct = 0.0;
    if (sensor1_data.red != 0 || sensor1_data.green != 0 || sensor1_data.blue != 0) {
        avg_cct += calculate_cct(sensor1_data.red, sensor1_data.green, sensor1_data.blue);
    }
    if (sensor2_data.red != 0 || sensor2_data.green != 0 || sensor2_data.blue != 0) {
        avg_cct += calculate_cct(sensor2_data.red, sensor2_data.green, sensor2_data.blue);
    }

    if (avg_cct > CCT_THRESHOLD) {
        fprintf(stderr, "CCT value out of range: %.2f\n", avg_cct);
    }

    if (avg_cct > 0) {
        avg_cct /= 2.0; // Average the two sensors
        if (log_cct(avg_cct) != 0) {
            fprintf(stderr, "Error logging CCT value.\n");
        }
    } else {
        fprintf(stderr, "No valid CCT values to average.\n");
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();

    return 0;
}

