    sensor_data_t sensor1_data, sensor2_data;
    if (read_sensor_data(i2c_handle_1, &sensor1_data) != 0) {
        fprintf(stderr, "Error reading sensor 1 data.\n");
    }
    if (read_sensor_data(i2c_handle_2, &sensor2_data) != 0) {
        fprintf(stderr, "Error reading sensor 2 data.\n");
    }

    // Calculate CCT and log average
    float avg_cct = 0.0;
    if (sensor1_data.red != 0 || sensor1_data.green != 0 || sensor1_data.blue != 0) {
        avg_cct += calculate_cct(sensor1_data.red, sensor1_data.green, sensor1_data.blue);
    }
    if (sensor2_data.red != 0 || sensor2_data.green != 0 || sensor2_data.blue != 0) {
        avg_cct += calculate_cct(sensor2_data.red, sensor2_data.green, sensor2_data.blue);
    }

    if (avg_cct > CCT_THRESHOLD) {
        fprintf(stderr, "CCT value out of range: %.2f\n", avg_cct);
    }

    if (avg_cct > 0) {
        avg_cct /= 2.0; // Average the two sensors
        if (log_cct(avg_cct) != 0) {
            fprintf(stderr, "Error logging CCT value.\n");
        }
    } else {
        fprintf(stderr, "No valid CCT values to average.\n");
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();

    return 0;
}

