#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMP_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32767
#define PMIN 0.0
#define PMAX 800.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_pressure(int handle, uint16_t *raw_pressure);
int read_temperature(int handle, uint16_t *raw_temperature);
float convert_pressure(uint16_t raw_pressure, float output_min, float output_max, float pmin, float pmax);
float convert_temperature(uint16_t raw_temperature, float output_min, float output_max, float pmin, float pmax);
void log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read pressure data from the sensor
int read_pressure(int handle, uint16_t *raw_pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure: %s\n", strerror(errno));
        return -1;
    }
    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Read temperature data from the sensor
int read_temperature(int handle, uint16_t *raw_temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }
    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

