    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f kPa, %.2f C\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint16_t raw_pressure, raw_temperature;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_pressure(i2c_handle, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading pressure, using previous value.\n");
        } else if (read_temperature(i2c_handle, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
        } else {
            // Convert data
            pressure = convert_pressure(raw_pressure, OUTPUT_MIN, OUTPUT_MAX, PMIN, PMAX);
            temperature = convert_temperature(raw_temperature, OUTPUT_MIN, OUTPUT_MAX, PMIN, PMAX);

            // Log data
            log_data(pressure, temperature);
        }

        // Wait 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

