#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t status;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, sensor_data_t *data) {
    char buf[9];
    int bytes_read;

    // Send continuous measurement command
    if (i2cWriteByteData(i2c_handle, 0x00, CMD_CONTINUOUS_MEASUREMENT) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for 45 ms
    gpioDelay(45000);

    // Read 9 bytes from the sensor
    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %d bytes read\n", bytes_read);
        return -1;
    }

    // CRC validation
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5] || crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract data from the buffer
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->status = buf[6];

    return 0;
}

