#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_CHIP_ID 0
#define GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define LED_ON_TIME_MS 500

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
float read_temperature(int fd);
void set_led_state(int fd, int state);
void log_temperature(float temperature);
void signal_handler(int sig);
int setup_gpio(int chip_num, int line_num);
void cleanup_gpio(int chip_num, int line_num);

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Temperature reading function
float read_temperature(int fd) {
    int16_t raw_temp = i2c_read_register(fd, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature register\n");
        return -1000.0; // Indicate an error
    }
    return (float)raw_temp * 0.0625;
}

// LED control function
void set_led_state(int fd, int state) {
    if (gpiod_line_set_value(gpio_line, state) != 0) {
        perror("Failed to set LED state");
    }
}

// Logging function
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[100];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Temperature: %.2f °C\n", buf, temperature);
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// GPIO setup function
int setup_gpio(int chip_num, int line_num) {
    gpio_chip = gpiod_chip_open_by_name(gpio_chip_id);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, line_num);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "temperature_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void cleanup_gpio(int chip_num, int line_num) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Turn off LED
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // GPIO setup
    if (setup_gpio(GPIO_CHIP, GPIO_CHIP_ID) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(i2c_fd);
        if (temperature > -999.0) { // Check for read error
            log_temperature(temperature);

            if (temperature > TEMP_THRESHOLD_HIGH) {
                set_led_state(i2c_fd, 1); // Turn on LED
            } else if (temperature < TEMP_THRESHOLD_LOW) {
                set_led_state(i2c_fd, 0); // Turn off LED
            }

            struct timespec ts;
            ts.tv_sec = 0;
            ts.tv_nsec = LED_ON_TIME_MS * 1000000; // 500ms
            nanosleep(&ts, NULL);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping LED control.\n");
        }

        sleep(1);
    }

    // Cleanup
    cleanup_gpio(GPIO_CHIP, GPIO_CHIP_ID);
    close(i2c_fd);

    return 0;
}

