int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity) {
    uint8_t cmd = TEMP_MEASURE_CMD;
    uint8_t data[2];
    int result;

    // Measure temperature
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement (datasheet says 50ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *raw_temperature = (data[0] << 8) | data[1];

    // Measure humidity
    cmd = HUMID_MEASURE_CMD;
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
