#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <stdbool.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define SCD40_CMD_START_PERIODIC 0x21B1
#define SCD40_CMD_STOP_PERIODIC 0x3F86
#define SCD40_CMD_READ_MEASUREMENT 0xE000
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;
circular_buffer_t data_buffer;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int send_command(int handle, unsigned int command);
int read_data(int handle, unsigned char *data, int count);
int validate_crc(unsigned char *data, int len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
bool is_buffer_full(const circular_buffer_t *buffer);
bool is_buffer_empty(const circular_buffer_t *buffer);
bool is_buffer_valid(const circular_buffer_t *buffer);
void *logging_thread(void *arg);
void send_data_to_server(const circular_buffer_t *buffer);
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to send a command to the SCD40
int send_command(int handle, unsigned int command) {
    unsigned char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command 0x%04X: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to validate CRC-8
int validate_crc(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0xFF);
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to check if the buffer is full
bool is_buffer_full(const circular_buffer_t *buffer) {
    return buffer->count == BUFFER_SIZE;
}

// Function to check if the buffer is empty
bool is_buffer_empty(const circular_buffer_t *buffer) {
    return buffer->count == 0;
}

// Function to check if the buffer is valid (not full and not empty)
bool is_buffer_valid(const circular_buffer_t *buffer) {
    return !is_buffer_full(buffer) && !is_buffer_empty(buffer);
}

// Function to send data to the server
void send_data_to_server(const circular_buffer_t *buffer) {
    time_t now = time(NULL);
    char filename[100];
    char command[200];
    time_t t = now;
    struct tm tm = *localtime(&t);
    sprintf(filename, "%s/scd40_data_%04d%02d%02d.csv", LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday);
    sprintf(command, "curl -X POST -d \"data=timestamp=%s&co2=%.2f&temperature=%.2f&humidity=%.2f\n\" http://%s:%d/receive_data",
            asctime(localtime(&now)),
            buffer->data[buffer->tail].co2,
            buffer->data[buffer->tail].temperature,
            buffer->data[buffer->tail].humidity,
            SERVER_IP, SERVER_PORT);

    int result = system(command);
    if (result == -1) {
        log_error("Failed to execute curl command");
    } else {
        printf("Data sent to server: %s\n", command);
    }
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to log errors
void log_error(const char *message) {
    FILE *fp = fopen(LOG_DIR "error.log", "a");
    if (fp != NULL) {
        time_t now = time(NULL);
        struct tm tm = *localtime(&now);
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        fprintf(stderr, "Failed to open error log file\n");
    }
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, SCD40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.tail = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Send start-periodic-measurement command
    if (send_command(i2c_handle, SCD40_CMD_START_PERIODIC) != 0) {
        log_error("Failed to send start-periodic-measurement command");
        i2cClose(i2c_handle);
        gpioTerminate();
        pthread_mutex_destroy(&data_buffer.mutex);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        unsigned char data[9];
        sensor_data_t sensor_data;

        // Read sensor data
        if (read_data(i2c_handle, data, 9) == 0) {
            // Validate CRC
            if (validate_crc(data, 9)) {
                // Convert data
                int co2_raw = (data[0] << 8) | data[1];
                int temperature_raw = (data[3] << 8) | data[4];
                int humidity_raw = (data[6] << 8) | data[7];

                // Convert to ppm, Celsius, and %RH
                sensor_data.co2 = (float)co2_raw;
                sensor_data.temperature = -45 + 175 * (float)temperature_raw / 65535;
                sensor_data.humidity = 100 * (float)humidity_raw / 65535;

                // Add data to buffer
                add_to_buffer(&data_buffer, sensor_data);

                // Check if buffer is valid and send data to server
                if (is_buffer_valid(&data_buffer)) {
                    send_data_to_server(&data_buffer);
                }
            } else {
                log_error("CRC validation failed");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(5);
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, SCD40_CMD_STOP_PERIODIC) != 0) {
        log_error("Failed to send stop-periodic-measurement command");
    }

    // Join logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
    }
    pthread_join(logging_thread_id, NULL);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&data_buffer.mutex);

    return 0;
}

