#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_MEASURE 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "sdp810_log.txt"
#define SLEEP_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, sensor_data_t *data) {
    uint8_t cmd[2] = {(CMD_MEASURE >> 8) & 0xFF, CMD_MEASURE & 0xFF};
    uint8_t buffer[9];
    int result;

    // Send continuous measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 45 ms
    gpioDelay(45000); // 45 ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for differential pressure
    uint8_t crc_dp = crc8(buffer, 2);
    if (crc_dp != buffer[2]) {
        fprintf(stderr, "CRC error for differential pressure\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t crc_temp = crc8(buffer + 3, 2);
    if (crc_temp != buffer[5]) {
        fprintf(stderr, "CRC error for temperature\n");
        return -1;
    }

    // Validate CRC for scale factor
    uint8_t crc_scale = crc8(buffer + 6, 2);
    if (crc_scale != buffer[8]) {
        fprintf(stderr, "CRC error for scale factor\n");
        return -1;
    }

    // Convert raw data to physical units
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t raw_scale_factor = (buffer[6] << 8) | buffer[7];

    data->pressure_Pa = (float)raw_pressure / 1000.0;
    data->temperature_C = -45 + 175 * (float)raw_temperature / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(FILE *log_file, float pressure_Pa, float temperature_C) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sdp810(i2c_handle, &sensor_data);
        if (result == 0) {
            // Log data
            log_data(log_file, sensor_data.pressure_Pa, sensor_data.temperature_C);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_data.pressure_Pa, sensor_data.temperature_C);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

