// I2C address of the ICP-10110 sensor
#define ICP10110_ADDR 0x63

// Register addresses
#define WHO_AM_I 0x08
#define MEASURE 0x00
#define PRESSURE_MSB 0x01
#define PRESSURE_CSB 0x02
#define PRESSURE_LSB 0x03
#define TEMPERATURE_MSB 0x04
#define TEMPERATURE_CSB 0x05
#define TEMPERATURE_LSB 0x06

// Calibration coefficients
#define COEFF1 0x07
#define COEFF2 0x09
#define COEFF3 0x0B
#define COEFF4 0x0D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration coefficients
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
} calibration_coefficients;

calibration_coefficients coeffs;

// Function prototypes
int initialize_i2c();
int verify_sensor_id();
int read_calibration_coefficients(calibration_coefficients *coeffs);
int read_raw_data(int32_t *pressure, int32_t *temperature);
double convert_pressure(int32_t raw_pressure);
double convert_temperature(int32_t raw_temperature);
void log_data(double pressure, double temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0); // I2C bus 1, address 0x63, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to verify the sensor's WHO_AM_I register
int verify_sensor_id() {
    int result = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (result < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", result);
        return -1;
    }

    if (result != 0x08) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", result);
        return -1;
    }

    printf("Sensor ID verified: 0x%02X\n", result);
