#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x63
#define MEASUREMENT_CMD 0x4011
#define LED_GPIO 17
#define HIGH_ALTITUDE_THRESHOLD 95000.0f
#define HIGH_FREQUENCY_Blink_PERIOD 100.0f // milliseconds

// Calibration coefficients (read from OTP memory)
struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} calibration;

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int read_calibration_coefficients(int fd);
int read_sensor_data(int fd, int32_t *pressure, int32_t *temperature);
float calculate_pressure(int32_t raw_pressure, int32_t raw_temperature, const struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} calibration);
void control_led(int gpio, int on);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd) {
    uint8_t data[20];
    if (i2c_read_bytes(fd, 0x66, data, 20) != 0) {
        fprintf(stderr, "Error reading calibration coefficients\n");
        return -1;
    }

    calibration.c0 = (int32_t)((uint32_t)data[0] << 0 | (uint32_t)data[1] << 8 | (uint32_t)data[2] << 16);
    calibration.c1 = (int32_t)((uint32_t)data[3] << 0 | (uint32_t)data[4] << 8 | (uint32_t)data[5] << 16);
    calibration.c00 = (int32_t)((uint32_t)data[6] << 0 | (uint32_t)data[7] << 8 | (uint32_t)data[8] << 16);
    calibration.c10 = (int32_t)((uint32_t)data[9] << 0 | (uint32_t)data[10] << 8 | (uint32_t)data[11] << 16);
    calibration.c01 = (int32_t)((uint32_t)data[12] << 0 | (uint32_t)data[13] << 8 | (uint32_t)data[14] << 16);
    calibration.c11 = (int32_t)((uint32_t)data[15] << 0 | (uint32_t)data[16] << 8 | (uint32_t)data[17] << 16);
    calibration.c20 = (int32_t)((uint32_t)data[18] << 0 | (uint32_t)data[19] << 8);
    return 0;
}

// Read raw sensor data
int read_sensor_data(int fd, int32_t *pressure, int32_t *temperature) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *pressure = (int32_t)((uint32_t)data[0] << 16 | (uint32_t)data[1] << 8 | (uint32_t)data[2]);
    *temperature = (int32_t)((uint32_t)data[3] << 16 | (uint32_t)data[4] << 8 | (uint32_t)data[5]);

    return 0;
}

// Calculate pressure using ICP-10125 conversion formulas
float calculate_pressure(int32_t raw_pressure, int32_t raw_temperature, const struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} calibration) {
    float pressure = 0.0f;
    float temp = 0.0f;

    float p_comp = (float)raw_pressure;
    float t_comp = (float)raw_temperature;

    pressure = calibration.c0 + p_comp * (calibration.c1 + p_comp * (calibration.c00 + p_comp * calibration.c20)) + t_comp * (calibration.c10 + p_comp * calibration.c11);
    temp = t_comp * (calibration.c01 + p_comp * calibration.c21) + calibration.c30;

    return pressure;
}

// Control the LED
void control_led(int gpio, int on) {
    if (on) {
        gpioWrite(gpio, 1); // HIGH
    } else {
        gpioWrite(gpio, 0); // LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Configure LED GPIO as output
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        perror("Failed to set GPIO mode");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int32_t raw_pressure, raw_temperature;
        float pressure;

        // Trigger measurement
        if (i2c_write_byte(i2c_fd, MEASUREMENT_CMD, 0x00) != 0) {
            fprintf(stderr, "Failed to trigger measurement. Continuing.\n");
            continue;
        }

        // Delay for measurement
        usleep(20000); // 20 ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, &raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Failed to read sensor data. Continuing.\n");
            continue;
        }

        // Calculate pressure
        pressure = calculate_pressure(raw_pressure, raw_temperature, calibration);

        // Check for high altitude condition
        if (pressure < HIGH_ALTITUDE_THRESHOLD) {
            printf("High altitude condition detected! Pressure: %.2f Pa\n", pressure);
            control_led(LED_GPIO, 1); // Blink at 5 Hz
            usleep(HIGH_FREQUENCY_Blink_PERIOD * 1000000); // 100 ms on, 100 ms off
            control_led(LED_GPIO, 0); // Blink at 1 Hz
        } else {
            control_led(LED_GPIO, 1); // Blink at 1 Hz
            usleep(HIGH_FREQUENCY_Blink_PERIOD * 1000000); // 100 ms on, 100 ms off
            control_led(LED_GPIO, 0); // Blink at 1 Hz
        }

        printf("Pressure: %.2f Pa\n", pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set GPIO to input (safer)

    return 0;
}

