#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd, new_socket;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Signal received, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd > 0) {
        close(server_fd);
    }
    if (new_socket > 0) {
        close(new_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char cmd[1] = {0xFD};
    unsigned char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device. Retry: %d\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10 ms delay
            continue;
        }

        gpioDelay(10000); // Wait for measurement (at least 10 ms)

        if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device. Retry: %d\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10 ms delay
            continue;
        }

        // Convert raw data to temperature and humidity
        int raw_temperature = (buffer[0] << 8) | buffer[1];
        int raw_humidity = (buffer[3] << 8) | buffer[4];

        *temperature = -45 + 175 * (raw_temperature / 65535);
        *humidity = -6 + 125 * (raw_humidity / 65535);

        // Clamp humidity to 0-100%
        if (*humidity < 0) *humidity = 0;
        if (*humidity > 100) *humidity = 100;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to create a simple HTML page with temperature and humidity
char *create_html_page(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    char *html_page = malloc(256);
    if (html_page == NULL) {
        fprintf(stderr, "Failed to allocate memory for HTML page.\n");
        return NULL;
    }

    sprintf(html_page, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>SHT40 Sensor Data</title></head><body><h1>SHT40 Sensor Data</h1><p>Temperature: %.2f C</p><p>Humidity: %.2f %</p></body></html>", temperature, humidity);
    return html_page;
}

// Function to send the HTML page to the client
int send_html_page(int socket, const char *html_page) {
    if (send(socket, html_page, strlen(html_page), 0) < 0) {
        fprintf(stderr, "Error sending HTML page.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Could not create socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept incoming connections
    while (1) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        if ((new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len)) < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        // Read sensor data
        float temperature, humidity;
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            // Create HTML page
            char *html_page = create_html_page(temperature, humidity);
            if (html_page != NULL) {
                // Send HTML page to client
                if (send_html_page(new_socket, html_page) != 0) {
                    fprintf(stderr, "Failed to send HTML page to client.\n");
                }
                free(html_page); // Free allocated memory
            } else {
                fprintf(stderr, "Failed to create HTML page.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        close(new_socket);
        new_socket = -1; // Reset new_socket for next connection
    }

    // Cleanup (this part will not be reached in the infinite loop)
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

