#include <time.h>
#include <sys/time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 registers
#define MEASUREMENT_CONFIG 0x0E
#define TEMPERATURE_REGISTER 0x00
#define HUMIDITY_REGISTER 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the HDC2010 sensor
int configure_sensor() {
    // Set heater to OFF
    if (i2cWriteByteData(i2c_handle, 0x0F, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    // Set resolution to 14 bits
    if (i2cWriteByteData(i2c_handle, 0x0E, 0x01) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint16_t raw_temperature, raw_humidity;

    // Wait for measurement to complete (polling MEASUREMENT_CONFIG)
    int timeout_count = 0;
    while (i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG) & 0x01) {
        if (timeout_count++ > 500) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_REGISTER);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    // Read humidity data
    raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_REGISTER);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    data->temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    data->humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

// Log temperature and humidity data to the console
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

