#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the continuous measurement command
#define MEASURE_CMD 0x362F

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Define the CRC initial value
#define CRC_INIT_VALUE 0xFF

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, float *pressure, float *temperature)
{
    unsigned char data[6];
    int result;

    // Send the continuous measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (at least 45 ms)
    gpioDelay(50); // Wait 50 ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Extract pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // CRC Check for pressure
    unsigned char crc_pressure = 0xFF;
    for (int i = 0; i < 2; i++)
    {
        crc_pressure ^= data[i + 2];
        for (int j = 0; j < 8; j++)
        {
            if (crc_pressure & 0x80)
            {
                crc_pressure = (crc_pressure << 1) ^ CRC_POLYNOMIAL;
            }
            else
            {
                crc_pressure <<= 1;
            }
        }
    }

    // CRC Check for temperature
    unsigned char crc_temperature = 0xFF;
    for (int i = 0; i < 2; i++)
    {
        crc_temperature ^= data[5 + i];
        for (int j = 0; j < 8; j++)
        {
            if (crc_temperature & 0x80)
            {
                crc_temperature = (crc_temperature << 1) ^ CRC_POLYNOMIAL;
            }
            else
            {
                crc_temperature <<= 1;
            }
        }
    }

    // Validate CRC checksums
    if (crc_pressure != 0xFF)
    {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }

    if (crc_temperature != 0xFF)
    {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Convert raw values to physical units (Pa and °C)
    *pressure = (float)raw_pressure / 240.0; // Scaling factor from datasheet
    *temperature = (float)raw_temperature / 200.0; // Scaling factor from datasheet

    return 0;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float pressure, temperature;

    // Main loop
    while (1)
    {
        // Read sensor data
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0)
        {
            // Log the data to the console
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        }
        else
        {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 500 ms
        gpioDelay(500);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

