static FILE *log_file;

// Structure for PID controller
typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double integral;
    double previous_error;
} PIDController;

// Function prototypes
int spi_read_temperature(int spi_handle, int *raw_temp);
double convert_raw_to_celsius(int raw_temp);
double calculate_pid(PIDController *pid, double setpoint, double actual_temp, double *integral, double *previous_error);
void set_relay_duty_cycle(int gpio_pin, double duty_cycle);
void log_temperature_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int read_target_temperature(const char *filename);
int send_udp_message(const char *message);

// SPI read temperature function
int spi_read_temperature(int spi_handle, int *raw_temp) {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];
    int result;

    // Read 2 bytes from MAX6675 (temperature MSB and LSB)
    tx_buf[0] = 0x00; // Dummy byte for reading
    tx_buf[1] = 0x00; // Dummy byte for reading

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes to get the raw temperature data
    *raw_temp = ((rx_buf[0] & 0x0F) << 8) | rx_buf[1];

    return 0; // Indicate success
}

// Convert raw temperature to Celsius
double convert_raw_to_celsius(int raw_temp) {
    // Shift right to get the 12-bit temperature value
    raw_temp = raw_temp >> 4;
    // Handle negative temperatures (two's complement)
    if (raw_temp & 0x800) {
        raw_temp |= 0xF000; // Sign extend
    }
    return raw_temp * 0.25;
}

// PID controller function
double calculate_pid(PIDController *pid, double setpoint, double actual_temp, double *integral, double *previous_error) {
    double error = setpoint - actual_temp;
    *integral += error;
    double derivative = error - *previous_error;
    double output = pid->Kp * error + pid->Ki * (*integral) + pid->Kd * derivative;
    *previous_error = error;
    return output;
}

// Set relay duty cycle
void set_relay_duty_cycle(int gpio_pin, double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int duty_cycle_int = (int)(duty_cycle * 1000000.0); // Convert to microseconds
    gpioPWM(gpio_pin, duty_cycle_int);
}

// Log temperature data
void log_temperature_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Read target temperature from file
int read_target_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening target temperature file: %s\n", filename);
        return -1;
    }

    int target_temp;
    while (fscanf(fp, "%d", &target_temp) == 1) {
        // Validate temperature range
        if (target_temp < -50.0 || target_temp > 200.0) {
            fprintf(stderr, "Invalid target temperature in file: %s\n", filename);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing target temperature file: %s\n", filename);
        return -1;
    }

    return 0;
}

// Send UDP message
int send_udp_message(const char *message) {
    int sockfd;
    struct sockaddr_in servaddr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Fill server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return -1;
    }

    // Send message
    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

