    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for relay control
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_RELAY, 1000); // 1 kHz
    gpioSetPWMrange(GPIO_RELAY, 1000000); // 0-100% duty cycle

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

