        pid.Kp = 0.5;
        pid.Ki = 0.05;
        pid.Kd = 0.005;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        spi_retry = 0;
        while (spi_retry < SPI_RETRY_COUNT) {
            if (spi_read_temperature(spi_handle, &raw_temp) == 0) {
                temperature = convert_raw_to_celsius(raw_temp);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", spi_retry + 1, SPI_RETRY_COUNT);
                spi_retry++;
                gpioDelay(SPI_RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (spi_retry == SPI_RETRY_COUNT) {
            fprintf(stderr, "Failed to read temperature after multiple retries. Skipping this cycle.\n");
            gpioDelay(1000000); // Delay 1 second
            continue;
        }

        pid_output = calculate_pid(&pid, 0.0, temperature, &integral, &previous_error); // Setpoint = 0.0 for temperature control
        set_relay_duty_cycle(GPIO_RELAY, (int)pid_output); // Convert double to integer for duty cycle
        log_temperature_data(temperature, (int)pid_output); // Log temperature and duty cycle

