#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define POLLING_INTERVAL_SEC 5

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int i2c_fd);
int aht20_read_data(int i2c_fd, float *humidity);
void control_dehumidifier(int gpio_pin, float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// AHT20 Initialization
int aht20_init(int i2c_fd) {
    char buf[3];
    buf[0] = 0xBE;
    buf[1] = 0x08;
    buf[2] = 0x00;

    int result = i2cWriteDevice(i2c_fd, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms
    return 0;
}

// AHT20 Read Data
int aht20_read_data(int i2c_fd, float *humidity) {
    char buf[6];
    int result;

    // Trigger measurement
    buf[0] = 0xAC;
    buf[1] = 0x33;
    buf[2] = 0x00;
    result = i2cWriteDevice(i2c_fd, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(80000); // Wait 80ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_fd, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Verify status byte
    if (buf[0] != 0x08) {
        fprintf(stderr, "Error: Invalid status byte: 0x%02X\n", buf[0]);
        return -1;
    }

    // Convert data
    unsigned int humidity_raw = ((unsigned int)buf[1] << 12) | ((unsigned int)buf[2] << 4) | ((unsigned int)buf[3] >> 4);
    *humidity = ((float)humidity_raw / 0x100000) * 100;

    return 0;
}

// Control Dehumidifier
void control_dehumidifier(int gpio_pin, float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(gpio_pin, 1); // Turn on dehumidifier
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(gpio_pin, 0); // Turn off dehumidifier
    }
}

// Log Data
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    float humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for dehumidifier control
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = aht20_read_data(i2c_fd, &humidity);
        if (result == 0) {
            log_data(humidity);
            control_dehumidifier(DEHUMIDIFIER_GPIO, humidity);
        } else {
            fprintf(stderr, "Failed to read humidity, retrying...\n");
        }

        gpioDelay(POLLING_INTERVAL_SEC * 1000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_fd);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    gpioTerminate();

    return 0;
}

