// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define POST_URL "http://api.example.com/humidity"
#define LOG_LEVEL LOG_INFO

// HTU21D Commands
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5

// Global variables
int i2c_fd = -1;
int sockfd = -1;
struct sockaddr_in servaddr;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char val);
float read_humidity(int fd);
int post_data(const char *url, const char *data);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write register address: %s", strerror(errno));
        return -1;
    }

    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "Failed to read data: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char val) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = val;

    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to write data: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Read humidity from HTU21D
float read_humidity(int fd) {
    unsigned char buf[3];
    int raw_humidity;
    float humidity;

    if (i2c_write_byte(fd, TRIGGER_HUMID_MEASURE, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement");
        return -1.0;
    }

    usleep(100000); // Wait for measurement (at least 8ms)

    if (i2c_read_bytes(fd, 0x00, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to read humidity data");
        return -1.0;
    }

    raw_humidity = (buf[0] << 8) | buf[1];

    // Check CRC
    unsigned char crc = buf[2];
    unsigned char data[2] = {buf[0], buf[1]};
    unsigned char crc_calculated = 0;
    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x131;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    if (crc_calculated != crc) {
        syslog(LOG_ERR, "CRC check failed");
        return -1.0;
    }

    humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);
    return humidity;
}

// Post data to server
int post_data(const char *url, const char *data) {
    struct sockaddr_in servaddr;

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Standard HTTP port
    if (inet_pton(AF_INET, url, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        return -1;
    }

    if (send(sockfd, data, strlen(data), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        return -1;
    }

    syslog(LOG_INFO, "Data posted successfully: %s", data);
    return 0;
}

// Signal handler
