#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 registers
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_DATA_PRESS_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_chip_id();
int read_calibration_data(bmp280_calib_data *calib);
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t adc_T, bmp280_calib_data calib);
double compensate_pressure(int32_t adc_P, bmp280_calib_data calib);
void log_pressure_breach(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // Bus 1, address 0x76, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the chip ID
int verify_chip_id() {
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        return -1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }
    return 0;
}

// Read calibration data from the sensor
int read_calibration_data(bmp280_calib_data *calib) {
    uint8_t data[26];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the sensor
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_DATA_PRESS_MSB, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    *temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    return 0;
}

// Compensate temperature using BMP280 compensation formulas
double compensate_temperature(int32_t adc_T, bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)adc_T) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using BMP280 compensation formulas
double compensate_pressure(int32_t adc_P, bmp280_calib_data calib) {
    double var1, var2, p;
    double t_fine;

    var1 = (((double)adc_T) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (var1 + var2);

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Log pressure breach to file
void log_pressure_breach(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Pressure breach: %.2f hPa\n", s, pressure);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    if (verify_chip_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure forced mode
    int32_t ctrl_meas = (0x01 << 5) | (0x01 << 2) | 0x03; // osrs_t = 1, osrs_p = 1, mode = forced
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    time_t last_log_time = time(NULL);

    while (!terminate) {
        // Trigger measurement
        if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
            fprintf(stderr, "Error writing to CTRL_MEAS register\n");
            break;
        }

        // Wait for conversion (adjust as needed)
        gpioDelay(10); // 10 ms

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            break;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, calib);

        // Check for pressure breach
        if (pressure > 1020.0 || pressure < 980.0) {
            log_pressure_breach(pressure);
        }

