#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define GPIO_PIR 17
#define I2C_DEVICE "/dev/i2c-1"
#define RETRY_COUNT 3
#define BACKOFF_MS 10
#define LOG_FILE_PATH "/home/pi/sensor_logs/"
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio(int gpio_pin);
int init_i2c(int i2c_address);
int read_sensor(int i2c_fd, int sensor_type, int *data);
float convert_temperature(int raw_temp);
float convert_humidity(int raw_humidity);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
char* get_timestamp();

// Function to initialize GPIO
int init_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_INPUT);
    return 0;
}

// Function to initialize I2C
int init_i2c(int i2c_address) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data
int read_sensor(int i2c_fd, int sensor_type, int *data) {
    int retries = RETRY_COUNT;
    int delay_ms = BACKOFF_MS;

    if (sensor_type == 0) { // TMP117
        // Read temperature register (0x00)
        unsigned char reg = 0x00;
        unsigned char buf[2];
        if (write(i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            return -1;
        }
        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            return -1;
        }
        *data = (buf[0] << 8) | buf[1];
        return 0;
    } else if (sensor_type == 1) { // AHT20
        // Send measure command (0xAC, 0x33, 0x00)
        unsigned char cmd[3] = {0xAC, 0x33, 0x00};
        if (write(i2c_fd, cmd, 3) != 3) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            return -1;
        }
        gpioDelay(100); // Wait for measurement (adjust as needed)

        // Read 7 bytes of data
        unsigned char buf[7];
        if (read(i2c_fd, buf, 7) != 7) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            return -1;
        }

        // Check busy bit (bit 7 of byte 0)
        if (buf[0] & 0x80) {
            fprintf(stderr, "AHT20 busy\n");
            return -1; // Sensor busy
        }

        // Extract humidity and temperature data
        *data = ((buf[1] << 16) | (buf[2] << 8) | buf[3]) & 0x3FFFFF;
        *data |= ((buf[4] << 16) | (buf[5] << 8) | buf[6]) >> 16;

        return 0;
    } else {
        fprintf(stderr, "Invalid sensor type\n");
        return -1;
    }
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw_temp) {
    return (float)raw_temp * 0.0078125;
}

// Function to convert raw humidity to percentage
float convert_humidity(int raw_humidity) {
    return (float)raw_humidity * 0.00000875;
}

// Function to log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    char *timestamp = get_timestamp();
    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    free(timestamp);
    return 0;
}

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, TIMESTAMP_FORMAT, timeinfo);
    return timestamp;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize GPIO
    if (init_gpio(GPIO_PIR) != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(AHT20_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Check if AHT20 sensor is present
    int aht20_data;
    if (read_sensor(i2c_fd, 1, &aht20_data) == 0) {
        printf("AHT20 sensor found\n");
    } else {
        fprintf(stderr, "AHT20 sensor not found\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    char *timestamp = get_timestamp();
    log_file = fopen(LOG_FILE_PATH + timestamp, "a");
    free(timestamp);
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int pir_value = gpioRead(GPIO_PIR);
        int raw_temperature, raw_humidity;
        float temperature, humidity;

        if (read_sensor(i2c_fd, 0, &raw_temperature) == 0) {
            temperature = convert_temperature(raw_temperature);
        } else {
            temperature = -999.0; // Indicate error
        }

        if (read_sensor(i2c_fd, 1, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        if (pir_value == 1) {
            motion_detected = 1;
        } else {
            motion_detected = 0;
        }

        if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(1);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();
    fclose(log_file);
    free(get_timestamp());

    return 0;
}

