    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int pir_value = gpioRead(GPIO_PIR);
        int raw_temperature, raw_humidity;
        float temperature, humidity;

        if (read_sensor(i2c_fd, 0, &raw_temperature) == 0) {
            temperature = convert_temperature(raw_temperature);
        } else {
            temperature = -999.0; // Indicate error
        }

        if (read_sensor(i2c_fd, 1, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        if (pir_value == 1) {
            motion_detected = 1;
        } else {
            motion_detected = 0;
        }

        if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(1);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();
    fclose(log_file);
    free(get_timestamp());

    return 0;
}

