#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nSIGINT received. Shutting down gracefully...\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as input or output
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Enable the motor (ENA high)
    gpioWrite(MOTOR_ENA_PIN, 1);

    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void control_motor(int forward) {
    gpioWrite(MOTOR_IN1_PIN, forward ? 1 : 0);
    gpioWrite(MOTOR_IN2_PIN, forward ? 0 : 1);
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_ENA_PIN, 0);
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        // Read rain sensor
        int rain_detected = read_rain_sensor();

        // If rain is detected, activate the motor
        if (rain_detected == 0) {
            log_event("Rain detected. Activating motor.");
            control_motor(1); // Run forward
            gpioDelay(5000);   // Wait for 5 seconds
            stop_motor();       // Stop the motor
            log_event("Motor stopped.");
        } else {
            log_event("No rain detected.");
        }

        // Wait for 2 seconds
        gpioDelay(2000);
    }

    // Stop the motor
    stop_motor();

    // Release GPIO pins
    gpioTerminate();

    log_event("Program terminated");

    return 0;
}

