#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to store the previous CPU load
static volatile unsigned long previous_cpu_load = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off the LED (common anode, so set all pins high)
    gpioWrite(RED_PIN, 1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off the LED (common anode, so set all pins high)
    gpioWrite(RED_PIN, 1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read CPU load from /proc/stat
unsigned long read_cpu_load()
{
    FILE *fp;
    unsigned long load;
    char line[256];

    fp = fopen("/proc/stat", "r");
    if (fp == NULL)
    {
        perror("Error opening /proc/stat");
        return 0; // Return 0 on error
    }

    // Read the first line of the file
    if (fgets(line, sizeof(line), fp) == NULL)
    {
        fclose(fp);
        return 0; // Return 0 on error
    }

    // Parse the line to extract the user and nice CPU time
    if (sscanf(line, "cpu  %lu %lu %lu %lu %lu", &load, &load, &load, &load, &load) != 5)
    {
        fclose(fp);
        return 0; // Return 0 on error
    }

    fclose(fp);
    return load;
}

// Function to map CPU load to RGB color values
void map_cpu_load_to_color(unsigned long cpu_load, int *red, int *green, int *blue)
{
    // Clamp the CPU load to the range 0-100
    if (cpu_load < 0) cpu_load = 0;
    if (cpu_load > 100) cpu_load = 100;

    // Map the CPU load to a color gradient (0-255)
    int red_value = (int)((float)(cpu_load - 50) / 50.0 * 255.0);
    int green_value = (int)((float)(100 - cpu_load) / 50.0 * 255.0);
    int blue_value = 255 - (int)((float)(cpu_load - 50) / 50.0 * 255.0);

    // Clamp the color values to the range 0-255
    if (red_value < 0) red_value = 0;
    if (red_value > 255) red_value = 255;
    if (green_value < 0) green_value = 0;
    if (green_value > 255) green_value = 255;
    if (blue_value < 0) blue_value = 0;
    if (blue_value > 255) blue_value = 255;

    *red   = red_value;
    *green = green_value;
    *blue  = blue_value;
}

// Function to set the RGB LED color using hardware PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, red);
    gpioPWM(BLUE_PIN,  red);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN,  255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN,  1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN,  1000);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT,   sigint_handler);
    signal(SIGTERM,  sigterm_handler);

    unsigned long current_cpu_load;
    int red, green, blue;

    // Main loop
    while (1)
    {
        // Read CPU load
        current_cpu_load = read_cpu_load();

        // Map CPU load to RGB color
        map_cpu_load_to_color(current_cpu_load, &red, &green, &blue);

        // Set the LED color
        set_led_color(red, green, blue);

        // Delay for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    return 0;
}

