#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TEMP_THRESHOLD_HIGH 60.0
#define TEMP_THRESHOLD_LOW 25.0
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 255
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;

// Function prototypes
int spi_read_max31855(int spi_handle, int *thermocouple_temp, int *fault_status);
float convert_thermocouple_temp(int raw_temp);
int map_temperature_to_duty_cycle(float temperature);
void update_fan_speed(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Function to read temperature and fault status from MAX31855
int spi_read_max31855(int spi_handle, int *thermocouple_temp, int *fault_status) {
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buf[4];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    *thermocouple_temp = ((rx_buf[0] << 24) | (rx_buf[1] << 16) | (rx_buf[2] << 8) | rx_buf[3]) >> 4;
    *fault_status = rx_buf[3] & 0x07; // Extract fault status bits

    return 0; // Indicate success
}

// Function to convert raw temperature data to Celsius
float convert_thermocouple_temp(int raw_temp) {
    // Check for fault
    if (raw_temp & 0x00000007) {
        fprintf(stderr, "MAX31855 Fault Detected: 0x%02X\n", raw_temp);
        return -273.15; // Return absolute zero as error indicator
    }

    // Extract thermocouple temperature (signed 14-bit value)
    int16_t thermocouple_data = (raw_temp >> 18) & 0x3FFF; // Mask and shift
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend if negative
    }

    return thermocouple_data * 0.25;
}

// Function to map temperature to PWM duty cycle using a piecewise function
int map_temperature_to_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_THRESHOLD_LOW) {
        duty_cycle = PWM_DUTY_CYCLE_MIN;
    } else if (temperature >= TEMP_THRESHOLD_HIGH) {
        duty_cycle = PWM_DUTY_CYCLE_MAX;
    } else {
        // Linear ramp from 0% to 50% between 25-40°C
        duty_cycle = (int)(((temperature - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW)) * 50.0);
        if (duty_cycle > 50) {
            duty_cycle = 50;
        } else if (duty_cycle < 0) {
            duty_cycle = 0;
        }
    }

    return duty_cycle;
}

// Function to update the fan speed using hardware PWM
void update_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].temperature = temperature;
    log_buffer[log_index].duty_cycle = duty_cycle;
    log_index = (log_index + 1) % BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int raw_thermocouple_temp;
    int fault_status;
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open SPI channel 0
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Fan control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature and fault status
        if (spi_read_max31855(spi_handle, &raw_thermocouple_temp, &fault_status) == 0) {
            // Convert raw temperature to Celsius
            temperature = convert_thermocouple_temp(raw_thermocouple_temp);

            // Map temperature to duty cycle
            duty_cycle = map_temperature_to_duty_cycle(temperature);

            // Update fan speed
            update_fan_speed(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);

            // Print current state
            printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read MAX31855 data. Skipping fan update.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Print the log buffer
    printf("Log Buffer Contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (log_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("  %s, Temperature: %.2f°C, Duty Cycle: %d%%\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

