#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // OSS = 0
#define BMP180_CMD_PRESSURE1 0x74 // OSS = 1
#define BMP180_CMD_PRESSURE2 0xB4 // OSS = 2
#define BMP180_CMD_PRESSURE3 0xF4 // OSS = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global variables
static int i2c_handle;
static int logging_enabled = 0;
static FILE *log_file = NULL;
static volatile int interrupt_count = 0;

// Calibration data
static short ac1, ac2, ac3, b1, b2, mb, mc, md;
static unsigned short ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(long *raw_temperature);
int read_raw_pressure(long *raw_pressure);
double calculate_temperature(long ut);
double calculate_pressure(long up, int oss);
void log_data(double temperature, double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
static int16_t read_int16(int reg)
{
    int16_t msb = wiringPiI2CReadReg8(i2c_handle, reg);
    int16_t lsb = wiringPiI2CReadReg8(i2c_handle, reg + 1);
    return (msb << 8) | lsb;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_int16(BMP180_REG_CAL_AC1);
    ac2 = read_int16(BMP180_REG_CAL_AC2);
    ac3 = read_int16(BMP180_REG_CAL_AC3);
    ac4 = read_int16(BMP180_REG_CAL_AC4);
    ac5 = read_int16(BMP180_REG_CAL_AC5);
    ac6 = read_int16(BMP180_REG_CAL_AC6);
    b1 = read_int16(BMP180_REG_CAL_B1);
    b2 = read_int16(BMP180_REG_CAL_B2);
    mb = read_int16(BMP180_REG_CAL_MB);
    mc = read_int16(BMP180_REG_CAL_MC);
    md = read_int16(BMP180_REG_CAL_MD);

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(long *raw_temperature)
{
    wiringPiI2CWriteReg8(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP);
    gpioDelay(5); // Wait 4.5ms

    int msb = wiringPiI2CReadReg8(i2c_handle, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_handle, BMP180_REG_LSB);

    *raw_temperature = (msb << 8) | lsb;
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(long *raw_pressure)
{
    int oss = 3; // Oversampling setting
    wiringPiI2CWriteReg8(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE3);
    gpioDelay(27); // Wait for conversion (OSS = 3)

    int msb = wiringPiI2CReadReg8(i2c_handle, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_handle, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_handle, BMP180_REG_XLSB);

    *raw_pressure = (((long)msb << 16) | ((long)lsb << 8) | (long)xlsb) >> (8 - oss);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(long ut)
{
    long x1 = ((ut - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(long up, int oss)
{
    long x1, x2, x3, b3, b6, p;
    unsigned long b4, b7;

    long ut = 0; // Dummy value for calculation
    long b5 = ((long)ut - (long)ac6) * ((long)ac5) >> 15;
    long x1_temp = b5 - ((long)mc << 11) / ((b5 + 8) >> 4);
    long x2_temp = (x1_temp * (x1_temp * (long)ac2 >> 12)) >> 11;
    long x3_temp = ((long)b2 * ((x1_temp * (long)ac1 >> 10) + ((long)ac3 * 2))) >> 13;
    unsigned long b4_temp = ((unsigned long)x3_temp + 2) >> 2;
    unsigned long b7_temp = ((unsigned long)x2_temp * (unsigned long)(x1_temp * (long)ac1 >> 10)) >> 16;

    b6 = b4_temp - ((long)b1 * 4096);
    if (b6 < 0)
    {
        b6 = 0;
    }
    b7 = ((unsigned long)b7_temp - ((long)b1 * 4096)) * ((unsigned long)4096) / (b6 + 32768);
    x1 = (b7 + 2) >> 15;
    x2 = ((long)ac3 * (x1 * x1 >> 13)) >> 11;
    x3 = ((long)ac2 * x1) >> 12;
    p = ((long)x2 + x3 + 2) >> 2;
    return p;
}

// Function to log data to a file
void log_data(double temperature, double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    interrupt_count++;
    if (interrupt_count % 2 == 0) // Toggle logging every other interrupt
    {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Disable interrupt
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);

    // Close I2C handle
    if (i2c_handle >= 0)
    {
        close(i2c_handle);
    }

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Release pigpio resources
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi I2C
    i2c_handle = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0)
    {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on GPIO2
    gpioSetMode(2, PI_INPUT);
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1)
    {
        if (logging_enabled)
        {
            long raw_temperature, raw_pressure;
            double temperature, pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) != 0 || read_raw_pressure(&raw_pressure) != 0)
            {
                fprintf(stderr, "Failed to read raw data\n");
                break; // Exit loop on error
            }

            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temperature);
            pressure = calculate_pressure(raw_pressure, 3); // OSS = 3

            // Log data
            log_data(temperature, pressure);
        }

        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

