#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define RTD_REGISTER 0x01
#define CONFIGURATION_REGISTER 0x00
#define CONFIGURATION_BIT_MASK 0x07
#define CONFIGURATION_BIT_VALUE 0x03 // 3-wire RTD, 100mV bias
#define TEMPERATURE_REGISTER 0x00
#define TEMPERATURE_REGISTER_MSB 0x00
#define TEMPERATURE_REGISTER_LSB 0x01
#define TEMPERATURE_REGISTER_XLSB 0x02
#define RTD_FAULT_REGISTER 0x03
#define RTD_FAULT_BIT_MASK 0x07
#define RTD_FAULT_BIT_VALUE 0x00 // No fault
#define LOG_FILE "rtd_log.csv"
#define SLEEP_SECONDS 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    int rtd_register;
    int configuration_register;
    int configuration_bit_mask;
    int configuration_bit_value;
    int temperature_register;
    int temperature_register_msb;
    int temperature_register_lsb;
    int temperature_register_xlsb;
    int rtd_fault_register;
    int rtd_fault_bit_mask;
    int rtd_fault_bit_value;
    char *log_file_name;
    int sleep_seconds;
} Config;

// Function prototypes
int initialize_spi(Config *config);
int configure_max31865(int spi_handle, int config_register, int config_bit_mask, int config_bit_value);
int read_rtd_register(int spi_handle, int rtd_register);
int read_fault_register(int spi_handle, int rtd_fault_register);
float calculate_temperature(int rtd_value, int rtd_fault);
int log_data(float temperature);
void signal_handler(int signal);
void cleanup(Config *config);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi(Config *config) {
    spi_handle = spiOpen(config->spi_channel, config->spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure MAX31865
int configure_max31865(int spi_handle, int config_register, int config_bit_mask, int config_bit_value) {
    int status;
    unsigned char config_data[3];

    // Write configuration data
    config_data[0] = config_bit_mask | 0x01; // Enable 3-wire RTD
    config_data[1] = config_bit_value;
    config_data[2] = 0x00; // Dummy byte

    status = spiWrite(spi_handle, (char *)config_data, 3);
    if (status != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read RTD register
int read_rtd_register(int spi_handle, int rtd_register) {
    unsigned char data[3];
    int status;

    data[0] = rtd_register & 0x0F; // MSB of register address
    data[1] = 0x00; // Dummy byte
    data[2] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, (char *)data, (char *)data, 3);
    if (status != 0) {
        fprintf(stderr, "Error reading RTD register: %d\n", status);
        return -1;
    }

    return ((unsigned int)data[1] << 16) | ((unsigned int)data[2] << 8) | (unsigned int)data[0];
}

// Read fault register
int read_fault_register(int spi_handle, int rtd_fault_register) {
    unsigned char data[2];
    int status;

    data[0] = rtd_fault_register & 0x0F; // MSB of register address
    data[1] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, (char *)data, (char *)data, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading fault register: %d\n", status);
        return -1;
    }

    return ((unsigned int)data[1] << 8) | (unsigned int)data[0];
}

// Calculate temperature
float calculate_temperature(int rtd_value, int rtd_fault) {
    float rtd_resistance = (float)rtd_value * 430.0 / 32768.0; // Assuming 430 ohms RTD
    float temperature = (rtd_resistance - 100.0) / 0.385; // Callendar-Van Dusen equation
    return temperature;
}

// Log data to file
int log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup(Config *config) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_baud = SPI_BAUD,
        .rtd_register = RTD_REGISTER,
        .configuration_register = CONFIGURATION_REGISTER,
        .configuration_bit_mask = CONFIGURATION_BIT_MASK,
        .configuration_bit_value = CONFIGURATION_BIT_VALUE,
        .temperature_register = TEMPERATURE_REGISTER,
        .temperature_register_msb = TEMPERATURE_REGISTER_MSB,
        .temperature_register_lsb = TEMPERATURE_REGISTER_LSB,
        .temperature_register_xlsb = TEMPERATURE_REGISTER_XLSB,
        .rtd_fault_register = RTD_FAULT_REGISTER,
        .rtd_fault_bit_mask = RTD_FAULT_BIT_MASK,
        .rtd_fault_bit_value = RTD_FAULT_BIT_VALUE,
        .log_file_name = LOG_FILE,
        .sleep_seconds = SLEEP_SECONDS
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi(&config) != 0) {
        cleanup(&config);
        return 1;
    }

    // Configure MAX31865
    if (configure_max31865(spi_handle, config.configuration_register, config.configuration_bit_mask, config.configuration_bit_value) != 0) {
        cleanup(&config);
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
