int bme280_read_raw_data(int i2c_fd, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t data[8];
    if (read(i2c_fd, data, 8) != 8) {
        perror("Failed to read raw data from I2C device");
        return -1;
    }

    *temperature = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *pressure = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *humidity = (data[6] << 8) | data[7];

    return 0;
