    uint8_t chip_id;

    // Check the chip ID
    if (bme280_read_register(i2c_fd, BME280_REG_CHIPID, &chip_id) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
        return -1;
    }

    // Set humidity oversampling to 1x
    if (bme280_write_register(i2c_fd, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error writing to CTRL_HUM register\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    if (bme280_write_register(i2c_fd, BME280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set the config register (t_sb = 0.5ms, filter off)
    if (bme280_write_register(i2c_fd, BME280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

