}

// Function to read temperature, humidity, and pressure data from the BME280
int bme280_read_data(int i2c_fd, struct bme280_calib_data *calib, float *temperature, float *humidity, float *pressure) {
    int32_t raw_temperature, raw_pressure, raw_humidity;

