// Function to log data to a CSV file
int log_data(FILE *fp, float temperature, float humidity, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("bme280_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }
    fflush(log_file);

    // Initialize BME280 sensor
    if (bme280_init(i2c_fd) != 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (bme280_read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity, pressure;

    // Main loop
    while (!stop_flag) {
        if (bme280_read_data(i2c_fd, &calib, &temperature, &humidity, &pressure) == 0) {
            if (log_data(log_file, temperature, humidity, pressure) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

