#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting
#define OSS 0

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size (60 seconds)
#define BUFFER_SIZE 60

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure data
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_data_t;

// Structure to hold rolling average pressure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} rolling_average_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
rolling_average_t pressure_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_calibration_data(bmp180_calibration_data_t *cal_data);
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t raw_temp, bmp180_calibration_data_t cal_data);
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp, bmp180_calibration_data_t cal_data, int oss);
void add_pressure_reading(rolling_average_t *avg, float pressure);
float calculate_rolling_average(rolling_average_t *avg);
void alert_callback(int gpio, int level, uint32_t tick);
