// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *cal_data) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal_data->ac1 = (buf[0] << 8) | buf[1];
    cal_data->ac2 = (buf[2] << 8) | buf[3];
    cal_data->ac3 = (buf[4] << 8) | buf[5];
    cal_data->ac4 = (buf[6] << 8) | buf[7];
    cal_data->ac5 = (buf[8] << 8) | buf[9];
    cal_data->ac6 = (buf[10] << 8) | buf[11];
    cal_data->b1 = (buf[12] << 8) | buf[13];
    cal_data->b2 = (buf[14] << 8) | buf[15];
    cal_data->mb = (buf[16] << 8) | buf[17];
    cal_data->mc = (buf[18] << 8) | buf[19];
    cal_data->md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5 ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5 ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for pressure read\n");
        return -1;
    }

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int32_t raw_temp, bmp180_calibration_data_t cal_data) {
    int32_t X1 = ((raw_temp - (int32_t)cal_data.ac6) * (int32_t)cal_data.ac5) >> 15;
    int32_t X2 = ((int32_t)cal_data.mc << 11) / (X1 + cal_data.md);
    int32_t B5 = X1 + X2;
    float temperature = ((B5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp, bmp180_calibration_data_t cal_data, int oss) {
    int32_t X1 = ((raw_temp - (int32_t)cal_data.ac6) * (int32_t)cal_data.ac5) >> 15;
    int32_t X2 = ((int32_t)cal_data.mc << 11) / (X1 + cal_data.md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (cal_data.b2 * (B6 * B6) >> 12) >> 11;
    X2 = (cal_data.ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((cal_data.ac1 * 4 + X3) << oss) + 2) >> 2;

    X1 = (cal_data.ac3 * B6) >> 13;
    X2 = (cal_data.b1 * ((B6 * B6) >> 12)) >> 16;
    int32_t X3_2 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = (cal_data.ac4 * (uint32_t)(X3_2 + 32768)) >> 15;

    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> oss);
    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Function to add a pressure reading to the circular buffer
void add_pressure_reading(rolling_average_t *avg, float pressure) {
    avg->buffer[avg->head] = pressure;
    avg->head = (avg->head + 1) % BUFFER_SIZE;
    if (avg->count < BUFFER_SIZE) {
        avg->count++;
    }
}

// Function to calculate the rolling average
float calculate_rolling_average(rolling_average_t *avg) {
    if (avg->count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < avg->count; i++) {
        sum += avg->buffer[i];
    }
    return sum / avg->count;
}

// Callback function for alert pin
void alert_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        float avg_pressure = calculate_rolling_average(&pressure_buffer);
