    time_t timestamp;
    float pressure;
} pressure_data_t;

// Structure to hold rolling average pressure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} rolling_average_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
rolling_average_t pressure_buffer;
