    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read a 16-bit value from the BMP180
uint16_t read_16bit_value_u(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_16bit_value(BMP180_REG_CAL_AC1);
    ac2 = read_16bit_value(BMP180_REG_CAL_AC2);
    ac3 = read_16bit_value(BMP180_REG_CAL_AC3);
    ac4 = read_16bit_value_u(BMP180_REG_CAL_AC4);
    ac5 = read_16bit_value_u(BMP180_REG_CAL_AC5);
    ac6 = read_16bit_value_u(BMP180_REG_CAL_AC6);
    b1 = read_16bit_value(BMP180_REG_CAL_B1);
    b2 = read_16bit_value(BMP180_REG_CAL_B2);
    mb = read_16bit_value(BMP180_REG_CAL_MB);
    mc = read_16bit_value(BMP180_REG_CAL_MC);
    md = read_16bit_value(BMP180_REG_CAL_MD);

    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        b1 == 0 || b2 == 0 || mb == 0 || mc == 0 || md == 0) {
        fprintf(stderr, "Error: Calibration data is invalid.\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature()
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing to control register for temperature: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }

    return (int)((buf[0] << 8) | buf[1]);
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure()
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing to control register for pressure: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
    }

    return ((int)buf[0] << 16 | (int)buf[1] << 8 | (int)buf[2]) >> (8 - BMP180_OSS);
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t up, int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    uint32_t x5 = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x6 = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t b4 = x5 + x6;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Timer interrupt handler
void timer_interrupt_handler(int timer_id)
{
    int32_t ut = read_raw_temperature();
    int32_t up = read_raw_pressure();

    if (ut == -1 || up == -1) {
        fprintf(stderr, "Error reading sensor data. Retrying...\n");
        return;
    }

    double temperature = calculate_temperature(ut);
    double pressure = calculate_pressure(up, ut);

    log_data(temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Calibration data read failed. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer interrupt
    if (gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, 0) != 0) {
        fprintf(stderr, "Error setting up timer interrupt: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up resources
    gpioSetTimerFuncEx(0, 500, NULL, 0); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

