#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to read temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

int map_temp_to_duty(int temp) {
    if (temp < 40) {
        return 0;
    } else if (temp > 70) {
        return 255;
    } else {
        return (int)(((float)(temp - 40) / (70 - 40)) * 255.0);
    }
}

int set_fan_speed(int duty) {
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set fan speed\n");
        return -1;
    }
    return 0;
}

int log_data(int temp, int duty) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %d°C, Duty Cycle: %d%%\n", timestamp, temp, duty);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read temperature, using previous value or exiting.\n");
            // Consider adding a delay here to avoid flooding the console with errors
        } else {
            int duty = map_temp_to_duty(temp);
            if (set_fan_speed(duty) != 0) {
                fprintf(stderr, "Failed to set fan speed, using previous value or exiting.\n");
            }

            if (log_data(temp, duty) != 0) {
                fprintf(stderr, "Failed to log data, using previous value or exiting.\n");
            }
        }
        sleep(5);
    }

    gpioPWM(FAN_GPIO, 0); // Stop the fan
    gpioTerminate();
    return 0;
}

