#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>
#include <pthread.h>
#include <stdatomic.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static int i2c_handle;
static volatile sig_atomic_t terminate = 0;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static double temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static double temperature_running_average = 0.0;
static volatile int running = 1; // Flag for the thread

// Function prototypes
int init_i2c();
int read_temperature(double *temperature);
double calculate_average(double new_value);
void control_led(double average_temperature);
void *sensor_reading_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    double temperature;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75 sensor
int read_temperature(double *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    *temperature = (double)raw_temp * 0.125; // Each bit is 0.125 degrees C

    return 0;
}

// Function to calculate the running average
double calculate_average(double new_value) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_running_average = new_value;
    pthread_mutex_unlock(&buffer_mutex);
    return temperature_running_average;
}

// Function to control the LED based on temperature
void control_led(double average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Thread function for sensor reading
void *sensor_reading_thread(void *arg) {
    while (!terminate) {
        double temperature;
        if (read_temperature(&temperature) == 0) {
            pthread_mutex_lock(&buffer_mutex);
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            pthread_mutex_unlock(&buffer_mutex);

            double average_temperature = calculate_average(temperature);
            control_led(average_temperature);
        } else {
            fprintf(stderr, "Error reading temperature, retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting thread.\n");
                break; // Exit the thread if re-initialization fails
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 1 second
    }
    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create the sensor reading thread
    pthread_t sensor_thread;
    if (pthread_create(&sensor_thread, NULL, sensor_reading_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor reading thread\n");
        cleanup();
        return 1;
    }

    // Wait for the thread to finish (or until termination signal is received)
    pthread_join(sensor_thread, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

