// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }

    // MAX31865 Initialization
    char config_data[2] = {0xC1, 0x00}; // Enable VBIAS, Auto-conversion
    spiWrite(spi_handle, config_data, 2);
    gpioDelay(10000); // Wait for initialization (10ms)

    return 0;
}

// Function to read data from MAX31865
int read_max31865(int *rtd_code) {
    char data[3];
    int result;

    // Read RTD code (2 bytes) and fault status (1 byte)
    result = spiRead(spi_handle, data, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return 1;
    }

    *rtd_code = ((data[0] & 0x3F) << 8) | data[1]; // Combine MSB and LSB

    // Check fault status
    int fault_status = (data[0] >> 6) & 0x03;
    if (fault_status != 0) {
        fprintf(stderr, "MAX31865 Fault detected: %d\n", fault_status);
        if (fault_status == 0x01) {
            fprintf(stderr, "Open circuit fault\n");
        } else if (fault_status == 0x02) {
            fprintf(stderr, "Short to VCC fault\n");
        } else if (fault_status == 0x03) {
            fprintf(stderr, "Short to GND fault\n");
        }
        return 1; // Indicate fault
    }

    return 0; // Indicate success
}

// Function to convert RTD code to resistance
double convert_rtd_code_to_resistance(int rtd_code) {
    return (rtd_code / 32768.0) * R_REF;
}

// Function to convert resistance to temperature
double convert_resistance_to_temperature(double resistance) {
    return R_PT100 * (1 + Kp * resistance + Ki * (time(NULL) - previous_error) + Kd * (sin(Kp * resistance) - sin(previous_error))));
}

// Function to calculate PID output
double calculate_pid(double current_temperature, double target_temperature, double *integral, double previous_error) {
    double error = target_temperature - current_temperature;
    *integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 1000.0 / 100.0); // Scale to 0-1000
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > 1000) pwm_value = 1000;
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to load configuration from JSON file
void load_config(const char *config_file) {
    json_t *root;
    json_error_t error;

    root = json_load_file(config_file, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        // Use default values if config file is missing
        target_temperature = TARGET_TEMPERATURE;
        Kp = Kp;
        Ki = Ki;
        Kd = Kd;
        return;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    if (target_temp) {
        target_temperature = json_real_value(target_temp);
    } else {
        target_temperature = TARGET_TEMPERATURE;
    }

    json_t *Kp_json = json_object_get(root, "Kp");
    if (Kp_json) {
        Kp = json_real_value(Kp_json);
    } else {
        Kp = Kp;
    }

    json_t *Ki_json = json_object_get(root, "Ki");
    if (Ki_json) {
