    json_t *Kd_json = json_object_get(root, "Kd");
    if (Kd_json) {
        Kd = json_real_value(Kd_json);
    } else {
        Kd = Kd;
    }

    json_decref(root);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioPWM(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    int rtd_code;
    double resistance, temperature;
    double pid_output;
    double target_temperature = TARGET_TEMPERATURE;
    double Kp = Kp;
    double Ki = Ki;
    double Kd = Kd;
    time_t last_config_read = 0;

    // Load configuration from file
    load_config("config.json");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read RTD code from MAX31865
        if (read_max31865(&rtd_code) != 0) {
            fprintf(stderr, "Failed to read RTD code. Exiting.\n");
            cleanup();
            return 1;
        }

        // Convert RTD code to resistance
        resistance = convert_rtd_code_to_resistance(rtd_code);

        // Convert resistance to temperature
        temperature = convert_resistance_to_temperature(resistance);

        // Calculate PID output
        pid_output = calculate_pid(temperature, target_temperature, &integral, &previous_error);

        // Set PWM duty cycle
        set_pwm_duty_cycle(pid_output);

        // Log data
        printf("Temperature: %.2f C, Resistance: %.2f ohms, PID Output: %.2f\n", temperature, resistance, pid_output);

        // Failsafe shutoff
        if (temperature > 80.0 || rtd_code == 0 || (time(NULL) - last_config_read > 5)) {
            fprintf(stderr, "Failsafe triggered! Shutting down heater.\n");
            set_pwm_duty_cycle(0.0);
            cleanup();
            return 1;
        }

        // Update last config read time
        last_config_read = time(NULL);

        // Wait for 100 ms
        gpioDelay(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

