#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c(int addr);
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int oss, int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, int raw_temp, int oss);
int check_thresholds(double temperature, double pressure);
void log_breach(double temperature, double pressure);
void signal_handler(int sig);

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

bmp180_calibration_data_t calibration;

// Function to initialize I2C
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    uint8_t buffer[22];
    if (read(i2c_fd, buffer, 22) != 22) {
        perror("Error reading calibration data");
        return -1;
    }

    calibration.ac1 = (buffer[0] << 8) | buffer[1];
    calibration.ac2 = (buffer[2] << 8) | buffer[3];
    calibration.ac3 = (buffer[4] << 8) | buffer[5];
    calibration.ac4 = (buffer[6] << 8) | buffer[7];
    calibration.ac5 = (buffer[8] << 8) | buffer[9];
    calibration.ac6 = (buffer[10] << 8) | buffer[11];
    calibration.b1 = (buffer[12] << 8) | buffer[13];
    calibration.b2 = (buffer[14] << 8) | buffer[15];
    calibration.mb = (buffer[16] << 8) | buffer[17];
    calibration.mc = (buffer[18] << 8) | buffer[19];
    calibration.md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    uint8_t write_buffer[2] = {BMP180_REG_CONTROL, BMP180_CMD_TEMP};
    if (write(i2c_fd, write_buffer, 2) != 2) {
        perror("Error writing temperature command");
        return -1;
    }
    usleep(5000); // Wait 4.5ms

    uint8_t read_buffer[2];
    write_buffer[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_buffer, 1) != 1) {
        perror("Error writing read register address");
        return -1;
    }
    if (read(i2c_fd, read_buffer, 2) != 2) {
        perror("Error reading raw temperature data");
        return -1;
    }

    *raw_temp = (read_buffer[0] << 8) | read_buffer[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int oss, int *raw_pressure) {
    uint8_t write_buffer[2];
    uint8_t read_buffer[3];

    switch (oss) {
        case 0: write_buffer[0] = BMP180_REG_CONTROL; write_buffer[1] = BMP180_CMD_PRESSURE0; break;
        case 1: write_buffer[0] = BMP180_REG_CONTROL; write_buffer[1] = BMP180_CMD_PRESSURE1; break;
        case 2: write_buffer[0] = BMP180_REG_CONTROL; write_buffer[1] = BMP180_CMD_PRESSURE2; break;
        case 3: write_buffer[0] = BMP180_REG_CONTROL; write_buffer[1] = BMP180_CMD_PRESSURE3; break;
        default: fprintf(stderr, "Invalid OSS value\n"); return -1;
    }

    if (write(i2c_fd, write_buffer, 2) != 2) {
        perror("Error writing pressure command");
        return -1;
    }

    switch (oss) {
        case 0: usleep(5000); break; // 4.5ms
        case 1: usleep(8000); break; // 7.5ms
        case 2: usleep(14000); break; // 13.5ms
        case 3: usleep(26000); break; // 25.5ms
    }

    write_buffer[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_buffer, 1) != 1) {
        perror("Error writing read register address");
        return -1;
    }

    if (read(i2c_fd, read_buffer, 3) != 3) {
        perror("Error reading raw pressure data");
        return -1;
    }

    *raw_pressure = ((read_buffer[0] << 16) | (read_buffer[1] << 8) | read_buffer[2]) >> (8 - oss);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1 = (((long)raw_temp - (long)calibration.ac6) * (long)calibration.ac5) >> 15;
    long x2 = ((long)calibration.mc << 11) / (x1 + calibration.md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temp, int oss) {
    long x1 = (((long)raw_temp - (long)calibration.ac6) * (long)calibration.ac5) >> 15;
    long x2 = ((long)calibration.mc << 11) / (x1 + calibration.md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration.b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)calibration.ac2 * b6) >> 11;
    long b3 = (((((long)calibration.ac1) * 4 + x3) << oss) + 2) >> 2;

    unsigned long x1_pressure = ((long)calibration.ac3 * b6) >> 13;
    unsigned long x2_pressure = ((long)calibration.b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) >> 2);
    unsigned long b4 = ((unsigned long)calibration.ac4 * (x3_pressure + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> oss);

    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to check if temperature or pressure exceeds thresholds
int check_thresholds(double temperature, double pressure) {
    return (temperature > 30.0 || pressure < 950.0);
}

// Function to log breach events to a file
void log_breach(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
