        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp, 3);

        // Check for breach
        if (check_thresholds(temperature, pressure)) {
            log_breach(temperature, pressure);
        }

        sleep(1); // Sample every second
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("BMP180 sensor monitoring stopped.\n");

    return 0;
}

