#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // OSS = 0

// GPIO pin for fan control
#define FAN_GPIO 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t raw_temp);
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
void add_to_buffer(float temperature, float pressure);
void print_buffer();
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        gpioTerminate();
        return 1;
    }

    // Set fan GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback (every 500ms)
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer callback\n");
        gpioTerminate();
        return 1;
    }

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("BMP180 sensor monitoring stopped.\n");

    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read calibration data from BMP180
int read_calibration_data() {
    ac1 = i2cReadWordData(i2c_handle, 0xAA);
    ac2 = i2cReadWordData(i2c_handle, 0xAC);
    ac3 = i2cReadWordData(i2c_handle, 0xAE);
    ac4 = i2cReadWordData(i2c_handle, 0xB0);
    ac5 = i2cReadWordData(i2c_handle, 0xB2);
    ac6 = i2cReadWordData(i2c_handle, 0xB4);
    b1 = i2cReadWordData(i2c_handle, 0xB6);
    b2 = i2cReadWordData(i2c_handle, 0xB8);
    mb = i2cReadWordData(i2c_handle, 0xBA);
    mc = i2cReadWordData(i2c_handle, 0xBC);
    md = i2cReadWordData(i2c_handle, 0xBE);

    if (ac1 == PI_I2C_READ_FAILED || ac2 == PI_I2C_READ_FAILED || ac3 == PI_I2C_READ_FAILED ||
        ac4 == PI_I2C_READ_FAILED || ac5 == PI_I2C_READ_FAILED || ac6 == PI_I2C_READ_FAILED ||
        b1 == PI_I2C_READ_FAILED || b2 == PI_I2C_READ_FAILED || mb == PI_I2C_READ_FAILED ||
        mc == PI_I2C_READ_FAILED || md == PI_I2C_READ_FAILED) {
        fprintf(stderr, "Failed to read calibration data from BMP180\n");
        return 1;
    }

    return 0;
}

// Read raw temperature value from BMP180
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    buf[0] = BMP180_CMD_TEMP;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write temperature command\n");
        return 1;
    }
    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write register address for temperature read\n");
        return 1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read raw temperature data\n");
        return 1;
    }
    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Read raw pressure value from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[2];
    buf[0] = BMP180_CMD_PRESSURE0;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write pressure command\n");
        return 1;
    }
    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write register address for pressure read\n");
        return 1;
    }
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Failed to read raw pressure data\n");
        return 1;
    }
    *raw_pressure = (buf[0] << 16 | buf[1] << 8 | buf[2]) >> (8 - 0); // OSS = 0
    return 0;
}

// Calculate true temperature (°C)
float calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    float temperature = ((B5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Calculate true pressure (Pa)
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X4 = ((int32_t)ac2 * B6) >> 11;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << 0) + X4 + 2) >> 2;

    uint32_t X1_u = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X2_u = ((uint32_t)b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t X3_u = ((X1_u + X2_u + 2) >> 2);
    uint32_t B4 = ((uint32_t)ac4 * (X3_u + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> 0);

    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Add new reading to the circular buffer
void add_to_buffer(float temperature, float pressure) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = circular_buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f °C, Pressure: %.2f Pa\n", time_str, circular_buffer[i].temperature, circular_buffer[i].pressure);
    }
    printf("--- End of Buffer ---\n\n");
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    int32_t raw_temp, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Failed to read raw temperature\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Failed to read raw pressure\n");
        return;
    }

    temperature = calculate_temperature(raw_temp);
    pressure = calculate_pressure(raw_pressure, raw_temp);

    add_to_buffer(temperature, pressure);
    print_buffer();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    program_running = 0;
}

