// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define SPI_MODE 0
#define MAX31855_FAULT_OPEN 0x40
#define MAX31855_FAULT_GND 0x20
#define MAX31855_FAULT_VCC 0x10
#define TARGET_TEMPERATURE 25.0
#define PI_KP 1.0
#define PI_KI 0.1
#define PI_KD 0.01
#define MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    float target_temperature;
    float kp;
    float ki;
    float kd;
    int max_duty_cycle;
} PIDConfig;

// Function prototypes
int initialize_gpio();
int initialize_spi();
float read_temperature();
float calculate_duty_cycle(float temperature);
void set_heater_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
void cleanup();

// PID controller functions
float pid_calculate(float setpoint, float actual_value, float *integral, float *previous_error, float dt);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // Set PWM frequency to 1 kHz
    gpioSetPWMrange(HEATER_GPIO, 100); // Set PWM range to 100

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int fault = 0;

    spiRead(spi_handle, data, 4);

    // Check for fault
    if (data[3] & 0x01) {
        if (data[3] & 0x02) {
            fprintf(stderr, "MAX31855 Fault: Open circuit\n");
            log_data(-273.15, 0.0); // Log error with absolute zero
            return -273.15; // Indicate error
        } else if (data[3] & 0x04) {
            fprintf(stderr, "MAX31855 Fault: GND short\n");
            log_data(-273.15, 0.0); // Log error with absolute zero
            return -273.15; // Indicate error
        } else {
            fprintf(stderr, "MAX31855 Fault: VCC short\n");
            log_data(-273.15, 0.0); // Log error with absolute zero
            return -273.15; // Indicate error
        }
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle using PI controller
float calculate_duty_cycle(float temperature) {
    float error = TARGET_TEMPERATURE - temperature;
    float integral = 0.0;
    float previous_error = 0.0;
    float dt = 1.0; // Time step (1 second)

    float duty_cycle = pid_calculate(TARGET_TEMPERATURE, temperature, &integral, &previous_error, dt);

    // Clamp duty cycle between 0 and 100%
    if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else if (duty_cycle > 100.0) {
        duty_cycle = 100.0;
    }

    return duty_cycle;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else if (duty_cycle > 100.0) {
        duty_cycle = 100.0;
    }
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    set_heater_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

// PID controller functions
float pid_calculate(float setpoint, float actual_value, float *integral, float *previous_error, float dt) {
    float error = setpoint - actual_value;
    *integral += error * dt;
    float derivative = (error - *previous_error) / dt;
    float output = PI_KP * error + PI_KI * (*integral) + PI_KD * derivative;
    *previous_error = error;
    return output;
}

