    // Initialize configuration
    PIDConfig config = {
        .target_temperature = TARGET_TEMPERATURE,
        .kp = PI_KP,
        .ki = PI_KI,
        .kd = PI_KD,
        .max_duty_cycle = MAX_DUTY_CYCLE
    };

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and SPI
    if (initialize_gpio() != 0 || initialize_spi() != 0) {
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature == -273.15) {
            fprintf(stderr, "Error reading temperature, skipping this iteration.\n");
            sleep(1);
            continue;
        }

        float duty_cycle = calculate_duty_cycle(temperature);
        set_heater_duty_cycle(duty_cycle);
        log_data(temperature, duty_cycle);

        sleep(1); // Control loop frequency
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

