#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds and corresponding colors
#define TEMP_THRESHOLD_LOW 40000
#define TEMP_THRESHOLD_HIGH 60000

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off all LEDs (common anode)
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();
    exit(0);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1; // Default to -1 to indicate error

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file!\n");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file!\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp;
}

// Function to map temperature to RGB values
void map_temperature_to_rgb(int temp, int *red, int *green, int *blue) {
    if (temp < TEMP_THRESHOLD_LOW) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp < TEMP_THRESHOLD_HIGH) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

// Function to set the RGB LED color using hardware PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red); // Invert for common anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common anode
    gpioPWM(BLUE_PIN, 255 - blue); // Invert for common anode
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (optional, but good practice)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (optional, but good practice)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(BLUE_PIN, 1000); // 1 kHz

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read CPU temperature
        int temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, skipping update cycle.\n");
            gpioDelay(500000); // 0.5 seconds
            continue;
        }

        // Map temperature to RGB values
        int red, green, blue;
        map_temperature_to_rgb(temp, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Print current temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);

        // Delay for 0.5 seconds
        gpioDelay(500000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();

    return 0;
}

