#include <pigpio.h>
#include <curl/curl.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5
#define LOG_FILE "dht22_log.txt"

// Global variables
static volatile int running = 1;
static int sockfd = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int checksum;
} sensor_data_t;

// Function prototypes
int init_gpio();
int read_dht22(sensor_data_t *data);
int validate_checksum(const sensor_data_t *data);
int post_data(const sensor_data_t *data);
void signal_handler(int signal);
void log_message(const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, exiting...");
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 1); // Set to high initially
    gpioDelay(1000); // 1 ms
    gpioWrite(DHT22_GPIO, 0); // Set to low
    gpioDelay(1000); // 1 ms
    gpioSetMode(DHT22_GPIO, PI_INPUT);
    gpioSetPullUpDown(DHT22_GPIO, PI_PUD_UP);

    log_message("GPIO initialized");
    return 0;
}

// Read DHT22 sensor data
int read_dht22(sensor_data_t *data) {
    int data_bits[40] = {0};
    int bit_index = 0;
    int byte_index = 0;
    int i;

    // Start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data bits
    for (i = 0; i < 40; i++) {
        // Wait for low signal
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1); // 1 us
            timeout++;
        }

        if (timeout >= 100) {
            log_message("Timeout waiting for high signal");
            return -1; // Timeout
        }

        // Wait for high signal
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // 1 us
            timeout++;
        }

        if (timeout >= 100) {
            log_message("Timeout waiting for low signal");
            return -1; // Timeout
        }

        // Determine if it's a 0 or a 1 based on the length of the high pulse
        if (i < 2) {
            data_bits[byte_index] |= (1 << (7 - bit_index));
        } else {
            data_bits[byte_index] |= (1 << (15 - bit_index));
