// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 1); // Set to high initially
    gpioDelay(1000); // 1 ms
    gpioWrite(DHT22_GPIO, 0); // Set to low
    gpioDelay(1000); // 1 ms
    gpioSetMode(DHT22_GPIO, PI_INPUT);
    gpioSetPullUpDown(DHT22_GPIO, PI_PUD_UP);

    log_message("GPIO initialized");
    return 0;
}

// Read DHT22 sensor data
int read_dht22(sensor_data_t *data) {
    int data_bits[40] = {0};
    int bit_index = 0;
    int byte_index = 0;
    int i;

    // Start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data bits
    for (i = 0; i < 40; i++) {
        // Wait for low signal
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1); // 1 us
            timeout++;
        }

