#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // OSS = 0
#define BMP180_CMD_PRESSURE1 0x74 // OSS = 1
#define BMP180_CMD_PRESSURE2 0xB4 // OSS = 2
#define BMP180_CMD_PRESSURE3 0xF4 // OSS = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global variables
int i2c_handle;
int logging_enabled = 0;
int gpio_button = 4;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t ut);
double calculate_pressure(int32_t up, double temperature);
void log_pressure(double pressure);
void button_isr(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read a 16-bit value from the BMP180
uint16_t read_uint16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_int16(BMP180_REG_CAL_AC1);
    ac2 = read_int16(BMP180_REG_CAL_AC2);
    ac3 = read_int16(BMP180_REG_CAL_AC3);
    ac4 = read_uint16(BMP180_REG_CAL_AC4);
    ac5 = read_uint16(BMP180_REG_CAL_AC5);
    ac6 = read_uint16(BMP180_REG_CAL_AC6);
    b1 = read_int16(BMP180_REG_CAL_B1);
    b2 = read_int16(BMP180_REG_CAL_B2);
    mb = read_int16(BMP180_REG_CAL_MB);
    mc = read_int16(BMP180_REG_CAL_MC);
    md = read_int16(BMP180_REG_CAL_MD);

    // Validate calibration data
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        b1 == 0 || b2 == 0 || mb == 0 || mc == 0 || md == 0) {
        fprintf(stderr, "Error: Invalid calibration data. Check sensor connection.\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp)
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE3) != 0) {
        fprintf(stderr, "Error writing pressure command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(26000); // Wait 26 ms (OSS = 3)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - 3); // OSS = 3
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t up, double temperature)
{
    int32_t b6 = ((int32_t)temperature * 10) - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 3) + 2) / 4;
    uint32_t x1_u = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_u = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_u = ((x1_u + x2_u) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (x3_u + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 3);
    int32_t p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to log pressure data to a file
void log_pressure(double pressure)
{
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f hPa\n", s, pressure);
    fclose(fp);
}

// Interrupt service routine for the button
void button_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == FALLING_EDGE) {
        if (gpio == gpio_button) {
            logging_enabled = !logging_enabled;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(gpio_button, PI_INPUT);
    gpioSetPullUpDown(gpio_button, PI_PUD_UP);

    // Set interrupt on falling edge
    gpioSetISRFuncEx(gpio_button, FALLING_EDGE, 0, button_isr, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temp, raw_pressure;
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                double temperature = calculate_temperature(raw_temp);
                double pressure = calculate_pressure(raw_pressure, temperature);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        }
        gpioDelay(2000000); // Sample every 2 seconds
    }

    return 0;
}

