#include <time.h>

#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_SECONDS 2
#define SLEEP_SECONDS 10

// Structure to hold DHT22 data
typedef struct {
    float humidity;
    int checksum;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *server_url = DEFAULT_SERVER_URL;
static int dht22_gpio = DHT22_GPIO;

// Function prototypes
int init_gpio();
DHT22Data read_dht22();
int validate_checksum(DHT22Data data);
int post_humidity(float humidity);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Initialize pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    log_message(LOG_INFO, "pigpio initialised");
    return 0;
}

// Read DHT22 sensor data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(dht22_gpio, PI_OUTPUT);
        gpioWrite(dht22_gpio, 0);
        gpioDelay(1); // 1ms
        gpioWrite(dht22_gpio, 1);
        gpioDelay(40); // 40us

        // Read data
        unsigned int data_bits[40] = {0};
        for (int i = 0; i < 40; i++) {
            int count = 0;
            while (gpioRead(dht22_gpio) == 0) {
                count++;
                gpioDelay(1); // Delay 1us
                if (count > 200) { // Timeout after 200us
                    log_message(LOG_ERR, "DHT22: Timeout waiting for HIGH");
                    data.humidity = -1.0; // Indicate error
                    data.checksum = -1;
                    return data;
                }
            }

            count = 0;
            while (gpioRead(dht22_gpio) == 1) {
                count++;
                gpioDelay(1); // Delay 1us
                if (count > 200) { // Timeout after 200us
                    log_message(LOG_ERR, "DHT22: Timeout waiting for LOW");
                    data.humidity = -1.0; // Indicate error
                    data.checksum = -1;
                    return data;
                }
            }

            data_bits[i] = count;
        }

        // Validate checksum
        if (validate_checksum(data)) {
            data.humidity = (float)((data_bits[0] << 8) | data_bits[1]);
            data.humidity = data.humidity / 10.0;
            data.checksum = data_bits[2];
            return data;
        } else {
            log_message(LOG_ERR, "DHT22: Checksum failure");
            data.humidity = -1.0; // Indicate error
            data.checksum = -1;
            return data;
        }
    }

    log_message(LOG_ERR, "DHT22: Max retries reached");
    data.humidity = -1.0; // Indicate error
    data.checksum = -1;
    return data;
}

// Validate DHT22 checksum
int validate_checksum(DHT22Data data) {
    if (data.checksum != ((data.humidity >> 8) & 0xFF) + (data.humidity & 0xFF)) {
        log_message(LOG_ERR, "DHT22: Checksum mismatch");
        return 0; // Checksum failed
    }
    return 1; // Checksum passed
}

// Post humidity data to server
int post_humidity(float humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[100];
    int retries = 0;

    // Format JSON data
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    while (retries < MAX_RETRIES) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, server_url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // Timeout after 10 seconds
            curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L); // Connection timeout after 5 seconds

            // Set Content-Type header
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                log_message(LOG_ERR, "HTTP POST failed: %s", curl_easy_strerror(res));
            } else {
                log_message(LOG_INFO, "HTTP POST successful");
                curl_slist_free_all(headers); // Free the header list
            }

            curl_easy_cleanup(curl);
            free(json_data);
            return 0; // Success
        } else {
            log_message(LOG_ERR, "curl_easy_init failed");
            retries++;
            sleep(RETRY_DELAY_SECONDS);
        }
    }

    log_message(LOG_ERR, "HTTP POST failed after multiple retries");
    return -1; // Failure
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_gpio() != 0) {
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "DHT22 monitor started");

    // Main loop
    while (running) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.humidity != -1.0) {
            if (post_humidity(dht22_data.humidity) == 0) {
                log_message(LOG_INFO, "Humidity data posted successfully");
            } else {
                log_message(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            log_message(LOG_ERR, "Failed to read humidity data");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    gpioTerminate();
    log_message(LOG_INFO, "DHT22 monitor stopped");
    closelog();

    return 0;
}

