// Constants
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_RANGE 100
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID variables
double integral = 0.0;
double previous_error = 0.0;

// Function prototypes
int spi_read_max31855(int spi_handle, float *thermocouple_temperature, float *internal_temperature, int *fault_status);
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_heater_pwm(int gpio, int duty_cycle);
void log_data(float thermocouple_temperature, int pwm_duty_cycle, double pid_output);
void signal_handler(int signal);

// SPI read function for MAX31855
int spi_read_max31855(int spi_handle, float *thermocouple_temperature, float *internal_temperature, int *fault_status) {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Check fault bits
    *fault_status = (data[0] >> 6) & 0x03; // Extract fault bits (bit 0-2)

    // Extract thermocouple temperature (bits 3-18, signed 14-bit value)
    int16_t thermocouple_raw = ((data[0] & 0x3F) << 8) | data[1];
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000; // Sign extend if negative
    }
    *thermocouple_temperature = thermocouple_raw * 0.25;

    // Extract internal temperature (bits 14-27, signed 14-bit value)
    int16_t internal_raw = ((data[2] << 6) | (data[3] >> 2));
    if (internal_raw & 0x400) {
        internal_raw |= 0xF000; // Sign extend if negative
    }
    *internal_temperature = internal_raw * 0.0625;

    return 0; // Indicate success
}

// PID calculation function
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

