#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Structure to hold configuration data
typedef struct {
    int pwm_frequency;
    int pwm_range;
    int temp_min;
    int temp_max;
    int temp_step;
    char log_file[64];
} Config;

// Function prototypes
int read_cpu_temperature(void);
int calculate_duty_cycle(int temperature);
int set_fan_speed(int duty_cycle);
int log_data(int temperature, int duty_cycle);
void signal_handler(int signal);
int initialize_gpio(void);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down...\n", signal);
    set_fan_speed(0); // Turn off the fan
    cleanup_gpio();     // Release GPIO resources
    exit(0);
}

// Function to read CPU temperature from file
int read_cpu_temperature(void) {
    FILE *fp;
    int temperature = 0;
    char buffer[10];

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000; // Convert millidegrees to degrees Celsius
    } else {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(int temperature) {
    int duty_cycle = 0;

    if (temperature < Config.temp_min) {
        duty_cycle = 0;
    } else if (temperature > Config.temp_max) {
        duty_cycle = Config.pwm_range;
    } else {
        duty_cycle = (int)(((float)(temperature - Config.temp_min) / (Config.temp_max - Config.temp_min)) * (Config.pwm_range - 0));
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > Config.pwm_range) {
        fprintf(stderr, "Error: Duty cycle out of range (0-%d)\n", Config.pwm_range);
        return -1;
    }

    gpioPWM(FAN_GPIO, duty_cycle);
    return 0;
}

// Function to log data to file
int log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

// Function to initialize GPIO
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, Config.pwm_frequency);
    gpioSetPWMrange(FAN_GPIO, Config.pwm_range);

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio(void) {
    gpioPWM(FAN_GPIO, 0); // Stop PWM signal
    gpioTerminate();
}

int main(void) {
    Config config = {25000, 100, 40, 70, 5, LOG_FILE};
    int temperature, duty_cycle;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        temperature = read_cpu_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider adding a retry mechanism or exiting if the error is critical
        } else {
            duty_cycle = calculate_duty_cycle(temperature);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed, using previous value or exiting.\n");
            }

            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data, using previous value or exiting.\n");
            }
        }

        sleep(5);
    }

    // Cleanup before exiting
    set_fan_speed(0); // Turn off the fan
    cleanup_gpio();     // Release GPIO resources

    return 0;
}

