#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define I2C bus
#define I2C_BUS 1

// Define continuous measurement command
#define MEASUREMENT_COMMAND 0x3608

// Define flow rate conversion factor
#define FLOW_RATE_FACTOR 0.01

// Define log file name
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor_data(int handle, uint8_t *data, int count);
int validate_crc(const uint8_t *data, int len);
float convert_to_flow_rate(uint32_t raw_value);
int log_data(float flow1, float flow2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int valid;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadDevice(handle, (char *)data, count);
        if (bytes_read == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading I2C data: %d, retries remaining: %d\n", bytes_read, retries);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read I2C data after multiple retries.\n");
    return -1; // Failure
}

// Function to validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Function to convert raw value to flow rate
float convert_to_flow_rate(uint32_t raw_value) {
    return (float)raw_value * FLOW_RATE_FACTOR;
}

// Function to log data to file
int log_data(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
