int init_i2c(int bus, int addr);
int read_sensor_data(int handle, uint8_t *data, int count);
int validate_crc(const uint8_t *data, int len);
float convert_to_flow_rate(uint32_t raw_value);
int log_data(float flow1, float flow2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int valid;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadDevice(handle, (char *)data, count);
        if (bytes_read == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading I2C data: %d, retries remaining: %d\n", bytes_read, retries);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read I2C data after multiple retries.\n");
    return -1; // Failure
}

// Function to validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Function to convert raw value to flow rate
