#include <string.h>

// Define GPIO pins for the encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the quadrature state machine states
typedef enum {
    STATE_00,
    STATE_01,
    STATE_10,
    STATE_11
} encoder_state_t;

// Global variables
static volatile int pulse_count = 0;
static volatile int encoder_state = STATE_00;
static volatile int encoder_direction = 1; // 1 for clockwise, -1 for counter-clockwise
static volatile int encoder_last_state = 0;
static volatile int encoder_last_direction = 1; // 1 for clockwise, -1 for counter-clockwise
static FILE *log_file = NULL;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
void log_state(int state, int position);
void signal_handler(int signal);

// Function to handle encoder pulses
void pulse_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ENCODER_A) {
        if (level == 1) { // Rising edge
            pulse_count++;
        }
    } else if (gpio == ENCODER_B) {
        if (level == 1) { // Rising edge
            pulse_count++;
        }
    }
}

// Function to log the encoder state and position
void log_state(int state, int position)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %d\n", timestamp, state, position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    gpioSetAlertFuncEx(ENCODER_A, NULL, NULL);
    gpioSetAlertFuncEx(ENCODER_B, NULL, NULL);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    // Set up interrupt handlers for both sensors
    gpioSetAlertFuncEx(ENCODER_A, pulse_callback, NULL);
    gpioSetAlertFuncEx(ENCODER_B, pulse_callback, NULL);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Determine the new encoder state based on the quadrature state machine
        encoder_state = (encoder_state == STATE_00) ? STATE_10 : (encoder_state == STATE_10) ? STATE_00 : (encoder_state == STATE_11) ? STATE_01 : STATE_11;

        // Determine the new encoder direction based on the previous direction
        encoder_direction = (encoder_direction == 1) ? -1 : 1; // Toggle direction

        // Update the last state and direction
        encoder_last_state = encoder_state;
        encoder_last_direction = encoder_direction;

        // Increment the pulse count
        pulse_count++;

        // Log the state and position
        log_state(encoder_state, pulse_count % PULSES_PER_REVOLUTION);

        // Sleep for a short interval to avoid busy-waiting
        gpioDelay(1000); // 1 ms
    }

    return 0;
}

