#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define FIFO_REG_ADDR 0x60
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    unsigned int red;
    unsigned int ir;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_log_file();
void cleanup();
void signal_handler(int signal);
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void control_led(int state);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize log file
int init_log_file() {
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int bytes_read = i2cReadI2CBlockData(i2c_fd, FIFO_REG_ADDR, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    data->red = (buffer[0] << 8) | buffer[1];
    data->ir = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, data.red, data.ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize log file
    if (init_log_file() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);

            if (sensor_data.ir > IR_THRESHOLD) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

