#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SLF3S_ADDR 0x36

// Define the command to start continuous measurement
#define MEASURE_CMD 0x3608

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define the CRC-8 initial value
#define CRC_INIT 0xFF

// Define the log file name
#define LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t flow_rate;
    uint8_t crc;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the sensor
int init_sensor() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Validate CRC for the flow rate data
    uint8_t crc_calculated = crc8(buffer, 2);
    if (crc_calculated != buffer[2]) {
        fprintf(stderr, "CRC check failed for flow rate data!\n");
        return -1;
    }

    // Extract the flow rate data
    data->flow_rate = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->crc = buffer[2];

    return 0;
}

// Function to log the flow rate to a file
int log_flow_rate(int16_t flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, flow_rate);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read data from the sensor
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the flow rate
            log_flow_rate(sensor_data.flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1000 ms
        gpioDelay(1000);
    }

    // Close the I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

