#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define TVOC_REG 0x00
#define eCO2_REG 0x05
#define IAQ_INDEX_MAX 100
#define IAQ_INDEX_MIN 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int tvoc;
    int eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_iaq(int tvoc, int eco2);
void log_data(float iaq, int tvoc, int eco2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-VZ-89TE
int read_sensor_data(sensor_data_t *data) {
    char buf[7];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TVOC_REG, buf, 7);

    if (bytes_read != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    data->tvoc = (buf[0] << 8) | buf[1];
    data->eco2 = (buf[3] << 8) | buf[4];

    return 0;
}

// Calculate the IAQ index
float calculate_iaq(int tvoc, int eco2) {
    float iaq = 100.0 - ((float)tvoc / 10.0) - ((float)(eco2 - 400) / 50.0);
    if (iaq < IAQ_INDEX_MIN) {
        iaq = IAQ_INDEX_MIN;
    } else if (iaq > IAQ_INDEX_MAX) {
        iaq = IAQ_INDEX_MAX;
    }
    return iaq;
}

// Log data to a CSV file
void log_data(float iaq, int tvoc, int eco2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("air_quality_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC,eCO2\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;
    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            float iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

