#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2s.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 2 // 2 bytes per sample (16-bit)
#define BUFFER_SIZE 1024

static volatile int keep_running = 1;
static int i2s_fd = -1;
static FILE *audio_file = NULL;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        keep_running = 0;
    }
}

int init_i2s(snd_pcm_t **pcm_handle) {
    int fd;
    struct snd_pcm_substream *substream;

    fd = open("/dev/snd/pcmC0D0c", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2S device");
        return -1;
    }

    if (ioctl(fd, SND_PCM_INFO, &info) < 0) {
        perror("Error getting I2S info");
        close(fd);
        return -1;
    }

    if (!(info.card->bformat & SND_PCM_FORMAT_S16_LE)) {
        fprintf(stderr, "Error: I2S device does not support 16-bit Little Endian.\n");
        close(fd);
        return -1;
    }

    *pcm_handle = snd_pcm_open(info.card, "capture", SND_PCM_STREAM_CAPTURE, 0);
    if (*pcm_handle < 0) {
        perror("Error opening PCM device");
        close(fd);
        return -1;
    }

    substream = snd_pcm_substream(*pcm_handle);
    if (substream < 0) {
        perror("Error getting substream");
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    snd_pcm_hw_params_t *hw_params;
    int rc;

    rc = snd_pcm_hw_params_malloc(&hw_params);
    if (rc < 0) {
        perror("Error allocating HW params");
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_any(*pcm_handle, hw_params) < 0) {
        perror("Error setting HW params");
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    rc = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        perror("Error setting access");
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    rc = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        perror("Error setting format");
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    rc = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS);
    if (rc < 0) {
        perror("Error setting channels");
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    rc = snd_pcm_hw_params_set_rate(*pcm_handle, hw_params, SAMPLE_RATE, 0);
    if (rc < 0) {
        perror("Error setting rate");
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    rc = snd_pcm_hw_params(*pcm_handle, hw_params);
    if (rc < 0) {
        perror("Error setting HW params");
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(*pcm_handle);
        close(fd);
        return -1;
    }

    snd_pcm_hw_params_free(hw_params);
    return fd;
}

int init_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0); // Set L/R select pin low initially
    return 0;
}

int main() {
    snd_pcm_t *pcm_handle;
    int rc;
    char buffer[BUFFER_SIZE * SAMPLE_SIZE];
    int bytes_read;
    int left_channel_selected = 0;

    signal(SIGINT, signal_handler);

    if (init_gpio(GPIO_PIN) < 0) {
        return 1;
    }

    if (init_i2s(&pcm_handle) < 0) {
        gpioTerminate();
        return 1;
    }

    audio_file = fopen("audio_capture.pcm", "wb");
    if (audio_file == NULL) {
        perror("Error opening audio file");
        snd_pcm_close(pcm_handle);
        close(i2s_fd);
        gpioTerminate();
        return 1;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (keep_running) {
        rc = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
        if (rc == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (rc < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(rc));
            break;
        } else if (rc != BUFFER_SIZE) {
            fprintf(stderr, "Short read, read %d frames\n", rc);
        } else {
            // Extract left channel data
            for (int i = 0; i < BUFFER_SIZE; i++) {
                int16_t sample = (int16_t)((buffer[i * 2] << 8) | buffer[i * 2 + 1]);
                if (left_channel_selected) {
                    // Right-shift to get 16-bit PCM samples
                    int16_t pcm_sample = (int16_t)(sample >> 1); // Right shift to get 16-bit
                    fwrite(&pcm_sample, 1, 1, audio_file);
                }
            }
        }
    }

    printf("Audio capture stopped.\n");

    if (audio_file != NULL) {
        fclose(audio_file);
    }

    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    if (i2s_fd != -1) {
        close(i2s_fd);
    }

    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }

    return 0;
}

