// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_MS 50
#define FLAME_DURATION_MS 1000
#define MAX_DUTY_CYCLE 80
#define MIN_DUTY_CYCLE 0

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int flame_detected = 0;
static int flame_duration = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected, int flame_duration);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int flame_sensor_pin;
    int fan_pin;
    int pwm_frequency;
    int debounce_delay_ms;
    int flame_duration_ms;
    int max_duty_cycle;
    int min_duty_cycle;
} Config;

Config config = {
    FLAME_SENSOR_PIN,
    FAN_PIN,
    PWM_FREQUENCY,
    DEBOUNCE_DELAY_MS,
    FLAME_DURATION_MS,
    MAX_DUTY_CYCLE,
    MIN_DUTY_CYCLE
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int flame_status = read_flame_sensor();

        if (flame_status == 0) { // Flame detected (LOW signal)
            if (!flame_detected) {
                flame_detected = 1;
                flame_duration = 0;
                log_event("Flame detected");
                control_fan(1, 0); // Turn on fan
            }
        } else { // No flame detected (HIGH signal)
            if (flame_detected) {
                flame_detected = 0;
                flame_duration = 0;
                log_event("Flame ended");
                control_fan(0, 0); // Turn off fan
            }
        }

        if (flame_detected) {
            flame_duration++;
            if (flame_duration >= config.flame_duration_ms) {
                // Calculate duty cycle based on flame duration
                int duty_cycle = (int)(((double)flame_duration / config.flame_duration_ms) * (config.max_duty_cycle - config.min_duty_cycle) + config.min_duty_cycle);
                gpioPWM(config.fan_pin, duty_cycle);
                log_event("Flame duration exceeded threshold, duty cycle adjusted");
                flame_duration = 0; // Reset flame duration
            }
        }

        gpioDelay(config.debounce_delay_ms * 1000); // Debounce delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.flame_sensor_pin, PI_INPUT);
    gpioSetMode(config.fan_pin, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(config.fan_pin, config.pwm_frequency);
    gpioSetPWMrange(config.fan_pin, 100); // Set range to 100 for percentage

    return 0;
}

// Read flame sensor with debouncing
int read_flame_sensor() {
    int i;
    for (i = 0; i < 5; i++) {
        if (gpioRead(config.flame_sensor_pin) == 0) { // Flame detected (LOW)
            return 0; // Return 0 to indicate flame detected
        }
        gpioDelay(config.debounce_delay_ms * 1000); // Debounce delay
    }
    return 1; // Return 1 to indicate no flame detected
}

// Control fan speed using PWM
void control_fan(int flame_detected, int flame_duration) {
    int duty_cycle;

    if (flame_detected) {
        // Linearly increase duty cycle based on flame duration
        duty_cycle = (int)(((double)flame_duration / config.flame_duration_ms) * 100);
        if (duty_cycle > 100) {
            duty_cycle = 100;
        }
        gpioPWM(config.fan_pin, duty_cycle);
    } else {
        gpioPWM(config.fan_pin, 0); // Turn off fan
    }
}

// Log events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(config.fan_pin, 0); // Turn off fan
    gpioSetMode(config.flame_sensor_pin, PI_INPUT); // Reset pin
    gpioSetMode(config.fan_pin, PI_INPUT); // Reset pin
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
}

