    while (!terminate) {
        // Trigger the radar
        gpioWrite(GPIO_TRIGGER, 1);
        gpioDelay(1000); // 1 ms trigger pulse
        gpioWrite(GPIO_TRIGGER, 0);

        // Wait for data ready interrupt
        while (gpioRead(GPIO_DATA_READY) == 0) {
            gpioDelay(1000); // Wait 1 ms
        }

        // Read data
        if (read_radar_data(spi_handle, data, 32768) == 0) {
            // Log data
