#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(const char *timestamp, const char *state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s,%s\n", timestamp, state);
    fclose(fp);
    return 0;
}

// Function to handle the flame sensor event
void handle_flame_sensor(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Flame detected (LOW signal)
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            if (log_flame_state(timestamp, "Flame Detected") != 0) {
                fprintf(stderr, "Error logging flame detection.\n");
            }
            free(timestamp);
        }
    } else { // Flame cleared (HIGH signal)
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            if (log_flame_state(timestamp, "Flame Cleared") != 0) {
                fprintf(stderr, "Error logging flame clearance.\n");
            }
            free(timestamp);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 20 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        handle_flame_sensor(GPIO_PIN, 0, 0); // Poll every 100ms
        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

