#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONTINUOUS_CONVERSION 0x8000 // 100ms conversion time
#define AUTO_RANGE 0x0000 // Automatic full-scale range
#define RESULT_REG 0x00
#define LUX_FACTOR 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t exponent;
    uint16_t mantissa;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_lux(sensor_data_t data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the OPT3001 sensor
int init_sensor() {
    char buf[2];
    buf[0] = 0x00; // Register to write to
    buf[1] = CONTINUOUS_CONVERSION | AUTO_RANGE; // Configuration value

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[1];
    char read_buf[2];
    int result;

    // Read result register (0x00)
    buf[0] = RESULT_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to result register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    // Combine exponent and mantissa
    data->exponent = (read_buf[0] >> 12) & 0x0F;
    data->mantissa = (read_buf[0] << 4) | (read_buf[1] >> 4);

    return 0;
}

// Calculate lux value
float calculate_lux(sensor_data_t data) {
    return LUX_FACTOR * (1 << data.exponent) * data.mantissa;
}

