#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 17
#define GPIO_CHIP_NAME "gpiochip0"

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "Caught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_settings settings;
    int ret;

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request GPIO line
    line = gpiod_chip_request_lines(chip, [GPIO_LINE]);
    if (!line) {
        perror("gpiod_chip_request_lines");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO line as input with pull-up resistor
    ret = gpiod_line_request_get_value(line, &config, &settings);
    if (ret < 0) {
        perror("gpiod_line_request_get_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ret != 0) {
        fprintf(stderr, "Failed to request line, returning 0.\n");
        config.value = 0; // Set to 0 to avoid active-low behavior
        ret = gpiod_line_request(line, &config, &settings);
        if (ret < 0) {
            perror("gpiod_line_request");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (keep_running) {
        int value = gpiod_line_request_get_value(line, &config, &settings);
        if (value < 0) {
            perror("gpiod_line_request_get_value");
            break; // Exit loop on error
        }

        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }

        time_sleep(1.0);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

