#include <pigpio.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int left_value, center_value, right_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read GPIO values
        left_value = gpioRead(LEFT_PIN);
        center_value = gpioRead(CENTER_PIN);
        right_value = gpioRead(RIGHT_PIN);

        // Print GPIO values
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait 50 ms
        usleep(50000);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

