#define CHANNEL_3 4
#define CHANNEL_4 5
#define CHANNEL_5 6
#define CHANNEL_6 7
#define CHANNEL_7 8
#define CHANNEL_8 9

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

int main() {
    int i;
    int channel_states[8];

    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the GPIO chip
    int chip_id = gpioInitialise();
    if (chip_id < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %d\n", chip_id);
        gpioTerminate();
        return 1;
    }

    // Request the GPIO lines for input
    for (i = 0; i < 8; i++) {
        int line = i + CHANNEL_1; // Calculate the line number based on the channel number
        if (gpioSetMode(line, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", line);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log the sensor data
    while (program_running) {
        // Read the state of each channel
        for (i = 0; i < 8; i++) {
            channel_states[i] = gpioRead(i + CHANNEL_1); // Calculate the line number based on the channel number
            printf("Channel %d: %d\n", i + 1, channel_states[i]);
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close the GPIO chip
    if (chip_id >= 0) {
        gpioTerminate();
    }

    return 0;
}

