#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the touch sensor channels
const int touch_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    program_running = 0;
    printf("\nSIGINT received. Exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal) {
    program_running = 0;
    printf("\nSIGTERM received. Exiting gracefully...\n");
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Configure each GPIO pin as an input with a pull-down resistor
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", touch_pins[i]);
            return 1; // Indicate failure
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down for GPIO %d\n", touch_pins[i]);
            return 1; // Indicate failure
        }
    }
    return 0; // Indicate success
}

// Function to read the state of all touch sensor channels
void read_touch_sensors(int *sensor_states) {
    for (int i = 0; i < num_channels; i++) {
        sensor_states[i] = gpioRead(touch_pins[i]);
    }
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int sensor_states[]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, sensor_states[i]);
    }
    printf("\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio and configure GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    int sensor_states[num_channels];

    // Main loop to continuously read and log sensor data
    while (program_running) {
        read_touch_sensors(sensor_states);
        log_sensor_data(sensor_states);
        gpioDelay(100000); // Delay for 100 ms (100000 microseconds)
    }

    // Terminate pigpio before exiting
    gpioTerminate();
    return 0;
}

