#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLLING_INTERVAL_MS 50

// Structure to hold GPIO line information
typedef struct {
    int gpio_pin;
    int gpio_direction;
    int gpio_value;
} gpio_line_t;

// Global variables
gpio_line_t gpio_lines[NUM_CHANNELS];
int running = 1;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_data(int channel_states[]);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Shutting down gracefully...\n");
        running = 0;
    }
}

// Function to initialize GPIO lines
int initialize_gpio() {
    int i;

    // Open the GPIO chip
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(gpio_lines[i].gpio_pin, PI_INPUT);
        gpioSetPullUpDown(gpio_lines[i].gpio_pin, PI_PUD_OFF); // Disable pull-up/down resistors
        gpio_lines[i].gpio_direction = PI_INPUT;
        gpio_lines[i].gpio_value = 0; // Initialize to 0
    }

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    int i;

    // Release GPIO lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(gpio_lines[i].gpio_pin, PI_INPUT); // Set back to input
        gpio_lines[i].gpio_value = 0; // Reset value
    }

    gpioTerminate();
}

// Function to log data to the console
void log_data(int channel_states[]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    int i;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s", timestamp);
    for (i = 0; i < NUM_CHANNELS; i++) {
        printf(",%d", channel_states[i]);
    }
    printf("\n");
}

int main() {
    int i, j;
    int current_state;
    int channel_states[NUM_CHANNELS];

    // Initialize GPIO lines
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Poll all 8 channels
        for (i = 0; i < NUM_CHANNELS; i++) {
            current_state = gpioRead(gpio_lines[i].gpio_pin);
            channel_states[i] = current_state;
        }

        // Log the data
        log_data(channel_states);

        // Wait for the next polling interval
        usleep(POLLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Touch sensor monitoring stopped.\n");

    return 0;
}

