#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define PART_ID 0x00
#define HW_KEY 0x17
#define CHLIST 0x01
#define ALS_FORCE 0x06
#define UVI_DATA_LSB 0x2C
#define UVI_DATA_MSB 0x2D
#define VIS_DATA_LSB 0x22
#define VIS_DATA_MSB 0x23

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_si1145_data(float *uv_index, float *visible_als);
void log_data(float uv_index, float visible_als);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float uv_index;
    float visible_als;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Si1145 not found. PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure CHLIST
    if (i2cWriteByteData(i2c_handle, CHLIST, 0x01) < 0) {
        fprintf(stderr, "Error writing CHLIST\n");
        return -1;
    }

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, ALS_FORCE, 0x06) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    return 0;
}

// Read UV index and Visible ALS data from the Si1145
int read_si1145_data(float *uv_index, float *visible_als) {
    int uv_lsb, uv_msb, vis_lsb, vis_msb;

    uv_lsb = i2cReadByteData(i2c_handle, UVI_DATA_LSB);
    if (uv_lsb < 0) {
        fprintf(stderr, "Error reading UV_LSB\n");
        return -1;
    }

    uv_msb = i2cReadByteData(i2c_handle, UVI_DATA_MSB);
    if (uv_msb < 0) {
        fprintf(stderr, "Error reading UV_MSB\n");
        return -1;
    }

    vis_lsb = i2cReadByteData(i2c_handle, VIS_DATA_LSB);
    if (vis_lsb < 0) {
        fprintf(stderr, "Error reading VIS_LSB\n");
        return -1;
    }

    vis_msb = i2cReadByteData(i2c_handle, VIS_DATA_MSB);
    if (vis_msb < 0) {
        fprintf(stderr, "Error reading VIS_MSB\n");
        return -1;
    }

    // Combine LSB and MSB for UV index and Visible ALS
    *uv_index = (float)((uv_msb << 8) | uv_lsb) / 10.0;
    *visible_als = (float)((vis_msb << 8) | vis_lsb) / 10.0;

    return 0;
}

// Log data to a CSV file
void log_data(float uv_index, float visible_als) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, uv_index, visible_als);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,visible_als\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float uv_index, visible_als;
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&uv_index, &visible_als) == 0) {
            // Log data
            log_data(uv_index, visible_als);

            // Print data to console
            printf("UV Index: %.2f, Visible ALS: %.2f\n", uv_index, visible_als);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

