#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define MEASUREMENT_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5 // ml/min
#define LOG_FILE "flow_log.txt"
#define SLEEP_SECONDS 1

// Global variables
int i2c_fd1 = -1;
int i2c_fd2 = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_setup(int bus, int addr);
int i2c_read_sensor(int fd, int *flow, int *temperature, int *crc);
int validate_flow(int raw_flow, int crc);
float calculate_flow_rate(int raw_flow);
void log_flow_rate(float avg_flow);
void alarm_control(float avg_flow);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int fd;
    int address;
} sensor_t;

// Function to initialize I2C
int i2c_setup(int bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read flow rate from a sensor
int i2c_read_sensor(int fd, int *flow, int *temperature, int *crc) {
    unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    unsigned char buffer[9];

    if (write(fd, command, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buffer, 9) != 9) {
        perror("Error reading from I2C device");
        return -1;
    }

    *flow = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *crc = (buffer[6] << 8) | buffer[7];

    return 0;
}

// Function to validate flow rate using CRC
int validate_flow(int raw_flow, int crc) {
    unsigned char data[3] = {(raw_flow >> 8) & 0xFF, raw_flow & 0xFF, 0x00, 0x00};
    unsigned char calculated_crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        calculated_crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (calculated_crc & 0x80) {
                calculated_crc = (calculated_crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                calculated_crc <<= 1;
            }
        }
    }

    return (calculated_crc == crc);
}

// Function to calculate flow rate in ml/min
float calculate_flow_rate(int raw_flow) {
    return (float)raw_flow * 0.036;
}

// Function to log flow rate to file
void log_flow_rate(float avg_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f ml/min\n", timestamp, avg_flow);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to control the alarm
void alarm_control(float avg_flow) {
    if (avg_flow < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Alarm ON
    } else {
        gpioWrite(ALARM_GPIO, 0); // Alarm OFF
    }
}

// Signal handler for clean shutdown
