    // Release GPIO resources
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioSetMode(ALARM_GPIO, PI_INPUT); // Release GPIO

    // Close I2C file descriptors
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C for both sensors
    i2c_fd1 = i2c_setup(I2C_BUS, SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to initialize sensor 1\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    i2c_fd2 = i2c_setup(I2C_BUS, SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to initialize sensor 2\n");
        close(i2c_fd1);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int sensor1_flow, sensor1_temperature, sensor1_crc;
    int sensor2_flow, sensor2_temperature, sensor2_crc;
    float avg_flow;

    // Main loop
    while (1) {
        // Read sensor 1
        if (i2c_read_sensor(i2c_fd1, &sensor1_flow, &sensor1_temperature, &sensor1_crc) == 0) {
            if (validate_flow(sensor1_flow, sensor1_crc)) {
                avg_flow += calculate_flow_rate(sensor1_flow);
            } else {
                fprintf(stderr, "Sensor 1 CRC check failed, skipping reading.\n");
            }
        } else {
            fprintf(stderr, "Sensor 1 read failed, skipping reading.\n");
        }

        // Read sensor 2
        if (i2c_read_sensor(i2c_fd2, &sensor2_flow, &sensor2_temperature, &sensor2_crc) == 0) {
            if (validate_flow(sensor2_flow, sensor2_crc)) {
                avg_flow += calculate_flow_rate(sensor2_flow);
            } else {
                fprintf(stderr, "Sensor 2 CRC check failed, skipping reading.\n");
            }
        } else {
            fprintf(stderr, "Sensor 2 read failed, skipping reading.\n");
        }

        // Calculate average flow rate
        avg_flow /= 2.0;

        // Log flow rate
        log_flow_rate(avg_flow);

        // Control alarm
        alarm_control(avg_flow);

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    return 0;
}

