#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and reading
typedef struct {
    long tv_sec;
    long tv_nsec;
    int reading;
} timestamp_t;

// Circular buffer
timestamp_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor();
void add_to_buffer(timestamp_t timestamp);
void print_buffer();
void signal_handler(int signal);

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add a timestamp and reading to the circular buffer
void add_to_buffer(timestamp_t timestamp) {
    buffer[buffer_index] = timestamp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Obstacle Detection Alerts ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        timestamp_t timestamp = buffer[(buffer_index - BUFFER_SIZE + i + BUFFER_SIZE) % BUFFER_SIZE];
        struct tm *timeinfo = localtime(&timestamp.tv_sec);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("Timestamp: %s, Reading: %d\n", timestamp_str, timestamp.reading);
    }
    printf("--- End of Alerts ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    print_buffer();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            timestamp_t timestamp;
            struct timespec ts;

            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                continue; // Or handle the error more appropriately
            }

            timestamp.tv_sec = ts.tv_sec;
            timestamp.tv_nsec = ts.tv_nsec;
            timestamp.reading = sensor_value;

            add_to_buffer(timestamp);
            printf("Obstacle detected! Timestamp: %ld.%09ld, Reading: %d\n", timestamp.tv_sec, timestamp.tv_nsec, timestamp.reading);
        }

        gpioDelay(50); // Poll every 50 ms
    }

    return 0;
}

