#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCELERATION_X 0x2A
#define ACCELERATION_Y 0x2C
#define ACCELERATION_Z 0x2E
#define SAMPLE_INTERVAL_MS 500
#define OPERATING_STATUS_TIMEOUT_S 1
#define LOG_FILE "fan_health.csv"

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int x;
    int y;
    int z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Sensor configuration function
int configure_sensor() {
    int result = i2cWriteByteData(i2c_fd, MODE_CONTROL, 0x10);
    if (result < 0) {
        fprintf(stderr, "Error writing to MODE_CONTROL register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_fd, ACCELERATION_X, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit signed integers
    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return;
        }
        fprintf(log_fp, "Timestamp,X,Y,Z\n");
    }

    fprintf(log_fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_fp); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
