#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCELERATION_X 0x2A
#define ACCELERATION_Y 0x2C
#define ACCELERATION_Z 0x2E
#define SAMPLE_INTERVAL_MS 500
#define OPERATING_STATUS_TIMEOUT_S 1
#define LOG_FILE "fan_health.csv"

