#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Define constants
#define OBSTACLE_THRESHOLD 10 // cm
#define LED_ON_TIME 500       // ms

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sensor pins as inputs
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN as input\n");
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR_1_PIN);
    int sensor2_value = gpioRead(SENSOR_2_PIN);

    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0; // Return 1 if any sensor detects an obstacle
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to turn the LED on
void turn_on_led() {
    control_led(1);
}

// Function to turn the LED off
void turn_off_led() {
    control_led(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int obstacle_detected = read_sensors();

        if (obstacle_detected) {
            turn_on_led();
            gpioDelay(LED_ON_TIME * 1000); // Delay in microseconds
            turn_off_led();
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

