void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor(int gpio) {
    return gpioRead(gpio);
}

int is_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

int log_stall(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Stall detected\n", timestamp);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return 1; // Indicate failure
    }

    fclose(fp);
    return 0; // Indicate success
