    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    printf("Conveyor belt stall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (is_stall(sensor1_value, sensor2_value)) {
            if (log_stall(LOG_FILE) == 0) {
                printf("Stall detected and logged.\n");
            } else {
                fprintf(stderr, "Failed to log stall.\n");
            }
        } else {
            //printf("No stall detected.\n"); //Removed to reduce console spam
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

