#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define CONFIG_REG 0x01
#define DATA_REG_X 0x02
#define DATA_REG_Y 0x04
#define DATA_REG_Z 0x06
#define SCALE_FACTOR 0.005 // mT per LSB for 50 mT range
#define CSV_FILE "magnetic_log.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int verify_device_id();
int configure_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mt(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }
    printf("Device ID verified: 0x%02X\n", device_id);
    return 0;
}

// Configure the sensor for continuous conversion mode
int configure_sensor() {
    // Set continuous conversion mode and 50 mT range
    // Refer to the TMAG5170 datasheet for the correct configuration value
    // Example: 0x03 (Continuous mode, 50 mT)
    int config_value = 0x03; // Example value, check datasheet
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data (X, Y, Z)
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    int x_msb = i2cReadByteData(i2c_handle, DATA_REG_X);
    int x_lsb = i2cReadByteData(i2c_handle, DATA_REG_X + 1);
    int y_msb = i2cReadByteData(i2c_handle, DATA_REG_Y);
    int y_lsb = i2cReadByteData(i2c_handle, DATA_REG_Y + 1);
    int z_msb = i2cReadByteData(i2c_handle, DATA_REG_Z);
    int z_lsb = i2cReadByteData(i2c_handle, DATA_REG_Z + 1);

    if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);

    return 0;
}

// Convert raw data to mT
float convert_to_mt(int16_t raw_value) {
    return raw_value * SCALE_FACTOR;
}

// Log data to CSV file
int log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_mt, y_mt, z_mt;

    while (!terminate) {
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            x_mt = convert_to_mt(raw_x);
            y_mt = convert_to_mt(raw_y);
            z_mt = convert_to_mt(raw_z);

            if (log_data(x_mt, y_mt, z_mt) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

