        if (log_file != NULL) {
            fprintf(log_file, "%s No water detected\n", timestamp);
            fflush(log_file); // Ensure immediate write to file
        }
    }
}

// Function to handle re-initialization attempts
void handle_reinit_attempts(int gpio_pin) {
    int attempts = 0;
    while (attempts < MAX_REINIT_ATTEMPTS && running) {
        if (initialize_gpio() != 0) {
            fprintf(stderr, "Re-initializing pigpio (attempt %d/%d)\n", attempts + 1, MAX_REINIT_ATTEMPTS);
            attempts++;
            gpioDelay(RETRY_DELAY_SEC * 1000); // Delay in milliseconds
        } else {
            break; // Exit the loop if initialization is successful
        }
    }

    if (!running) return; // Exit if signal received during re-initialization

    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to re-initialize pigpio after %d attempts\n", MAX_REINIT_ATTEMPTS);
        running = 0; // Exit the daemon if re-initialization fails
    }
}

