    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO mode
    if (set_gpio_mode(WATER_SENSOR_GPIO, PI_INPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int water_level = read_water_level(WATER_SENSOR_GPIO);
        if (water_level == 1) {
            log_water_level(water_level);
        } else if (water_level < 0) {
            fprintf(stderr, "Error reading water level, retrying pigpio initialization.\n");
            handle_reinit_attempts(WATER_SENSOR_GPIO);
        }
        gpioDelay(POLL_INTERVAL_SEC * 1000); // Delay in milliseconds
    }

    // Clean up resources before exiting
    printf("Cleaning up resources.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

