#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define SAMPLE_WINDOW_MS 1000
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
volatile unsigned long last_interrupt_time = 0;
FILE *log_file = NULL;

// Function to handle the interrupt
void pulse_callback(int gpio, int level, unsigned int tick, void *user)
{
    unsigned long current_time = gpioTick();
    if (current_time - last_interrupt_time > SAMPLE_WINDOW_MS * 1000)
    {
        // Calculate RPM
        double rpm = (double)pulse_count / (double)SAMPLE_WINDOW_MS * 60.0;
        if (rpm > 0)
        {
            // Log RPM to file and stdout
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

            if (log_file != NULL)
            {
                fprintf(log_file, "%s RPM: %.2f\n", buf, rpm);
                fflush(log_file); // Ensure data is written to disk
            }
            else
            {
                fprintf(stderr, "Error: Log file is not open.\n");
            }

            printf("%s RPM: %.2f\n", buf, rpm);

            // Reset pulse count and interrupt time
            pulse_count = 0;
            last_interrupt_time = current_time;
        }
        else
        {
            // Log RPM as 0 if no pulses detected
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

            if (log_file != NULL)
            {
                fprintf(log_file, "%s RPM: 0.0\n", buf);
                fflush(log_file);
            }
            else
            {
                fprintf(stderr, "Error: Log file is not open.\n");
            }

            printf("%s RPM: 0.0\n", buf);
        }
    }
    pulse_count = 0; // Reset pulse count
    last_interrupt_time = current_time;
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupt callback
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Disable timer callback
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt callback for rising edge detection
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0)
    {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

