#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <stdatomic.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the quadrature states
typedef enum {
    STATE_NONE,
    STATE_CW,
    STATE_CCW,
    STATE_INVALID
} QuadratureState;

// Define the mutex type
typedef atomic_flag mutex_t;

// Global variables
static volatile QuadratureState previous_state = STATE_NONE;
static volatile QuadratureState current_state = STATE_NONE;
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void *log_thread(void *arg);
void signal_handler(int signal);

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    // Determine the new state based on the current state and the sensor's level
    switch (current_state) {
        case STATE_NONE:
            if (level == 0) {
                current_state = STATE_CW;
            } else {
                current_state = STATE_CCW;
            }
            break;
        case STATE_CW:
            if (level == 0) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_CCW;
            }
            break;
        case STATE_CCW:
            if (level == 0) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_CW;
            }
            break;
        case STATE_INVALID:
            // Do nothing, as the state is invalid
            break;
    }

    // Update the previous state
    previous_state = current_state;

    // Log the event
    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);
    char milliseconds[5];
    sprintf(milliseconds, ".%03ld", (long int)now % 1000);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s.%s - Sensor A: %s\n", buf, milliseconds, (current_state == STATE_CW) ? "CW" : "CCW");
    fflush(log_file);
    fprintf(log_file, "%s", log_message);
    pthread_mutex_unlock(&log_mutex);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    // Determine the new state based on the current state and the sensor's level
    switch (current_state) {
        case STATE_NONE:
            if (level == 0) {
                current_state = STATE_CW;
            } else {
                current_state = STATE_CCW;
            }
            break;
        case STATE_CW:
            if (level == 0) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_CCW;
            }
            break;
        case STATE_CCW:
            if (level == 0) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_CW;
            }
            break;
        case STATE_INVALID:
            // Do nothing, as the state is invalid
            break;
    }

    // Update the previous state
    previous_state = current_state;

    // Log the event
    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
