#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

#define TOUCH_PIN 23
#define LED_PIN 18

static volatile int running = 1;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

int main() {
    int touch_state;
    int led_state = 0; // 0 = off, 1 = on
    int pigpio_init_result;

    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %d", pigpio_init_result);
        closelog();
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set TOUCH_PIN to input mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED_PIN to output mode");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 1 && led_state == 0) {
            // Touch detected, turn on LED
            if (gpioWrite(LED_PIN, 1) != 0) {
                syslog(LOG_ERR, "Failed to write to LED_PIN");
            }
            led_state = 1;
            syslog(LOG_INFO, "Touch detected, LED ON");
        } else if (touch_state == 0 && led_state == 1) {
            // Touch released, turn off LED
            if (gpioWrite(LED_PIN, 0) != 0) {
                syslog(LOG_ERR, "Failed to write to LED_PIN");
            }
            led_state = 0;
            syslog(LOG_INFO, "Touch released, LED OFF");
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    closelog();

    return 0;
}

