#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 17
#define LED_PIN 18

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int touch_level;
    int last_touch_level = 0;
    int led_level = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        touch_level = gpioRead(TOUCH_PIN);

        if (touch_level != last_touch_level) {
            // Debounce: Wait for a stable HIGH signal
            while (gpioRead(TOUCH_PIN) == touch_level && running) {
                usleep(1000); // 1 ms delay
            }

            if (touch_level == 1) {
                led_level = !led_level; // Toggle LED state
                gpioWrite(LED_PIN, led_level);
                printf("Touch detected! LED toggled to %d\n", led_level);
            }

            last_touch_level = touch_level;
        }

        usleep(1000); // Check every 1 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

