#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define LED_1_GPIO 27
#define LED_2_GPIO 22
#define CIRCULAR_BUFFER_SIZE 100

// Structure to hold sensor and LED information
typedef struct {
    int sensor_pin;
    int led_pin;
} SensorLedPair;

// Circular buffer structure
typedef struct {
    int buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer log_buffer;
int running = 1;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_event(int sensor_pin, int led_pin, int new_state);
void update_circular_buffer(int sensor_pin, int led_pin, int new_state);
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add event to circular buffer
void add_to_buffer(CircularBuffer *cb, int sensor_pin, int led_pin, int new_state) {
    cb->buffer[cb->head] = new_state;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (cb->count < CIRCULAR_BUFFER_SIZE) {
        cb->count++;
    }
}

// Print circular buffer contents
void print_buffer(CircularBuffer *cb) {
    printf("\nCircular Buffer Contents:\n");
    int start = (cb->count == CIRCULAR_BUFFER_SIZE) ? cb->head : 0;
    for (int i = 0; i < cb->count; i++) {
        int index = (start + i) % CIRCULAR_BUFFER_SIZE;
        printf("  %d: %d\n", cb->buffer[index], cb->buffer[index]);
    }
}

// Print overflow count
void print_overflow_count(CircularBuffer *cb) {
    printf("Overflow Count: %d\n", cb->count);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup_gpio();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&log_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = gpioRead(SENSOR_1_GPIO);
        int sensor2_value = gpioRead(SENSOR_2_GPIO);

        // Update LEDs based on sensor values
        gpioWrite(LED_1_GPIO, sensor1_value);
        gpioWrite(LED_2_GPIO, sensor2_value);

        // Log events
        if (sensor1_value != gpioRead(SENSOR_1_GPIO)) {
            log_event(SENSOR_1_GPIO, LED_1_GPIO, sensor1_value);
        }
        if (sensor2_value != gpioRead(SENSOR_2_GPIO)) {
            log_event(SENSOR_2_GPIO, LED_2_GPIO, sensor2_value);
        }

        // Update circular buffer
        update_circular_buffer(SENSOR_1_GPIO, LED_1_GPIO, sensor1_value);
        update_circular_buffer(SENSOR_2_GPIO, LED_2_GPIO, sensor2_value);

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    print_buffer(&log_buffer);
    print_overflow_count(&log_buffer);
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_GPIO\n");
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_GPIO\n");
        return 1;
    }
    if (gpioSetMode(LED_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_GPIO\n");
        return 1;
    }
    if (gpioSetMode(LED_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_GPIO\n");
        return 1;
    }
    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_1_GPIO, 0); // Turn off LED 1
    gpioWrite(LED_2_GPIO, 0); // Turn off LED 2
    gpioTerminate();
}

// Log event to circular buffer
void log_event(int sensor_pin, int led_pin, int new_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    add_to_buffer(&log_buffer, sensor_pin, led_pin, new_state);
    printf("%s: Sensor %d, LED %d: %d\n", buf, sensor_pin, led_pin, new_state);
}

// Update circular buffer
void update_circular_buffer(int sensor_pin, int led_pin, int new_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    add_to_buffer(&log_buffer, sensor_pin, led_pin, new_state);
    printf("%s: Sensor %d, LED %d: %d\n", buf, sensor_pin, led_pin, new_state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

