    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Enable internal pull-up resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_state = read_sensor();

        if (sensor_state == 0) { // Rain detected (active low)
            log_message("Rain Detected");
        } else {
            log_message("No Rain");
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

