#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME_MS 5

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 2

// Global variables for pulse counts and last pulse times
volatile int pulse_count_1 = 0;
volatile int pulse_count_2 = 0;
volatile unsigned int last_pulse_time_1 = 0;
volatile unsigned int last_pulse_time_2 = 0;

// File pointer for the log file
FILE *log_file = NULL;

// Function prototypes
void pulse_counter_1(int gpio, int level, uint32_t tick);
void pulse_counter_2(int gpio, int level, uint32_t tick);
double calculate_rpm(int pulses_1, int pulses_2);
void log_data(int pulses_1, int pulses_2, double rpm);
void signal_handler(int signal);

// Interrupt handler for sensor 1
void pulse_counter_1(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count_1++;
        last_pulse_time_1 = tick;
    }
}

// Interrupt handler for sensor 2
void pulse_counter_2(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count_2++;
        last_pulse_time_2 = tick;
    }
}

// Function to calculate RPM
double calculate_rpm(int pulses_1, int pulses_2) {
    return (double)pulses_1 * 60.0 / PULSES_PER_REVOLUTION / DEBOUNCE_TIME_MS;
}

// Function to log data to a CSV file
void log_data(int pulses_1, int pulses_2, double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d,%.2f\n", timestamp, pulses_1, pulses_2, rpm);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    gpioSetAlertFuncEx(SENSOR_1_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_GPIO, NULL, NULL);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Set up interrupt handlers for both sensors
    gpioSetAlertFuncEx(SENSOR_1_GPIO, pulse_counter_1, NULL);
    gpioSetAlertFuncEx(SENSOR_2_GPIO, pulse_counter_2, NULL);

    // Open the log file in append mode
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Monitoring RPM. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Calculate the number of pulses for each sensor
        int pulses_1 = pulse_count_1;
        int pulses_2 = pulse_count_2;

        // Reset pulse counts for the next interval
        pulse_count_1 = 0;
        pulse_count_2 = 0;

        // Calculate the RPM
        double rpm = calculate_rpm(pulses_1, pulses_2);

        // Log the data
        log_data(pulses_1, pulses_2, rpm);

        // Print the RPM to the console
        printf("RPM: %.2f\n", rpm);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    return 0;
}

