#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1182 I2C address
#define SI1182_ADDR 0x28

// Si1182 register addresses
#define REG_PART_ID 0x00
#define REG_CONFIG 0x30
#define REG_HR_DATA 0x02
#define REG_SPO2_DATA 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1182_init();
int read_si1182_data(int *heart_rate, int *spo2);
void log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1182 sensor
int si1182_init() {
    // Check if the sensor is present by reading the PART_ID register
    char part_id;
    if (i2cReadI2CBlockData(i2c_handle, REG_PART_ID, &part_id, 1) != 1) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", i2c_handle);
        return -1;
    }

    if (part_id != 0x52) {
        fprintf(stderr, "Si1182 not found. PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure the sensor for continuous measurement (example configuration)
    char config_data[2] = {0x01, 0x03}; // Example configuration values
    if (i2cWriteI2CBlockData(i2c_handle, REG_CONFIG, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read heart rate and SpO2 data from the Si1182 sensor
int read_si1182_data(int *heart_rate, int *spo2) {
    char hr_data[2];
    char spo2_data[2];

    // Read heart rate data
    if (i2cReadI2CBlockData(i2c_handle, REG_HR_DATA, hr_data, 2) != 2) {
        fprintf(stderr, "Error reading heart rate data: %d\n", i2c_handle);
        return -1;
    }
    *heart_rate = (hr_data[1] << 8) | hr_data[0];

    // Read SpO2 data
    if (i2cReadI2CBlockData(i2c_handle, REG_SPO2_DATA, spo2_data, 2) != 2) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", i2c_handle);
        return -1;
    }
    *spo2 = (spo2_data[1] << 8) | spo2_data[0];

    return 0;
}

// Log the heart rate and SpO2 data to a file
void log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (si1182_init() != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    int heart_rate, spo2;

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_si1182_data(&heart_rate, &spo2) == 0) {
            // Log the data
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function in milliseconds
    }

    // Close the I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

