// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define TILT_THRESHOLD_MS 2000 // 2 seconds
#define ALARM_DURATION_MS 5000 // 5 seconds

// Global variables
FILE *log_file = NULL;
int alarm_active = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(const char *event_type);
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log events with ISO-8601 timestamp
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the alarm (buzzer/LED)
void activate_alarm() {
    if (alarm_active == 0) {
        gpioWrite(ALARM_PIN, 1); // Set alarm pin HIGH
        alarm_active = 1;
        log_event("Alarm Activated");
    }
}

// Function to deactivate the alarm
void deactivate_alarm() {
    if (alarm_active == 1) {
        gpioWrite(ALARM_PIN, 0); // Set alarm pin LOW
        alarm_active = 0;
        log_event("Alarm Deactivated");
    }
}

