    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int tilt_start_time = 0;
    int sensor_1_value, sensor_2_value;

    while (1) {
        sensor_1_value = read_sensor(SENSOR_1_PIN);
        sensor_2_value = read_sensor(SENSOR_2_PIN);

        if (sensor_1_value == 1) {
            if (tilt_start_time == 0) {
                tilt_start_time = gpioTick();
            }
        } else {
            tilt_start_time = 0; // Reset timer if sensor goes LOW
        }

        if (tilt_start_time != 0) {
            if (gpioTick() - tilt_start_time >= TILT_THRESHOLD_MS) {
                log_event("Tilt Start");
                activate_alarm();
            }
        }

        if (sensor_1_value == 1 && sensor_2_value == 1) {
            if (alarm_active == 0) {
                log_event("Threshold Exceeded");
                activate_alarm();
            }
        } else {
            if (alarm_active == 1) {
                deactivate_alarm();
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    fclose(log_file);
    gpioTerminate();
    return 0;
}

