#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x1F
#define CTRL2_REG 0x20
#define CTRL3_REG 0x21
#define DATA_REG_BASE 0x28
#define DATA_REG_LENGTH 6
#define THRESHOLD 500
#define LED_GPIO 17
#define LOG_FILE "seismic_events.log"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_magnitude(const sensor_data_t *data);
void log_event(float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        // Verify sensor presence (read CTRL1_REG)
        char buf[1];
        buf[0] = CTRL1_REG;
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to CTRL1_REG: %s\n", strerror(errno));
            retries++;
            gpioDelay(100000); // 100ms delay
            continue;
        }
        char read_buf[2];
        if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
            fprintf(stderr, "Error reading CTRL1_REG: %s\n", strerror(errno));
            retries++;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        if ((read_buf[0] & 0x07) == 0x01) {
            printf("Sensor found!\n");
            // Clear power-down bit (set CTRL1_REG to 0x00)
            buf[0] = CTRL1_REG;
            if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
                fprintf(stderr, "Error writing to CTRL1_REG (clear power-down): %s\n", strerror(errno));
                retries++;
                gpioDelay(100000); // 100ms delay
                continue;
            }
            if (i2cWriteDevice(i2c_handle, (char[]){0x00}, 1) != 0) {
                fprintf(stderr, "Error writing to CTRL1_REG (clear power-down): %s\n", strerror(errno));
                retries++;
                gpioDelay(100000); // 100ms delay
                continue;
            }
            printf("Sensor initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Sensor not found (CTRL1_REG value: 0x%02X). Retry %d\n", read_buf[0], retries + 1);
            retries++;
            gpioDelay(100000); // 100ms delay
        }
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        char buf[1];
        buf[0] = DATA_REG_BASE;
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to data register: %s\n", strerror(errno));
            retries++;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        char read_buf[DATA_REG_LENGTH];
        if (i2cReadDevice(i2c_handle, read_buf, DATA_REG_LENGTH) != DATA_REG_LENGTH) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            retries++;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert little-endian to big-endian
        data->x = (int16_t)((read_buf[1] << 8) | read_buf[0]);
        data->y = (int16_t)((read_buf[3] << 8) | read_buf[2]);
        data->z = (int16_t)((read_buf[5] << 8) | read_buf[4]);

        return 0; // Success
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to calculate the Euclidean magnitude
float calculate_magnitude(const sensor_data_t *data) {
    return sqrt(data->x * data->x + data->y * data->y + data->z * data->z);
}

// Function to log an event
void log_event(float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            magnitude = calculate_magnitude(&sensor_data);

            if (magnitude > THRESHOLD) {
                printf("Vibration detected! Magnitude: %.2f\n", magnitude);
                gpioWrite(LED_GPIO, 1); // Turn on LED
                gpioDelay(1000000);     // 1 second delay
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

