        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
