#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

#define NUM_SENSORS 5
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor information
typedef struct {
    int pin;
    struct gpiod_line *line;
    bool flame_detected;
    time_t last_flame_time;
} sensor_t;

// Global variables
sensor_t sensors[NUM_SENSORS];
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(sensor_t *sensor);
int debounce(sensor_t *sensor);
void log_event(int pin, const char *event);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to read a sensor
int read_sensor(sensor_t *sensor) {
    int value = gpiod_line_get_value(sensor->line);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading sensor on GPIO %d: %s", sensor->pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce a sensor
int debounce(sensor_t *sensor) {
    int current_value = read_sensor(sensor);
    if (current_value < 0) return -1; // Propagate error

    time_t now = time(NULL);
    if (difftime(now, sensor->last_flame_time) * 1000 > DEBOUNCE_DELAY_MS) {
        if (current_value == 0) { // Flame detected (LOW)
            sensor->flame_detected = true;
            sensor->last_flame_time = now;
        } else {
            sensor->flame_detected = false;
        }
    }
    return 0;
}

// Function to log an event
void log_event(int pin, const char *event) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Error opening log file: %s", strerror(errno));
        return;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - %s\n", buf, pin, pin, event);
    fclose(fp);
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].line) {
            gpiod_line_release(sensors[i].line);
        }
    }
    closelog();
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensors
    sensors[0].pin = 2;
    sensors[0].flame_detected = false;
    sensors[0].last_flame_time = 0;

    sensors[1].pin = 3;
    sensors[1].flame_detected = false;
    sensors[1].last_flame_time = 0;

    sensors[2].pin = 4;
    sensors[2].flame_detected = false;
    sensors[2].last_flame_time = 0;

    sensors[3].pin = 17;
    sensors[3].flame_detected = false;
    sensors[3].last_flame_time = 0;

    sensors[4].pin = 27;
    sensors[4].flame_detected = false;
    sensors[4].last_flame_time = 0;

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].line = gpiod_chip_get_line(chip, sensors[i].pin);
        if (!sensors[i].line) {
            syslog(LOG_ERR, "Error requesting GPIO line %d: %s", sensors[i].pin, strerror(errno));
            cleanup();
            return 1;
        }

        // Request line for input
        if (gpiod_line_request_input(sensors[i].line, "flame_monitor", 0) < 0) {
            syslog(LOG_ERR, "Error requesting GPIO line %d as input: %s", sensors[i].pin, strerror(errno));
            cleanup();
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (debounce(&sensors[i])) {
                if (sensors[i].flame_detected) {
                    log_event(sensors[i].pin, "Flame Detected");
                } else {
                    log_event(sensors[i].pin, "Flame Disappeared");
                }
            }
        }
        usleep(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

