#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLLING_INTERVAL_MS 50

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int bcm_pin;
} sensor_t;

// Global array to store sensor data
sensor_t sensors[NUM_SENSORS];

// Signal handler for graceful shutdown
void signal_handler(int sig);

// Function to initialize a sensor
int initialize_sensor(sensor_t *sensor);

// Function to read the sensor state
int read_sensor_state(sensor_t *sensor);

// Function to log sensor events
void log_sensor_event(sensor_t *sensor, int state);

// Function to cleanup a sensor
void cleanup_sensor(sensor_t *sensor);

// Function to get the current timestamp in ISO-8601 format
void get_iso8601_timestamp(char *timestamp);

int main() {
    // Initialize sensors
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].sensor_id = i;
        sensors[i].bcm_pin = i; // Assign BCM pin number
        if (initialize_sensor(&sensors[i]) != 0) {
            fprintf(stderr, "Error initializing sensor %d\n", i);
            return 1;
        }
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int current_state = read_sensor_state(&sensors[i]);
            if (current_state != -1) {
                log_sensor_event(&sensors[i], current_state);
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }
        usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    return 0;
}

// Function to initialize a sensor
int initialize_sensor(sensor_t *sensor) {
    char chip_name[20];
    snprintf(chip_name, sizeof(chip_name), "gpiochip%d", sensor->sensor_id);

    sensor->chip = gpiod_chip_open_by_name(chip_name);
    if (!sensor->chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", chip_name);
        return -1;
    }

    // Request the GPIO line
    char line_name[20];
    snprintf(line_name, sizeof(line_name), "gpiochip%d/line%d", sensor->sensor_id, sensor->bcm_pin);
    sensor->line = gpiod_chip_get_line(sensor->chip, line_name);
    if (!sensor->line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", line_name);
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    // Request the line for input
    int ret = gpiod_line_request_input(sensor->line, "touch_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", line_name);
        gpiod_chip_close(sensor->chip);
        gpiod_line_release(sensor->line);
        return -1;
    }

    return 0;
}

// Function to read the sensor state
int read_sensor_state(sensor_t *sensor) {
    int current_state = gpiod_line_get_value(sensor->line);
    if (current_state < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", line_name);
        return -1;
    }
    return current_state;
}

// Function to log sensor events
void log_sensor_event(sensor_t *sensor, int state) {
    char timestamp[30];
    get_iso8601_timestamp(timestamp);

    if (state == 0) {
        printf("%s Sensor %d (BCM %d) touched\n", timestamp, sensor->sensor_id, sensor->bcm_pin);
    } else {
        printf("%s Sensor %d (BCM %d) released\n", timestamp, sensor->sensor_id, sensor->bcm_pin);
    }
}

// Function to cleanup a sensor
void cleanup_sensor(sensor_t *sensor) {
    if (sensor->line) {
        gpiod_line_release(sensor->line);
    }
    if (sensor->chip) {
        gpiod_chip_close(sensor->chip);
    }
}

// Function to get the current timestamp in ISO-8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    for (int i = 0; i < NUM_SENSORS; i++) {
        cleanup_sensor(&sensors[i]);
    }
    exit(0);
}

