        gpiod_chip_close(sensor->chip);
    }
}

// Function to get the current timestamp in ISO-8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    for (int i = 0; i < NUM_SENSORS; i++) {
        cleanup_sensor(&sensors[i]);
    }
    exit(0);
}

