    fprintf(log_file, "%s, %.2f, %d, %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(config.pwm_gpio, 0); // Turn off LED
    gpioTerminate();
}

