#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the touch sensor channels (BCM numbering)
#define TOUCH_CHANNELS_START 2
#define NUM_CHANNELS 8

// Define GPIO pin for the LED
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_touch_event(int channel);
void handle_touch_event(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold the last touch time for each channel
struct {
    int last_touch_time[8] = {0};
} channel_last_touch_time;

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins for touch sensor channels as inputs with pull-down resistors
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(TOUCH_CHANNELS_START + i, PI_INPUT);
        gpioSetPullUpDown(TOUCH_CHANNELS_START + i, PI_PUD_DOWN);
    }

    // Set GPIO pin for LED as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn off the LED initially

    return 0;
}

// Function to clean up the GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off the LED
    gpioTerminate();
}

// Function to log a touch event to the file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to handle touch events
void handle_touch_event(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge (touch detected)
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint32_t current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        // Debounce check
        if (current_time - channel_last_touch_time[gpio - TOUCH_CHANNELS_START].last_touch_time > DEBOUNCE_TIME * 1000) {
            log_touch_event(gpio - TOUCH_CHANNELS_START);
            channel_last_touch_time[gpio - TOUCH_CHANNELS_START].last_touch_time = current_time;
        }
    } else if (level == 0) { // Falling edge (touch released)
        // Turn off the LED if all channels are released
        int all_released = 1;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (channel_last_touch_time[i].last_touch_time > 0) {
                all_released = 0;
                break;
            }
        }
        if (all_released) {
            gpioWrite(LED_PIN, 0);
        }
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Set up interrupt handlers for each touch sensor channel
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetAlertFuncEx(TOUCH_CHANNELS_START + i, handle_touch_event, NULL);
    }

    printf("Security keypad application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(50); // Poll every 50 ms
    }

    // Clean up and exit
    cleanup_gpio();
    fclose(log_file);
    printf("Application terminated.\n");
    return 0;
}

