#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0xC810
#define CONVERSION_TIME_MS 100
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_pigpio();
int init_i2c();
int configure_opt3001();
int read_opt3001_data(int *mantissa, int *exponent);
float calculate_lux(int mantissa, int exponent);
int log_data(float lux_value);
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    int exponent;
    int mantissa;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001
int configure_opt3001() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = (CONFIG_VALUE >> 8) & 0xFF; // MSB
    buf[1] |= CONFIG_VALUE & 0xFF;      // LSB

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (result < 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the OPT3001
int read_opt3001_data(int *mantissa, int *exponent) {
    char buf[1];
    buf[0] = RESULT_REG;

    int result = i2cWriteWordData(i2c_handle, RESULT_REG, 0); // Dummy write to trigger read
    if (result < 0) {
        fprintf(stderr, "Failed to trigger read: %d\n", result);
        return -1;
    }

    char data[2];
    int bytes_read = i2cReadWordData(i2c_handle, RESULT_REG);
    if (bytes_read < 0) {
        fprintf(stderr, "Failed to read data: %d\n", bytes_read);
        return -1;
    }

    *exponent = (data[0] >> 8) & 0xFF;
    *mantissa = data[0] & 0xFF;

    // Byte swap
    *exponent = (*exponent << 8) | (*exponent >> 8);
    *mantissa = (*mantissa << 8) | (*mantissa >> 8);

    return 0;
}

// Function to calculate lux value
float calculate_lux(int mantissa, int exponent) {
    return (float)mantissa * 0.01 * (float)(1 << exponent);
}

// Function to log data to file
int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

