    while (program_running) {
        // Wait for conversion to complete (at least 100 ms)
        gpioDelay(CONVERSION_TIME_MS * 1000); // pigpioDelay takes microseconds

        // Read data from OPT3001
        if (read_opt3001_data(&mantissa, &exponent) == 0) {
            // Calculate lux value
            lux_value = calculate_lux(mantissa, exponent);

            // Log data
            log_data(lux_value);

            // Print to stdout
            printf("Lux: %.2f\n", lux_value);
        } else {
            fprintf(stderr, "Failed to read data, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

