void log_message(const char *message) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open. Message: %s\n", message);
    }
}

// Function to handle flame detection
void handle_flame_detection() {
    log_message("Flame Detected!");
    gpioWrite(ALERT_GPIO, 1); // Set ALERT_GPIO HIGH
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(ALERT_GPIO, 0); // Set ALERT_GPIO LOW
}

// Function to handle sensor read failure
void handle_sensor_read_failure() {
    log_message("Error: Failed to read sensor data.");
}

