#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state = 0;
    int previous_state = 0;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char *touch_event;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != previous_state) {
            // Debounce
            gpioDelay(DEBOUNCE_INTERVAL_MS * 1000); // Convert ms to us
            current_state = gpioRead(GPIO_PIN);

            if (current_state != previous_state) {
                // Transition detected
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                if (current_state == 1) {
                    touch_event = strdup("Touch Detected");
                } else {
                    touch_event = strdup("Touch Released");
                }

                fprintf(log_file, "%s: %s\n", timestamp, touch_event);
                fflush(log_file);
                free(touch_event); // Free the allocated memory
            }
        }

        previous_state = current_state;
        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

