#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define MEASURE_CMD 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define SAMPLING_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int raw_flow;
    uint8_t crc;
    float flow_rate;
    int status;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor(int i2c_handle, sensor_data_t *data) {
    char buf[3];
    int bytes_read;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0, MEASURE_CMD) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 2 ms)
    gpioDelay(2000); // 2 ms

    // Read 3 bytes from the sensor
    bytes_read = i2cReadDevice(i2c_handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Validate CRC
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    // Convert raw data to flow rate
    data->raw_flow = (buf[0] << 8) | buf[1];
    data->flow_rate = (float)data->raw_flow / 90.0;
    data->crc = buf[2];
    data->status = 0; // Success

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *log_file, sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d,%s\n", timestamp, data.flow_rate, data.status, (data.flow_rate < FLOW_MIN || data.flow_rate > FLOW_MAX) ? "INVALID" : (data.status == 0) ? "OK" : "ERROR");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    fflush(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor(i2c_handle, &sensor_data) == 0) {
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(SAMPLING_INTERVAL_SEC * 1000000); // Sleep for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

