        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
            sleep(1); // Avoid spamming errors
            continue;
