#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <pigpio.h>

#define TOUCH_GPIO 23
#define LED_GPIO 24
#define LOG_FILE "touch_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO configuration
typedef struct {
    int touch_gpio;
    int led_gpio;
    char log_file[64];
} gpio_config_t;

// Function prototypes
int gpio_init(gpio_config_t *config);
int gpio_read(int gpio);
int gpio_write(int gpio, int value);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int gpio_init(gpio_config_t *config) {
    int touch_fd, led_fd;
    char buf[64];

    // Open GPIO chip
    touch_fd = open("/dev/gpiochip4", O_RDWR);
    if (touch_fd < 0) {
        fprintf(stderr, "Error opening /dev/gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    led_fd = open("/dev/gpiochip4", O_RDWR);
    if (led_fd < 0) {
        fprintf(stderr, "Error opening /dev/gpiochip4: %s\n", strerror(errno));
        close(touch_fd);
        return -1;
    }

    // Request GPIO lines
    if (gpioSetMode(config->touch_gpio, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode: %s\n", config->touch_gpio, strerror(errno));
        close(touch_fd);
        close(led_fd);
        return -1;
    }
    if (gpioSetMode(config->led_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode: %s\n", config->led_gpio, strerror(errno));
        close(touch_fd);
        close(led_fd);
        return -1;
    }

    // Open log file
    FILE *log_file = fopen(config->log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", config->log_file, strerror(errno));
        close(touch_fd);
        close(led_fd);
        return -1;
    }

    return 0;
}

// Function to read GPIO value
int gpio_read(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write GPIO value
int gpio_write(int gpio, int value) {
    int result = gpioWrite(gpio, value);
    if (result < 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log event with timestamp
int log_event(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[32];

    time(&now);
    timeinfo = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        if (flock(fileno(log_file), LOCK_EX) == -1) {
            fprintf(stderr, "Error acquiring lock on log file: %s\n", strerror(errno));
            return -1;
        }

        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure data is written to disk

        if (flock(fileno(log_file), LOCK_UN) == -1) {
            fprintf(stderr, "Error releasing lock on log file: %s\n", strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    return 0;
}

int main() {
    gpio_config_t config = {TOUCH_GPIO, LED_GPIO, LOG_FILE};
    int touch_value;
    char log_message[128];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(&config) != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        touch_value = gpio_read(config.touch_gpio);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor value. Exiting.\n");
            break;
        }

        if (touch_value == 1) {
            // Toggle LED state
            int current_led_state = gpio_read(config.led_gpio);
            if (current_led_state < 0) {
                fprintf(stderr, "Error reading LED state. Continuing.\n");
            } else {
                int new_led_state = (current_led_state == 0) ? 1 : 0;
                if (gpio_write(config.led_gpio, new_led_state) != 0) {
                    fprintf(stderr, "Error writing to LED GPIO. Continuing.\n");
                }

                // Log the event
                snprintf(log_message, sizeof(log_message), "Touch detected, LED toggled to %s", new_led_state ? "ON" : "OFF");
                if (log_event(log_message) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_write(config.led_gpio, 0); // Turn off LED
    if (config.log_file != NULL) {
        fclose(config.log_file);
    }
    close(touch_fd);
    close(led_fd);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

