#define BUZZER_CHIP "gpiochip0"
#define FLAME_SENSOR_LINE 17
#define BUZZER_LINE 18

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(const char *chip_name, int line_num, const char *direction);
int read_flame_sensor(int line_num);
int activate_buzzer(int line_num, int duration_ms);
int log_event(const char *message);
void signal_handler(int signal);

// Structure to hold GPIO line information
typedef struct {
    int chip_name;
    int line_num;
    const char *direction;
} gpio_line_t;

// Function to initialize a GPIO line
int initialize_gpio(const char *chip_name, int line_num, const char *direction) {
    int line = gpiod_chip_open_by_name(chip_name);
    if (line < 0) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", chip_name, strerror(errno));
        return -1;
    }

    int dir_fd = gpiod_line_get_direction(line, direction);
    if (dir_fd < 0) {
        fprintf(stderr, "Error setting direction for line %d: %s\n", line, strerror(errno));
        gpiod_chip_close(line);
        return -1;
    }

    if (gpiod_line_request_input(line, direction) < 0) {
        fprintf(stderr, "Error requesting input for line %d: %s\n", line, strerror(errno));
        gpiod_chip_close(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

