int activate_buzzer(int line_num, int duration_ms) {
    if (gpiod_line_set_value(line_num, 1) < 0) {
        fprintf(stderr, "Error setting buzzer HIGH: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000); // Convert ms to microseconds
    if (gpiod_line_set_value(line_num, 0) < 0) {
        fprintf(stderr, "Error setting buzzer LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

