        fprintf(stderr, "Error turning off buzzer: %s\n", strerror(errno));
    }

    // Release GPIO lines
    struct gpiod_chip *chip = gpiod_chip_open_by_name(FLAME_SENSOR_CHIP);
    struct gpiod_line *flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, BUZZER_LINE);

    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close the log file
    FILE *fp = fopen("alert_log.txt", "a");
    if (fp != NULL) {
        fclose(fp);
    }

    exit(0);
}

