    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio(FLAME_SENSOR_CHIP, FLAME_SENSOR_LINE, "in") < 0) {
        fprintf(stderr, "Failed to initialize flame sensor GPIO.\n");
        return 1;
    }

    if (initialize_gpio(BUZZER_CHIP, BUZZER_LINE, "out") < 0) {
        fprintf(stderr, "Failed to initialize buzzer GPIO.\n");
        return 1;
    }

    printf("System started.\n");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_LINE);
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (flame_detected == 0) { // Flame detected (LOW signal)
            printf("Flame detected!\n");
            log_event("Flame detected!");
            activate_buzzer(BUZZER_LINE, 2000); // Activate buzzer for 2 seconds
        }

        usleep(500000); // 500 ms delay
    }

    printf("System stopped.\n");

    return 0;
}

