#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_DELAY_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in UTC ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30); // Allocate memory for the timestamp
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime); // Use gmtime for UTC

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to log the touch event to a file
void log_touch_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to toggle the LED
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_level);
}

// Function to handle the touch event
void handle_touch_event() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        log_touch_event(timestamp);
        free(timestamp);
    }
}

// Function to handle the touch interrupt
void touch_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    uint32_t diff = current_tick - last_tick;

    if (diff > DEBOUNCE_DELAY_MS * 1000) { // Debounce
        handle_touch_event();
        last_tick = current_tick;
    }
}

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    running = 0;
    printf("Caught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (Terminate)
void sigterm_handler(int signal) {
    running = 0;
    printf("Caught SIGTERM, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open touch_log.txt");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up the interrupt handler
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup
    gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

