#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor GPIO pins
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define log file name
#define LOG_FILE "magnet_log.txt"

// Global file pointer for the log file
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_event(int sensor_id, int state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR3_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read sensor state
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return state;
}

// Function to log sensor event
int log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, state ? "Magnet Removed" : "Magnet Present");
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensors[] = {
        {SENSOR1_GPIO, 1},
        {SENSOR2_GPIO, 2},
        {SENSOR3_GPIO, 3}
    };
    int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

    // Main loop
    while (1) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor(sensors[i].gpio_pin);
            if (current_state == -1) {
                // Error reading sensor, but continue to next sensor
            } else {
                if (current_state != sensors[i].sensor_id) {
                    log_event(sensors[i].sensor_id, current_state);
                }
            }
        }
        gpioDelay(100); // Delay for 100 ms
    }

    return 0;
}

