    int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

    // Main loop
    while (1) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor(sensors[i].gpio_pin);
            if (current_state == -1) {
