    gpio_status = gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d: %d\n", FLAME_SENSOR_PIN, gpio_status);
        gpioTerminate();
        return 1;
