#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

// Define GPIO pins
#define NUM_CHANNELS 8
const int GPIO_PINS[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
const int COUNTER_LSB_PIN = 17;
const int COUNTER_MSB_PIN = 24;

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS];
static int counter = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor_lines(void);
int update_counter(int new_value);
int log_touch_event(int channel, int counter_value);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Reset output pins
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0); // Set to low (inactive)
            gpiod_line_release(lines[i]);
        }
    }
    if (counter_lsb_pin) {
        gpiod_chip_close(chip);
        if (log_file) {
            fclose(log_file);
        }
        exit(0);
    }

    // Release resources
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request lines for input
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_request_lines(chip, GPIO_PINS[i], 0);
        if (!lines[i]) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PINS[i], strerror(errno));
            goto cleanup;
        }

        // Set direction to input
        ret = gpiod_line_request_direction(lines[i], GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error setting direction for GPIO %d: %s\n", GPIO_PINS[i], strerror(errno));
            goto cleanup;
        }
    }

    // Request counter pins for output
    counter_lsb_pin = gpiod_chip_request_lines(chip, COUNTER_LSB_PIN, 0);
    if (!counter_lsb_pin) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", COUNTER_LSB_PIN, strerror(errno));
        goto cleanup;
    }
    ret = gpiod_line_request_direction(counter_lsb_pin, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting direction for GPIO %d: %s\n", COUNTER_LSB_PIN, strerror(errno));
        goto cleanup;
    }

    counter_lsb_pin = gpiod_chip_request_lines(chip, COUNTER_MSB_PIN, 0);
    if (!counter_lsb_pin) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", COUNTER_MSB_PIN, strerror(errno));
        goto cleanup;
    }
    ret = gpiod_line_request_direction(counter_lsb_pin, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting direction for GPIO %d: %s\n", COUNTER_MSB_PIN, strerror(errno));
        goto cleanup;
    }

    return 0;

cleanup:
    cleanup(signal);
    return -1;
}

// Read sensor lines
int read_sensor_lines(void) {
    int ret;
    int new_values[NUM_CHANNELS];
