#define NUM_SENSORS 4

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    int gpio_line;
    int value;
} sensor_data_t;

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_SENSORS];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

