int initialize_gpio(int sensor_id, int gpio_line);
int read_sensor(int sensor_id);
void log_data(int sensor1, int sensor2, int sensor3, int sensor4);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to initialize a GPIO line for input
int initialize_gpio(int sensor_id, int gpio_line) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_line);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, "sensor_input") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    lines[sensor_id] = line;
    return 0;
}

// Function to read the value of a sensor
int read_sensor(int sensor_id) {
    if (lines[sensor_id] == NULL) {
        fprintf(stderr, "Error: Invalid sensor ID: %d\n", sensor_id);
        return -1;
    }

    int value = gpiod_line_get_value(lines[sensor_id]);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1;
    }

    return value;
}

// Function to log sensor data to a CSV file
void log_data(int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("tracking_log.csv", "a+");
        if (!log_file) {
            perror("Error opening tracking_log.csv");
            return;
        }

        // Check if the file is newly created, and write the header if needed
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        }
    }

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
    fflush(log_file); // Ensure data is written to disk
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (initialize_gpio(i, i) < 0) {
            fprintf(stderr, "Failed to initialize GPIO %d\n", i);
            cleanup();
            return 1;
        }
    }

    printf("Tracking system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int sensor_value = read_sensor(i);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                continue; // Continue to the next sensor
            }

            // Active low, so 0 means detected, 1 means not detected
            if (sensor_value == 0) {
                sensor_value = 1; // Invert the value for logging
            }

            log_data(sensor_value, sensor_value, sensor_value, sensor_value);
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

