#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO18 18
#define DEBOUNCE_MS 50

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
void log_event(int sensor_number);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Release GPIO resources
    gpioSetMode(GPIO17, PI_INPUT); // Set back to input
    gpioSetMode(GPIO18, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read sensor value with debouncing
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay in microseconds
    return gpioRead(gpio);
}

// Function to log tilt event
void log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO17, PI_INPUT);
    gpioSetMode(GPIO18, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(GPIO17, PI_PUD_UP);
    gpioSetPullUpDown(GPIO18, PI_PUD_UP);

    // Open log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor17_value = read_sensor(GPIO17);
        int sensor18_value = read_sensor(GPIO18);

        if (sensor17_value == 0) {
            log_event(1);
        }
        if (sensor18_value == 0) {
            log_event(2);
        }

        gpioDelay(100 * 1000); // 100 ms delay
    }

