#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125 // 8 kHz

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    struct timespec ts;
    int peak_detected;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(MIC_PIN, PI_PUD_DOWN);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Monitoring microphone on GPIO%d. Press Ctrl+C to exit.\n", MIC_PIN);

    while (program_running) {
        peak_detected = 0;
        for (int i = 0; i < 100; ++i) { // Sample 100 times
            gpio_status = gpioRead(MIC_PIN);
            if (gpio_status < 0) {
                fprintf(stderr, "Error reading GPIO%d: %d\n", MIC_PIN, gpio_status);
                program_running = 0; // Exit loop on error
                break;
            }

            if (gpio_status == 1) {
                peak_detected = 1;
                break;
            }

            gpioDelay(SAMPLE_PERIOD_US);
        }

        if (peak_detected) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%09ld: Peak detected!\n", ts.tv_sec, ts.tv_nsec);

            // Turn LED on
            gpioWrite(LED_PIN, 1);
            gpioDelay(100); // 100 ms

            // Turn LED off
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Clean up
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

