#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_CHIP 0
#define GPIO_PIN_LEFT 2
#define GPIO_PIN_MIDDLE 3
#define GPIO_PIN_RIGHT 4

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int main() {
    int left_gpio, middle_gpio, right_gpio;
    int left_value, middle_value, right_value;

    // Register signal handler for SIGINT
    signal(SIGINT, int_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    gpioChipSelect(GPIO_CHIP);

    // Get GPIO lines
    left_gpio = gpioGetLine(GPIO_PIN_LEFT);
    middle_gpio = gpioGetLine(GPIO_PIN_MIDDLE);
    right_gpio = gpioGetLine(GPIO_PIN_RIGHT);

    if (left_gpio < 0 || middle_gpio < 0 || right_gpio < 0) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpioTerminate();
        return 1;
    }

    // Request GPIO lines as input
    if (gpioSetMode(left_gpio, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", left_gpio);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(middle_gpio, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", middle_gpio);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(right_gpio, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", right_gpio);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read GPIO values
        left_value = gpioRead(left_gpio);
        middle_value = gpioRead(middle_gpio);
        right_value = gpioRead(right_gpio);

