    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, channel_states[i]);
    }
    printf("\n");
}

