    int chip_id = gpiochipOpen(GPIO_CHIP);
    if (chip_id < 0) {
        fprintf(stderr, "Error opening GPIO chip %d: %d\n", GPIO_CHIP, chip_id);
        gpioTerminate();
        return 1;
    }

    // Request all 8 GPIO lines as inputs
    for (int i = 0; i < num_channels; i++) {
        int line_id = touch_lines[i];
        if (gpioSetMode(line_id, PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as input\n", line_id);
            gpioChipClose(chip_id);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to poll the sensor data
    while (program_running) {
        int channel_states[num_channels];
        for (int i = 0; i < num_channels; i++) {
            channel_states[i] = read_gpio_line(touch_lines[i]);
            if (channel_states[i] < 0) {
                // Error already printed in read_gpio_line, no need to re-print here
            }
        }
        log_sensor_data(channel_states);
        gpioDelay(200); // Poll every 200 ms
    }

    // Close the GPIO chip and terminate the pigpio library
    gpioChipClose(chip_id);
    gpioTerminate();

    return 0;
}

