#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Number of fading steps
#define NUM_STEPS 50

// Hue range (0-360 degrees)
#define HUE_MIN 0
#define HUE_MAX 360

// HSV-to-RGB conversion constants
#define MIN_HUE 0
#define MAX_HUE 360

// Global variables
volatile sig_atomic_t program_running = 1;

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Function prototypes
int initialize_gpio();
void set_led_color(int red, int green, int blue);
void fade_color(RGBColor start_color, RGBColor end_color, int steps);
void generate_random_hue();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Initialize GPIO pins and pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    return 0;
}

// Set the RGB color of the LED
void set_led_color(int red, int green, int blue) {
    // Common anode, so invert the PWM duty cycle
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

// Fade between two RGB colors over a specified number of steps
void fade_color(RGBColor start_color, RGBColor end_color, int steps) {
    float red_diff = (float)(end_color.red - start_color.red);
    float green_diff = (float)(end_color.green - start_color.green);
    float blue_diff = (float)(end_color.blue - start_color.blue);

    float red_step = red_diff / steps;
    float green_step = green_diff / steps;
    float blue_step = blue_diff / steps;

    for (int i = 0; i < steps; i++) {
        // Calculate the current RGB values based on the step number
        int red = start_color.red + (int)(red_step * i);
        int green = start_color.green + (int)(green_step * i);
        int blue = start_color.blue + (int)(blue_step * i);

        // Clamp the values to the range [0, 255]
        if (red < 0) red = 0;
        if (red > 255) red = 255;
        if (green < 0) green = 0;
        if (green > 255) green = 255;
        if (blue < 0) blue = 0;
        if (blue > 255) blue = 255;

        // Invert the PWM duty cycle for common anode
        gpioPWM(RED_PIN, 255 - red);
        gpioPWM(GREEN_PIN, 255 - green);
        gpioPWM(BLUE_PIN, 255 - blue);

        // Wait for a short period
        gpioDelay(10000); // 10ms
    }
}

// Generate a random hue between HUE_MIN and HUE_MAX
void generate_random_hue() {
    int hue = HUE_MIN + (rand() % (HUE_MAX - HUE_MIN + 1));
    printf("Generated random hue: %d\n", hue);
}

// Cleanup resources before exiting
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    closelog();
}

int main() {
    // Open syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator
    srand(time(NULL));

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Generate a random hue
        generate_random_hue();

        // Generate random RGB values
        RGBColor start_color, end_color;
        start_color.red = rand() % 256;
        start_color.green = rand() % 256;
        start_color.blue = rand() % 256;

        end_color.red = rand() % 256;
        end_color.green = rand() % 256;
        end_color.blue = rand() % 256;

        // Fade between the two colors
        fade_color(start_color, end_color, NUM_STEPS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

