#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_ID 0x12
#define TCS34725_ATIME 0x00
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define GPIO_LED 17
#define RED_THRESHOLD 200
#define POLLING_INTERVAL_MS 200

// Global variables
int i2c_fd = -1;
int running = 1;

// Function prototypes
int initialize_sensor(int i2c_fd);
int read_sensor_data(int i2c_fd, unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
void calibrate_sensor_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue, unsigned int *calibrated_red, unsigned int *calibrated_green, unsigned int *calibrated_blue, unsigned int *calibrated_clear);
void control_led(unsigned int calibrated_red);
void log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue, unsigned int calibrated_red, unsigned int calibrated_green, unsigned int calibrated_blue, unsigned int calibrated_clear);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize the sensor
int initialize_sensor(int i2c_fd) {
    unsigned char buf[2];
    int result;

    // Power on the sensor
    buf[0] = TCS34725_ATIME;
    buf[1] = 0x00; // 154ms integration time
    result = write(i2c_fd, buf, 2);
    if (result != 2) {
        perror("Failed to write ATIME register");
        return -1;
    }
    usleep(10000); // Wait for power-on

    // Enable RGBC
    buf[0] = TCS34725_CONTROL;
    buf[1] = 0x01; // RGBC enable
    result = write(i2c_fd, buf, 2);
    if (result != 2) {
        perror("Failed to write CONTROL register");
        return -1;
    }
    usleep(10000); // Wait for enable

    // Verify sensor ID
    buf[0] = TCS34725_ID;
    result = read(i2c_fd, buf, 1);
    if (result != 1) {
        perror("Failed to read sensor ID");
        return -1;
    }
    unsigned int sensor_id = buf[0];
    if (sensor_id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int i2c_fd, unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    unsigned char buf[8];
    int result;

    // Read all channel data in one go
    result = read(i2c_fd, buf, 8);
    if (result != 8) {
        perror("Failed to read sensor data");
        return -1;
    }

    *clear = (unsigned int)buf[0] | ((unsigned int)buf[1] << 8);
    *red = (unsigned int)buf[2] | ((unsigned int)buf[3] << 8);
    *green = (unsigned int)buf[4] | ((unsigned int)buf[5] << 8);
    *blue = (unsigned int)buf[6] | ((unsigned int)buf[7] << 8);

    return 0;
}

// Calibrate sensor data
void calibrate_sensor_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue, unsigned int *calibrated_red, unsigned int *calibrated_green, unsigned int *calibrated_blue, unsigned int *calibrated_clear) {
    // Simple calibration: divide by 1000 (adjust as needed)
    *calibrated_red = red / 1000;
    *calibrated_green = green / 1000;
    *calibrated_blue = blue / 1000;
    *calibrated_clear = clear / 1000;
}

// Control LED based on red value
void control_led(unsigned int calibrated_red) {
    if (calibrated_red > RED_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // HIGH
    } else {
        gpioWrite(GPIO_LED, 0); // LOW
    }
}

// Log data to file
void log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue, unsigned int calibrated_red, unsigned int calibrated_green, unsigned int calibrated_blue, unsigned int calibrated_clear) {
    FILE *fp = fopen("color_log.txt", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Clear: %u, Red: %u, Green: %u, Blue: %u, Calibrated Red: %u, Calibrated Green: %u, Calibrated Blue: %u, Calibrated Clear: %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            clear, red, green, blue, calibrated_red, calibrated_green, calibrated_blue, calibrated_clear);

    fclose(fp);
}

int main() {
    unsigned int clear, red, green, blue, calibrated_red, calibrated_green, calibrated_blue, calibrated_clear;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Color sensor initialized successfully.\n");

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate sensor data
            calibrate_sensor_data(clear, red, green, blue, &calibrated_red, &calibrated_green, &calibrated_blue, &calibrated_clear);

            // Control LED
            control_led(calibrated_red);

            // Log data
            log_data(clear, red, green, blue, calibrated_red, calibrated_green, calibrated_blue, calibrated_clear);

            printf("Clear: %u, Red: %u, Green: %u, Blue: %u, Calibrated Red: %u, Calibrated Green: %u, Calibrated Blue: %u, Calibrated Clear: %u\n", clear, red, green, blue, calibrated_red, calibrated_green, calibrated_blue, calibrated_clear);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying initialization.\n");
            // Attempt sensor re-initialization
            if (initialize_sensor(i2c_fd) != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                running = 0; // Exit loop if re-initialization fails
            }
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    // Clean up
    close(i2c_fd);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

