#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for WS2812B strip
#define WS2812B_CLK 18
#define WS2812B_DATA 23

// Define I2C address for BH1750 sensor
#define BH1750_ADDR 0x23

// Define BH1750 command for continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Define BH1750 register address for lux value
#define BH1750_LUX_REG 0x00

// Define PWM frequency for WS2812B (approximately 800kHz)
#define PWM_FREQUENCY 800000

// Define logarithmic mapping constants
#define MIN_LUX 0.0
#define MAX_LUX 1000.0
#define MIN_BRIGHTNESS 0.0
#define MAX_BRIGHTNESS 255.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
float read_bh1750_lux();
int set_led_brightness(int brightness);
void map_lux_to_brightness(float lux, int *brightness);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read lux value from BH1750 sensor
float read_bh1750_lux() {
    char buf[2];
    int result;

    // Send command to start continuous high-resolution mode
    result = i2cWriteByteData(i2c_handle, BH1750_CONTINUOUS_HIGH_RES_MODE, 0);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1.0;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of lux data
    result = i2cReadI2CBlockData(i2c_handle, BH1750_LUX_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1.0;
    }

    // Combine MSB and LSB to get lux value
    unsigned int lux_raw = (buf[0] << 8) | buf[1];
    return (float)lux_raw / 1.2;
}

// Function to set the brightness of a single LED
int set_led_brightness(int brightness) {
    gpioPWM(WS2812B_DATA, brightness);
    return 0;
}

// Function to map lux value to LED brightness using a logarithmic function
void map_lux_to_brightness(float lux, int *brightness) {
    // Use a logarithmic mapping
    *brightness = (int)(MIN_BRIGHTNESS + (MAX_BRIGHTNESS - MIN_BRIGHTNESS) * (1.0 - (lux / MAX_LUX)));
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for WS2812B clock
    gpioSetMode(WS2812B_CLK, PI_OUTPUT);
    gpioSetMode(WS2812B_DATA, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read lux value from BH1750 sensor
        float lux = read_bh1750_lux();
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value, retrying in 500ms...\n");
            gpioDelay(500000); // 500ms
            continue;
        }

        // Map lux value to LED brightness
        int brightness;
        map_lux_to_brightness(lux, &brightness);

        // Set LED brightness
        set_led_brightness(brightness);

        // Delay for a short period
        gpioDelay(50000); // 50ms
    }

    // Clean up and terminate
    set_led_brightness(0); // Turn off all LEDs
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

