#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x20
#define APA102_START_FRAME 0xE0
#define APA102_END_FRAME 0xFF
#define APA102_FRAME_LENGTH 40 // 4 bytes per LED * 10 LEDs + 4 bytes end frame
#define MAX_LUX 300.0
#define MIN_LUX 10.0
#define MAX_BRIGHTNESS 31
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int bh1750_init(int fd);
float bh1750_read_lux(int fd);
int apa102_init(int fd);
int apa102_send_frame(int fd, uint8_t start_frame, uint8_t *led_frames, int num_leds);
int apa102_end_frame(int fd, uint8_t end_frame);
int apa102_set_brightness(int fd, int brightness);
void signal_handler(int sig);

// BH1750 initialization function
int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    // Set to continuous high-resolution mode
    uint8_t mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &mode, 1) != 1) {
        perror("Error: Could not write to I2C device");
        return -1;
    }
    return 0;
}

// BH1750 lux reading function
float bh1750_read_lux(int fd) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error: Could not read from I2C device");
        return -1.0;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// APA102 initialization function
int apa102_init(int fd) {
    uint8_t start_frame = APA102_START_FRAME;
    if (write(fd, &start_frame, 1) != 1) {
        perror("Error: Could not write to SPI device");
        return -1;
    }
    return 0;
}

// APA102 send frame function
int apa102_send_frame(int fd, uint8_t start_frame, uint8_t *led_frames, int num_leds) {
    if (write(fd, &start_frame, 1) != 1) {
        perror("Error: Could not write start frame to SPI device");
        return -1;
    }

    for (int i = 0; i < num_leds; i++) {
        uint8_t led_frame = (led_frames[i] << 24) | (led_frames[i] << 16) | (led_frames[i] << 8) | led_frames[i];
        if (write(fd, &led_frame, 4) != 4) {
            perror("Error: Could not write LED frame to SPI device");
            return -1;
        }
    }

    if (write(fd, &APA102_END_FRAME, 1) != 1) {
        perror("Error: Could not write end frame to SPI device");
        return -1;
    }
    return 0;
}

// APA102 set brightness function
int apa102_set_brightness(int fd, int brightness) {
    uint8_t blue = 0;
    uint8_t green = 0;
    uint8_t red = 0;

    switch (brightness) {
        case 0: blue = 0x00; green = 0x00; red = 0x00; break;
        case 1: blue = 0x10; green = 0x00; red = 0x00; break;
        case 2: blue = 0x20; green = 0x00; red = 0x00; break;
        case 3: blue = 0x30; green = 0x00; red = 0x00; break;
        case 4: blue = 0x40; green = 0x00; red = 0x00; break;
        case 5: blue = 0x50; green = 0x00; red = 0x00; break;
        case 6: blue = 0x60; green = 0x00; red = 0x00; break;
        case 7: blue = 0x70; green = 0x00; red = 0x00; break;
        case 8: blue = 0x70; green = 0x10; red = 0x00; break;
        case 9: blue = 0x70; green = 0x20; red = 0x00; break;
        case 10: blue = 0x70; green = 0x30; red = 0x00; break;
        case 11: blue = 0x70; green = 0x40; red = 0x00; break;
        case 12: blue = 0x70; green = 0x50; red = 0x00; break;
        case 13: blue = 0x70; green = 0x60; red = 0x00; break;
        case 14: blue = 0x70; green = 0x70; red = 0x00; break;
        case 15: blue = 0x70; green = 0x70; red = 0x10; break;
        case 16: blue = 0x70; green = 0x70; red = 0x20; break;
        case 17: blue = 0x70; green = 0x70; red = 0x30; break;
        case 18: blue = 0x70; green = 0x70; red = 0x40; break;
        case 19: blue = 0x70; green = 0x70; red = 0x50; break;
        case 20: blue = 0x70; green = 0x70; red = 0x60; break;
        case 21: blue = 0x70; green = 0x70; red = 0x70; break;
        case 22: blue = 0x70; green = 0x70; red = 0x70; break;
        case 23: blue = 0x70; green = 0x70; red = 0x70; break;
        case 24: blue = 0x70; green = 0x70; red = 0x70; break;
        case 25: blue = 0x70; green = 0x70; red = 0x70; break;
        case 26: blue = 0x70; green = 0x70; red = 0x70; break;
        case 27: blue = 0x70; green = 0x70; red = 0x70; break;
        case 28: blue = 0x70; green = 0x70; red = 0x70; break;
        case 29: blue = 0x70; green = 0x70; red = 0x70; break;
        case 30: blue = 0x70; green = 0x70; red = 0x70; break;
        case 31: blue = 0x70; green = 0x70; red = 0x70; break;
        default: return -1; // Invalid brightness
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT. Shutting down gracefully...\n");
        terminate = 1;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error: Could not open SPI device");
        close(i2c_fd);
        return 1;
    }

    // Initialize I2C
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) != 0) {
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Initialize SPI
    uint8_t mode = SPI_MODE_0;
    uint8_t bits_per_word = 8;
    uint32_t speed = 1000000; // 1 MHz

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error: Could not set SPI mode");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
