#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define constants
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define APA102_GPIO 10
#define APA102_SCLK 11
#define NUM_LEDS 32
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_COMMAND_HIGH_RES 0x10
#define BH1750_COMMAND_CONTINUOUS_HIGH_RES 0x11
#define BH1750_ERROR_SENSOR_NOT_PRESENT -1
#define BH1750_ERROR_I2C_READ -2
#define BH1750_ERROR_I2C_WRITE -3
#define BH1750_ERROR_SPI_READ -4
#define BH1750_ERROR_SPI_WRITE -5

// Global variables
int i2c_handle_low, i2c_handle_high;
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750(int i2c_handle);
int read_bh1750(int i2c_handle, float *lux);
int init_apa102(int spi_handle);
void set_apa102_brightness(int spi_handle, int brightness);
int map_lux_to_brightness(float lux);
void fade_brightness(int spi_handle, int target_brightness);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750(int i2c_handle) {
    // Attempt to open the I2C device at the specified address
    if (i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0) < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X\n", BH1750_ADDR_LOW);
        return BH1750_ERROR_I2C_READ;
    }
    i2c_handle = BH1750_ADDR_LOW;
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    uint8_t buffer[2];
    int result;

    // Send the One-Time High-Resolution Mode 2 command
    result = i2cWriteByteData(i2c_handle, 0x00, BH1750_COMMAND_CONTINUOUS_HIGH_RES);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return BH1750_ERROR_I2C_WRITE;
    }

    // Wait for the conversion to complete (at least 180 ms)
    gpioDelay(180000); // 180 ms

    // Read two bytes of data from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return BH1750_ERROR_I2C_READ;
    }

    // Convert the raw data to lux
    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Initialize APA102 LED strip
int init_apa102(int spi_handle) {
    // Configure the SPI interface
    gpioSetMode(APA102_SCLK, PI_OUTPUT);
    gpioSetMode(APA102_GPIO, PI_OUTPUT);

    // Send start frame
    gpioWrite(APA102_SCLK, 0);
    gpioWrite(APA102_GPIO, 0);
    gpioDelay(10000); // 10 ms
    gpioWrite(APA102_SCLK, 1);
    gpioDelay(10000); // 10 ms
    gpioWrite(APA102_SCLK, 0);
    gpioDelay(10000); // 10 ms
    gpioWrite(APA102_GPIO, 1);
    gpioDelay(10000); // 10 ms
    gpioWrite(APA102_SCLK, 1);
    gpioDelay(10000); // 10 ms
    gpioWrite(APA102_SCLK, 0);
    gpioDelay(10000); // 10 ms
    gpioWrite(APA102_GPIO, 0);
    gpioDelay(10000); // 10 ms

    return 0;
}

// Set the brightness of the APA102 LED strip
void set_apa102_brightness(int spi_handle, int brightness) {
    // Send the brightness data to the LED strip
    for (int i = 0; i < NUM_LEDS; i++) {
        // Calculate the global brightness value
        int global_brightness = map_lux_to_brightness(0.0); // Assuming lux is 0 for now

        // Map the global brightness to the LED strip's brightness
        int led_brightness = (brightness - global_brightness) * (255.0 / 31.0); // Scale to 0-255

        // Set the LED strip's brightness
        gpioWrite(APA102_GPIO, (led_brightness > 0) ? 1 : 0); // On/Off
        gpioWrite(APA102_SCLK, 1);
        gpioDelay(1000); // 1 ms
        gpioWrite(APA102_SCLK, 0);
        gpioDelay(1000); // 1 ms
    }
}

// Map lux value to brightness level (0-31)
int map_lux_to_brightness(float lux) {
    // Ensure lux is within a reasonable range
    if (lux < 0.0) {
        return 31; // Max brightness if no light detected
    }

    // Map the lux value to a brightness level (0-31)
    return (int)(31.0 - (lux / 1000.0) * 31.0); // Invert and scale
}

// Fade the brightness of the APA102 LED strip
void fade_brightness(int spi_handle, int target_brightness) {
    // Calculate the number of steps to fade
    int num_steps = 500 / 100; // 500 ms / 100 ms per step = 5 steps

    // Calculate the increment for each step
    int increment = (int)((target_brightness - 0) / num_steps);

    // Fade the brightness
    for (int i = 0; i < num_steps; i++) {
        set_apa102_brightness(spi_handle, i * increment + target_brightness);
        gpioDelay(10000); // 10 ms
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle_low = -1;
    i2c_handle_high = -1;
    if (init_bh1750(i2c_handle_low) != 0) {
        fprintf(stderr, "Failed to initialize BH1750 at address 0x%02X\n", BH1750_ADDR_LOW);
    }
    if (init_bh1750(i2c_handle_high) != 0) {
        fprintf(stderr, "Failed to initialize BH1750 at address 0x%02X\n", BH1750_ADDR_HIGH);
    }

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1 MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APA102
    if (init_apa102(spi_handle) != 0) {
        fprintf(stderr, "Failed to initialize APA102 LED strip\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for clean shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    float lux_low, lux_high;
    int target_brightness;
    while (!terminate) {
        // Read lux values from BH1750 sensors
        if (i2c_handle_low != -1) {
            if (read_bh1750(i2c_handle_low, &lux_low) == 0) {
                printf("Lux (0x23): %.2f\n", lux_low);
            } else {
                fprintf(stderr, "Error reading from BH1750 at address 0x%02X\n", BH1750_ADDR_LOW);
            }
        }
        if (i2c_handle_high != -1) {
            if (read_bh1750(i2c_handle_high, &lux_high) == 0) {
                printf("Lux (0x5C): %.2f\n", lux_high);
            } else {
                fprintf(stderr, "Error reading from BH1750 at address 0x%02X\n", BH1750_ADDR_HIGH);
            }
        }

        // Calculate the average lux value
        float total_lux = 0.0;
        int valid_sensors = 0;
        if (i2c_handle_low != -1) {
            total_lux += lux_low;
            valid_sensors++;
        }
        if (i2c_handle_high != -1) {
            total_lux += lux_high;
            valid_sensors++;
        }

        if (valid_sensors > 0) {
            float average_lux = total_lux / valid_sensors;
            printf("Average Lux: %.2f\n", average_lux);

            // Map the average lux to a brightness level
            target_brightness = map_lux_to_brightness(average_lux);

            // Fade the brightness of the LED strip
            fade_brightness(spi_handle, target_brightness);
        } else {
            fprintf(stderr, "No valid sensors available for brightness calculation\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Clean up
    set_apa102_brightness(spi_handle, 0); // Turn off LED strip
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

