#include <string.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define GAIN 1/8
#define INTEGRATION_TIME 100 // ms
#define PWM_FREQUENCY 800000 // Hz
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE_MAX 120000 // Max lux for PWM

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_als_data(uint16_t *als_value);
float calculate_lux(uint16_t als_value);
float calculate_brightness(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize VEML7700
int init_veml7700() {
    uint8_t config_data[2];
    config_data[0] = (CONFIG_REG >> 8) & 0xFF; // MSB
    config_data[1] = CONFIG_REG & 0xFF;      // LSB

    int retries = 0;
    while (retries < 3) {
        if (write(i2c_fd, config_data, 2) == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to VEML7700 config register: %s. Retry %d/%d\n", strerror(errno), retries + 1, 3);
            retries++;
            gpioDelay(100000); // 100ms delay
        }
    }
    fprintf(stderr, "Failed to initialize VEML7700 after multiple retries.\n");
    return -1; // Failure
}

// Read ALS data from VEML7700
int read_als_data(uint16_t *als_value) {
    uint8_t buffer[2];
    int retries = 0;

    while (retries < 3) {
        if (read(i2c_fd, buffer, 2) == 2) {
            *als_value = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading ALS data: %s. Retry %d/%d\n", strerror(errno), retries + 1, 3);
            retries++;
            gpioDelay(100000); // 100ms delay
        }
    }
    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1; // Failure
}

// Calculate lux value
float calculate_lux(uint16_t als_value) {
    return (float)als_value * 0.0288 * GAIN * (1.0 / INTEGRATION_TIME);
}

// Calculate brightness using gamma correction
float calculate_brightness(float lux) {
    float brightness = 255 * pow(lux / 120000.0, 1.0/2.2);
    if (brightness > 255) brightness = 255;
    if (brightness < 0) brightness = 0;
    return brightness;
}

