void set_led_brightness(int brightness) {
    // Bit-banging PWM (example, adjust as needed)
    // This is a simplified example and may need adjustments for optimal performance.
    // It toggles the GPIO pin at a high frequency.
    // A more robust implementation would use a timer or interrupt.

    // For simplicity, we'll just set the GPIO pin high/low based on the brightness.
    gpioWrite(18, brightness > 120 ? 1 : 0); // Turn on/off LED
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(18, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(18, PWM_FREQUENCY);
    gpioSetPWMrange(18, PWM_RANGE);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als_value;
    float lux, brightness;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_als_data(&als_value) == 0) {
            // Calculate lux
            lux = calculate_lux(als_value);

            // Calculate brightness
            brightness = calculate_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print values
            printf("Lux: %6.2f, Brightness: %5.2f\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }

        gpioDelay(200000); // 200ms delay
    }

    // Clean up
    set_led_brightness(0); // Turn off LED
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

