#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define BUZZER_DURATION 1000 // milliseconds
#define LED_FLASH_DURATION 500 // milliseconds
#define FLAME_SENSOR_READ_INTERVAL 50 // milliseconds
#define SENSOR_FAULT_THRESHOLD 4 // Number of consecutive LOW readings to consider a fault

// Global variables
static volatile int running = 1;
static int sensor_fault_detected = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void activate_led();
void deactivate_led();
void self_test();
void log_event(const char *event);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up resistor on the flame sensor pin
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // HIGH
    gpioDelay(BUZZER_DURATION);
    gpioWrite(BUZZER_PIN, 0); // LOW
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0); // LOW
}

// Function to activate the LED
void activate_led() {
    gpioWrite(LED_PIN, 1); // HIGH
}

// Function to deactivate the LED
void deactivate_led() {
    gpioWrite(LED_PIN, 0); // LOW
}

// Function to perform the self-test
void self_test() {
    // Blink the LED twice
    for (int i = 0; i < 2; i++) {
        activate_led();
        gpioDelay(LED_FLASH_DURATION);
        deactivate_led();
        gpioDelay(LED_FLASH_DURATION);
    }

    // Read the flame sensor 5 times
    int sensor_readings[5];
    for (int i = 0; i < 5; i++) {
        sensor_readings[i] = read_flame_sensor();
        gpioDelay(FLAME_SENSOR_READ_INTERVAL);
    }

    // Check if all readings are LOW (flame detected)
    int all_low = 1;
    for (int i = 0; i < 5; i++) {
        if (sensor_readings[i] == 0) {
            all_low = 0;
        }
    }

    if (all_low) {
        log_event("Sensor Fault Detected: All readings are LOW.");
        sensor_fault_detected = 1; // Set the fault flag
    } else {
        log_event("Sensor Fault Detected: Not all readings are LOW.");
    }
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] %s\n", timestamp, event);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    log_event("Exiting program...");
    deactivate_buzzer();
    deactivate_led();
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Perform self-test
    self_test();

    // Main loop
    while (running) {
        if (read_flame_sensor() == 0) { // Flame detected (LOW)
            activate_buzzer();
            activate_led();
            log_event("Flame detected!");
        } else {
            deactivate_buzzer();
            deactivate_led();
        }

        gpioDelay(FLAME_SENSOR_READ_INTERVAL);
    }

    // Clean up GPIO on exit
    gpioTerminate();

    return 0;
}

