// I2C read function with retry
int i2c_read_sensor(int fd, unsigned char command) {
    unsigned char data[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = write(fd, &command, 1);
        if (result == 1) {
            result = read(fd, data, 2);
            if (result == 2) {
                unsigned int raw_value = (data[0] << 8) | data[1];
                return raw_value;
