#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for '5'
const unsigned char segment_pattern[] = {
    0b00111111, // 5
    0b00111111, // 5
    0b00111111, // 5
    0b00111111, // 5
    0b00111111, // 5
    0b00111111, // 5
    0b00111111, // 5
    0b00111111  // 5
};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line) {
    int ret;

    // Request data pin as output
    ret = gpiod_line_request_output(data_line, "data", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting data line: %d\n", ret);
        return -1;
    }

    // Request clock pin as output
    ret = gpiod_line_request_output(clock_line, "clock", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting clock line: %d\n", ret);
        return -1;
    }

    // Request latch pin as output
    ret = gpiod_line_request_output(latch_line, "latch", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting latch line: %d\n", ret);
        return -1;
    }

    return 0;
}

// Function to shift out data to the 74HC595
int shift_out(struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line, unsigned char data_byte, int num_bits) {
    int i, j;

    // Set data pin low
    gpiod_line_set_value(data_line, 0);

    // Shift out the data
    for (i = 0; i < num_bits; i++) {
        // Set clock low
        gpiod_line_set_value(clock_line, 0);

        // Set data pin high if the bit is 1
        if (data_byte & (1 << (num_bits - 1 - i))) {
            gpiod_line_set_value(data_line, 1);
        } else {
            gpiod_line_set_value(data_line, 0);
        }

        // Set clock high
        gpiod_line_set_value(clock_line, 1);

        // Delay for clock timing
        usleep(1); // 1 us delay
    }

    // Set clock high for latching
    gpiod_line_set_value(clock_line, 1);
    usleep(1); // 1 us delay

    // Set data pin low for latching
    gpiod_line_set_value(data_line, 0);
    usleep(1); // 1 us delay

    // Latch the data
    gpiod_line_set_value(latch_line, 1);
    usleep(1); // 1 us delay
    gpiod_line_set_value(latch_line, 0);
    usleep(1); // 1 us delay

    return 0;
}

// Function to display a digit on the 74HC595
int display_digit(struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line, unsigned char digit_pattern) {
    int ret;

    // Shift out the digit pattern
    ret = shift_out(data_line, clock_line, latch_line, digit_pattern, 8);
    if (ret < 0) {
        fprintf(stderr, "Error shifting out digit\n");
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *clock_line, *latch_line;
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get line handles
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(chip, data_line, clock_line, latch_line) < 0) {
        fprintf(stderr, "Error initializing GPIO pins\n");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Display '5'
        if (display_digit(data_line, clock_line, latch_line, segment_pattern[0]) < 0) {
            fprintf(stderr, "Error displaying digit\n");
        }

        // Wait for 500ms
        usleep(500000);

        // Display off
        if (display_digit(data_line, clock_line, latch_line, 0) < 0) {
            fprintf(stderr, "Error displaying digit\n");
        }

        // Wait for 500ms
        usleep(500000);
    }

    // Release GPIO lines
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

