#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
        gpioWrite(LED_PIN, 0); // Turn off LED
        gpioTerminate();       // Terminate pigpio
        exit(0);                 // Exit with code 0
    }
}

int main() {
    int rc;

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO5 as an output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    printf("LED blinking on GPIO%d (Ctrl+C to exit)\n", LED_PIN);

    // Main loop
    while (program_running) {
        // Turn LED on
        gpioWrite(LED_PIN, 1);
        printf("LED ON\n");
        fflush(stdout);

        // Wait 750 ms
        time_sleep(0.75);

        // Turn LED off
        gpioWrite(LED_PIN, 0);
        printf("LED OFF\n");
        fflush(stdout);

        // Wait 750 ms
        time_sleep(0.75);
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio
    return 0;
}

