#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 24
#define BUTTON_PIN 22

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    int led_state = 0; // 0 = off, 1 = on
    int button_state = 0;
    int last_button_state = 0;
    int led_on_time = 0;
    int button_pressed_count = 0;
    int button_debounce_time = 50; // Debounce time in milliseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    int chip_id = gpiochipOpen(0);
    if (chip_id < 0) {
        fprintf(stderr, "Failed to open GPIO chip 0: %d\n", chip_id);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially off

    // Set button pin as input with pull-down
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN);

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    while (running) {
        button_state = gpioRead(BUTTON_PIN);

        if (button_state != last_button_state) {
            last_button_state = button_state;

            if (button_state == 1) {
                button_pressed_count++;
                if (button_pressed_count >= 2) { // Debounce
                    button_pressed_count = 0; // Reset debounce counter
                    led_on_time = 0; // Reset LED on time
                    led_state = 1; // Turn LED on
                    gpioWrite(LED_PIN, 1);
                    printf("Button pressed, LED ON\n");
                }
            } else {
                button_pressed_count = 0; // Reset debounce counter
                led_on_time = 0; // Reset LED on time
                led_state = 0; // Turn LED off
                gpioWrite(LED_PIN, 0);
                printf("Button released, LED OFF\n");
            }
        }

        if (led_state == 1) {
            if (led_on_time == 0) {
                led_on_time = gpioTick();
            }
            if (gpioTick() - led_on_time >= 500) {
                led_state = 0;
                gpioWrite(LED_PIN, 0);
                led_on_time = 0; // Reset on time
            }
        } else {
            led_on_time = 0; // Reset on time
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioSetMode(LED_PIN, PI_INPUT); // Set back to input
    gpioSetMode(BUTTON_PIN, PI_INPUT); // Set back to input
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN); // Set back to pull-down
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

