#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define PWM period (in nanoseconds)
#define PWM_PERIOD 10000000 // 10 ms period

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void set_pwm_duty_cycle(int pin, int duty_cycle);
void generate_random_color(int *red, int *green, int *blue);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up and exiting...\n");
        cleanup_gpio();
        exit(0);
    }
}

// Initializes the GPIO pins
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0); // Use GPIO chip 0
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("Error requesting red line as output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("Error requesting green line as output");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("Error requesting blue line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleans up the GPIO lines
void cleanup_gpio(void) {
    if (red_line) {
        gpiod_line_set_value(red_line, 0); // Turn off LED
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_set_value(green_line, 0); // Turn off LED
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_set_value(blue_line, 0); // Turn off LED
        gpiod_line_release(blue_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Sets the PWM duty cycle for a given pin
void set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (pin == RED_PIN) {
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;
        gpiod_line_set_value(red_line, 1); // Set GPIO high
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = (long)(duty_cycle * PWM_PERIOD * 1000000); // Calculate nanoseconds
        nanosleep(&ts, NULL);
        gpiod_line_set_value(red_line, 0); // Set GPIO low
    } else if (pin == GREEN_PIN) {
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;
        gpiod_line_set_value(green_line, 1); // Set GPIO high
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = (long)(duty_cycle * PWM_PERIOD * 1000000); // Calculate nanoseconds
        nanosleep(&ts, NULL);
        gpiod_line_set_value(green_line, 0); // Set GPIO low
    } else if (pin == BLUE_PIN) {
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;
        gpiod_line_set_value(blue_line, 1); // Set GPIO high
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = (long)(duty_cycle * PWM_PERIOD * 1000000); // Calculate nanoseconds
        nanosleep(&ts, NULL);
        gpiod_line_set_value(blue_line, 0); // Set GPIO low
    }
}

// Generates random RGB color values
void generate_random_color(int *red, int *green, int *blue) {
    srand(time(NULL)); // Seed the random number generator with current time
    *red = rand() % 101; // Generate random value between 0 and 100
    *green = rand() % 101;
    *blue = rand() % 101;
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int red, green, blue;

    // Main loop
    while (1) {
        // Generate random color
        generate_random_color(&red, &green, &blue);

        // Set PWM duty cycle
        set_pwm_duty_cycle(RED_PIN, red);
        set_pwm_duty_cycle(GREEN_PIN, green);
        set_pwm_duty_cycle(BLUE_PIN, blue);

        // Delay for 100 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 ms
        nanosleep(&ts, NULL);
    }

    return 0;
}

