// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x28
#define CTRL_REG4_A 0x29
#define OUT_X_L_A 0x2A
#define OUT_X_H_A 0x2B
#define OUT_Y_L_A 0x2C
#define OUT_Y_H_A 0x2D
#define OUT_Z_L_A 0x2E
#define OUT_Z_H_A 0x2F

// GPIO pin for impact indication
#define IMPACT_PIN 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// I2C handle
int i2c_handle;

// Threshold value
float threshold = DEFAULT_THRESHOLD;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_i2c();
int init_accelerometer();
int read_accelerometer(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_data(float x, float y, float z, float magnitude);
void impact_detected();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line argument for threshold
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Using threshold: %.2f\n", threshold);
    } else {
        printf("Using default threshold: %.2f\n", DEFAULT_THRESHOLD);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer
    if (init_accelerometer() != 0) {
        fprintf(stderr, "Accelerometer initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);
    gpioWrite(IMPACT_PIN, 0); // Ensure it starts LOW

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float x, y, z, magnitude;
    while (1) {
        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Calculate G-force magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > threshold) {
                impact_detected();
            }

            // Log data
            log_data(x, y, z, magnitude);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        // Delay for 100ms (10Hz polling rate)
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize accelerometer
int init_accelerometer() {
    // Enable all axes and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return 1;
    }

    // Set full-scale range to +/- 2G and sensitivity to 16384 LSB/G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes starting from OUT_X_L_A (0x28)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return 1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to G-force (assuming +/- 2G full-scale)
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;

    return 0;
}

// Calculate G-force magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log data to file
void log_data(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f, Y: %.3f, Z: %.3f, Magnitude: %.3f\n",
            timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Impact detection
void impact_detected() {
    gpioWrite(IMPACT_PIN, 1); // Set GPIO HIGH
    gpioDelay(50000);        // Wait 50ms
    gpioWrite(IMPACT_PIN, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

