#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // PWM range for brightness control
#define LOG_FILE "color_log.csv"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(const sensor_data_t *data);
void set_led_brightness(uint16_t als_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Function to initialize the ADPD188BI sensor
int initialize_sensor() {
    // Enter normal operation mode
    if (i2cWriteByteData(i2c_handle, 0x0D, 0x01) < 0) {
        fprintf(stderr, "Error writing to MODE register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int als_lsb, als_msb, red, green, blue;

    als_lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
    if (als_lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %s\n", strerror(errno));
        return -1;
    }

    als_msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
    if (als_msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %s\n", strerror(errno));
        return -1;
    }

    red = i2cReadByteData(i2c_handle, RED_REG);
    if (red < 0) {
        fprintf(stderr, "Error reading Red: %s\n", strerror(errno));
        return -1;
    }

    green = i2cReadByteData(i2c_handle, GREEN_REG);
    if (green < 0) {
        fprintf(stderr, "Error reading Green: %s\n", strerror(errno));
        return -1;
    }

    blue = i2cReadByteData(i2c_handle, BLUE_REG);
    if (blue < 0) {
        fprintf(stderr, "Error reading Blue: %s\n", strerror(errno));
        return -1;
    }

    data->als = (uint16_t)((als_msb << 8) | als_lsb);
    data->red = red;
    data->green = green;
    data->blue = blue;

    return 0;
}

// Function to log data to a CSV file
void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data->als, data->red, data->green, data->blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to set LED brightness using PWM
void set_led_brightness(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als_value / 65535.0) * PWM_RANGE);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(PWM_GPIO, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            set_led_brightness(sensor_data.als);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(PWM_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

