    fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
