        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(PWM_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

