#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_Y_MSB 0x03
#define OUT_Z_MSB 0x05
#define CTRL_REG2 0x2B
#define CTRL_REG3 0x2C
#define CTRL_REG4 0x2D
#define CTRL_REG5 0x2E
#define CTRL_REG6 0x2F

// Sensitivity (4096 counts/g)
#define SENSITIVITY 4096.0

// Impact threshold (2g)
#define IMPACT_THRESHOLD 19.62

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
