    while (1) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue; // Continue to the next iteration
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(x, y, z);

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            // Log impact
            if (log_impact(x, y, z, magnitude) != 0) {
                fprintf(stderr, "Error logging impact\n");
            }
        }

        // Delay for 50 ms (20 Hz sampling rate)
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize sensor
int init_sensor() {
    // Verify WHO_AM_I register
    int who_am_i;
    if (read_register(WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Standby mode
    if (write_register(CTRL_REG1, 0x00) != 0) return -1;

    // ±2g mode
    if (write_register(CTRL_REG2, 0x00) != 0) return -1;
    if (write_register(CTRL_REG3, 0x00) != 0) return -1;
    if (write_register(CTRL_REG4, 0x00) != 0) return -1;
    if (write_register(CTRL_REG5, 0x00) != 0) return -1;
    if (write_register(CTRL_REG6, 0x00) != 0) return -1;

    // Active mode, 200 Hz ODR
    if (write_register(CTRL_REG1, 0x15) != 0) return -1; // Active mode, 200 Hz ODR

    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data block: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / SENSITIVITY;
    double y_g = (double)y / SENSITIVITY;
    double z_g = (double)z / SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact
int log_impact(double x, double y, double z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

