#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Sensitivity (dps/LSB)
#define SENSITIVITY 0.00875

// Calibration sample count
#define CALIBRATION_SAMPLES 100

// Threshold for angular velocity (dps)
#define THRESHOLD 50.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x, y, z;
} gyro_data_t;

// Function prototypes
int i2c_setup(const char *bus);
int gyro_read_register(int fd, uint8_t reg);
int gyro_write_register(int fd, uint8_t reg, uint8_t value);
int gyro_configure(int fd);
int gyro_read_data(int fd, gyro_data_t *data);
void calibrate_gyro(int fd, gyro_data_t *data);
void log_data(FILE *fp, gyro_data_t data);
void log_alert(FILE *fp, const char *message);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to read a single byte from a register
int gyro_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to a register
int gyro_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

// Function to configure the gyroscope
int gyro_configure(int fd) {
    if (gyro_write_register(fd, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error configuring CTRL_REG1\n");
        return -1;
    }
    if (gyro_write_register(fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error configuring CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int gyro_read_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        perror("Error reading gyro data");
        return -1;
    }

    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to calibrate the gyroscope
void calibrate_gyro(int fd, gyro_data_t *data) {
    int16_t sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (gyro_read_data(fd, data) != 0) {
            fprintf(stderr, "Error reading data during calibration\n");
            return;
        }
        sum_x += data->x;
        sum_y += data->y;
        sum_z += data->z;
        usleep(1000); // 1 ms delay
    }

    data->x -= sum_x / CALIBRATION_SAMPLES;
    data->y -= sum_y / CALIBRATION_SAMPLES;
    data->z -= sum_z / CALIBRATION_SAMPLES;
}

// Function to log data to a file
void log_data(FILE *fp, gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(fp);
}

// Function to log an alert message
void log_alert(FILE *fp, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(fp, "%s,ALERT: %s\n", timestamp, message);
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_setup(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Verify sensor presence
    int who_am_i = gyro_read_register(i2c_fd, 0x0F);
    if (who_am_i != 0x43) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%X, expected 0x43\n", who_am_i);
        close(i2c_fd);
        return 1;
    }

    // Configure gyroscope
    if (gyro_configure(i2c_fd) != 0) {
        fprintf(stderr, "Error configuring gyroscope\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    gyro_data_t data;
    calibrate_gyro(i2c_fd, &data);

    // Main loop
    while (!terminate) {
        if (gyro_read_data(i2c_fd, &data) == 0) {
            log_data(log_file, data);

            // Check for threshold exceedances
            if (fabs(data.x) > THRESHOLD || fabs(data.y) > THRESHOLD || fabs(data.z) > THRESHOLD) {
                log_alert(log_file, "Threshold exceeded");
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }
        usleep(50000); // 50 ms delay
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

