#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL_MS 10

// Define TDOA threshold (in seconds)
#define TDOA_THRESHOLD 0.1

// Define TDOA resolution (in seconds)
#define TDOA_RESOLUTION 0.01

// Define TDOA range (in seconds)
#define TDOA_RANGE 10.0

// Define data log file name
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1_data;
    int16_t sensor2_data;
    double tdoa;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int address);
int configure_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int16_t *data);
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %s\n", address, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to configure the sensor
int configure_sensor(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, 0x00, 0x80); // Enable continuous measurement
    if (result < 0) {
        fprintf(stderr, "Failed to configure sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int16_t *data) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x01, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    *data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Function to calculate TDOA
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return (double)(sensor2_data - sensor1_data) / 1000.0; // Convert to seconds
}

// Function to log data to file
int log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%ld.%09ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, data.sensor1_data, data.sensor2_data, data.tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Configure both sensors
    if (configure_sensor(i2c_handle1) != 0) {
        cleanup();
        return 1;
    }
    if (configure_sensor(i2c_handle2) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int16_t sensor1_data, sensor2_data;
    double tdoa;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0 && read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
            // Calculate TDOA
            tdoa = calculate_tdoa(sensor1_data, sensor2_data);

            // Log data
            if (log_data((sensor_data_t){sensor1_data, sensor2_data, tdoa}) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Check for TDOA threshold
            if (abs(tdoa) < TDOA_THRESHOLD) {
                printf("TDOA threshold exceeded: %.6f seconds\n", tdoa);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

