    int result = i2cReadI2CBlockData(i2c_handle, 0x01, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    *data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Function to calculate TDOA
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return (double)(sensor2_data - sensor1_data) / 1000.0; // Convert to seconds
}

// Function to log data to file
int log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%ld.%09ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, data.sensor1_data, data.sensor2_data, data.tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Configure both sensors
    if (configure_sensor(i2c_handle1) != 0) {
        cleanup();
        return 1;
    }
    if (configure_sensor(i2c_handle2) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int16_t sensor1_data, sensor2_data;
    double tdoa;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0 && read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
            // Calculate TDOA
            tdoa = calculate_tdoa(sensor1_data, sensor2_data);

            // Log data
            if (log_data((sensor_data_t){sensor1_data, sensor2_data, tdoa}) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Check for TDOA threshold
            if (abs(tdoa) < TDOA_THRESHOLD) {
                printf("TDOA threshold exceeded: %.6f seconds\n", tdoa);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

