void signal_handler(int signal);
void cleanup();

// Function to read a 16-bit word from the ADIS16488A via SPI
int spi_read_register(int spi_handle, uint8_t address, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: MSB 0, address, dummy byte
    tx_buf[0] = 0x00; // MSB = 0 for read
    tx_buf[1] = address;
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Extract the 16-bit data from the receive buffer
    *data = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    return 0; // Indicate success
}

// Function to write a 16-bit word to the ADIS16488A via SPI
int spi_write_register(int spi_handle, uint8_t address, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: MSB 1, address, data
    tx_buf[0] = 0x01; // MSB = 1 for write
    tx_buf[1] = address;
    tx_buf[2] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] |= (data << 8); // LSB of data

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "SPI write error: %s\n", strerror(errno));
        return -1; // Indicate error
    }

