#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 3
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO 8

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
    }
}

// Function to initialize the SPI device
int spi_init(int fd) {
    int mode = SPI_MODE;
    int speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        return -1;
    }

    return 0;
}

// Function to read a 16-bit value from the ADIS16448 via SPI
int16_t read_adis16448_register(int fd, uint8_t register_address) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message to read the register
    tx_buf[0] = register_address | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading
    tx_buf[2] = 0x00; // Dummy byte for reading

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Combine the received bytes to form the 16-bit value
    return (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
}

// Function to read gyroscope data
void read_gyro_data(int fd, float *x_rate, float *y_rate, float *z_rate) {
    int16_t raw_x = read_adis16448_register(fd, XGYRO_OUT);
    int16_t raw_y = read_adis16448_register(fd, YGYRO_OUT);
    int16_t raw_z = read_adis16448_register(fd, ZGYRO_OUT);

    if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return;
    }

    *x_rate = (float)raw_x * 0.02;
    *y_rate = (float)raw_y * 0.02;
    *z_rate = (float)raw_z * 0.02;
}

// Function to read accelerometer data
void read_accel_data(int fd, float *x_accel, float *y_accel, float *z_accel) {
    int16_t raw_x = read_adis16448_register(fd, XACCL_OUT);
    int16_t raw_y = read_adis16448_register(fd, YACCL_OUT);
    int16_t raw_z = read_adis16448_register(fd, ZACCL_OUT);

    if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return;
    }

    *x_accel = (float)raw_x * 0.00025;
    *y_accel = (float)raw_y * 0.00025;
    *z_accel = (float)raw_z * 0.00025;
}

int main() {
    int spi_fd;
    int cs_fd;
    int spi_mode = SPI_MODE;
    int spi_speed = SPI_SPEED;
    uint8_t cs_pin = CS_GPIO;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return 1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open Chip Select file descriptor
    cs_fd = open("/dev/gpiochip0", O_RDWR);
    if (cs_fd < 0) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Set GPIO pin mode to output
    if (ioctl(cs_fd, GPIO_SET_MODE, cs_pin) == -1) {
        perror("Error setting GPIO mode");
        close(cs_fd);
        close(spi_fd);
        return 1;
    }

    // Set Chip Select pin as output
    if (ioctl(cs_fd, GPIO_SET_PUD, 0) == -1) {
        perror("Error setting GPIO pull-down");
        close(cs_fd);
        close(spi_fd);
        return 1;
    }

    // Set Chip Select pin to low (inactive)
    if (ioctl(cs_fd, GPIO_SET_DRIVE, 0) == -1) {
        perror("Error setting GPIO drive");
        close(cs_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        float gyro_x_rate, gyro_y_rate, gyro_z_rate;
        float accel_x_accel, accel_y_accel, accel_z_accel;

        read_gyro_data(spi_fd, &gyro_x_rate, &gyro_y_rate, &gyro_z_rate);
        read_accel_data(spi_fd, &accel_x_accel, &accel_y_accel, &accel_z_accel);

