#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05 // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit value from the ADIS16448 via SPI
int16_t read_adis16448_register(int spi_handle, uint8_t register_address)
{
    char tx_buffer[2];
    char rx_buffer[2];

    // Construct the SPI message to read the register
    tx_buffer[0] = register_address | 0x8000; // Set MSB to 1 for read operation
    tx_buffer[1] = 0x0000; // Dummy data for reading

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the 16-bit value from the received data
    int16_t value = (rx_buffer[0] << 8) | rx_buffer[1];
    return value;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0)
    {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        // Read gyroscope data
        int16_t gyro_x = read_adis16448_register(spi_handle, X_GYRO_OUT);
        int16_t gyro_y = read_adis16448_register(spi_handle, Y_GYRO_OUT);
        int16_t gyro_z = read_adis16448_register(spi_handle, Z_GYRO_OUT);

        // Read accelerometer data
        int16_t acc_x = read_adis16448_register(spi_handle, X_ACCL_OUT);
        int16_t acc_y = read_adis16448_register(spi_handle, Y_ACCL_OUT);
        int16_t acc_z = read_adis16448_register(spi_handle, Z_ACCL_OUT);

        // Scale the data
        float gyro_x_deg_per_sec = gyro_x * GYRO_SCALE;
        float gyro_y_deg_per_sec = gyro_y * GYRO_SCALE;
        float gyro_z_deg_per_sec = gyro_z * GYRO_SCALE;
        float acc_x_g = acc_x * ACCL_SCALE;
        float acc_y_g = acc_y * ACCL_SCALE;
        float acc_z_g = acc_z * ACCL_SCALE;

        // Print the data
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | Acc: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
               gyro_x_deg_per_sec, gyro_y_deg_per_sec, gyro_z_deg_per_sec,
               acc_x_g, acc_y_g, acc_z_g);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

