#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to initialize the MPU-6886 sensor
int init_mpu6886(int fd) {
    int retries = 3;
    int result;

    // Verify sensor presence
    while (retries > 0) {
        uint8_t who_am_i = 0;
        result = i2c_smbus_read_byte_data(fd, WHO_AM_I);
        if (result < 0) {
            perror("Error reading WHO_AM_I register");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        if (who_am_i != 0x86) {
            fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x86\n", who_am_i);
            retries--;
            usleep(100000);
            continue;
        }
        break; // WHO_AM_I register read successful
    }
    if (retries == 0) {
        fprintf(stderr, "Error: WHO_AM_I register read failed after multiple retries.\n");
        return -1;
    }

    // Wake up the sensor
    retries = 3;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0x00);
        if (result < 0) {
            perror("Error writing PWR_MGMT_1 register");
            retries--;
            usleep(100000);
            continue;
        }
        break;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to wake up sensor after multiple retries.\n");
        return -1;
    }

    // Configure accelerometer range to +-2g
    retries = 3;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, ACCEL_CONFIG, 0x00);
        if (result < 0) {
            perror("Error writing ACCEL_CONFIG register");
            retries--;
            usleep(100000);
            continue;
        }
        break;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure accelerometer range after multiple retries.\n");
        return -1;
    }

    // Configure gyroscope range to +-250 dps
    retries = 3;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, GYRO_CONFIG, 0x00);
        if (result < 0) {
            perror("Error writing GYRO_CONFIG register");
            retries--;
            usleep(100000);
            continue;
        }
        break;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure gyroscope range after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read raw accelerometer data
int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_word_data(fd, ACCEL_XOUT_H);
        if (result < 0) {
            perror("Error reading ACCEL_XOUT_H register");
            retries--;
            usleep(100000);
            continue;
        }
        *x = (int16_t)result;

        result = i2c_smbus_read_word_data(fd, ACCEL_XOUT_L);
        if (result < 0) {
            perror("Error reading ACCEL_XOUT_L register");
            retries--;
            usleep(100000);
            continue;
        }
        *x = (*x << 8) | (int16_t)result; // Combine high and low bytes

        result = i2c_smbus_read_word_data(fd, ACCEL_YOUT_H);
        if (result < 0) {
            perror("Error reading ACCEL_YOUT_H register");
            retries--;
            usleep(100000);
            continue;
        }
        *y = (int16_t)result;

        result = i2c_smbus_read_word_data(fd, ACCEL_YOUT_L);
        if (result < 0) {
            perror("Error reading ACCEL_YOUT_L register");
            retries--;
            usleep(100000);
            continue;
        }
        *y = (*y << 8) | (int16_t)result; // Combine high and low bytes

        result = i2c_smbus_read_word_data(fd, ACCEL_ZOUT_H);
        if (result < 0) {
            perror("Error reading ACCEL_ZOUT_H register");
            retries--;
            usleep(100000);
            continue;
        }
        *z = (int16_t)result;

        result = i2c_smbus_read_word_data(fd, ACCEL_ZOUT_L);
        if (result < 0) {
            perror("Error reading ACCEL_ZOUT_L register");
            retries--;
            usleep(100000);
            continue;
        }
        *z = (*z << 8) | (int16_t)result; // Combine high and low bytes

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read accelerometer data after multiple retries.\n");
    return -1; // Failure
}

// Function to read raw gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_word_data(fd, GYRO_XOUT_H);
        if (result < 0) {
            perror("Error reading GYRO_XOUT_H register");
            retries--;
            usleep(100000);
            continue;
        }
        *x = (int16_t)result;

        result = i2c_smbus_read_word_data(fd, GYRO_XOUT_L);
        if (result < 0) {
            perror("Error reading GYRO_XOUT_L register");
            retries--;
            usleep(100000);
            continue;
        }
        *x = (*x << 8) | (int16_t)result; // Combine high and low bytes

        result = i2c_smbus_read_word_data(fd, GYRO_YOUT_H);
        if (result < 0) {
            perror("Error reading GYRO_YOUT_H register");
            retries--;
            usleep(100000);
            continue;
        }
        *y = (int16_t)result;

        result = i2c_smbus_read_word_data(fd, GYRO_YOUT_L);
        if (result < 0) {
            perror("Error reading GYRO_YOUT_L register");
            retries--;
            usleep(100000);
            continue;
        }
        *y = (*y << 8) | (int16_t)result; // Combine high and low bytes

        result = i2c_smbus_read_word_data(fd, GYRO_ZOUT_H);
        if (result < 0) {
            perror("Error reading GYRO_ZOUT_H register");
            retries--;
            usleep(100000);
            continue;
        }
        *z = (int16_t)result;

        result = i2c_smbus_read_word_data(fd, GYRO_ZOUT_L);
        if (result < 0) {
            perror("Error reading GYRO_ZOUT_L register");
            retries--;
            usleep(100000);
            continue;
        }
        *z = (*z << 8) | (int16_t)result; // Combine high and low bytes

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read gyroscope data after multiple retries.\n");
    return -1; // Failure
}

int main() {
    int fd;
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 50 ms

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
