#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30

// GPIO pin for LED
#define LED_PIN 17

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.5

// Full-scale range (+/- 2g)
#define FULL_SCALE_RANGE 2.0

// Sensitivity (LSB/g)
#define SENSITIVITY 0.0025 // 256 LSB/g

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float magnitude, float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int adxl345_init() {
    // Check device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set data rate\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to enable measurement mode\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force units
    *x = (float)x_raw * SENSITIVITY;
    *y = (float)y_raw * SENSITIVITY;
    *z = (float)z_raw * SENSITIVITY;

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log impact data to a file
void log_impact(float magnitude, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Impact detected: Magnitude = %.2f g, X = %.2f g, Y = %.2f g, Z = %.2f g\n",
            timestamp, magnitude, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    float x, y, z, magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Turn on LED
                gpioWrite(LED_PIN, 1);
                gpioDelay(500); // 500 ms

                // Log impact
                log_impact(magnitude, x, y, z);
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data, retrying...\n");
        }

        // Delay for 10 ms
        gpioDelay(10);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

