#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define CTRL_REG3 0x2C
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0
#define LED_ON_DURATION 500 // milliseconds
#define POLLING_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_acceleration_data(int fd, accelerometer_data_t *data);
float calculate_magnitude(accelerometer_data_t data);
void control_led(int gpio, int on);
void log_impact(const char *timestamp);
void signal_handler(int sig);
int verify_sensor_id(int fd);

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Read acceleration data from the MMA8451Q
int read_acceleration_data(int fd, accelerometer_data_t *data) {
    int16_t x, y, z;

    x = (i2c_read_register(fd, OUT_X_MSB) << 8) | i2c_read_register(fd, OUT_X_LSB);
    y = (i2c_read_register(fd, OUT_Y_MSB) << 8) | i2c_read_register(fd, OUT_Y_LSB);
    z = (i2c_read_register(fd, OUT_Z_MSB) << 8) | i2c_read_register(fd, OUT_Z_LSB);

    data->x = x;
    data->y = y;
    data->z = z;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    float x = (float)data.x / 1024.0; // Convert to g
    float y = (float)data.y / 1024.0;
    float z = (float)data.z / 1024.0;
    return sqrt(x * x + y * y + z * z);
}

// Control the LED
void control_led(int gpio, int on) {
    if (on) {
        if (write(gpio, "1", 1) != 1) {
            perror("Failed to write to GPIO");
        }
    } else {
        if (write(gpio, "0", 1) != 1) {
            perror("Failed to write to GPIO");
        }
    }
}

// Log impact event to file
void log_impact(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s Impact detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Verify sensor ID
int verify_sensor_id(int fd) {
    int sensor_id = i2c_read_register(fd, WHO_AM_I);
    if (sensor_id != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect sensor ID (0x%X != 0x%X)\n", sensor_id, WHO_AM_I_VALUE);
        return -1;
    }
    printf("Sensor ID verified: 0x%X\n", sensor_id);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_fd) != 0) {
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Configure accelerometer (adjust as needed)
    if (i2c_write_register(i2c_fd, CTRL_REG1, 0x01) != 0) { // Enable accelerometer
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_register(i2c_fd, CTRL_REG2, 0x00) != 0) { // Set data rate to 100 Hz
        fprintf(stderr, "Failed to write to CTRL_REG2\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_register(i2c_fd, CTRL_REG3, 0x00) != 0) { // Set full scale to +-2g
        fprintf(stderr, "Failed to write to CTRL_REG3\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    accelerometer_data_t data;
    float magnitude;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration_data(i2c_fd, &data) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(data);

            // Check for impact
            if (magnitude > ACCEL_THRESHOLD) {
                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Turn on LED
                control_led(LED_GPIO, 1);
                usleep(LED_ON_DURATION * 1000); // Convert milliseconds to microseconds

                // Turn off LED
                control_led(LED_GPIO, 0);

                // Log impact
                log_impact(timestamp);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    // Clean up
    printf("Cleaning up...\n");
    control_led(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

