    if (i2c_write_register(i2c_fd, CTRL_REG2, 0x00) != 0) { // Set data rate to 100 Hz
        fprintf(stderr, "Failed to write to CTRL_REG2\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_register(i2c_fd, CTRL_REG3, 0x00) != 0) { // Set full scale to +-2g
        fprintf(stderr, "Failed to write to CTRL_REG3\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    accelerometer_data_t data;
    float magnitude;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration_data(i2c_fd, &data) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(data);

            // Check for impact
            if (magnitude > ACCEL_THRESHOLD) {
                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Turn on LED
                control_led(LED_GPIO, 1);
                usleep(LED_ON_DURATION * 1000); // Convert milliseconds to microseconds

                // Turn off LED
                control_led(LED_GPIO, 0);

                // Log impact
                log_impact(timestamp);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    // Clean up
    printf("Cleaning up...\n");
    control_led(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

