#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define ADXL345_ADDR 0x53
#define INT1_PIN 17
#define FREEFALL_THRESHOLD 300 // mg
#define FREEFALL_TIME 100      // ms
#define DATA_FILE "freefall_log.csv"

// ADXL345 Registers
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define INT_SOURCE 0x30
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int adxl345_init(int fd);
int adxl345_read_acceleration(int fd, float *x, float *y, float *z);
int adxl345_get_freefall_status(int fd);
int log_data(FILE *fp, float x, float y, float z);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize the ADXL345
int adxl345_init(int fd) {
    // Standby mode
    if (i2cWriteByteData(fd, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set POWER_CTL register.\n");
        return -1;
    }

    // Enable freefall interrupt
    if (i2cWriteByteData(fd, INT_ENABLE, 0x02) < 0) {
        fprintf(stderr, "Error: Could not set INT_ENABLE register.\n");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (i2cWriteByteData(fd, INT_MAP, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set INT_MAP register.\n");
        return -1;
    }

    // Enter measurement mode
    if (i2cWriteByteData(fd, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set POWER_CTL register.\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int fd, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(fd, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    // Convert raw data to g-force units (assuming +/- 2g range)
    *x = (float)((int16_t)((buffer[1] << 8) | buffer[0])) * 0.0039;
    *y = (float)((int16_t)((buffer[3] << 8) | buffer[2])) * 0.0039;
    *z = (float)((int16_t)((buffer[5] << 8) | buffer[4])) * 0.0039;

    return 0;
}

// Function to check for freefall status
int adxl345_get_freefall_status(int fd) {
    int status = i2cReadByteData(fd, INT_SOURCE);
    if (status < 0) {
        fprintf(stderr, "Error: Could not read INT_SOURCE register.\n");
        return -1;
    }

    // Check if freefall bit is set (bit 2)
    return (status & 0x04) ? 1 : 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    if (level == 0) { // Falling edge detected
        int freefall_status = adxl345_get_freefall_status(i2c_fd);
        if (freefall_status == 1) {
            float x, y, z;
            if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                log_data(log_file, x, y, z);
            } else {
                fprintf(stderr, "Error: Failed to read acceleration data during freefall.\n");
            }
        } else {
            fprintf(stderr, "Freefall not active.\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INT1_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set up interrupt handler.\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    float x, y, z;
    while (program_running) {
        // Check for freefall status
        int freefall_status = adxl345_get_freefall_status(i2c_fd);
        if (freefall_status == 1) {
            // Read acceleration data
            if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                // Log data
                log_data(log_file, x, y, z);
            } else {
                fprintf(stderr, "Error: Failed to read acceleration data during freefall.\n");
            }
        } else {
            // No freefall, check if the sensor is still present
            int device_id = i2cReadByteData(i2c_fd, 0x00);
            if (device_id == 0xE5) {
                printf("ADXL345 sensor detected.\n");
            } else {
                fprintf(stderr, "Error: ADXL345 sensor not detected.\n");
                program_running = 0; // Exit loop if sensor is not present
            }
        }

        // Sleep for a short interval
        usleep(10000); // 10ms
    }

    // Cleanup
    gpioSetISRFuncEx(INT1_PIN, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt handler
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

