        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INT1_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set up interrupt handler.\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    float x, y, z;
    while (program_running) {
        // Check for freefall status
        int freefall_status = adxl345_get_freefall_status(i2c_fd);
        if (freefall_status == 1) {
            // Read acceleration data
            if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                // Log data
                log_data(log_file, x, y, z);
            } else {
                fprintf(stderr, "Error: Failed to read acceleration data during freefall.\n");
            }
        } else {
            // No freefall, check if the sensor is still present
            int device_id = i2cReadByteData(i2c_fd, 0x00);
            if (device_id == 0xE5) {
                printf("ADXL345 sensor detected.\n");
            } else {
                fprintf(stderr, "Error: ADXL345 sensor not detected.\n");
                program_running = 0; // Exit loop if sensor is not present
            }
        }

        // Sleep for a short interval
        usleep(10000); // 10ms
    }

    // Cleanup
    gpioSetISRFuncEx(INT1_PIN, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt handler
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

