#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f  // g
#define IMPACT_THRESHOLD 2.5f   // g
#define IMPACT_WINDOW_SEC 1.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_lsm6dsr();
int read_accel_data(float *x, float *y, float *z);
int read_gyro_data(float *x, float *y, float *z);
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
void fall_detection(float accel_x, float accel_y, float accel_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Configure accelerometer: +-2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80 = 104 Hz, +-2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80 = 104 Hz, +-250 dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accel_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to g
    *x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) / 16384.0f; // +-2g range
    *y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) / 16384.0f;
    *z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) / 16384.0f;

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes, convert to dps
    *x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) / 131.0f; // +-250 dps range
    *y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) / 131.0f;
    *z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) / 131.0f;

    return 0;
}

// Function to log data to a CSV file
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to detect falls
void fall_detection(float accel_x, float accel_y, float accel_z) {
    static time_t freefall_start_time = 0;
    static int freefall_state = 0; // 0: IDLE, 1: FREEFALL
    static float freefall_magnitude = 0.0f;
    static int impact_detected = 0; // 0: NOT DETECTED, 1: DETECTED

    time_t current_time = time(NULL);

    if (freefall_state == 0) {
        if (accel_x * accel_x + accel_y * accel_y + accel_z * accel_z < FREEFALL_THRESHOLD) {
            freefall_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
            freefall_state = 1;
            freefall_start_time = current_time;
            printf("Freefall detected\n");
        }
    } else if (freefall_state == 1) {
        if (difftime(current_time, freefall_start_time) >= IMPACT_WINDOW_SEC) {
            float magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
            if (magnitude > IMPACT_THRESHOLD) {
                impact_detected = 1;
                printf("Impact detected\n");
            }
            freefall_state = 0; // Reset state after impact
        }
    } else {
        // Do nothing if not in freefall state
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_accel_data(&sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            continue; // Retry reading
        }
        if (read_gyro_data(&sensor_data.gyro_x, &sensor_data.gyro_y, &sensor_data.gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            continue; // Retry reading
        }

        // Log data
        log_data(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.gyro_x, sensor_data.gyro_y, sensor_data.gyro_z);

        // Detect falls
        fall_detection(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z);

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

