// Function to write a single byte to the ADIS16266 register
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    if (spiWrite(handle, tx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Function to read the X_GYRO_OUT register and convert to degrees/sec
int read_gyro_data(int handle, float *angular_rate) {
    int raw_data = spi_read_register(handle, X_GYRO_OUT);
    if (raw_data == -1) {
        return -1;
    }

    // The ADIS16266 returns a 16-bit value, but we only need the lower 14 bits.
    raw_data = raw_data & 0x0FFF; // Mask out the higher bits

    *angular_rate = (float)raw_data * SCALE_FACTOR;

    return 0;
}

// Function to log the angular rate to a CSV file
int log_data(FILE *fp, float angular_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.4f\n", timestamp, angular_rate);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Function to check the WHO_AM_I register
int check_who_am_i(int handle) {
    int who_am_i = spi_read_register(handle, WHO_AM_I);
    if (who_am_i == -1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x3F5A\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I: 0x%02X\n", who_am_i);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check WHO_AM_I register
    if (check_who_am_i(spi_handle) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float angular_rate;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_handle, &angular_rate) == 0) {
            log_data(log_file, angular_rate);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

