#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Sensitivity (MDPS/LSB)
#define SENSITIVITY 8.75

// File to log data to
#define LOG_FILE "gyro_log.csv"

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the gyroscope
int init_gyro()
{
    int retries = 3;
    int result;

    while (retries > 0) {
        // Check WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
        if (who_am_i == 0xD3) {
            break; // WHO_AM_I is correct
        } else {
            fprintf(stderr, "Error: WHO_AM_I register returned 0x%X. Retrying...\n", who_am_i);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Failed to initialize gyroscope after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1: Normal mode, all axes enabled
    result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG1 (error code %d).\n", result);
        return -1;
    }

    // Configure CTRL_REG4: +-250 dps full-scale range
    result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG4 (error code %d).\n", result);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data (error code %d).\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps)
{
    *x_dps = (float)x * SENSITIVITY / 114.285;
    *y_dps = (float)y * SENSITIVITY / 114.285;
    *z_dps = (float)z * SENSITIVITY / 114.285;
}

// Function to log data to a file
int log_data(float x, float y, float z)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main()
{
    int16_t x, y, z;
    float x_dps, y_dps, z_dps;

    // Register signal handler for graceful termination
    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file (%s)\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Convert data to degrees per second
            convert_to_dps(x, y, z, &x_dps, &y_dps, &z_dps);

            // Log data
            log_data(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

