#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a flame event to the log file
int log_flame_event(const char* timestamp, const char* event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s - Flame detected: %s\n", timestamp, event);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

// Function to check for flame detection
int is_flame_detected(int gpio_value) {
    return (gpio_value == 0); // Active low
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    int gpio_value;
    char* timestamp;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the sensor value
        gpio_value = gpioRead(FLAME_SENSOR_GPIO);

        // Check for errors during sensor read
        if (gpio_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
        } else {
            // Get the current timestamp
            timestamp = get_timestamp();

            // Log the flame event
            if (log_flame_event(timestamp, "YES") != 0) {
                fprintf(stderr, "Error logging flame event\n");
            }

            // Check for flame detection
            if (is_flame_detected(gpio_value)) {
                printf("FLAME DETECTED!\n");
            }
        }

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close the log file
    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

