#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdbool.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53

// Define the register addresses for acceleration data
#define X_LSB_REG 0x28
#define X_MSB_REG 0x29
#define Y_LSB_REG 0x2A
#define Y_MSB_REG 0x2B
#define Z_LSB_REG 0x2C
#define Z_MSB_REG 0x2D

// Define the log file name
#define LOG_FILE "vibration_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelerationData;

// Function prototypes
int i2c_open(const char *device);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
AccelerationData read_acceleration_data(int fd);
void log_data(FILE *fp, AccelerationData data);
void signal_handler(int sig);

// Function to open the I2C device
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// Function to read bytes from the I2C device
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }

    return 0;
}

// Function to write a byte to the I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;

    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the sensor
AccelerationData read_acceleration_data(int fd) {
    AccelerationData data;
    uint8_t lsb, msb;

    if (i2c_read_bytes(fd, X_LSB_REG, &lsb, 1) != 0) {
        fprintf(stderr, "Error reading X_LSB_REG\n");
        data.x = 0; // Set to 0 to avoid using garbage value
    } else if (i2c_read_bytes(fd, X_MSB_REG, &msb, 1) != 0) {
        fprintf(stderr, "Error reading X_MSB_REG\n");
        data.x = 0; // Set to 0 to avoid using garbage value
    } else {
        data.x = (int16_t)((msb << 8) | lsb);
    }

    if (i2c_read_bytes(fd, Y_LSB_REG, &lsb, 1) != 0) {
        fprintf(stderr, "Error reading Y_LSB_REG\n");
