#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value with error handling
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log data to file
void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

// Function to check for conveyor halt condition
void check_halt(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 1 && sensor2_state == 1) {
        printf("Conveyor Halt Condition Detected!\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Enable internal pull-ups
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor monitoring system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1) {
            // Error reading sensors, but continue running
            gpioDelay(50); // Small delay to avoid flooding the console with errors
            continue;
        }

        log_data(sensor1_state, sensor2_state);
        check_halt(sensor1_state, sensor2_state);

        gpioDelay(50); // 50 ms delay
    }

    // Clean up and exit
    gpioTerminate();
    printf("Conveyor monitoring system stopped.\n");
    return 0;
}

