#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// MMA8452Q I2C address
#define MMA8452Q_ADDR 0x1D

// MMA8452Q register addresses
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06

// Function prototypes
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_open(int dev, int addr);
int i2c_close(int fd);
int i2c_ioctl(int fd, int request, void *arg);
int verify_sensor_id(int fd);
int initialize_sensor(int fd);
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to read a block of data from the I2C device
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data block");
        return -1;
    }
    return 0;
}

// Function to write a byte to the I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int i2c_open(int dev, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", dev);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to close the I2C device
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close I2C device");
        return -1;
    }
    return 0;
}

// Function to perform I2C I/O using ioctl
int i2c_ioctl(int fd, int request, void *arg) {
    if (ioctl(fd, request, arg) < 0) {
        perror("Failed to perform I2C operation");
        return -1;
    }
    return 0;
}

// Function to verify the sensor ID
int verify_sensor_id(int fd) {
    uint8_t id;
    if (i2c_read_block(fd, 0x0D, &id, 1) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (id != 0x2A) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", id);
        return -1;
    }
    printf("Sensor ID verified: 0x%02X\n", id);
    return 0;
}

// Function to initialize the sensor
int initialize_sensor(int fd) {
    // Standby mode
    if (i2c_write_byte(fd, CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby)\n");
        return -1;
    }
    // 100 Hz data rate
    if (i2c_write_byte(fd, CTRL_REG2, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }
    // Active mode
    if (i2c_write_byte(fd, CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active)\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_block(fd, OUT_X_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]) >> 4;
    *y = (int16_t)((data[2] << 8) | data[3]) >> 4;
    *z = (int16_t)((data[4] << 8) | data[5]) >> 4;

    return 0;
}

// Function to calculate the tilt angle
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double sqrt_y_z = sqrt(y * y + z * z);
    return atan2(x, sqrt_y_z) * 180.0 / M_PI;
}

// Function to log data to a file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(1, MMA8452Q_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device, exiting\n");
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_fd) != 0) {
        fprintf(stderr, "Failed to verify sensor ID, exiting\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize sensor, exiting\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (1) {
        if (read_sensor_data(i2c_fd, &x, &y, &z) == 0) {
            double tilt_angle = calculate_tilt_angle(x, y, z);

            if (fabs(tilt_angle) > 45.0) {
                log_data(x, y, z);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        usleep(10000); // 10 ms delay
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2c_close(i2c_fd);
    fclose(log_file);

    return 0;
}

