// Function to read a block of data from the I2C device
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data block");
        return -1;
    }
    return 0;
}

// Function to write a byte to the I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int i2c_open(int dev, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", dev);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to close the I2C device
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close I2C device");
        return -1;
    }
    return 0;
}

// Function to perform I2C I/O using ioctl
int i2c_ioctl(int fd, int request, void *arg) {
    if (ioctl(fd, request, arg) < 0) {
        perror("Failed to perform I2C operation");
        return -1;
    }
    return 0;
}

// Function to verify the sensor ID
int verify_sensor_id(int fd) {
    uint8_t id;
    if (i2c_read_block(fd, 0x0D, &id, 1) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (id != 0x2A) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", id);
        return -1;
    }
    printf("Sensor ID verified: 0x%02X\n", id);
    return 0;
}

// Function to initialize the sensor
int initialize_sensor(int fd) {
    // Standby mode
    if (i2c_write_byte(fd, CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby)\n");
        return -1;
    }
    // 100 Hz data rate
    if (i2c_write_byte(fd, CTRL_REG2, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }
    // Active mode
    if (i2c_write_byte(fd, CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active)\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_block(fd, OUT_X_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]) >> 4;
    *y = (int16_t)((data[2] << 8) | data[3]) >> 4;
    *z = (int16_t)((data[4] << 8) | data[5]) >> 4;

    return 0;
}

// Function to calculate the tilt angle
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double sqrt_y_z = sqrt(y * y + z * z);
    return atan2(x, sqrt_y_z) * 180.0 / M_PI;
}

