        fprintf(stderr, "Error reading OUT_Z_H\n");
        data.z = 0; // Set to 0 to avoid garbage values
    } else {
        data.x = (int16_t)((x_h << 8) | x_l);
        data.y = (int16_t)((y_h << 8) | y_l);
        data.z = (int16_t)((z_h << 8) | z_l);
    }

    return data;
}

// Convert raw data to milliGauss
float convert_to_milliGauss(int16_t raw_value) {
    return (float)raw_value * 0.146; // Sensitivity: 0.146 mG/LSB
}

// Log data to file
void log_data(FILE *fp, magnetometer_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(fp, "%.6f,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written immediately
}

// Check for metal detector threshold
void check_threshold(magnetometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > THRESHOLD) {
        printf("Metal detector alert! Total field magnitude: %.2f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor verification failed\n");
        close(i2c_fd);
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    magnetometer_data_t data;
    while (!terminate) {
        // Read magnetometer data
        data = read_magnetometer_data(i2c_fd);

        // Convert to milliGauss
        float x_mG = convert_to_milliGauss(data.x);
        float y_mG = convert_to_milliGauss(data.y);
        float z_mG = convert_to_milliGauss(data.z);

        // Log data
        log_data(log_file, data);

        // Check for metal detector threshold
        check_threshold(data);

        // Delay for 10 Hz sampling rate
        usleep(SAMPLE_PERIOD_US);
    }

    // Clean up
    printf("Closing I2C device...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    printf("Closing log file...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Exiting.\n");
    return 0;
}

