// Function to read a register via SPI
int spi_read_register(int reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, len); // Fill with dummy data for reading

    gpioWrite(8, 1); // Set CE0 high
    int result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);
    gpioWrite(8, 0); // Set CE0 low

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to write a register via SPI
int spi_write_register(int reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    gpioWrite(8, 1); // Set CE0 high
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(8, 0); // Set CE0 low

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int read_acceleration_data(accelerometer_data_t *data) {
    uint8_t xdata[3], ydata[3], zdata[3];

    if (spi_read_register(0x08, xdata, 3) != 0) return -1;
    if (spi_read_register(0x0B, ydata, 3) != 0) return -1;
    if (spi_read_register(0x0E, zdata, 3) != 0) return -1;

    data->x = (int16_t)((xdata[0] << 12) | (xdata[1] << 4) | (xdata[2] >> 4));
    data->y = (int16_t)((ydata[0] << 12) | (ydata[1] << 4) | (ydata[2] >> 4));
