void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check sensor presence
    if (check_sensor_presence() != 0) {
        fprintf(stderr, "Sensor check failed, exiting\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    if (spi_write_register(POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // 1 ms delay

    if (spi_write_register(POWER_CTL, RUN_BIT | POWER_CTL) != 0) {
        fprintf(stderr, "Failed to set RUN bit\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait for STABLE bit to go high

    // Main loop
    while (!terminate) {
        accelerometer_data_t data;

        if (read_acceleration_data(&data) == 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

