int spi_read_register(int spi_handle, uint8_t address, uint16_t *data);
int spi_write_register(int spi_handle, uint8_t address, uint16_t data);
sensor_data_t read_sensor_data(int spi_handle);
void log_data(FILE *log_file, sensor_data_t data);
void signal_handler(int signal);

// Function to read a 16-bit value from the ADIS16362 via SPI
int spi_read_register(int spi_handle, uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message: address (MSB set) + dummy byte + register address
    tx_buf[0] = address | 0x80; // MSB set for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = address; // Register address

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the 16-bit data from the received bytes
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0; // Indicate success
}

// Function to write a 16-bit value to the ADIS16362 via SPI
int spi_write_register(int spi_handle, uint8_t address, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message: address (MSB clear) + data + dummy byte
    tx_buf[0] = address & 0x7F; // LSB clear for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to read sensor data from the ADIS16362
sensor_data_t read_sensor_data(int spi_handle) {
    sensor_data_t data;
    uint16_t gyro_data, accel_data;

    // Read gyroscope data
    if (spi_read_register(spi_handle, ADIS16362_X_GYRO, &gyro_data) != 0) {
        fprintf(stderr, "Error reading X_GYRO\n");
        data.gyro_x = 0.0; data.gyro_y = 0.0; data.gyro_z = 0.0;
    } else {
        data.gyro_x = (float)gyro_data * GYRO_SCALE;
    }

    if (spi_read_register(spi_handle, ADIS16362_Y_GYRO, &gyro_data) != 0) {
        fprintf(stderr, "Error reading Y_GYRO\n");
        data.gyro_y = 0.0; data.gyro_z = 0.0;
    } else {
        data.gyro_y = (float)gyro_data * GYRO_SCALE;
    }

    if (spi_read_register(spi_handle, ADIS16362_Z_GYRO, &gyro_data) != 0) {
        fprintf(stderr, "Error reading Z_GYRO\n");
        data.gyro_z = 0.0;
    } else {
        data.gyro_z = (float)gyro_data * GYRO_SCALE;
    }

    // Read accelerometer data
    if (spi_read_register(spi_handle, ADIS16362_X_ACCL, &accel_data) != 0) {
        fprintf(stderr, "Error reading X_ACCL\n");
        data.accel_x = 0.0; data.accel_y = 0.0; data.accel_z = 0.0;
    } else {
        data.accel_x = (float)accel_data * ACCL_SCALE;
    }

    if (spi_read_register(spi_handle, ADIS16362_Y_ACCL, &accel_data) != 0) {
        fprintf(stderr, "Error reading Y_ACCL\n");
        data.accel_y = 0.0; data.accel_z = 0.0;
    } else {
        data.accel_y = (float)accel_data * ACCL_SCALE;
    }

    if (spi_read_register(spi_handle, ADIS16362_Z_ACCL, &accel_data) != 0) {
        fprintf(stderr, "Error reading Z_ACCL\n");
        data.accel_z = 0.0;
    } else {
        data.accel_z = (float)accel_data * ACCL_SCALE;
    }

    return data;
}

// Function to log sensor data to a CSV file
void log_data(FILE *log_file, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    long nanoseconds = time(NULL) * 1000000000LL; // Get nanoseconds since epoch

    fprintf(log_file, "%s.%09ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, nanoseconds,
            data.gyro_x, data.gyro_y, data.gyro_z,
            data.accel_x, data.accel_y, data.accel_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data(spi_handle);
        log_data(log_file, data);
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

