#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_CHIP 4
#define GPIO_LINE 17

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    int gpio_line = GPIO_LINE;
    int pigpio_init_result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Open GPIO chip
    int chip_result = gpiod_chip_open_by_name("gpiochip4");
    if (chip_result < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %d\n", chip_result);
        gpioTerminate();
        return 1;
    }

    // Open GPIO line
    int line_result = gpiod_chip_open_by_name("gpiochip4") ->line_open(GPIO_LINE);
    if (line_result < 0) {
        fprintf(stderr, "Failed to open GPIO line: %d\n", line_result);
        gpiod_chip_close(chip_result);
        gpioTerminate();
        return 1;
    }

    // Request GPIO line for input
    int request_result = gpiod_line_request_input(line_result, "obstacle_sensor");
    if (request_result < 0) {
        fprintf(stderr, "Failed to request GPIO line for input: %d\n", request_result);
        gpiod_line_close(line_result);
        gpiod_chip_close(chip_result);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int value = gpiod_line_get_value(line_result);
        if (value < 0) {
            fprintf(stderr, "Failed to get GPIO line value: %d\n", value);
            break; // Exit loop on error
        }

        if (value == 0) { // Obstacle detected (LOW)
            printf("Obstacle detected! Starting self-parking sequence...\n");
            time_t start_time = time(NULL);
            while (time(NULL) - start_time < 5) { // Simulate 5 seconds
                printf("Self-parking sequence: Moving forward...\n");
                gpioDelay(1000000); // 1 second delay
            }
            printf("Self-parking sequence completed.\n");
        } else {
            gpioDelay(1000000); // Poll every 1 second
        }
    }

    // Clean up
    gpiod_line_set_value(line_result, 1); // Set to HIGH to release the line
    gpiod_line_request_output(line_result, 1); // Request output to release the line
    gpiod_line_close(line_result);
    gpiod_chip_close(chip_result);
    gpioTerminate();

    return 0;
}

