#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIOCHIP 0
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    int status;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Request GPIO lines for input
    status = gpiod_line_request_get_values(GPIOCHIP, SENSOR1_PIN, &SENSOR1_LINE, &SENSOR2_LINE);
    if (status < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %d\n", status);
        gpioTerminate();
        return 1;
    }

    printf("Collision avoidance system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        int sensor1_value = gpiod_line_get_value(SENSOR1_LINE);
        int sensor2_value = gpiod_line_get_value(SENSOR2_LINE);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values: %d, %d\n", sensor1_value, sensor2_value);
            // Attempt to recover by re-requesting the lines
            status = gpiod_line_request_get_values(GPIOCHIP, SENSOR1_PIN, &SENSOR1_LINE, &SENSOR2_LINE);
            if (status < 0) {
                fprintf(stderr, "Failed to re-request GPIO lines: %d\n", status);
                running = 0; // Exit loop if re-request fails
                break;
            }
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log obstacle detection status
        if (sensor1_value == 0 || sensor2_value == 0) {
            printf("%s - Obstacle detected! Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
        } else {
            printf("%s - No obstacle detected. Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up resources
    gpiod_line_release(SENSOR1_LINE);
    gpiod_line_release(SENSOR2_LINE);
    gpioTerminate();

    return 0;
}

