#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// GPIO Configuration
#define CS_PIN 8

// ADIS16266 Register Addresses
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08

// Scaling factor for angular rate (deg/s/LSB)
#define SCALE_FACTOR 0.02

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the SPI interface
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the GPIO line for CS
int gpio_init() {
    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", CS_PIN);
        return -1;
    }
    gpioWrite(CS_PIN, 1); // Set CS high initially
    return 0;
}

// Function to write a byte to the ADIS16266
int adis16266_write_byte(uint8_t reg_addr, uint8_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for write operation
    tx_buf[1] = data;
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deassert CS

    if (result != 0) {
        fprintf(stderr, "Error during write operation: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a byte from the ADIS16266
int adis16266_read_byte(uint8_t reg_addr, uint8_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deassert CS

    if (result != 0) {
        fprintf(stderr, "Error during read operation: %d\n", result);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// Function to initialize the ADIS16266
int adis16266_init() {
    // Enable data ready mode (MSB first)
    if (adis16266_write_byte(0x24, 0x00) != 0) {
        fprintf(stderr, "Error initializing ADIS16266\n");
        return -1;
    }
    return 0;
}

// Function to read the angular rate data from the ADIS16266
int adis16266_read_angular_rate(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_data, y_data, z_data;

    // Read X-axis data
    if (adis16266_read_byte(X_GYRO_REG, &x_data) != 0) return -1;
    if (adis16266_read_byte(X_GYRO_REG + 1, &z_data) != 0) return -1;

    // Read Y-axis data
    if (adis16266_read_byte(Y_GYRO_REG, &y_data) != 0) return -1;
    if (adis16266_read_byte(Y_GYRO_REG + 1, &z_data) != 0) return -1;

    // Read Z-axis data
    if (adis16266_read_byte(Z_GYRO_REG, &x_data) != 0) return -1;
    if (adis16266_read_byte(Z_GYRO_REG + 1, &z_data) != 0) return -1;

    // Combine the two bytes into a 16-bit signed integer
    *x = (int16_t)((x_data << 8) | z_data);
    *y = (int16_t)((y_data << 8) | z_data);
    *z = (int16_t)((x_data << 8) | z_data);

    return 0;
}

// Function to convert raw data to angular rates
void convert_to_angular_rates(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_deg, float *y_deg, float *z_deg) {
    *x_deg = (float)raw_x * SCALE_FACTOR;
    *y_deg = (float)raw_y * SCALE_FACTOR;
    *z_deg = (float)raw_z * SCALE_FACTOR;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for CS
    if (gpio_init() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16266
    if (adis16266_init() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_deg, y_deg, z_deg;

    // Main loop
    while (!terminate) {
        // Read angular rate data
        if (adis16266_read_angular_rate(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to angular rates
            convert_to_angular_rates(raw_x, raw_y, raw_z, &x_deg, &y_deg, &z_deg);

            // Log the angular rates
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_deg, y_deg, z_deg);
        } else {
            fprintf(stderr, "Error reading angular rate data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    spiClose(spi_handle);
    gpioWrite(CS_PIN, 1); // Deassert CS
    gpioTerminate();

    return 0;
}

