#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Gyroscope sensitivity (mdps/LSB)
#define GYRO_SENSITIVITY 8.75

// Acceleration sensitivity (mg/LSB)
#define ACCEL_SENSITIVITY 0.061

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr()
{
    // Check WHO_AM_I register
    char who_am_i;
    if (i2cReadI2CBlockData(i2c_handle, 0x0F, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: Expected 0x6B, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42) != 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register: %s\n", strerror(errno));
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x42) != 0) {
        fprintf(stderr, "Error writing to CTRL2_G register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_lsm6dsr(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z)
{
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read 12 bytes starting from OUTX_L_G (0x22)
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) != 12) {
        fprintf(stderr, "Error reading accelerometer/gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for accelerometer and gyroscope
    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    raw_gyro_x  = (int16_t)((buffer[7] << 8) | buffer[6]);
    raw_gyro_y  = (int16_t)((buffer[9] << 8) | buffer[8]);
    raw_gyro_z  = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to physical units
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY / 1000.0;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY / 1000.0;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY / 1000.0;
    *gyro_x  = (float)raw_gyro_x * GYRO_SENSITIVITY / 1000.0;
    *gyro_y  = (float)raw_gyro_y * GYRO_SENSITIVITY / 1000.0;
    *gyro_z  = (float)raw_gyro_z * GYRO_SENSITIVITY / 1000.0;

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the LSM6DSR sensor
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        // Read accelerometer and gyroscope data
        if (read_lsm6dsr(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the data
            printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g | Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Exiting.\n");
            break;
        }

        // Sleep for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

