#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 registers
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

// Function prototypes
int init_fxos8700(int i2c_handle);
int read_fxos8700_data(int i2c_handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z);
void log_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z);
void signal_handler(int signal);

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700(int i2c_handle) {
    int status;

    // Set to active mode, hybrid
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01); // Active mode, hybrid
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set to active mode, hybrid
    status = i2cWriteByteData(i2c_handle, CTRL_REG2, 0x02); // Active mode, hybrid
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    // Set magnetometer to active mode
    status = i2cWriteByteData(i2c_handle, M_CTRL_REG1, 0x1F); // Active mode
    if (status < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set magnetometer to active mode
    status = i2cWriteByteData(i2c_handle, M_CTRL_REG2, 0x00); // Active mode
    if (status < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read data from the FXOS8700 sensor
int read_fxos8700_data(int i2c_handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int status;

    // Read 12 bytes from OUT_X_MSB
    status = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 12);
    if (status < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    // Combine bytes to form 14-bit accelerometer data
    *accel_x = (int16_t)((buffer[0] << 6) | (buffer[1] >> 2));
    *accel_y = (int16_t)((buffer[2] << 6) | (buffer[3] >> 2));
    *accel_z = (int16_t)((buffer[4] << 6) | (buffer[5] >> 2));

    // Combine bytes to form 16-bit magnetometer data
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

// Function to log the sensor data
void log_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z) {
    printf("Accel: X=%6d, Y=%6d, Z=%6d | Mag: X=%6d, Y=%6d, Z=%6d\n",
           accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
}

int main() {
    int status;
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0); // Bus 1, address 0x1D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, 0x0D);
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%X, expected 0xC7\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing FXOS8700 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (read_fxos8700_data(i2c_handle, &accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            // Log the data
            log_data(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

