#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define DATA_RATE 100 // Hz
#define SAMPLE_RATE (1000000 / DATA_RATE) // microseconds
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_setup(const char *device);
int adxl345_read_register(int fd, uint8_t reg);
int adxl345_write_register(int fd, uint8_t reg, uint8_t value);
int adxl345_read_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angles(int16_t x, int16_t y, int16_t z);
void log_event(const char *message);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int i2c_setup(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a single byte from an ADXL345 register
int adxl345_read_register(int fd, uint8_t reg) {
    uint8_t value;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, &value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to an ADXL345 register
int adxl345_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int adxl345_read_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate tilt angles using atan2
double calculate_tilt_angles(int16_t x, int16_t y, int16_t z) {
    double angle_x = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
    double angle_y = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;
    return angle_x; // Return only the X-axis tilt angle
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // ADXL345 Initialization
    if (adxl345_write_register(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "ADXL345 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    double tilt_angle;

    // Main loop
    while (program_running) {
        if (adxl345_read_data(i2c_fd, &x, &y, &z) == 0) {
            tilt_angle = calculate_tilt_angles(x, y, z);

            // Check for tilt threshold
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                char message[128];
                snprintf(message, sizeof(message), "Tilt angle: %.2f degrees", tilt_angle);
                log_event(message);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        usleep(SAMPLE_RATE); // 100 ms delay
    }

    // Clean up
    close(i2c_fd);
    printf("Program terminated.\n");
    return 0;
}

