#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_MS 5000
#define ALERT_WINDOW_MS 1000

volatile int high_count = 0;
volatile int alert_triggered = 0;

void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int validate_threshold(int threshold) {
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);

    if (validate_threshold(threshold) != 0) {
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_alert_time = 0;

    while (1) {
        // Sample GPIO17 every 1 ms
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds

        // Count high readings in a 5-second window
        int current_high_count = 0;
        for (int i = 0; i < ALERT_WINDOW_MS; i += SAMPLE_INTERVAL_MS) {
            if (gpioRead(GPIO_PIN) == 1) {
                current_high_count++;
            }
        }

        if (current_high_count > high_count) {
            high_count = current_high_count;
        }

        // Check if the threshold has been exceeded
        if (high_count >= threshold) {
            if (!alert_triggered) {
                time_t now = time(NULL);
                if (difftime(now, last_alert_time) >= 1) {
                    printf("%ld: ALERT - Threshold exceeded!\n", now);
                    alert_triggered = 1;
                }
            }
        } else {
            alert_triggered = 0;
        }

        last_alert_time = time(NULL);

        // Print status line
        printf("%ld: Status - High Count: %d, Alert: %s\n", time(NULL), high_count, alert_triggered ? "ALERT" : "NORMAL");

        // Reset high count for the next window
        high_count = 0;
    }

    gpioTerminate();
    return 0;
}

