#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>
#include <sys/file.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_PIN_A 17
#define GPIO_PIN_B 27
#define NUM_DIGITS 6
#define CODE_MIN 100000
#define CODE_MAX 999999
#define UNLOCK_DURATION_MS 5000
#define LOG_FILE "access_log.txt"

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_a = NULL;
static struct gpiod_line *line_b = NULL;
static FILE *log_file = NULL;

// Function to generate a random 6-digit code
int generate_code() {
    int code = (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN;
    return code;
}

// Function to set the GPIO output level
int set_gpio_output(int pin, int level) {
    if (gpiod_line_set_value(line_a, level) < 0) {
        fprintf(stderr, "Error setting GPIO%d value: %s\n", pin, strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(line_b, level) < 0) {
        fprintf(stderr, "Error setting GPIO%d value: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to unlock the door
int unlock_door() {
    if (set_gpio_output(GPIO_PIN_A, 1) < 0) return -1;
    if (set_gpio_output(GPIO_PIN_B, 0) < 0) return -1;
    return 0;
}

// Function to lock the door
int lock_door() {
    if (set_gpio_output(GPIO_PIN_A, 0) < 0) return -1;
    if (set_gpio_output(GPIO_PIN_B, 0) < 0) return -1;
    return 0;
}

// Function to log the access event
int log_access(int code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to handle the access control logic
int access_control(int code) {
    if (code == (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN) {
        if (unlock_door() == 0) {
            printf("Access granted.\n");
            if (lock_door() == 0) {
                if (log_access(code) == 0) {
                    printf("Access logged.\n");
                } else {
                    fprintf(stderr, "Error logging access.\n");
                }
            } else {
                fprintf(stderr, "Error locking door.\n");
            }
        } else {
