#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE 0x21
#define MAX_RETRIES 3

// Global variables for cleanup
int i2c_fd = -1;
FILE *log_file = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to write a command to the BH1750
int write_command(int fd, unsigned char command) {
    unsigned char buf[2];
    buf[0] = 0x00; // Bus address
    buf[1] = command;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the BH1750
int read_data(int fd, unsigned char *data, int count) {
    if (write(fd, NULL, 0) != 0) {
        perror("Failed to write to I2C device for reading");
        return -1;
    }

    if (read(fd, data, count) != count) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to calculate illuminance in lux
float calculate_lux(unsigned int raw_value) {
    return (float)raw_value / 1.2;
}

// Function to log data to a file
int log_data(FILE *fp, float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Lux: %.2f\n", timestamp, lux_value) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    unsigned char data[2];
    unsigned int raw_value;
    float lux_value;
    int retries;

    // Main loop
    while (1) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            // Send One-Time High-Resolution Mode 2 command
            if (write_command(i2c_fd, ONE_TIME_HIGH_RES_MODE) == 0) {
                // Wait for conversion (at least 180ms)
                usleep(180000); // 180ms

                // Read data from the sensor
                if (read_data(i2c_fd, data, 2) == 0) {
                    // Combine the two bytes into a 16-bit unsigned integer
                    raw_value = (data[0] << 8) | data[1];

                    // Calculate illuminance
                    lux_value = calculate_lux(raw_value);

                    // Log the data
                    if (log_data(log_file, lux_value) != 0) {
                        fprintf(stderr, "Error logging data, but continuing...\n");
                    }

                    printf("Lux: %.2f\n", lux_value);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Error reading data, retry %d\n", retries + 1);
                }
            } else {
                fprintf(stderr, "Error writing command, retry %d\n", retries + 1);
            }
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor after %d retries, skipping this iteration.\n", MAX_RETRIES);
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup (should not reach here normally due to the signal handler)
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

