#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PORT 12345
#define MAX_CLIENTS 5
#define MAX_MESSAGE_LENGTH 1024
#define LOG_FILE "frequency_log.txt"

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTER_CONFIG 0x5E
#define MPR121_ECR 0x2B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D

// Global variables
int i2c_handle;
int server_fd;
struct sockaddr_in address;
int addrlen = sizeof(address);
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(int *touch_data);
int map_touch_to_frequency(int touch_data);
int play_tone(int frequency);
int log_frequency(int frequency);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize MPR121
int init_mpr121() {
    // Reset the MPR121
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure Electrode Configuration
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x0C) < 0) { // Enable all 12 electrodes
        fprintf(stderr, "Error: Failed to configure electrode configuration\n");
        return -1;
    }

    // Configure Filter Configuration
    if (i2cWriteByteData(i2c_handle, MPR121_FILTER_CONFIG, 0x01) < 0) { // Set filter to 1
        fprintf(stderr, "Error: Failed to configure filter configuration\n");
        return -1;
    }

    // Enable Electrode 0
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enable electrode 0\n");
        return -1;
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    *touch_data = ((int)buf[1] << 8) | (int)buf[0];
    return 0;
}

// Map touch data to frequency
int map_touch_to_frequency(int touch_data) {
    // Simple mapping: higher touch data -> higher frequency
    // You can adjust the mapping based on your needs
    int frequency = 440 + (touch_data * 100); // Map 0-127 to 440-1270 Hz
    if (frequency < 220) frequency = 220;
    if (frequency > 880) frequency = 880;
    return frequency;
}

// Play tone using PWM
int play_tone(int frequency) {
    if (frequency <= 0) return -1; // Invalid frequency

    // Calculate period and duty cycle
    double period = 1000000.0 / frequency; // Period in microseconds
    double duty_cycle = 0.5; // 50% duty cycle

    // Calculate PWM range
    int pwm_range = (int)(duty_cycle * period);

    // Set PWM range
    gpioSetPWMrange(GPIO_PWM, pwm_range);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PWM, frequency);

    // Set PWM duty cycle
    gpioPWM(GPIO_PWM, pwm_range / 2); // 50% duty cycle

    return 0;
}

// Log frequency to file
int log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as PWM output
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Error: Socket creation failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("Error: setsockopt");
        close(server_fd);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address and port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error: Socket bind failed");
        close(server_fd);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("Error: Socket listen failed");
        close(server_fd);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

