        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            set_led_brightness(GPIO_LED, (int)(magnitude * 1000.0 / 1000.0)); // Scale magnitude to 0-1000 for PWM
            log_data(magnitude);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, skipping this sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    set_led_brightness(GPIO_LED, 0); // Turn off LED
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

