#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D registers
#define CTRL_REG1 0x20
#define OUT_X_L_A 0x28
#define INT1_CFG 0x5E
#define INT1_THS 0x5B
#define INT1_DURATION 0x5C

// GPIO pin for interrupt
#define INT_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *int_line = NULL;
static struct gpiod_line *int_line_free = NULL;
static struct gpiod_chip *int_chip = NULL;
static volatile sig_atomic_t running = 1;

// Data structure for acceleration samples
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_sample_t;

// Circular buffer structure
typedef struct {
    acceleration_sample_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global circular buffer
static circular_buffer_t buffer;

// Function prototypes
int init_i2c(int addr);
int init_lsm303d(int fd);
int init_gpio(int pin);
int configure_interrupt(int line, int config);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void buffer_add(circular_buffer_t *cb, acceleration_sample_t sample);
int buffer_get(circular_buffer_t *cb, int index, acceleration_sample_t *sample);
void print_buffer(circular_buffer_t *cb, int n);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int sig);
void cleanup(void);

// I2C initialization function
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// LSM303D initialization function
int init_lsm303d(int fd) {
    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (i2c_smbus_read_byte_data(fd, 0x0F) < 0) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }
    who_am_i = i2c_smbus_read_byte_data(fd, 0x0F);
    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2c_smbus_write_byte_data(fd, CTRL_REG1, 0x57) < 0) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // Configure full-scale range
    if (i2c_smbus_write_byte_data(fd, CTRL_REG4, 0x00) < 0) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    return 0;
}

// GPIO initialization function
int init_gpio(int pin) {
    int line = gpiod_chip_get_line(int_chip, pin);
    if (line < 0) {
        perror("Error getting GPIO line");
        return -1;
    }

    int_line = line;
    int_line_free = line;

    if (gpiod_line_request_output(line, "int_line", 0) < 0) {
        perror("Error requesting GPIO line as output");
        return -1;
    }

    return 0;
}

// Interrupt configuration function
int configure_interrupt(int line, int config) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line to low");
        return -1;
    }

    if (gpiod_line_set_value(line, config) < 0) {
        perror("Error setting GPIO line to high");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (i2c_smbus_read_i2c_block_data(fd, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        perror("Error reading acceleration data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Circular buffer add function
void buffer_add(circular_buffer_t *cb, acceleration_sample_t sample) {
    cb->buffer[cb->head] = sample;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Circular buffer get function
int buffer_get(circular_buffer_t *cb, int index, acceleration_sample_t *sample) {
    if (index < 0 || index >= cb->count) {
        return -1; // Invalid index
    }
    int actual_index = (cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    *sample = cb->buffer[actual_index];
    return 0;
}

// Print buffer function
void print_buffer(circular_buffer_t *cb, int n) {
    printf("\n--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        acceleration_sample_t sample;
        if (buffer_get(cb, i, &sample) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%09ld, %d, %d, %d\n", ts.tv_sec, ts.tv_nsec, sample.x, sample.y, sample.z);
        } else {
            fprintf(stderr, "Error getting sample %d\n", i);
        }
    }
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld - Interrupt triggered!\n", ts.tv_sec, ts.tv_nsec);
    print_buffer(&buffer, BUFFER_SIZE);
}

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function
void cleanup(void) {
    if (int_line) {
        gpiod_line_release(int_line);
    }
    if (int_chip) {
        gpiod_chip_close(int_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (int_line_free) {
        gpiod_line_release(int_line_free);
    }
    if (int_chip) {
        gpiod_chip_close(int_chip);
    }
}

int main() {
    // Initialize GPIO interrupt line
    if (init_gpio(INT_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(LSM303D_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d(i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    if (gpiod_line_request_trigger(int_line, 1, 0, interrupt_handler) < 0) {
        perror("Error requesting interrupt handler");
        cleanup();
        return 1;
    }

    int16_t x, y, z;
    struct timespec ts;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Add sample to circular buffer
            acceleration_sample_t sample;
            sample.timestamp = ts;
            sample.x = x;
            sample.y = y;
            sample.z = z;
            buffer_add(&buffer, sample);

            // Print timestamp and acceleration data
            printf("%ld.%09ld, %d, %d, %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data, skipping sample\n");
        }

        // Sleep for 10 ms (100 Hz)
        usleep(10000);
    }

    // Disable accelerometer
    if (configure_interrupt(int_line, 0) < 0) {
        fprintf(stderr, "Failed to disable interrupt\n");
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

