#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define UART_PORT1 "/dev/serial0"
#define UART_PORT2 "/dev/serial1"
#define BAUD_RATE 9600
#define CODE_LENGTH 6
#define CODE_EXPECTED "123456"
#define UNLOCK_DURATION 2 // seconds

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int read_serial_port(int fd, char *buffer, int max_length) {
    ssize_t bytes_read = read(fd, buffer, max_length - 1);
    if (bytes_read < 0) {
        perror("Error reading from serial port");
        return -1;
    } else if (bytes_read == 0) {
        // Timeout or no data received
        return 0;
    }
    buffer[bytes_read] = '\0';
    return bytes_read;
}

int validate_code(const char *code) {
    return (strcmp(code, CODE_EXPECTED) == 0);
}

int unlock_doors(int gpio17, int gpio27, int duration_seconds) {
    gpioWrite(gpio17, 1); // Activate lock 1
    gpioWrite(gpio27, 1); // Activate lock 2
    gpioDelay(duration_seconds * 1000000); // Delay in microseconds
    gpioWrite(gpio17, 0); // Deactivate lock 1
    gpioWrite(gpio27, 0); // Deactivate lock 2
    return 0;
}

int main() {
    int uart_fd1, uart_fd2;
    char input_buffer1[CODE_LENGTH + 1], input_buffer2[CODE_LENGTH + 1];
    int code1_found, code2_found;
    int i;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    gpioWrite(LOCK1_GPIO, 0); // Ensure locks are initially locked
    gpioWrite(LOCK2_GPIO, 0);

    // Open serial ports
    uart_fd1 = open(UART_PORT1, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd1 == -1) {
        perror("Error opening serial port 1");
        gpioTerminate();
        return 1;
    }

    uart_fd2 = open(UART_PORT2, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd2 == -1) {
        perror("Error opening serial port 2");
        close(uart_fd1);
        gpioTerminate();
        return 1;
    }

    // Configure serial port settings
    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(uart_fd1, &tty) != 0) {
        perror("Error getting serial port attributes");
        close(uart_fd1);
        close(uart_fd2);
        gpioTerminate();
        return 1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(uart_fd1, TCSANOW, &tty) != 0) {
        perror("Error setting serial port attributes");
        close(uart_fd1);
        close(uart_fd2);
        gpioTerminate();
        return 1;
    }

    memset(&tty, 0, sizeof(tty));
    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(uart_fd2, TCSANOW, &tty) != 0) {
        perror("Error setting serial port attributes");
        close(uart_fd1);
        close(uart_fd2);
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read code from UART port 1
        memset(input_buffer1, 0, sizeof(input_buffer1));
        code1_found = 0;
        while (1) {
            int bytes_read = read_serial_port(uart_fd1, input_buffer1, sizeof(input_buffer1));
            if (bytes_read > 0) {
                if (validate_code(input_buffer1)) {
                    code1_found = 1;
                    break;
                }
            } else if (bytes_read < 0) {
                fprintf(stderr, "Error reading from UART port 1, retrying...\n");
                gpioDelay(100000); // Wait 0.1 seconds before retrying
                continue;
            } else {
                // Timeout or no data received
                break;
            }
        }

        // Read code from UART port 2
        memset(input_buffer2, 0, sizeof(input_buffer2));
        code2_found = 0;
        while (1) {
            int bytes_read = read_serial_port(uart_fd2, input_buffer2, sizeof(input_buffer2));
            if (bytes_read > 0) {
                if (validate_code(input_buffer2)) {
                    code2_found = 1;
                    break;
                }
            } else if (bytes_read < 0) {
                fprintf(stderr, "Error reading from UART port 2, retrying...\n");
                gpioDelay(100000); // Wait 0.1 seconds before retrying
                continue;
            } else {
                // Timeout or no data received
                break;
            }
        }

        // Check if both codes match
        if (code1_found && code2_found && strcmp(input_buffer1, input_buffer2) == 0) {
            printf("Codes matched! Unlocking doors.\n");
            unlock_doors(LOCK1_GPIO, LOCK2_GPIO, UNLOCK_DURATION);
            printf("Doors locked.\n");
        } else {
            fprintf(stderr, "Invalid code or codes do not match. Doors remain locked.\n");
        }

        gpioDelay(100000); // Check every 0.1 seconds
    }

    // Clean up
    close(uart_fd1);
    close(uart_fd2);
    gpioWrite(LOCK1_GPIO, 0); // Ensure locks are locked on exit
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

