#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

// Configuration
#define PIR_GPIO 4
#define RELAY_GPIO 17
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "/var/log/door_strike.log"
#define DEBOUNCE_DELAY_MS 50
#define FAILSAFE_TIMEOUT_SEC 10

// Global variables
static volatile int running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static int server_fd = -1;

// Function prototypes
int gpiochip_open(const char *chipname);
int gpiochip_close(struct gpiod_chip *chip);
int gpiochip_get_line(struct gpiod_chip *chip, int index);
int gpiochip_request_line(struct gpiod_chip *chip, int index, const char *consumer);
int gpiochip_release_line(struct gpiod_chip *chip, int index);
int gpiochip_set_consumer(struct gpiod_line *line, const char *consumer);
int gpiochip_get_consumer(struct gpiod_line *line);
int gpiochip_get_value(struct gpiod_line *line);
int gpiochip_set_value(struct gpiod_line *line, int value);
int pir_read();
int relay_control(int state);
int send_data(int motion_detected, int relay_state);
void log_message(int priority, const char *message);
void signal_handler(int sig);
void cleanup();

// GPIO functions
int gpiochip_open(const char *chipname) {
    int fd = open(chipname, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s: %s", chipname, strerror(errno));
        return -1;
    }
    return fd;
}

int gpiochip_close(struct gpiod_chip *chip) {
    if (chip) {
        if (gpiod_chip_close(chip) < 0) {
            syslog(LOG_ERR, "Failed to close GPIO chip: %s", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int gpiochip_get_line(struct gpiod_chip *chip, int index) {
    if (index < 0 || index >= gpiod_chip_get_linecount(chip)) {
        syslog(LOG_ERR, "Invalid GPIO line index: %d", index);
        return -1;
    }
    return gpiod_chip_get_line(chip, index);
}

int gpiochip_request_line(struct gpiod_chip *chip, int index, const char *consumer) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, index);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line %d", index);
        return -1;
    }

    int ret = gpiod_line_request(line, consumer, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request line %d: %s", index, strerror(errno));
        return -1;
    }
    return 0;
}

int gpiochip_release_line(struct gpiod_chip *chip, int index) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, index);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line %d", index);
        return -1;
    }
    return gpiod_line_release(line);
}

int gpiochip_set_consumer(struct gpiod_line *line, const char *consumer) {
    return gpiod_line_set_consumer(line, consumer);
}

int gpiochip_get_consumer(struct gpiod_line *line) {
    return gpiod_line_get_consumer(line);
}

int gpiochip_get_value(struct gpiod_line *line) {
    return gpiod_line_get_value(line);
}

int gpiochip_set_value(struct gpiod_line *line, int value) {
    return gpiod_line_set_value(line, value);
}

// PIR sensor functions
int pir_read() {
    return gpiochip_get_value(pir_line);
}

// Relay control functions
int relay_control(int state) {
    return gpiochip_set_value(relay_line, state);
}

// Data transmission functions
int send_data(int motion_detected, int relay_state) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid server IP address");
        return -1;
    }

    if (send(server_fd, &motion_detected, sizeof(motion_detected), 0) < 0) {
        syslog(LOG_ERR, "Failed to send motion data: %s", strerror(errno));
        return -1;
    }

