#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file path
#define LOG_FILE "/var/log/irrigation_system.log"

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Define the activation duration (in seconds)
#define ACTIVATION_DURATION 300

// Define the pause duration (in seconds)
#define PAUSE_DURATION 60

// Define the number of relays
#define NUM_RELAYS 4

// Define the state machine states
enum {
    STATE_IDLE,
    STATE_ACTIVATING,
    STATE_PAUSED,
    STATE_DEACTIVATING
};

// Global variables
volatile sig_atomic_t program_running = 1;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void log_message(int priority, const char *message);
void signal_handler(int signal);
void *timer_task(void *arg);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void pause_relay(int relay_pin);
void relay_state_change(int relay_pin, int state);

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    pthread_mutex_lock(&log_mutex);
    syslog(priority, message);
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Timer task function
void *timer_task(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (program_running) {
        // Check if it's time to activate the next relay
        if (current_relay_state == STATE_ACTIVATING) {
            activate_relay(RELAY1_PIN);
            relay_state_change(RELAY1_PIN, 0); // Deactivate relay after activation
            current_relay_state = STATE_PAUSED;
        } else if (current_relay_state == STATE_PAUSED) {
            // Wait for the pause duration
            gpioDelay(PAUSE_DURATION * 1000000); // Convert seconds to microseconds
            current_relay_state = STATE_ACTIVATING;
        } else if (current_relay_state == STATE_DEACTIVATING) {
            deactivate_relay(RELAY2_PIN);
            relay_state_change(RELAY2_PIN, 0); // Deactivate relay after deactivation
            current_relay_state = STATE_PAUSED;
        } else {
            // Wait for the activation duration
            gpioDelay(ACTIVATION_DURATION * 1000000); // Convert seconds to microseconds
            current_relay_state = STATE_PAUSED;
        }
    }
    return NULL;
}

// Function to activate a relay
void activate_relay(int relay_pin) {
    int result;
    char message[100];

    result = gpioWrite(relay_pin, 0); // Set the pin to LOW (active-LOW)
    if (result != 0) {
        snprintf(message, sizeof(message), "Failed to activate relay on pin %d", relay_pin);
        log_message(LOG_ERR, message);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    snprintf(message, sizeof(message), "Activated relay on pin %d", relay_pin);
    log_message(LOG_INFO, message);
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    int result;
    char message[100];

    result = gpioWrite(relay_pin, 1); // Set the pin to HIGH (active-LOW)
    if (result != 0) {
        snprintf(message, sizeof(message), "Failed to deactivate relay on pin %d", relay_pin);
        log_message(LOG_ERR, message);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    snprintf(message, sizeof(message), "Deactivated relay on pin %d", relay_pin);
    log_message(LOG_INFO, message);
}

// Function to pause a relay
void pause_relay(int relay_pin) {
    int result;
    char message[100];

    result = gpioWrite(relay_pin, 1); // Set the pin to HIGH (active-LOW)
    if (result != 0) {
        snprintf(message, sizeof(message), "Failed to pause relay on pin %d", relay_pin);
        log_message(LOG_ERR, message);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    snprintf(message, sizeof(message), "Paused relay on pin %d", relay_pin);
    log_message(LOG_INFO, message);
}

// Function to log relay state changes
void relay_state_change(int relay_pin, int state) {
    char message[100];
    pthread_mutex_lock(&log_mutex);
    snprintf(message, sizeof(message), "Relay on pin %d is now %s", relay_pin, state ? "ON" : "OFF");
    log_message(LOG_INFO, message);
    pthread_mutex_unlock(&log_mutex);
}

int main() {
    int i;
    pthread_t timer_thread;
    struct sigaction sa;

    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction (SIGINT)");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction (SIGTERM)");
        closelog();
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial relay states to HIGH (OFF)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Set up the timer
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_task, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set up timer");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Start the timer thread
    if (pthread_create(&timer_thread, NULL, timer_task, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create timer thread");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    current_relay_state = STATE_IDLE;
    while (program_running) {
        // Check for termination signal
        if (pthread_kill(timer_thread, SIGINT) == 0) {
            log_message(LOG_INFO, "Received SIGINT, shutting down...");
            program_running = 0;
        } else {
            log_message(LOG_ERR, "Failed to send SIGINT to timer thread");
        }

        // Check if it's time to activate the next relay
        if (current_relay_state == STATE_ACTIVATING) {
            activate_relay(RELAY1_PIN);
            relay_state_change(RELAY1_PIN, 0); // Deactivate relay after activation
            current_relay_state = STATE_PAUSED;
        } else if (current_relay_state == STATE_PAUSED) {
            // Wait for the pause duration
            gpioDelay(PAUSE_DURATION * 1000000); // Convert seconds to microseconds
            current_relay_state = STATE_ACTIVATING;
        } else if (current_relay_state == STATE_DEACTIVATING) {
            deactivate_relay(RELAY2_PIN);
            relay_state_change(RELAY2_PIN, 0); // Deactivate relay after deactivation
            current_relay_state = STATE_PAUSED;
        } else {
            // Wait for the activation duration
            gpioDelay(ACTIVATION_DURATION * 1000000); // Convert seconds to microseconds
            current_relay_state = STATE_PAUSED;
        }
    }

    // Clean up
    pthread_join(timer_thread, NULL);
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);
    gpioTerminate();
    closelog();

    return 0;
}

