#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <stdbool.h>

// MPU6050 Registers
#define MPU6050_ADDR_1 0x68
#define MPU6050_ADDR_2 0x69
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// Configuration
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define BUFFER_SIZE 100
#define TIMER_ID 1

// Global variables
static int i2c_fd = -1;
static int mpu6050_address = MPU6050_ADDR_1;
static volatile sig_atomic_t keep_running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Function prototypes
int init_mpu6050(int i2c_fd, int address);
int read_mpu6050_data(int i2c_fd, int address, float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z);
void get_latest_data(circular_buffer_t *buffer, float *x, float *y, float *z);
void signal_handler(int sig);
int export_i2c(int bus, int addr);
int unexport_i2c(int bus, int addr);
int set_i2c_slave(int fd, int addr);
int open_i2c_device(int bus, int addr);
int close_i2c_device(int fd);

// Function to initialize the MPU6050
int init_mpu6050(int i2c_fd, int address) {
    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02x\n", address);
        return -1;
    }

    // Wake up the MPU6050
    if (write(i2c_fd, &PWR_MGMT_1, 1) != 1) {
        fprintf(stderr, "Error: Could not write to PWR_MGMT_1 register\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (write(i2c_fd, &ACCEL_CONFIG, 1) != 1) {
        fprintf(stderr, "Error: Could not write to ACCEL_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read raw acceleration data from the MPU6050
int read_mpu6050_data(int i2c_fd, int address, float *x, float *y, float *z) {
    char buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes, and scale to g units
    *x = (float)((int16_t)(buffer[0] << 8 | buffer[1])) / 16384.0f;
    *y = (float)((int16_t)(buffer[2] << 8 | buffer[3])) / 16384.0f;
    *z = (float)((int16_t)(buffer[4] << 8 | buffer[5])) / 16384.0f;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to get the latest data from the circular buffer
void get_latest_data(circular_buffer_t *buffer, float *x, float *y, float *z) {
    if (buffer->count > 0) {
        int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        *x = buffer->x[index];
        *y = buffer->y[index];
        *z = buffer->z[index];
    } else {
        *x = 0.0f;
        *y = 0.0f;
        *z = 0.0f;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    keep_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Function to export the I2C device
int export_i2c(int bus, int addr) {
    char buffer[10];
    int fd;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open /dev/i2c-1\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02x\n", addr);
        close(fd);
        return -1;
    }

    return fd;
}

// Function to unexport the I2C device
int unexport_i2c(int bus, int addr) {
    char buffer[10];
    int fd;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open /dev/i2c-1\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02x\n", addr);
        close(fd);
        return -1;
    }

    if (write(fd, "\0", 1) != 1) {
        fprintf(stderr, "Error: Could not unexport I2C device\n");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02x\n", addr);
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device(int bus, int addr) {
    return open("/dev/i2c-1", O_RDWR);
}

// Function to close the I2C device
int close_i2c_device(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error: Could not close I2C device\n");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    struct timespec req;
    req.tv_sec = 0;
    req.tv_nsec = SAMPLE_PERIOD_US;

    // Parse command-line arguments
    if (argc > 1) {
        mpu6050_address = strtol(argv[1], NULL, 16);
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open_i2c_device(1, mpu6050_address);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd, mpu6050_address) < 0) {
        fprintf(stderr, "Error: Could not initialize MPU6050\n");
        close_i2c_device(i2c_fd);
        return 1;
    }

    // Create circular buffer
    circular_buffer_t buffer = {{0.0f}, 0, 0};

    // Main loop
    while (keep_running) {
        float x, y, z;

        // Read acceleration data
        if (read_mpu6050_data(i2c_fd, mpu6050_address, &x, &y, &z) == 0) {
            // Add data to buffer
            add_to_buffer(&buffer, x, y, z);

            // Get latest data
            get_latest_data(&buffer, &x, &y, &z);

            // Log data to sysfs file
            FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "w");
            if (fp != NULL) {
                fprintf(fp, "%.3f,%.3f,%.3f\n", x, y, z);
                fclose(fp);
            } else {
                fprintf(stderr, "Error: Could not open sysfs file for writing\n");
            }
        } else {
            fprintf(stderr, "Error: Could not read MPU6050 data\n");
        }

        // Wait for the next sample
        nanosleep(&req, NULL);
    }

    // Clean up resources
    close_i2c_device(i2c_fd);

    return 0;
}

