#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define SOUND_THRESHOLD 1  // Digital HIGH indicates sound detected
#define DEBOUNCE_DELAY 500 // milliseconds
#define ALARM_DURATION 3000 // milliseconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void log_alarm();
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sound_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Activate relay (HIGH)
    gpioDelay(ALARM_DURATION);
    gpioWrite(RELAY_PIN, 0); // Deactivate relay (LOW)
}

// Function to log the alarm event
void log_alarm() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Alarm triggered\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Could not write to log file.\n");
    }
}

// Function to cleanup GPIO and close the log file
void cleanup() {
    printf("Cleaning up and exiting...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

