    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == SOUND_THRESHOLD) {
            printf("Sound detected! Activating alarm.\n");
            activate_relay();
            log_alarm();
            gpioDelay(DEBOUNCE_DELAY); // Debounce delay
        }

        gpioDelay(100); // Poll every 100 ms
    }

    cleanup(); // Cleanup before exiting
    return 0;
}

