#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define WHO_AM_I 0x75

// Gyroscope Sensitivity
#define GYRO_SENSITIVITY 131.0

// Circular Buffer Size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to hold timestamped gyroscope data
typedef struct {
    struct timeval timestamp;
    gyro_data_t data;
} gyro_data_with_time_t;

// Circular buffer structure
typedef struct {
    gyro_data_with_time_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_with_time_t data);
int get_from_buffer(circular_buffer_t *buffer, int index, gyro_data_with_time_t *data);
double calculate_magnitude(gyro_data_t data);
void trigger_callback(double magnitude);
void signal_handler(int signal);

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize MPU-6050
int init_mpu6050(int fd) {
    // Wake up the sensor
    if (write(fd, &0x00, 1) != 1) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Verify the sensor is present
    char who_am_i;
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, gyro_data_t *data) {
    char buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_with_time_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Get data from the circular buffer
int get_from_buffer(circular_buffer_t *buffer, int index, gyro_data_with_time_t *data) {
    if (index < 0 || index >= buffer->count) {
        return -1; // Invalid index
    }

    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    *data = buffer->buffer[actual_index];
    return 0;
}

// Calculate the magnitude of the angular velocity vector
double calculate_magnitude(gyro_data_t data) {
    return sqrt(pow(data.x, 2) + pow(data.y, 2) + pow(data.z, 2)) / GYRO_SENSITIVITY;
}

// Trigger callback function
void trigger_callback(double magnitude) {
    printf("Magnitude: %.2f deg/s\n", magnitude);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    gyro_data_t gyro_data;
    gyro_data_with_time_t gyro_data_with_time;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Get timestamp
            struct timeval tv;
            gettimeofday(&tv, NULL);

            // Create gyro_data_with_time_t struct
            gyro_data_with_time.timestamp = tv;
            gyro_data_with_time.data = gyro_data;

            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, gyro_data_with_time);

            // Calculate magnitude
            double magnitude = calculate_magnitude(gyro_data);

            // Trigger callback if magnitude exceeds threshold
            if (magnitude > 50.0) {
                trigger_callback(magnitude);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Delay for 100ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&ts, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

