#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <termios.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CHECKSUM_OFFSET 1
#define CHECKSUM_LENGTH 2
#define MAX_RETRIES 3
#define TIMEOUT_MS 100

int uart_fd = -1;
FILE *log_file = NULL;
FILE *error_file = NULL;

// Structure to hold sensor data
typedef struct {
    int co2_ppm;
    int error_flag;
} sensor_data_t;

// Function prototypes
int init_uart(const char *device, int baud_rate);
int read_sensor_data(int fd, unsigned char *data, int bytes_to_read);
int validate_checksum(const unsigned char *data, int length);
int convert_to_ppm(const unsigned char *data);
int log_data(FILE *fp, sensor_data_t data);
int send_data_to_server(sensor_data_t data);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (uart_fd != -1) {
        serClose(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize UART
int init_uart(const char *device, int baud_rate) {
    int fd = serOpen(device, baud_rate, 0); // 0 for default flags
    if (fd < 0) {
        log_error("Failed to open UART");
        return -1;
    }
    return fd;
}

// Read sensor data from UART
int read_sensor_data(int fd, unsigned char *data, int bytes_to_read) {
    int bytes_read = 0;
    int start_time = time(NULL);

    while (bytes_read < bytes_to_read && (time(NULL) - start_time) < TIMEOUT_MS / 1000.0) {
        int available = serDataAvailable(fd);
        if (available > 0) {
            bytes_read += serRead(fd, (char *)data + bytes_read, available);
            if (bytes_read < bytes_to_read) {
                start_time = time(NULL); // Reset timeout if not all bytes are read
            }
        } else {
            // Timeout or no data available
            return -1; // Indicate timeout or no data
        }
    }

    if (bytes_read != bytes_to_read) {
        log_error("Incomplete data read from sensor");
        return -1;
    }

    return 0;
}

// Validate checksum
int validate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 0; i < length - 1; i++) {
        checksum += data[i];
    }
    checksum = 255 - checksum; // Invert the checksum
    if (checksum != data[length - 1]) {
        return 0; // Checksum mismatch
    }
    return 1; // Checksum valid
}

// Convert raw data to CO2 concentration (ppm)
int convert_to_ppm(const unsigned char *data) {
    return (data[2] << 8) | data[3];
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp, data.co2_ppm, data.error_flag);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Simulate sending data to a remote server
int send_data_to_server(sensor_data_t data) {
    printf("{\"timestamp\": \"%ld\", \"co2_ppm\": %d, \"error_flag\": %d}\n", data.co2_ppm, data.co2_ppm, data.error_flag);
    return 0;
}

// Log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("co2_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        log_error("UART initialization failed");
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        serClose(uart_fd);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char sensor_data[9];
    sensor_data_t sensor_data_local;

    // Main loop
    while (1) {
        // Send read command
        if (serWrite(uart_fd, CO2_COMMAND, sizeof(CO2_COMMAND)) != sizeof(CO2_COMMAND)) {
            log_error("Failed to send read command");
            break;
        }

        // Wait for response (at least 100ms)
        gpioDelay(100000); // 100ms

        // Read sensor data
        if (read_sensor_data(uart_fd, sensor_data, sizeof(CO2_COMMAND)) == 0) {
            // Validate checksum
            if (validate_checksum(sensor_data, sizeof(CO2_COMMAND) - 1)) {
                // Convert to CO2 concentration
                sensor_data_local.co2_ppm = convert_to_ppm(sensor_data);
                sensor_data_local.error_flag = 0; // No error

                // Log data
                log_data(log_file, sensor_data_local);

                // Send data to server
                send_data_to_server(sensor_data_local);
            } else {
                log_error("Checksum validation failed");
                sensor_data_local.co2_ppm = -1; // Indicate error
                sensor_data_local.error_flag = 1; // Set error flag
            }
        } else {
            log_error("Failed to read sensor data");
            sensor_data_local.co2_ppm = -1; // Indicate error
            sensor_data_local.error_flag = 1; // Set error flag
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup (should not reach here normally due to signal handler)
    serClose(uart_fd);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

