#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_START 0x03

// GPIO pin for LED
#define LED_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold compensated heading
typedef struct {
    float heading;
} compensated_heading_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
compensated_heading_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_magnetometer_data(magnetometer_data_t *data);
void compensate_heading(magnetometer_data_t data, compensated_heading_t *compensated);
float calculate_heading(compensated_heading_t compensated);
void control_led(float heading);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configure register 0x00 (CONFIG_A)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        log_error("Failed to write to CONFIG_A register");
        return -1;
    }

    // Configure register 0x01 (CONFIG_B)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        log_error("Failed to write to CONFIG_B register");
        return -1;
    }

    // Configure register 0x02 (MODE)
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        log_error("Failed to write to MODE register");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_START, buffer, 6);

    if (result != 6) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Compensate for hard-iron distortion
void compensate_heading(magnetometer_data_t data, compensated_heading_t *compensated) {
    compensated->heading = atan2(data.y, data.x) * 180 / M_PI;
    compensated->heading += 180; // Adjust for sensor orientation
}

// Calculate heading in degrees
float calculate_heading(compensated_heading_t compensated) {
    return compensated.heading;
}

// Control LED based on heading deviation
void control_led(float heading) {
    if (fabs(heading - TARGET_HEADING) > 10.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Log error messages
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s: %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        magnetometer_data_t data;
        compensated_heading_t compensated;

        // Read magnetometer data
        if (read_magnetometer_data(&data) == 0) {
            // Compensate for hard-iron distortion
            compensate_heading(data, &compensated);

            // Calculate heading
            float heading = calculate_heading(compensated);

            // Control LED
            control_led(heading);

            // Log data
            printf("Heading: %.2f degrees\n", heading);

            // Store in circular buffer
            circular_buffer[buffer_index].heading = heading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            log_error("Failed to read magnetometer data in main loop");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

