#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C address for BH1750 sensor
#define BH1750_ADDR 0x23

// Define I2C bus
#define I2C_BUS 1

// Define log file path
#define LOG_FILE "lighting_log.txt"

// Define lux thresholds for relays
#define RED_THRESHOLD 50
#define GREEN_THRESHOLD 150
#define BLUE_THRESHOLD 300

// Define continuous high-resolution mode command for BH1750
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
float read_lux();
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void cleanup();
void signal_handler(int signal);

// Structure to hold relay states
typedef struct {
    int red_relay;
    int green_relay;
    int blue_relay;
} RelayStates;

RelayStates current_relay_states = {0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    return 0;
}

// Function to initialize I2C communication
int initialize_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_cmd[2] = {BH1750_CONTINUOUS_HIGH_RES_MODE, 0x00};
    if (write(i2c_fd, config_cmd, 2) != 2) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    return 0;
}

// Function to read lux value from BH1750 sensor
float read_lux() {
    unsigned char buffer[2];
    int result;

    // Wait for at least 120ms for the first conversion
    gpioDelay(120000); // 120ms

    // Read two bytes from the sensor
    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1.0; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];

    // Convert raw value to lux
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to control relays based on lux value
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < RED_THRESHOLD) {
        gpioWrite(RED_RELAY_PIN, 1);
        red_state = 1;
    } else if (lux >= RED_THRESHOLD && lux < GREEN_THRESHOLD) {
        // Do nothing
    } else if (lux >= GREEN_THRESHOLD && lux < BLUE_THRESHOLD) {
        gpioWrite(GREEN_RELAY_PIN, 1);
        green_state = 1;
    } else if (lux >= BLUE_THRESHOLD && lux < BLUE_THRESHOLD + 100) {
        // Do nothing
    } else {
        gpioWrite(BLUE_RELAY_PIN, 1);
        blue_state = 1;
    }

    current_relay_states.red_relay = red_state;
    current_relay_states.green_relay = green_state;
    current_relay_states.blue_relay = blue_state;
}

// Function to log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off all relays
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    // Close I2C device
    close(i2c_fd);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = read_lux();

        if (lux >= 0) {
            // Control relays
            control_relays(lux);

            // Log data
            log_data(lux, current_relay_states.red_relay, current_relay_states.green_relay, current_relay_states.blue_relay);
        } else {
            fprintf(stderr, "Error reading lux value. Skipping relay control and logging.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

