// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM Frequency
#define PWM_FREQUENCY 1000

// Distance Sensor Input
#define DISTANCE_SENSOR_PIN 4

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to set motor direction and speed
void set_motor_speed(int motor, int direction, int speed) {
    int in1, in2;

    if (motor == 0) {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    } else {
        in1 = MOTOR_B_IN3;
        in2 = MOTOR_B_IN4;
    }

    if (direction == 1) { // Forward
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
        gpioPWM(in2, speed);
    } else if (direction == 0) { // Backward
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
        gpioPWM(in2, speed);
    } else { // Stop
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
        gpioPWM(in2, 0);
    }
}

int main(int argc, char *argv[]) {
    int distance;
    int motor_a_speed, motor_b_speed;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance sensor value
        distance = gpioRead(DISTANCE_SENSOR_PIN);

        // Validate sensor reading
        if (distance < 0 || distance > 100) {
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
            continue; // Skip to the next iteration
        }

        // Map distance to PWM duty cycle
        motor_a_speed = (int)(((float)distance / 100.0) * 255.0);
        motor_a_speed = (motor_a_speed > 255) ? 255 : motor_a_speed;
        motor_a_speed = (motor_a_speed < 0) ? 0 : motor_a_speed;

        motor_b_speed = (int)(((float)(100.0 - distance) / 100.0) * 255.0);
        motor_b_speed = (motor_b_speed > 255) ? 255 : motor_b_speed;
        motor_b_speed = (motor_b_speed < 0) ? 0 : motor_b_speed;

        // Set motor speeds
        set_motor_speed(0, (distance < 50) ? 1 : 0, motor_a_speed);
        set_motor_speed(1, (distance < 50) ? 1 : 0, motor_b_speed);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Stop motors and terminate pigpio
    set_motor_speed(0, 0, 0);
    set_motor_speed(1, 0, 0);
    gpioTerminate();

    return 0;
}

