#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>
#include <sys/time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_GPIO 18
#define PWM_PERIOD_NS 10000000 // 10ms
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_RANGE 180
#define LOG_FILE "solar_tracker.log"

// MPU6050 Registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char val);
int init_mpu6050(int fd);
int read_mpu6050(int fd, float *pitch, float *roll);
int map_pitch_roll_to_servo_position(float pitch, float roll, int *servo_position);
int set_servo_position(int gpio, int position);
int log_data(float pitch, float roll, int servo_position);
void signal_handler(int sig);

// I2C read function with exponential backoff
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < 3) {
        result = read(fd, buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            log_data(-999.0, -999.0, -1); // Log error
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after 3 retries.\n");
    return -1; // Failure after retries
}

// I2C write function with exponential backoff
int i2c_write_byte(int fd, unsigned char reg, unsigned char val) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < 3) {
        result = write(fd, &reg, 1);
        if (result == 1) {
            result = write(fd, &val, 1);
            if (result == 1) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C write (reg) failed (attempt %d): %s\n", retries + 1, strerror(errno));
                log_data(-999.0, -999.0, -1); // Log error
                usleep(delay_ms * 1000); // Exponential backoff
                delay_ms *= 2;
                retries++;
            }
        } else {
            fprintf(stderr, "I2C write (reg) failed (attempt %d): %s\n", retries + 1, strerror(errno));
            log_data(-999.0, -999.0, -1); // Log error
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after 3 retries.\n");
    return -1; // Failure after retries
}

// MPU6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_write_byte(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Read accelerometer and gyroscope data from MPU6050
int read_mpu6050(int fd, float *pitch, float *roll) {
    unsigned char buf[14];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    if (i2c_read_bytes(fd, ACCEL_XOUT_H, buf, 14) != 0) {
        fprintf(stderr, "Failed to read MPU6050 data\n");
        return -1;
    }

    accel_x = (buf[0] << 8) | buf[1];
    accel_y = (buf[2] << 8) | buf[3];
    accel_z = (buf[4] << 8) | buf[5];
    gyro_x = (buf[8] << 8) | buf[9];
    gyro_y = (buf[10] << 8) | buf[11];
    gyro_z = (buf[12] << 8) | buf[13];

    // Convert to g and degrees/second
    *pitch = (float)accel_x / 16384.0f; // Assuming +/- 2g range
    *roll = (float)gyro_y / 131.0f;    // Assuming +/- 250 deg/s

    return 0;
}

// Map pitch and roll angles to servo position
int map_pitch_roll_to_servo_position(float pitch, float roll, int *servo_position) {
    // Simple mapping: pitch controls horizontal tilt, roll controls vertical tilt
    // Assuming servo range is 0-180 degrees
    *servo_position = (int)(pitch * SERVO_RANGE) + (int)(roll * SERVO_RANGE);

    // Clamp the servo position to the valid range
    if (*servo_position < 0) {
        *servo_position = 0;
    } else if (*servo_position > SERVO_RANGE) {
        *servo_position = SERVO_RANGE;
    }

    return 0;
}

// Set servo position using sysfs
int set_servo_position(int gpio, int position) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm%d/duty_cycle", gpio);
    snprintf(path, sizeof(path), "%d", position);

    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open servo duty cycle file: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(&position, sizeof(int), 1, fp) != 1) {
        fprintf(stderr, "Failed to write servo duty cycle: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int servo_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    float pitch, roll;
    int servo_position;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Set PWM period
    int pwm_period_ns = PWM_PERIOD_NS;
    if (set_pwm_period(pwm_period_ns) != 0) {
        fprintf(stderr, "Failed to set PWM period\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_mpu6050(i2c_fd, &pitch, &roll) == 0) {
            // Map data to servo position
            if (map_pitch_roll_to_servo_position(pitch, roll, &servo_position) == 0) {
                // Set servo position
                if (set_servo_position(SERVO_GPIO, servo_position) == 0) {
                    // Log data
                    log_data(pitch, roll, servo_position);
                } else {
                    fprintf(stderr, "Failed to set servo position\n");
                }
            } else {
                fprintf(stderr, "Failed to map pitch/roll to servo position\n");
            }
        } else {
            fprintf(stderr, "Failed to read MPU6050 data\n");
        }

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

// Function to set PWM period
int set_pwm_period(int period_ns) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm%d/period", SERVO_GPIO);

    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open PWM period file: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(&period_ns, sizeof(int), 1, fp) != 1) {
        fprintf(stderr, "Failed to write PWM period: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

