    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open PWM period file: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(&period_ns, sizeof(int), 1, fp) != 1) {
        fprintf(stderr, "Failed to write PWM period: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
