#include <math.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 100

// Define sunrise/sunset duration
#define SUNRISE_DURATION 300 // seconds
#define SUNSET_DURATION 300  // seconds

// Define schedule file path
#define SCHEDULE_FILE "lighting_schedule.txt"

// Global variables
FILE *schedule_file;
int running = 1;

// Structure to hold schedule data
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    char *state;
} ScheduleEntry;

// Function prototypes
int initialize_gpio();
int read_schedule(ScheduleEntry schedule[], int max_entries);
int apply_schedule(int current_time);
void fade_lamp(int relay_number, int duration_seconds);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(RELAY1_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY2_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY3_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY4_PIN, PWM_RANGE);

    return 0;
}

// Function to read the schedule from file
int read_schedule(ScheduleEntry schedule[], int max_entries) {
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Error opening schedule file: %s\n", SCHEDULE_FILE);
        return 1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), schedule_file) != NULL && count < max_entries) {
        if (sscanf(line, "%d:%d:%d,%d,%s", &schedule[count].hour, &schedule[count].minute, &schedule[count].second, &schedule[count].relay_number, schedule[count].state) == 5) {
            if (schedule[count].state[0] == 'o' || schedule[count].state[0] == 'O') {
                schedule[count].state[0] = '1';
            } else if (schedule[count].state[0] == 'i' || schedule[count].state[0] == 'I') {
                schedule[count].state[0] = '0';
            } else {
                fprintf(stderr, "Invalid state in schedule file: %s\n", line);
                fclose(schedule_file);
                return 1;
            }
            count++;
        } else {
            fprintf(stderr, "Invalid format in schedule file: %s\n", line);
            fclose(schedule_file);
            return 1;
        }
    }

    fclose(schedule_file);
    return (count < max_entries) ? 1 : 0;
}

// Function to apply the schedule
int apply_schedule(int current_time) {
    ScheduleEntry schedule[100]; // Assuming a maximum of 100 entries
    int count;

    if (read_schedule(schedule, sizeof(schedule) / sizeof(schedule[0])) != 0) {
        return 1;
    }

    for (count = 0; count < sizeof(schedule) / sizeof(schedule[0]); count++) {
        if (schedule[count].relay_number == 1) {
            if (schedule[count].state[0] == '1') {
                fade_lamp(1, SUNRISE_DURATION);
            } else {
                fade_lamp(1, SUNSET_DURATION);
            }
        } else if (schedule[count].relay_number == 2) {
            if (schedule[count].state[0] == '1') {
                fade_lamp(2, SUNRISE_DURATION);
            } else {
                fade_lamp(2, SUNSET_DURATION);
            }
        } else if (schedule[count].relay_number == 3) {
            if (schedule[count].state[0] == '1') {
                fade_lamp(3, SUNRISE_DURATION);
            } else {
                fade_lamp(3, SUNSET_DURATION);
            }
        } else if (schedule[count].relay_number == 4) {
            if (schedule[count].state[0] == '1') {
                fade_lamp(4, SUNRISE_DURATION);
            } else {
                fade_lamp(4, SUNSET_DURATION);
            }
        }
    }

    return 0;
}

// Function to fade a lamp on/off
void fade_lamp(int relay_number, int duration_seconds) {
    time_t start_time = time(NULL);
    double elapsed_time;
    int duty_cycle;

    while (time(NULL) - start_time < duration_seconds) {
        elapsed_time = difftime(time(NULL), start_time);
        duty_cycle = (int)(100.0 * (1.0 - fabs(sin(elapsed_time * M_PI / 180.0))));

        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        gpioPWM(RELAY_PIN, duty_cycle);
        gpioDelay(1000); // 1 ms delay
    }

    // Turn off the lamp after the fade duration
    gpioPWM(RELAY_PIN, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release GPIO resources
void cleanup() {
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Read the schedule
    if (read_schedule(schedule, sizeof(schedule) / sizeof(schedule[0])) != 0) {
        cleanup();
        return 1;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        time_t current_time = time(NULL);
        struct tm *timeinfo = localtime(&current_time);
        int current_hour = timeinfo->tm_hour;
        int current_minute = timeinfo->tm_min;
        int current_second = timeinfo->tm_sec;

        printf("Current time: %02d:%02d:%02d\n", current_hour, current_minute, current_second);

        if (apply_schedule(current_time) != 0) {
            fprintf(stderr, "Error applying schedule\n");
        }

        sleep(1); // Check every second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

