#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 30.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define PWM_RANGE 1000         // PWM range for buzzer
#define PWM_FREQUENCY 440      // PWM frequency (approx. 440 Hz)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // Period in microseconds
#define TIMEOUT_US 1000000 // 1 second timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor(int triggerPin);
long long measurePulseWidth(int echoPin);
float calculateDistance(long long pulseWidth);
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(int buzzerPin, float frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    setBuzzerFrequency(BUZZER_PIN, 0.0); // Silence the buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor(int triggerPin) {
    gpioWrite(triggerPin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(triggerPin, 0);
}

// Function to measure the pulse width of the echo signal
long long measurePulseWidth(int echoPin) {
    long long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(echoPin) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo high.\n");
        return -1; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(echoPin) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo low.\n");
        return -1; // Indicate timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate the distance from the pulse width
float calculateDistance(long long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Distance in cm
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }
    return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
}

// Function to set the buzzer frequency using PWM
void setBuzzerFrequency(int buzzerPin, float frequency) {
    if (frequency < 0.0) return; // Ignore invalid frequencies
    int pwm_value = (int)((frequency / PWM_FREQUENCY) * (PWM_RANGE / 2.0)); // Calculate PWM value
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    gpioPWM(buzzerPin, pwm_value);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor(TRIGGER_PIN);

        // Measure the pulse width
        long long pulseWidth = measurePulseWidth(ECHO_PIN);

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Map the distance to a frequency
        float frequency = mapDistanceToFrequency(distance);

        // Set the buzzer frequency
        setBuzzerFrequency(BUZZER_PIN, frequency);

        // Print the distance and frequency (for debugging)
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay to control the sampling rate
        usleep(10000); // 10 ms
    }

    // Silence the buzzer and terminate pigpio before exiting
    setBuzzerFrequency(BUZZER_PIN, 0.0);
    gpioTerminate();

    return 0;
}

