#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Sensitivity factor for gyroscope
#define GYRO_SENSITIVITY 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Log file path
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the sensor
    if (write(fd, &0x00, 1) != 1) {
        perror("Failed to wake up MPU-6050");
        return -1;
    }

    // Configure gyroscope sensitivity (+/- 250 deg/s)
    if (write(fd, &0x00, 1) != 1) {
        perror("Failed to configure gyroscope sensitivity");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    char buffer[6];
    int bytes_read = read(fd, buffer, 6);

    if (bytes_read != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees/second
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data / GYRO_SENSITIVITY;
}

// Function to log gyroscope data to a file
int log_gyro_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", timestamp,
            convert_to_degrees_per_second(data.x),
            convert_to_degrees_per_second(data.y),
            convert_to_degrees_per_second(data.z));
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    gyro_data_t gyro_data;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Log gyroscope data
            log_gyro_data(log_file, gyro_data);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

