#include <pigpio.h>
#include <stdint.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody (example)
const int melody[] = {0x03, 0x02, 0x04, 0x04, 0x02, 0x01, 0x01, 0x00, 0x00, 0x01, 0x01, 0x02, 0x02, 0x04, 0x04, 0x03};

// Define debounce time (milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
volatile int melody_index = 0;
volatile int melody_length = sizeof(melody) / sizeof(melody[0]);
volatile int melody_playing = 0;
volatile int button_pressed = 0;

// Function prototypes
void button_callback(int gpio, int level, uint32_t tick, void *user);
void melody_callback(int gpio, int level, uint32_t tick, void *user);
void stop_melody();
void play_melody();
void signal_handler(int signal);

// Interrupt handler for button press
void button_callback(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) // Button pressed (active low)
    {
        if (current_tick - last_tick > DEBOUNCE_TIME * 1000) // Debounce
        {
            button_pressed = 1;
            last_tick = current_tick;
        }
    }
    else if (level == 1) // Button released
    {
        button_pressed = 0;
    }
}

// Callback function for melody playback
void melody_callback(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) // Button pressed (active low)
    {
        if (button_pressed) // Check if button is still pressed
        {
            melody_playing = 1;
            button_pressed = 0;
        }
    }
    else if (level == 1) // Button released
    {
        melody_playing = 0;
        button_pressed = 0;
    }

    if (melody_playing)
    {
        if (melody_index < melody_length)
        {
            int duty_cycle = melody[melody_index];
            gpioHardwarePWM(BUZZER_PIN, duty_cycle, 1); // Set duty cycle to 50%
            melody_index++;
        }
        else
        {
            melody_playing = 0;
        }
    }
}

// Function to stop the melody
void stop_melody()
{
    melody_playing = 0;
    gpioHardwarePWM(BUZZER_PIN, 0, 1); // Stop PWM
}

// Function to play the melody
void play_melody()
{
    melody_playing = 1;
    gpioHardwarePWM(BUZZER_PIN, 0, 1); // Start PWM
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_callback, NULL) != 0)
    {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set callback function for melody playback
    if (gpioSetISRFuncEx(BUZZER_PIN, RISING_EDGE, 0, melody_callback, NULL) != 0)
    {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        if (melody_playing)
        {
            gpioDelay(100000); // Delay to control melody speed (100ms)
        }
    }

    return 0;
}

