#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEFAULT_TIMEOUT_MS 1000

// Global variables
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int timeout_ms = DEFAULT_TIMEOUT_MS;

// Function prototypes
int setup_gpio(void);
int read_gpio(void);
void log_event(const char *event_type, int value);
void check_earthquake_alert(void);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold the last 5 events
typedef struct {
    time_t timestamps[5];
    int values[5];
    int index;
} EventWindow;

EventWindow event_window = {{0}, {0}, 0};

// Function to add a new event to the sliding window
void add_event(time_t timestamp, int value) {
    event_window.timestamps[event_window.index] = timestamp;
    event_window.values[event_window.index] = value;
    event_window.index = (event_window.index + 1) % 5;
}

// Function to check if the earthquake alert condition is met
bool is_earthquake_alert_condition(void) {
    int count = 0;
    for (int i = 0; i < 5; i++) {
        if (event_window.values[i] == 1) {
            count++;
        }
    }
    return (count >= 3);
}

// Function to log an event with a timestamp
void log_event(const char *event_type, int value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%s,%d\n", buf, event_type, value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

