#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define OUT_X_L_M 0x03
#define OUT_X_H_M 0x04
#define OUT_Z_L_M 0x05
#define OUT_Z_H_M 0x06
#define OUT_Y_L_M 0x07
#define OUT_Y_H_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
const char *compass_directions[8] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int init_i2c();
int init_magnetometer();
int read_magnetometer_data(magnetometer_data_t *data);
float calibrate_magnetometer_data(magnetometer_data_t raw_data);
float calculate_heading(float x, float y);
int log_data(magnetometer_data_t raw_data, float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the magnetometer
int init_magnetometer() {
    // Set continuous-conversion mode
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to MR_REG_M\n");
        return -1;
    }

    // Set output data rate to 15 Hz
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Error writing to CRA_REG_M\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetometer data
float calibrate_magnetometer_data(magnetometer_data_t raw_data) {
    return (float)raw_data.x + X_OFFSET + (float)raw_data.y + Y_OFFSET + (float)raw_data.z + Z_OFFSET;
}

// Calculate compass heading
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to CSV file
int log_data(magnetometer_data_t raw_data, float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("mag_log.csv", "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    magnetometer_data_t raw_data;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;

    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_data) == 0) {
            // Calibrate magnetometer data
            calibrated_x = calibrate_magnetometer_data(raw_data);
            calibrated_y = calibrate_magnetometer_data(raw_data);
            calibrated_z = calibrate_magnetometer_data(raw_data);

            // Calculate compass heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Log data
            if (log_data(raw_data, calibrated_x, calibrated_y, calibrated_z, heading) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Print data to console
            printf("Timestamp: %s, Calibrated X: %.2f, Calibrated Y: %.2f, Calibrated Z: %.2f, Heading: %.2f\n",
                   timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, skipping this sample.\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

