#include <sys/types.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the log file path
#define LOG_FILE "irrigation_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(int gpio_pins[], int num_pins);
int activate_relay(int gpio_pin);
int deactivate_relay(int gpio_pin);
int log_event(int relay_number, int moisture_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, exiting gracefully...\n");

        // Deactivate all relays
        deactivate_relay(RELAY1_PIN);
        deactivate_relay(RELAY2_PIN);
        deactivate_relay(RELAY3_PIN);
        deactivate_relay(RELAY4_PIN);

        // Release the GPIO lines
        gpioTerminate();

        // Close the log file
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp != NULL) {
            fclose(fp);
        }

        exit(0);
    }
}

// Function to initialize the GPIO pins
int initialize_gpio(int gpio_pins[], int num_pins) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(gpio_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", gpio_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

// Function to activate a relay
int activate_relay(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to activate relay on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
int log_event(int relay_number, int moisture_level) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, relay_number, moisture_level);
    fclose(fp);
    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Define the GPIO pins
    int gpio_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(gpio_pins, num_pins) != 0) {
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate a random soil moisture value
        int moisture_level = rand() % 101;

        // Activate relays if moisture level is below 30
        if (moisture_level < 30) {
            for (int i = 0; i < 4; i++) {
                if (activate_relay(gpio_pins[i]) != 0) {
                    fprintf(stderr, "Failed to activate relay %d\n", i + 1);
                    deactivate_relay(gpio_pins[i]); // Deactivate all relays on error
                }
                sleep(5);
                if (deactivate_relay(gpio_pins[i]) != 0) {
                    fprintf(stderr, "Failed to deactivate relay %d\n", i + 1);
                    deactivate_relay(gpio_pins[i]); // Deactivate all relays on error
                }
                sleep(1);
            }
        }

        // Log the event
        if (log_event(1, moisture_level) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }
        if (log_event(2, moisture_level) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }
        if (log_event(3, moisture_level) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }
        if (log_event(4, moisture_level) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }

        sleep(10);
    }

    // Deactivate all relays, release the lines, close the log file, and terminate pigpio
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);
    gpioTerminate();
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fclose(fp);
    }

    return 0;
}

