void set_servo_pulse(int gpio, int pulse_width);
void open_valve();
void close_valve();
void water_plant();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Caught signal, stopping program...\n");
        program_running = 0;
        close_valve();
        gpioTerminate();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    return 0;
}

// Set servo angle
void set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle: %d\n", angle);
        return;
    }

    int pulse_width = SERVO_MIN_PULSE + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    set_servo_pulse(gpio, pulse_width);
}

// Set servo pulse width
void set_servo_pulse(int gpio, int pulse_width) {
    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse for GPIO %d\n", gpio);
        // Retry after a short delay
        gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        if (program_running) {
            set_servo_pulse(gpio, pulse_width); // Retry immediately if still running
        }
    }
}

// Open the water valve
void open_valve() {
    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (gpioServo(VALVE_PIN, VALVE_OPEN_PULSE) == 0) {
            printf("Valve opened successfully\n");
            return;
        } else {
            fprintf(stderr, "Failed to open valve, retry %d\n", i + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    fprintf(stderr, "Critical error: Failed to open valve after %d retries\n", MAX_RETRIES);
    close_valve();
    exit(1);
}

// Close the water valve
void close_valve() {
    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (gpioServo(VALVE_PIN, VALVE_CLOSE_PULSE) == 0) {
            printf("Valve closed successfully\n");
            return;
        } else {
            fprintf(stderr, "Failed to close valve, retry %d\n", i + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    fprintf(stderr, "Critical error: Failed to close valve after %d retries\n", MAX_RETRIES);
    exit(1);
}

// Water the plant
void water_plant() {
    int moisture_level = 0;
    int valve_angle = 0;
    int nozzle_angle = 0;
    int watering_status = 0;

    // Simulate moisture readings
    moisture_level = rand() % 101; // 0-100

    printf("Moisture level: %d\n", moisture_level);

    if (moisture_level < MOISTURE_THRESHOLD_LOW) {
        printf("Moisture level below threshold, opening valve\n");
        open_valve();
        valve_angle = 90; // Set valve to open position
        watering_status = 1; // Set watering status to open
    } else if (moisture_level >= MOISTURE_THRESHOLD_HIGH) {
        printf("Moisture level above threshold, closing valve\n");
        close_valve();
        valve_angle = 0; // Set valve to close position
        watering_status = 0; // Set watering status to closed
    } else {
        printf("Moisture level within threshold, skipping watering\n");
        watering_status = 0; // Set watering status to closed
    }

    if (watering_status == 1) {
        printf("Starting watering cycle\n");
        for (int i = 0; i < 5; ++i) {
            for (int j = 0; j < 5; ++j) {
                set_servo_angle(NOZZLE_PIN, j);
                gpioDelay(2000000); // 2 seconds
                set_servo_angle(NOZZLE_PIN, 180);
                gpioDelay(500000); // 0.5 seconds
                set_servo_angle(NOZZLE_PIN, 0);
                gpioDelay(2000000); // 2 seconds
            }
            set_servo_angle(NOZZLE_PIN, 0);
            gpioDelay(500000); // 0.5 seconds
        }
        printf("Watering cycle complete\n");
    } else {
        printf("Skipping watering cycle\n");
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        water_plant();
        gpioDelay(5000000); // Wait 5 seconds
    }

    // Stop servos and terminate pigpio
    close_valve();
    gpioTerminate();

    return 0;
}

