#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity factor (degrees/second per LSB)
#define SENSITIVITY_FACTOR 131.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    stop_flag = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the sensor
    if (write(i2c_fd, &0x00, 1) != 1) {
        perror("Failed to wake up MPU-6050");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw data to degrees/second
void convert_to_degrees_per_second(gyro_data_t data, float *x, float *y, float *z) {
    *x = (float)data.x / SENSITIVITY_FACTOR;
    *y = (float)data.y / SENSITIVITY_FACTOR;
    *z = (float)data.z / SENSITIVITY_FACTOR;
}

// Function to log data to a file
int log_data(time_t timestamp, float x, float y, float z) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp_str, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    gyro_data_t gyro_data;
    float x, y, z;
    time_t current_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Convert data to degrees/second
            convert_to_degrees_per_second(gyro_data, &x, &y, &z);

            // Get current timestamp
            current_time = time(NULL);

            // Log data
            log_data(current_time, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying.\n");
        }

        // Delay for 100 milliseconds (10 Hz sampling rate)
        usleep(100000); // 100 ms = 100000 us
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

