#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MIN_DELAY_MS 60
#define MAX_DELAY_MS 100
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0
#define SPEED_OF_SOUND 34300.0 // cm/s

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioDelay(100000); // 100ms delay

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout_count = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < 10000) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }

    if (timeout_count >= 10000) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < 10000) {
        gpioDelay(1);
        timeout_count++;
    }

    if (timeout_count >= 10000) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 for us to s conversion
}

// Function to log the distance to a file
int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
