#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// GPIO pin for relay control
#define RELAY_GPIO 18

// Distance threshold (in mm)
#define DISTANCE_THRESHOLD 50

// I2C handle
int i2c_handle;

// Function prototypes
int vl53l1x_reset();
int vl53l1x_configure();
int vl53l1x_read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
        gpioWrite(RELAY_GPIO, 0); // Set relay to LOW
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(0);
    }
}

// VL53L1X reset function
int vl53l1x_reset() {
    char buf[2];
    buf[0] = VL53L1X_REG_SYSTEM_START;
    buf[1] = 0x00; // Reset value

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error resetting VL53L1X: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms after reset
    return 0;
}

// VL53L1X configuration function
int vl53l1x_configure() {
    char buf[2];
    buf[0] = VL53L1X_REG_SYSTEM_START;
    buf[1] = 0x01; // Start continuous ranging

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error configuring VL53L1X: %d\n", result);
        return -1;
    }
    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int *distance) {
    char reg[1];
    char data[2];
    int result;

    // Read range status
    reg[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    result = i2cWriteDevice(i2c_handle, reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to range status register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading range status: %d\n", result);
        return -1;
    }
    int range_status = data[0];

    // Read distance data
    reg[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    result = i2cWriteDevice(i2c_handle, reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to distance register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }
    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Relay control function
void control_relay(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Open door (HIGH)
    } else {
        gpioWrite(RELAY_GPIO, 0); // Close door (LOW)
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially close the door

    // VL53L1X Initialization
    if (vl53l1x_reset() != 0) {
        fprintf(stderr, "VL53L1X reset failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_configure() != 0) {
        fprintf(stderr, "VL53L1X configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int distance;
    while (program_running) {
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_relay(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

