#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor
#define GYRO_SCALE_FACTOR 131.0

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (set PWR_MGMT_1 to 0)
    if (write(fd, &0x00, 1) != 1) {
        perror("Failed to wake up MPU-6050");
        return -1;
    }

    // Set the gyroscope full-scale range to ±250 dps
    if (write(fd, &0x00, 1) != 1) {
        perror("Failed to set gyroscope full-scale range");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees/second
void convert_gyro_data(int16_t raw_data, float *degrees_per_second) {
    *degrees_per_second = (float)raw_data / GYRO_SCALE_FACTOR;
}

// Function to log gyroscope data to the console
void log_gyro_data(float x, float y, float z) {
    printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x, y, z);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to continuously read and log gyroscope data
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    float gyro_x, gyro_y, gyro_z;

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &raw_gyro_x, &raw_gyro_y, &raw_gyro_z) == 0) {
            // Convert raw data to degrees/second
            convert_gyro_data(raw_gyro_x, &gyro_x);
            convert_gyro_data(raw_gyro_y, &gyro_y);
            convert_gyro_data(raw_gyro_z, &gyro_z);

            // Log the gyroscope data
            log_gyro_data(gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

