int request_lines(struct gpiod_chip *chip, int num_lines, int *lines);
int set_line_direction(struct gpiod_line *line, int direction);
int set_line_value(struct gpiod_line *line, int value);
int write_log(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Function to open the GPIO chip
int open_chip(struct gpiod_chip **chip) {
    struct gpiod_chip_open_info info;
    memset(&info, 0, sizeof(info));
    info.consumer = "watering_system";
    info.flags = 0;

    if (gpiod_chip_open(CHIP_NAME, &info, chip) < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return -1;
    }

    return 0;
}

// Function to request GPIO lines
int request_lines(struct gpiod_chip *chip, int num_lines, int *lines) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.num_lines = num_lines;

    if (gpiod_chip_request_lines(chip, &config, lines) < 0) {
        fprintf(stderr, "Error requesting GPIO lines: %s\n", CHIP_NAME);
        return -1;
    }

    return 0;
}

// Function to set GPIO line direction
int set_line_direction(struct gpiod_line *line, int direction) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.direction = direction;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting line for direction: %s\n", line->chip->name);
        return -1;
    }

    return 0;
}

// Function to set GPIO line value
int set_line_value(struct gpiod_line *line, int value) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.value = value;

    if (gpiod_line_set_value(line, &config, 0) < 0) {
        fprintf(stderr, "Error setting line value: %s\n", line->chip->name);
        return -1;
    }

    return 0;
}

// Function to write to the log file
int write_log(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

