#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range (duty cycle values)
#define PWM_RANGE 255

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 30 * 60  // 30 minutes

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to set the duty cycle of a relay
int set_relay_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle value for GPIO %d. Must be between 0 and %d.\n", gpio_pin, PWM_RANGE);
        return -1; // Indicate an error
    }

    gpioPWM(gpio_pin, duty_cycle);
    return 0; // Indicate success
}

// Function to simulate PWM frequency
void simulate_pwm_frequency(int gpio_pin, int duty_cycle) {
    // This is a placeholder.  Real PWM requires hardware PWM.
    // pigpio does not directly support software PWM.
    // For a real implementation, you would use gpioWave to create a PWM signal.
    // This example just prints a message.
    printf("Simulating PWM frequency on GPIO %d with duty cycle %d\n", gpio_pin, duty_cycle);
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Main loop for sunrise simulation
    for (int duty_cycle = 0; duty_cycle <= PWM_RANGE && program_running; duty_cycle++) {
        // Set duty cycle for each relay
        if (set_relay_duty_cycle(RELAY1_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error setting duty cycle for relay 1\n");
        }
        if (set_relay_duty_cycle(RELAY2_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error setting duty cycle for relay 2\n");
        }
        if (set_relay_duty_cycle(RELAY3_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error setting duty cycle for relay 3\n");
        }
        if (set_relay_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error setting duty cycle for relay 4\n");
        }

        // Simulate PWM frequency
        simulate_pwm_frequency(RELAY1_PIN, duty_cycle);
        simulate_pwm_frequency(RELAY2_PIN, duty_cycle);
        simulate_pwm_frequency(RELAY3_PIN, duty_cycle);
        simulate_pwm_frequency(RELAY4_PIN, duty_cycle);

        // Log the event
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Sunrise simulation: Duty cycle set to %d", duty_cycle);
        log_event(log_message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function in milliseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

