#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data and timestamp
typedef struct {
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
    time_t timestamp;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void process_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int status;

    // Wake up the sensor
    status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to wake up

    // Set sample rate divider
    status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07); // 1 kHz / (1 + 7) = 125 Hz
    if (status != 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
        return -1;
    }

    // Set gyro full-scale range
    status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00); // ±250 deg/s
    if (status != 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
        return -1;
    }

    // Verify WHO_AM_I register
    char who_am_i;
    status = i2cReadByteData(i2c_handle, 0x75);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }
    who_am_i = (char)status;

    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }

    printf("MPU-6050 initialized successfully.\n");
    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Process gyroscope data
void process_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    // Convert to degrees per second
    float gyro_x_dps = (float)gyro_x / 131.0;
    float gyro_y_dps = (float)gyro_y / 131.0;
    float gyro_z_dps = (float)gyro_z / 131.0;

    // Store in circular buffer
    gyro_buffer[buffer_index].gyro_x = (int16_t)(-gyro_x_dps * 1000); // Store signed 16-bit value
    gyro_buffer[buffer_index].gyro_y = (int16_t)(-gyro_y_dps * 1000);
    gyro_buffer[buffer_index].gyro_z = (int16_t)(-gyro_z_dps * 1000);
    gyro_buffer[buffer_index].timestamp = time(NULL);

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    int status;
    int16_t gyro_x, gyro_y, gyro_z;
    time_t current_time;
    struct tm *time_info;
    char timestamp_str[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process gyroscope data
            process_gyro_data(gyro_x, gyro_y, gyro_z);

            // Check if any axis exceeds the threshold
            if (abs(gyro_x) > 250 || abs(gyro_y) > 250 || abs(gyro_z) > 250) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait before retrying
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
                break;
            }
            if (init_mpu6050() != 0) {
                fprintf(stderr, "MPU-6050 re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                break;
            }
        }

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp and gyroscope data (optional)
        printf("%s - Gyro X: %d, Y: %d, Z: %d\n", timestamp_str, gyro_x, gyro_y, gyro_z);

        // Delay for 50 ms (20 Hz sampling rate)
        gpioDelay(50);
    }

    // Clean up
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

