#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define GPIO_CHIP 0
#define GPIO_LINE 8
#define GYRO_REG_X_HIGH 0x43
#define GYRO_REG_X_LOW 0x44
#define GYRO_REG_Y_HIGH 0x45
#define GYRO_REG_Y_LOW 0x46
#define GYRO_REG_Z_HIGH 0x47
#define GYRO_REG_Z_LOW 0x48
#define SCALE_FACTOR 131.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "gyro_log.txt"

// Global variables
int spi_fd = -1;
int gpio_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
    int16_t z_rate;
} gyro_data_t;

// Function prototypes
int spi_init(const char *device, int speed, int mode, int bits_per_word);
int gpio_init(int gpio_line);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_gyro_data(int fd, gyro_data_t *data);
double convert_to_dps(int16_t raw_rate);
int log_data(FILE *fp, struct timespec ts, gyro_data_t data);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int speed, int mode, int bits_per_word) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_value = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI bits per word
    uint8_t bits_per_word_value = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_value) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_value = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_value) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int gpio_init(int gpio_line) {
    int fd = gpioSetMode(gpio_line, PI_OUTPUT);
    if (fd < 0) {
        perror("Error setting GPIO mode");
        return -1;
    }
    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t tx_buf[7] = {GYRO_REG_X_HIGH, GYRO_REG_X_LOW, GYRO_REG_Y_HIGH, GYRO_REG_Y_LOW, GYRO_REG_Z_HIGH, GYRO_REG_Z_LOW, 0x00}; // Dummy value for reading
    uint8_t rx_buf[7];

    if (spi_transfer(fd, tx_buf, rx_buf, 7) < 0) {
        fprintf(stderr, "SPI transfer failed, retrying...\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    data->x_rate = (int16_t)((rx_buf[1] << 8) | rx_buf[0]);
    data->y_rate = (int16_t)((rx_buf[3] << 8) | rx_buf[2]);
    data->z_rate = (int16_t)((rx_buf[5] << 8) | rx_buf[4]);

    return 0;
}

// Convert raw rate to degrees per second
double convert_to_dps(int16_t raw_rate) {
    return (double)raw_rate / SCALE_FACTOR;
}

// Log data function
int log_data(FILE *fp, struct timespec ts, gyro_data_t data) {
    char timestamp[30];
    struct tm tm_info;

    // Format timestamp
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    // Write data to file
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x_rate, data.y_rate, data.z_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_fd != -1) {
        gpioSetMode(GPIO_LINE, PI_INPUT); // Release GPIO line
        gpioSetMode(GPIO_LINE, PI_INPUT); // Release GPIO line
