#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 3900000 // 3.9 MHz
#define MPU6050_CS_PIN 8
#define LED_PIN 17
#define BUFFER_SIZE 64
#define GYRO_SENSITIVITY 131.0
#define THRESHOLD 200.0

// MPU6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global variables
int spi_fd;
int running = 1;

// Circular buffer structure
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void process_gyro_data(int16_t x, int16_t y, int16_t z);
void check_threshold(int16_t x, int16_t y, int16_t z);
void print_buffer(void);
void signal_handler(int signal);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
