#include <errno.h>

// Define the I2C address of the Si1145 sensor
#define SI1145_I2C_ADDR 0x5A

// Define the register addresses for ambient light and proximity
#define SI1145_REG_ALS_VIS_DATA0 0x20
#define SI1145_REG_PS1_DATA0 0x22

// Define the GPIO pin for the LED
#define LED_GPIO 17

// Define the log file name
#define LOG_FILE "biometric_log.txt"

// Global variables for I2C file descriptor and log file pointer
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_register(int fd, uint8_t reg_addr, uint8_t *data, int len);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void control_led(int gpio_pin, int state);
void signal_handler(int signum);

// Structure to hold sensor data
typedef struct {
    uint16_t ambient_light;
    uint16_t proximity;
} sensor_data_t;

// Function to read a single byte from a register
int i2c_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retrying...\n", reg_addr, strerror(errno));
            usleep(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg_addr);
    return -1; // Failure
}

// Function to write a single byte to a register
int i2c_write_register(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = write(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X): %s. Retrying...\n", reg_addr, strerror(errno));
            usleep(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X).\n", reg_addr);
    return -1; // Failure
}

// Function to read ambient light and proximity data from the sensor
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t buffer[4];

    if (i2c_read_register(fd, SI1145_REG_ALS_VIS_DATA0, buffer, 4) != 0) {
        fprintf(stderr, "Failed to read ambient light data.\n");
        return -1;
    }

    *ambient_light = (buffer[1] << 8) | buffer[0];

    if (i2c_read_register(fd, SI1145_REG_PS1_DATA0, buffer, 4) != 0) {
        fprintf(stderr, "Failed to read proximity data.\n");
        return -1;
    }

    *proximity = (buffer[1] << 8) | buffer[0];

    return 0;
}

// Function to log the sensor data to a file
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to the file immediately
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d.\n", gpio_pin);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);

        // Close the I2C file descriptor
        if (i2c_fd != -1) {
            close(i2c_fd);
        }

        // Close the log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        // Turn off the LED
        control_led(LED_GPIO, 0);

        // Exit the program
        exit(0);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set the LED GPIO pin as output
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", LED_GPIO);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t ambient_light, proximity;

        // Read sensor data
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            // Log the data
