#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define SENSITIVITY 200.0 // LSB/deg/s
#define SAMPLE_RATE 100.0 // Hz
#define SAMPLE_PERIOD (1000000000 / SAMPLE_RATE) // microseconds
#define LOG_FILE "gyro_data.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int spi_init();
int spi_read_register(int channel, uint8_t reg_addr, uint8_t *data);
int spi_write_register(int channel, uint8_t reg_addr, uint8_t data);
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// SPI Initialization
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI Read Register
int spi_read_register(int channel, uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(channel, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// SPI Write Register
int spi_write_register(int channel, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit
    tx_buf[1] = data;

    if (spiXfer(channel, tx_buf, NULL, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }
    return 0;
}

// Read Gyroscope Data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint8_t x_data, y_data;

    if (spi_read_register(SPI_CHANNEL, GYRO_X_REG, &x_data) != 0) {
        fprintf(stderr, "Error reading X rate\n");
        data.x_rate = 0; // Set to 0 to avoid using garbage value
    } else {
        data.x_rate = (int16_t)x_data;
    }

    if (spi_read_register(SPI_CHANNEL, GYRO_Y_REG, &y_data) != 0) {
        fprintf(stderr, "Error reading Y rate\n");
        data.y_rate = 0; // Set to 0 to avoid using garbage value
    } else {
        data.y_rate = (int16_t)y_data;
    }

    return data;
}

// Log Data to File
void log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_rate,Y_rate\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        usleep(SAMPLE_PERIOD);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

