#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define ANGULAR_RATE_THRESHOLD 20.0 // degrees/second
#define CIRCULAR_BUFFER_SIZE 100

// Data Structures
typedef struct {
    time_t timestamp;
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global Variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int initialize_gpio();
int initialize_spi();
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
void add_to_circular_buffer(circular_buffer_t *buffer, int16_t x_rate, int16_t y_rate);
int check_angular_rate_threshold(int16_t x_rate, int16_t y_rate, double threshold);
void signal_handler(int signal);

// Function Implementations
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Read X-axis data
    tx_buffer[0] = 0x02; // RATE_XL
    tx_buffer[1] = 0x00; // Dummy byte for reading
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "SPI Xfer (X-axis) failed\n");
        return -1;
    }
    *x_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[0]);

    // Read Y-axis data
    tx_buffer[0] = 0x03; // RATE_YL
    tx_buffer[1] = 0x00; // Dummy byte for reading
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "SPI Xfer (Y-axis) failed\n");
        return -1;
    }
    *y_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[0]);

    return 0;
}

void add_to_circular_buffer(circular_buffer_t *buffer, int16_t x_rate, int16_t y_rate) {
    pthread_mutex_lock(&buffer->mutex);

    buffer->data[buffer->head].timestamp = time(NULL);
    buffer->data[buffer->head].x_rate = x_rate;
    buffer->data[buffer->head].y_rate = y_rate;

    buffer->head = (buffer->head + 1) % CIRCULAR_BUFFER_SIZE;

    if (buffer->count < CIRCULAR_BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % CIRCULAR_BUFFER_SIZE;
    }

    pthread_mutex_unlock(&buffer->mutex);
}

int check_angular_rate_threshold(int16_t x_rate, int16_t y_rate, double threshold) {
    double magnitude = sqrt(x_rate * x_rate + y_rate * y_rate);
    return (magnitude > threshold) ? 1 : 0;
}

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize
    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Circular Buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    pthread_mutex_init(&gyro_buffer.mutex, NULL);

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_rate, y_rate;
    double threshold = ANGULAR_RATE_THRESHOLD;

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            add_to_circular_buffer(&gyro_buffer, x_rate, y_rate);

            if (check_angular_rate_threshold(x_rate, y_rate, threshold)) {
                gpioWrite(LED_GPIO, 1); // Turn on LED
            } else {
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(10); // 10ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    pthread_mutex_destroy(&gyro_buffer.mutex);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

