    int step = (int)(((float)duty_cycle / duration_seconds) * 100.0);
    int current_duty_cycle = 0;

    for (int i = 0; i <= duration_seconds; ++i) {
        current_duty_cycle = (current_duty_cycle + step) % PWM_RANGE;
        if (current_duty_cycle < 0) current_duty_cycle += PWM_RANGE;
        control_lamp(gpio_pin, 1); // Turn lamp on
        gpioPWM(gpio_pin, current_duty_cycle);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 10ms (100Hz)
        control_lamp(gpio_pin, 0); // Turn lamp off
        gpioPWM(gpio_pin, 0);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 10ms (100Hz)
        if (i == duration_seconds) {
            break;
        }
    }
}

// Function to run the sunset simulation
void run_sunset_simulation(int duration_seconds) {
    if (duration_seconds < 1 || duration_seconds > 3600) {
        fprintf(stderr, "Invalid duration. Duration must be between 1 and 3600 seconds.\n");
        return;
    }

    printf("Starting sunset simulation...\n");

    // Fade lamp 1
    fade_lamp(LAMP1_PIN, duration_seconds);
    printf("Lamp 1 faded for %d seconds\n", duration_seconds);

    // Fade lamp 2
    fade_lamp(LAMP2_PIN, duration_seconds);
    printf("Lamp 2 faded for %d seconds\n", duration_seconds);

    // Fade lamp 3
    fade_lamp(LAMP3_PIN, duration_seconds);
    printf("Lamp 3 faded for %d seconds\n", duration_seconds);

    printf("Sunset simulation complete.\n");
}

// Function to cleanup GPIO pins and terminate pigpio
void cleanup_gpio() {
    printf("Cleaning up GPIO and terminating pigpio...\n");
    control_lamp(LAMP1_PIN, 0); // Turn off lamp 1
    control_lamp(LAMP2_PIN, 0); // Turn off lamp 2
    control_lamp(LAMP3_PIN, 0); // Turn off lamp 3
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int duration_seconds = 0;

    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the command-line argument
    if (sscanf(argv[1], "%d", &duration_seconds) != 1 || duration_seconds < 1 || duration_seconds > 3600) {
        fprintf(stderr, "Invalid duration. Please provide a value between 1 and 3600 seconds.\n");
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Run the sunset simulation
    run_sunset_simulation(duration_seconds);

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

