#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_TIME 0x21
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(int *touch_status);
void control_relay(int touch_status);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, cleaning up...");
}

// Initialize MPR121
int initialize_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Error: Failed to reset MPR121");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Stop Mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("Error: Failed to set stop mode");
        return -1;
    }

    // Enable Electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Error: Failed to enable electrode 0");
        return -1;
    }

    // Touch Threshold
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_message("Error: Failed to set touch threshold");
        return -1;
    }

    // Release Threshold
    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_message("Error: Failed to set release threshold");
        return -1;
    }

    // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, DEBOUNCE_TIME) < 0) {
        log_message("Error: Failed to set debounce");
        return -1;
    }

    // Charge Time
    if (i2cWriteByteData(i2c_handle, 0x5C, CHARGE_TIME) < 0) {
        log_message("Error: Failed to set charge time");
        return -1;
    }

    // Run Mode
    if (i2cWriteByteData(i2c_handle, 0x5E, RUN_MODE) < 0) {
        log_message("Error: Failed to set run mode");
        return -1;
    }

    log_message("MPR121 initialized successfully");
    return 0;
}

// Read touch status
int read_touch_status(int *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Error: Failed to read touch status");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Control relay
void control_relay(int touch_status) {
    static int relay_state = 0; // 0 = off, 1 = on
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    log_message(relay_state ? "Relay ON" : "Relay OFF");
}

// Log message with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C device");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int touch_status;
    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x01) {
                gpioDelay(100000); // 100ms debounce
                control_relay(touch_status);
            }
        } else {
            log_message("Error reading touch status, retrying...");
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off on exit
    gpioTerminate();

    log_message("Program terminated");
    return 0;
}

