#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Debounce interval (milliseconds)
#define DEBOUNCE_INTERVAL 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor(int gpio_pin);
void activate_alarm(int buzzer_pin, int led_pin);
void deactivate_alarm(int buzzer_pin, int led_pin);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor(int gpio_pin) {
    int i, low_count = 0;
    for (i = 0; i < 3; i++) {
        if (gpioRead(gpio_pin) == 0) { // Flame detected (LOW)
            low_count++;
        }
        gpioDelay(DEBOUNCE_INTERVAL * 1000); // Delay for debouncing
    }

    if (low_count == 3) {
        return 1; // Flame detected
    } else {
        return 0; // No flame detected
    }
}

// Function to activate the alarm (buzzer and LED)
void activate_alarm(int buzzer_pin, int led_pin) {
    gpioWrite(buzzer_pin, 1); // Turn on buzzer
    gpioWrite(led_pin, 1);    // Turn on LED
}

// Function to deactivate the alarm (buzzer and LED)
void deactivate_alarm(int buzzer_pin, int led_pin) {
    gpioWrite(buzzer_pin, 0); // Turn off buzzer
    gpioWrite(led_pin, 0);    // Turn off LED
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Release GPIO resources
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioWrite(LED_PIN, 0);    // Turn off LED
    gpioTerminate();          // Terminate pigpio

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
