// Define GPIO pins for the solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define the dispensing duration (half of 1000ms)
#define DISPENSE_DURATION 500

// Define the total dispensing time (5 seconds)
#define DISPENSE_TIME 5000

// Define the log file name
#define LOG_FILE "dispense_log.txt"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense_cycle();
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Deactivating solenoids and exiting.\n");
        program_running = 0; // Set the flag to exit the main loop

        // Deactivate both solenoids
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);

        // Terminate pigpio
        gpioTerminate();

        // Close the log file
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            fclose(log_file);
        } else {
            perror("Error closing log file");
        }

        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO17 as an output
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as an output
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to perform a single dispense cycle
int dispense_cycle() {
    // Activate solenoid 1 for half the duration
    if (gpioWrite(SOLENOID_1_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid 1\n");
        return 1;
    }
    gpioDelay(DISPENSE_DURATION * 1000); // Delay for half the duration (microseconds)
    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1\n");
        return 1;
    }

    // Activate solenoid 2 for the remaining half the duration
    if (gpioWrite(SOLENOID_2_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid 2\n");
        return 1;
    }
    gpioDelay(DISPENSE_DURATION * 1000); // Delay for the remaining half the duration (microseconds)
    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2\n");
        return 1;
    }

    return 0; // Indicate success
}

// Function to log a dispense event to a file
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1; // Indicate failure
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Solenoid 1: GPIO%d, Solenoid 2: GPIO%d, Duration: %d ms\n",
            timestamp, solenoid1_pin, solenoid2_pin, duration_ms);

    fclose(log_file);
    return 0; // Indicate success
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense_cycle() != 0) {
            fprintf(stderr, "Dispense cycle failed. Exiting.\n");
            break; // Exit the loop if dispense fails
        }

        // Log the dispense event
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Failed to log dispense event. Continuing.\n");
        }

        // Wait for the specified dispensing time
        gpioDelay(DISPENSE_TIME * 1000); // Delay for the specified time (microseconds)
    }

    // Deactivate solenoids and terminate pigpio (in case the loop exited unexpectedly)
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return 0;
}

