#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable pins for L298N
#define MOTOR_ENA 24
#define MOTOR_ENB 25

// Ultrasonic sensor GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 5

// PID parameters
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Tilt error range
#define TILT_ERROR_MIN -10.0
#define TILT_ERROR_MAX 10.0

// Distance error range
#define DISTANCE_ERROR_MIN 2.0
#define DISTANCE_ERROR_MAX 400.0

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20.0

// PWM range
#define PWM_RANGE 255

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void enable_motor(int motor);
void disable_motor(int motor);
float calculate_pid(float tilt_error, float distance);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// PID variables
float integral = 0.0;
float previous_error = 0.0;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Generate tilt error
        float tilt_error = (float)(rand() % (TILT_ERROR_MAX - TILT_ERROR_MIN + 1)) + TILT_ERROR_MIN;

        // Generate distance error
        float distance_error = (float)(rand() % (DISTANCE_ERROR_MAX - DISTANCE_ERROR_MIN + 1)) + DISTANCE_ERROR_MIN;

        // Calculate PID output
        float pid_output = calculate_pid(tilt_error, distance_error);

        // Set motor speeds
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        // Apply tilt compensation
        if (tilt_error > 0) {
            motor_a_speed -= 50; // Reduce speed if tilt is positive
        } else if (tilt_error < 0) {
            motor_a_speed += 50; // Increase speed if tilt is negative
        }

        // Apply distance compensation
        if (distance_error > 0) {
            motor_b_speed -= 50; // Reduce speed if distance is greater than threshold
        } else if (distance_error < 0) {
            motor_b_speed += 50; // Increase speed if distance is less than threshold
        }

        // Set motor directions
        set_motor_direction(1, (tilt_error > 0) ? 1 : 0); // Motor A direction
        set_motor_direction(2, (distance_error > 0) ? 1 : 0); // Motor B direction

        // Set motor speeds
        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        // Log data
        log_data(tilt_error, distance_error, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50); // 50 ms delay
    }

    // Stop motors
    disable_motor(1);
    disable_motor(2);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

// Initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_ENB, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Enable motors
    enable_motor(1);
    enable_motor(2);

    return 0;
}

// Set motor speed
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR_A_FORWARD, speed);
        gpioPWM(MOTOR_A_BACKWARD, 0);
    } else if (motor == 2) {
        gpioPWM(MOTOR_B_FORWARD, speed);
        gpioPWM(MOTOR_B_BACKWARD, 0);
    }
}

// Set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        if (direction == 1) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
        } else if (direction == 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
        }
    } else if (motor == 2) {
        if (direction == 1) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
        } else if (direction == 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
        }
    }
}

// Enable motor
void enable_motor(int motor) {
    gpioWrite(MOTOR_ENA, 1);
}

// Disable motor
void disable_motor(int motor) {
    gpioWrite(MOTOR_ENA, 0);
}

// Calculate PID output
float calculate_pid(float tilt_error, float distance_error) {
    // Tilt compensation
    float tilt_integral = integral + tilt_error * 0.1; // Integrate tilt error
    float tilt_proportional = Kp * tilt_error;

    // Distance compensation
    float distance_integral = previous_error + distance_error * 0.1; // Integrate distance error
    float distance_proportional = Kp * distance_error;

    // Calculate PID output
    float pid_output = tilt_integral + tilt_proportional + distance_integral + distance_proportional;

    // Clamp PID output
    if (pid_output > 255) {
        pid_output = 255;
    } else if (pid_output < -255) {
        pid_output = -255;
    }

    // Update previous error
    previous_error = distance_error;

    return pid_output;
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping motors and exiting.\n", signal);
}

