// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Global variable to track relay state
int relay_state = 0;

// Function prototypes
int read_touch_sensor();
void toggle_relay(int current_state);
void cleanup_handler(int signum);

// Signal handler for Ctrl+C
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    gpioWrite(RELAY_PIN, 0); // Turn off relay on exit
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay(int current_state) {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay is now %s\n", relay_state ? "ON" : "OFF");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor for the touch sensor
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            // Debounce delay
            gpioDelay(50000); // 50 ms
            if (read_touch_sensor() == 1) {
                toggle_relay(relay_state);
            }
        }

        gpioDelay(10000); // Check every 10 ms
    }

    return 0;
}

