#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Default ALSA device name
#define DEFAULT_DEVICE "/dev/dsp"

// Default sensitivity scaling factor
#define DEFAULT_SENSITIVITY 1.0

// RMS amplitude threshold for color mapping
#define RMS_THRESHOLD 0.05

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Global variables
snd_pcm_t *pcm_handle;
int alsa_available = 0;

// Function prototypes
int init_alsa(const char *device_name);
int capture_audio(snd_pcm_t *pcm_handle, int buffer_size, short *buffer);
double calculate_rms(const short *buffer, int buffer_size);
RGBColor map_amplitude_to_color(double rms_amplitude, double sensitivity);
void set_led_color(int red, int green, int blue);
void cleanup_alsa(snd_pcm_t *pcm_handle);
void cleanup_gpio();
void signal_handler(int signal);
void print_status(const char *message);
void print_error(const char *message);

// Function to initialize ALSA
int init_alsa(const char *device_name) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device for capture
    if ((err = snd_pcm_open(&pcm_handle, device_name, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        return -1;
    }

    // Set sample format to 16-bit signed little-endian
    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting sample format: %s\n", snd_strerror(err));
        return -1;
    }

    // Set number of channels to 1
    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, 1)) < 0) {
        fprintf(stderr, "Error setting number of channels: %s\n", snd_strerror(err));
        return -1;
    }

    // Set sample rate to 8000 Hz
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, 8000, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        return -1;
    }

    // Set period size to 1024 frames
    if ((err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, 1024, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

// Function to capture audio samples
int capture_audio(snd_pcm_t *pcm_handle, int buffer_size, short *buffer) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, buffer_size)) != buffer_size) {
        fprintf(stderr, "Error reading audio: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

// Function to calculate the RMS amplitude of the audio samples
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_of_squares / buffer_size);
}

// Function to map the RMS amplitude to RGB color values
RGBColor map_amplitude_to_color(double rms_amplitude, double sensitivity) {
    RGBColor color;

    // Normalize RMS amplitude to the range [0, 1]
    double normalized_amplitude = rms_amplitude / sensitivity;

    // Map the normalized amplitude to the RGB color space
    if (normalized_amplitude < 0.0) {
        color.red = 0;
        color.green = 0;
        color.blue = 0;
    } else if (normalized_amplitude < 0.25) {
        // Cool colors
        color.red = 0;
        color.green = sqrt(normalized_amplitude * 0.75);
        color.blue = 1 - sqrt(normalized_amplitude * 0.75);
    } else if (normalized_amplitude < 0.5) {
        // Warm colors
        color.red = sqrt(normalized_amplitude * 0.75);
        color.green = 1 - sqrt(normalized_amplitude * 0.75);
        color.blue = 0;
    } else {
        // Neutral colors
        color.red = 1 - normalized_amplitude * 2;
        color.green = normalized_amplitude * 2;
        color.blue = 0;
    }

    return color;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to cleanup ALSA resources
void cleanup_alsa(snd_pcm_t *pcm_handle) {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_alsa(pcm_handle);
    cleanup_gpio();
    exit(0);
}

// Function to print status messages
void print_status(const char *message) {
    printf("%s\n", message);
}

// Function to print error messages
void print_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main(int argc, char *argv[]) {
    int buffer_size = 1024;
    double sensitivity = DEFAULT_SENSITIVITY;

    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value. Using default value of %.2f\n", DEFAULT_SENSITIVITY);
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    // Check if ALSA is available
    alsa_available = (init_alsa(DEFAULT_DEVICE) == 0);
    if (!alsa_available) {
        printf("ALSA not available. Simulating audio input with sine wave.\n");
        // Simulate audio input with a sine wave
        for (int i = 0; i < buffer_size; i++) {
            short buffer[2];
            buffer[0] = (short)(sin(2 * M_PI * 1000 * i / 44100) * 32767); // 1000 Hz sine wave
            buffer[1] = (short)(sin(2 * M_PI * 2000 * i / 44100) * 32767); // 2000 Hz sine wave
            capture_audio(pcm_handle, buffer_size, buffer);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(BLUE_PIN, 1000); // 1 kHz

    // Initialize ALSA
    if (init_alsa(DEFAULT_DEVICE) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup_gpio();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    short buffer[buffer_size];
    double rms_amplitude;
    RGBColor rgb_color;
    int red, green, blue;

    while (1) {
        // Capture audio samples
        if (capture_audio(pcm_handle, buffer_size, buffer) == 0) {
            // Calculate RMS amplitude
            rms_amplitude = calculate_rms(buffer, buffer_size);

            // Map amplitude to color
            rgb_color = map_amplitude_to_color(rms_amplitude, sensitivity);

            // Set LED color
            set_led_color(rgb_color.red, rgb_color.green, rgb_color.blue);
        } else {
            print_error("Failed to capture audio. Retrying...");
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    return 0;
}

