#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 13
#define RELAY3_PIN 15
#define RELAY4_PIN 23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000000 for 10-bit resolution)
#define PWM_RANGE 1000000

// Define sunrise/sunset duration (seconds)
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600

// Define daytime duration (seconds)
#define DAYTIME_DURATION 1800

// Define nighttime duration (seconds)
#define NIGHTTIME_DURATION 14400

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the duty cycle of a relay (simulated PWM)
void set_relay_duty_cycle(int pin, int duty_cycle) {
    // Convert duty cycle to a percentage (0-100)
    int percentage = (int)(((float)duty_cycle / PWM_RANGE) * 100.0);

    // Set the GPIO pin as output
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return;
    }

    // Set the duty cycle (simulated PWM)
    gpioPWM(pin, percentage);
}

// Function to simulate sunrise
void sunrise() {
    printf("Starting sunrise phase...\n");
    for (int i = 0; i < SUNRISE_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, i);
        set_relay_duty_cycle(RELAY2_PIN, i);
        set_relay_duty_cycle(RELAY3_PIN, i);
        set_relay_duty_cycle(RELAY4_PIN, i);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Sunrise complete.\n");
}

// Function to simulate daytime
void daytime() {
    printf("Starting daytime phase...\n");
    for (int i = 0; i < DAYTIME_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, 100);
        set_relay_duty_cycle(RELAY2_PIN, 100);
        set_relay_duty_cycle(RELAY3_PIN, 100);
        set_relay_duty_cycle(RELAY4_PIN, 100);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Daytime complete.\n");
}

// Function to simulate sunset
void sunset() {
    printf("Starting sunset phase...\n");
    for (int i = 0; i < SUNSET_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, 100 - i);
        set_relay_duty_cycle(RELAY2_PIN, 100 - i);
        set_relay_duty_cycle(RELAY3_PIN, 100 - i);
        set_relay_duty_cycle(RELAY4_PIN, 100 - i);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Sunset complete.\n");
}

// Function to simulate nighttime
void nighttime() {
    printf("Starting nighttime phase...\n");
    for (int i = 0; i < NIGHTTIME_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, 0);
        set_relay_duty_cycle(RELAY2_PIN, 0);
        set_relay_duty_cycle(RELAY3_PIN, 0);
        set_relay_duty_cycle(RELAY4_PIN, 0);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Nighttime complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the GPIO chip
    int chip_id = gpiod_chip_open_by_name("gpiochip0");
    if (chip_id < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", chip_id);
        gpioTerminate();
        return 1;
    }

    // Get the GPIO lines for the relays
    int relay1_line = gpiod_chip_get_line(chip_id, RELAY1_PIN);
    int relay2_line = gpiod_chip_get_line(chip_id, RELAY2_PIN);
    int relay3_line = gpiod_chip_get_line(chip_id, RELAY3_PIN);
    int relay4_line = gpiod_chip_get_line(chip_id, RELAY4_PIN);

    if (relay1_line < 0 || relay2_line < 0 || relay3_line < 0 || relay4_line < 0) {
        fprintf(stderr, "Error getting GPIO line for one or more relays\n");
        gpiod_chip_close(chip_id);
        gpioTerminate();
        return 1;
    }

    // Request the GPIO lines as outputs
    if (gpiod_line_request_output(relay1_line, "light_control", 0) < 0 ||
        gpiod_line_request_output(relay2_line, "light_control", 0) < 0 ||
        gpiod_line_request_output(relay3_line, "light_control", 0) < 0 ||
        gpiod_line_request_output(relay4_line, "light_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip_id);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip_id);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    // Clean up GPIO resources
    gpiod_line_release(relay1_line);
    gpiod_line_release(relay2_line);
    gpiod_line_release(relay3_line);
    gpiod_line_release(relay4_line);
    gpiod_chip_close(chip_id);
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

