#include <fcntl.h>
#include <pigpio.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL 200 // milliseconds
#define VIDEO_DURATION 5       // seconds
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define SERVER_URL "http://yourserver.com/api/motion_events"

volatile sig_atomic_t program_running = 1;

// Structure to hold the server response
typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

// Callback function to write the server response to memory
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (ptr == NULL) {
        printf("Not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Function to execute the curl command
int execute_curl(const char *url, const char *filename) {
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    chunk.memory = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            FILE *fp = fopen(filename, "wb");
            if (fp) {
                fwrite(chunk.memory, chunk.size, 1, fp);
                fclose(fp);
                printf("File saved to %s\n", filename);
            } else {
                fprintf(stderr, "Error opening file for writing: %s\n", filename);
            }
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    free(chunk.memory);
    return (res == CURLE_OK) ? 0 : 1;
}

// Function to log motion events to a file
int log_motion_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return 1;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to generate a timestamp string
char *generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(21 * sizeof(char)); // ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to record a video using raspivid
int record_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d000", filename, VIDEO_DURATION * 1000);
    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid command");
        return 1;
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return 1;
    }
    return 0;
}

// Function to send motion event data to the server
int send_motion_event(const char *timestamp) {
    CURL *curl;
    CURLcode res;
    char json_data[256];
    snprintf(json_data, sizeof(json_data), "{\"timestamp\": \"%s\"}", timestamp);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("Motion event data sent to server\n");
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : 1;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Install signal handler
    signal(SIGINT, signal_handler);

    time_t last_motion_time = 0;

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int motion_detected = gpioRead(GPIO_PIN);

        if (motion_detected == 0) { // Obstacle detected (LOW signal)
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_INTERVAL) {
                char *timestamp = generate_timestamp();
                if (timestamp != NULL) {
                    printf("Motion detected at %s\n", timestamp);

                    if (execute_curl(SERVER_URL, VIDEO_DIR "motion_event.h264") != 0) {
                        fprintf(stderr, "Failed to send video to server\n");
                    }

                    if (log_motion_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event\n");
                    }

                    if (send_motion_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to send motion event to server\n");
                    }

                    free(timestamp);
                    last_motion_time = current_time;
                }
            }
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

