#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int initialize_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the MPU-6050
int initialize_mpu6050() {
    int status;

    // Wake up the MPU-6050
    status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050 (status = %d)\n", status);
        return -1;
    }

    // Set the gyroscope full-scale range to ±250°/s
    status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range (status = %d)\n", status);
        return -1;
    }

    // Set the sample rate divider to 125 Hz
    status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x07);
    if (status != 0) {
        fprintf(stderr, "Error: Could not set sample rate divider (status = %d)\n", status);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int status;

    // Read all gyroscope data in one block
    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data (status = %d)\n", status);
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to log data to a CSV file
void log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp with millisecond precision
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", (long int)time(NULL) % 1000);

    // Write data to CSV file
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    int status;
    gyro_data_t gyro_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (status = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (initialize_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data = read_gyro_data();

        // Log data
        log_data(gyro_data);

        // Sleep for 10 milliseconds (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

