#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Constants
#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 4000 // 4 meters
#define MAX_PULSE_WIDTH 23200 // 23.2 ms
#define TIMEOUT_MS 100
#define TIMESTAMP_NS_SIZE 16
#define TIMESTAMP_SIZE 8

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static int socket_desc;
static struct sockaddr_in server_addr;
static pthread_mutex_t mutex;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void *sensor_thread(void *arg);
void *network_thread(void *arg);
void signal_handler(int signal);
void log_data(double timestamp_ns, double distance_cm);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 µs trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;

        // Handle wrap-around
        if (pulse_width > 4294967295) {
            pulse_width -= 4294967296;
        }

        if (pulse_width > MAX_PULSE_WIDTH || pulse_width < 0) {
            pthread_mutex_lock(&mutex);
            pulse_width = 0; // Reset if invalid
            pthread_mutex_unlock(&mutex);
        }
    }
}

// Thread function for the ultrasonic sensor
void *sensor_thread(void *arg) {
    while (running) {
        trigger_pulse();
        gpioDelay(200); // 200 ms delay between measurements
    }
    pthread_exit(NULL);
}

// Thread function for network communication
void *network_thread(void *arg) {
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[TIMESTAMP_NS_SIZE + 1]; // Buffer to hold timestamp and distance
    double timestamp_ns, distance_cm;

    while (running) {
        // Accept incoming connection
        if (accept(socket_desc, (struct sockaddr *)&client_addr, &client_len) < 0) {
            perror("Accept failed");
            break;
        }

        // Get timestamp
        timestamp_ns = time_time();

        // Read distance from shared memory (not implemented here, but would be in a real implementation)
        // pthread_mutex_lock(&mutex);
        // distance_cm = pulse_width / 1000000.0; // Convert pulse width to seconds
        // pulse_width = 0; // Reset pulse width after reading
        // pthread_mutex_unlock(&mutex);

        // Format data as a string
        snprintf(buffer, TIMESTAMP_NS_SIZE + 1, "%.0f,%.2f\n", timestamp_ns, distance_cm);

        // Send data to client
        if (send(socket_desc, buffer, strlen(buffer), 0) < 0) {
            perror("Send failed");
            break;
        }

        // Close the socket
        close(socket_desc);
        socket_desc = -1; // Reset socket descriptor
        break;
    }
    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Cancel callbacks
    pthread_mutex_lock(&mutex);
    pulse_start = 0;
    pulse_end = 0;
    pulse_width = 0;
    pthread_mutex_unlock(&mutex);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close socket
    if (socket_desc != -1) {
        close(socket_desc);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    // Terminate threads
    pthread_cancel(sensor_thread_id);
    pthread_cancel(network_thread_id);

    exit(0);
}

// Function to log data to file
void log_data(double timestamp_ns, double distance_cm) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp_ns);
