// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 µs trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;

        // Handle wrap-around
        if (pulse_width > 4294967295) {
            pulse_width -= 4294967296;
        }

        if (pulse_width > MAX_PULSE_WIDTH || pulse_width < 0) {
            pthread_mutex_lock(&mutex);
            pulse_width = 0; // Reset if invalid
            pthread_mutex_unlock(&mutex);
        }
    }
}

// Thread function for the ultrasonic sensor
void *sensor_thread(void *arg) {
    while (running) {
        trigger_pulse();
        gpioDelay(200); // 200 ms delay between measurements
    }
