        snprintf(buffer, TIMESTAMP_NS_SIZE + 1, "%.0f,%.2f\n", timestamp_ns, distance_cm);

        // Send data to client
        if (send(socket_desc, buffer, strlen(buffer), 0) < 0) {
            perror("Send failed");
            break;
        }

        // Close the socket
        close(socket_desc);
        socket_desc = -1; // Reset socket descriptor
        break;
    }
    pthread_exit(NULL);
}

