#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void detect_fall(double magnitude);
void detect_impact(double magnitude);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure for LIS3DH configuration
typedef struct {
    int ctrl_reg1;
    int ctrl_reg4;
} lis3dh_config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure LIS3DH
int configure_lis3dh() {
    // 100 Hz data rate and ±2g full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calculate acceleration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to detect freefall
void detect_fall(double magnitude) {
    if (magnitude < freefall_threshold) {
        printf("Freefall detected!\n");
        activate_buzzer();
    }
}

// Function to detect impact
void detect_impact(double magnitude) {
    if (magnitude > impact_threshold) {
        printf("Impact detected!\n");
        activate_buzzer();
    }
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(1000);           // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Detect fall and impact
            detect_fall(magnitude);
            detect_impact(magnitude);
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        gpioDelay(10); // Delay for 10ms (100 Hz data rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

