#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Stepper motor parameters
#define STEPS_PER_REVOLUTION 2048
#define STEPS_PER_MM 10
#define STEP_DELAY_US 1000 // 1000 microseconds = 1 millisecond

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to set the GPIO pins for a single step
void set_step(int motor, int step) {
    int in1, in2, in3, in4;

    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    gpioWrite(in1, (step == 0) ? 0 : 1);
    gpioWrite(in2, (step == 0) ? 1 : 0);
    gpioWrite(in3, (step == 0) ? 0 : 1);
    gpioWrite(in4, (step == 0) ? 0 : 1);
}

// Function to move a motor a specified number of steps
void move_steps(int motor, int steps, int direction) {
    int i;
    for (i = 0; i < steps && program_running; i++) {
        set_step(motor, direction);
        gpioDelay(STEP_DELAY_US);
    }
}

// Function to draw a square
void draw_square(int side_length) {
    move_steps(1, side_length * STEPS_PER_MM, 1); // Move X-axis
    move_steps(2, side_length * STEPS_PER_MM, -1); // Move Y-axis
    move_steps(1, side_length * STEPS_PER_MM, -1); // Move X-axis
    move_steps(2, side_length * STEPS_PER_MM, 1); // Move Y-axis
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Draw a square
    draw_square(50); // Draw a square with 50mm sides

    // Stop motors and release resources
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    gpioTerminate();

    return 0;
}

