#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_SHUTDOWN_DELAY 5 // seconds
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG5 0x24
#define CTRL_REG6 0x25
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
char *log_file = DEFAULT_LOG_FILE;
int shutdown_delay = DEFAULT_SHUTDOWN_DELAY;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
float calculate_g(int16_t raw_value);
void log_event(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the LIS3DH sensor
int configure_sensor(int i2c_handle) {
    // Enable X, Y, and Z axes, 100 Hz data rate, and ±2g range
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    // Set full-scale range to +/- 2g and high-resolution mode (12-bit)
    if (i2cWriteByteData(i2c_handle, CTRL_REG5, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG5\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG6, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG6\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the LIS3DH sensor
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = calculate_g(raw_x);
    *y = calculate_g(raw_y);
    *z = calculate_g(raw_z);

    return 0;
}

// Calculate g-force value from raw acceleration data
float calculate_g(int16_t raw_value) {
    return (float)raw_value / 2048.0f;
}

// Log high-acceleration event to file
void log_event(float x, float y, float z) {
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", log_file);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %.4f g, Y: %.4f g, Z: %.4f g\n", timestamp, x, y, z);
    fclose(fp);
}

// Shutdown the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:l:d:")) != -1) {
        switch (opt) {
            case 'a':
                if (sscanf(optarg, "%x", &i2c_address) != 1 || i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                if (sscanf(optarg, "%f", &threshold) != 1 || threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            case 'l':
                log_file = optarg;
                break;
            case 'd':
                shutdown_delay = atoi(optarg);
                if (shutdown_delay <= 0) {
                    fprintf(stderr, "Invalid shutdown delay. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold] [-l log_file] [-d shutdown_delay]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_event(x, y, z);
                shutdown_system();
                break; // Exit loop after shutdown
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Continuing...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

