#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

// Define buffer size
#define BUFFER_SIZE 5

// Define alert duration
#define ALERT_DURATION 2000 // milliseconds

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer structure
typedef struct {
    SensorReadings readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer sensor_buffer;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void add_reading(CircularBuffer *cb, int left, int center, int right);
int check_line_following(SensorReadings readings);
void control_motor(int direction);
void log_reading(SensorReadings readings);
void cleanup();
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a reading to the circular buffer
void add_reading(CircularBuffer *cb, int left, int center, int right) {
    cb->readings[cb->head].left = left;
    cb->readings[cb->head].center = center;
    cb->readings[cb->head].right = right;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Check line following logic
int check_line_following(SensorReadings readings) {
    if (readings.left == 0 && readings.center == 0 && readings.right == 0) {
        return 1; // Line following
    } else if (readings.left == 0) {
        return 2; // Turn left
    } else if (readings.center == 0) {
        return 3; // Turn right
    } else {
        return 4; // Stop
    }
}

// Control motor (placeholder)
void control_motor(int direction) {
    switch (direction) {
        case 1: // Forward
            gpioWrite(ALERT_PIN, 0); // LED off
            break;
        case 2: // Left turn
            gpioWrite(ALERT_PIN, 1); // LED on
            gpioWrite(ALERT_PIN, 0); // LED on
            break;
        case 3: // Right turn
            gpioWrite(ALERT_PIN, 0); // LED off
            gpioWrite(ALERT_PIN, 1); // LED on
            break;
        case 4: // Stop
            gpioWrite(ALERT_PIN, 0); // LED off
            break;
        default:
            fprintf(stderr, "Invalid motor direction\n");
            break;
    }
}

// Log sensor readings
void log_reading(SensorReadings readings) {
    printf("Left: %d, Center: %d, Right: %d\n", readings.left, readings.center, readings.right);
}

// Cleanup GPIO resources
void cleanup() {
    gpioWrite(ALERT_PIN, 0); // Turn off LED/buzzer
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

int main() {
    // Initialize circular buffer
    init_circular_buffer(&sensor_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Add readings to circular buffer
        add_reading(&sensor_buffer, left, center, right);

        // Check line following logic
        int direction = check_line_following(sensor_buffer.readings[sensor_buffer.head]);

        // Control motor
        control_motor(direction);

        // Log readings
        log_reading(sensor_buffer.readings[sensor_buffer.head]);

        // Check for alert condition
        if (sensor_buffer.count == 5 && sensor_buffer.readings[sensor_buffer.head].center == 0) {
            printf("Alert: No line detected for 5 consecutive readings!\n");
            gpioWrite(ALERT_PIN, 1); // Turn on LED/buzzer
            gpioDelay(ALERT_DURATION * 1000); // Delay for alert duration
            gpioWrite(ALERT_PIN, 0); // Turn off LED/buzzer
        }

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    return 0;
}

