    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Add readings to circular buffer
        add_reading(&sensor_buffer, left, center, right);

        // Check line following logic
        int direction = check_line_following(sensor_buffer.readings[sensor_buffer.head]);

        // Control motor
        control_motor(direction);

        // Log readings
        log_reading(sensor_buffer.readings[sensor_buffer.head]);

        // Check for alert condition
        if (sensor_buffer.count == 5 && sensor_buffer.readings[sensor_buffer.head].center == 0) {
            printf("Alert: No line detected for 5 consecutive readings!\n");
            gpioWrite(ALERT_PIN, 1); // Turn on LED/buzzer
            gpioDelay(ALERT_DURATION * 1000); // Delay for alert duration
            gpioWrite(ALERT_PIN, 0); // Turn off LED/buzzer
        }

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    return 0;
}

