#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define THRESHOLD 5.0 // mT
#define RELAY_GPIO 17
#define POLL_DELAY_MS 100
#define MAX_POLL_ATTEMPTS 50
#define MEASUREMENT_COMMAND 0x01
#define MEASUREMENT_STATUS 0xC1
#define FIELD_DATA_REG 0xC0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int read_sensor_data(int *field_raw);
float convert_to_mT(int field_raw);
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    int field_raw;
    float field_mT;
} sensor_data_t;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *field_raw) {
    int status;
    int retries = 0;

    // Start measurement
    while (retries < MAX_POLL_ATTEMPTS) {
        status = i2cWriteByteData(i2c_handle, MEASUREMENT_COMMAND, MEASUREMENT_COMMAND);
        if (status >= 0) break; // Success
        else {
            log_event("I2C write failed, retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    if (retries == MAX_POLL_ATTEMPTS) {
        log_event("I2C write failed after multiple attempts, skipping cycle.");
        return -1; // Indicate failure
    }

    // Poll for measurement status
    while (retries < MAX_POLL_ATTEMPTS) {
        status = i2cReadByteData(i2c_handle, MEASUREMENT_STATUS);
        if (status >= 0) break; // Success
        else {
            log_event("I2C read failed, retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    if (retries == MAX_POLL_ATTEMPTS) {
        log_event("I2C read failed after multiple attempts, skipping cycle.");
        return -1; // Indicate failure
    }

    // Read field data
    char buffer[2];
    retries = 0;
    while (retries < MAX_POLL_ATTEMPTS) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, FIELD_DATA_REG, buffer, 2);
        if (bytes_read == 2) break; // Success
        else {
            log_event("I2C read failed, retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    if (retries == MAX_POLL_ATTEMPTS) {
        log_event("I2C read failed after multiple attempts, skipping cycle.");
        return -1; // Indicate failure
    }

    *field_raw = (buffer[0] << 8) | buffer[1];
    return 0; // Success
}

// Function to convert raw data to mT
float convert_to_mT(int field_raw) {
    return (float)field_raw * 0.01;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        log_event("Received SIGINT, shutting down...");
        program_running = 0;
    }
}

// Cleanup function
void cleanup() {
    log_event("Cleaning up...");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    int field_raw;
    float field_mT;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&field_raw) == 0) {
            // Convert to mT
            field_mT = convert_to_mT(field_raw);

            // Check threshold
            if (field_mT > THRESHOLD) {
                log_event("Threshold exceeded, activating relay");
                control_relay(1); // Activate relay
                log_event("Relay activated");
            } else {
                log_event("Threshold not exceeded, deactivating relay");
                control_relay(0); // Deactivate relay
                log_event("Relay deactivated");
            }
        } else {
            log_event("Failed to read sensor data, skipping cycle");
        }

        gpioDelay(POLL_DELAY_MS * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

