#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int setup_gpio(int gpio_pin);
int setup_socket(int port);
int handle_client(int client_fd);
void log_event(const char *event);
void cleanup();
void signal_handler(int signum);

// Structure to hold configuration data
typedef struct {
    int port;
    int gpio_pin;
    char *log_file_path;
} Config;

Config config = {PORT, GPIO_PIN, LOG_FILE};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup GPIO
    if (setup_gpio(config.gpio_pin) != 0) {
        fprintf(stderr, "GPIO setup failed\n");
        cleanup();
        return 1;
    }

    // Setup socket
    server_fd = setup_socket(config.port);
    if (server_fd == -1) {
        fprintf(stderr, "Socket setup failed\n");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", config.port);

    // Main loop to accept connections
    while (program_running) {
        struct sockaddr_in client_addr;
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, NULL);
        if (client_fd < 0) {
            perror("Accept failed");
            continue; // Continue listening for new connections
        }

        printf("Connection accepted\n");
        handle_client(client_fd);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to setup GPIO
int setup_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pin);
        return 1;
    }
    return 0;
}

// Function to setup socket
int setup_socket(int port) {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    return server_fd;
}

// Function to handle client connection
int handle_client(int client_fd) {
    char buffer[1024] = {0};
    ssize_t valread;

    // Receive a message from the client
    valread = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        return 1;
    }
    buffer[valread] = '\0'; // Null-terminate the received string

    printf("Received: %s\n", buffer);

    // Process the command
    if (strcmp(buffer, "ON") == 0 || strcmp(buffer, "OFF") == 0) {
        char *command = buffer;
        char *endptr;

        if (strstr(command, " ") == NULL) {
            fprintf(stderr, "Invalid command format\n");
            log_event("Invalid command format");
            return 1;
        }

        char *command_lower = strstr(command, " ") ? strstr(command, " ") - command : command;
        char *command_upper = strstr(command, " ") ? strstr(command, " ") + 1 : command;

        if (strcmp(command_lower, "on") == 0) {
            gpioWrite(config.gpio_pin, 1); // Turn relay ON
            log_event("Relay ON");
        } else if (strcmp(command_upper, "off") == 0) {
            gpioWrite(config.gpio_pin, 0); // Turn relay OFF
            log_event("Relay OFF");
        } else {
            fprintf(stderr, "Invalid command: %s\n", command);
            log_event("Invalid command");
            return 1;
        }
    } else {
        fprintf(stderr, "Unknown command: %s\n", buffer);
        log_event("Unknown command");
    }

    // Send a response back to the client
    char response[100];
    snprintf(response, sizeof(response), "OK\n");
    send(client_fd, response, strlen(response), 0);

    return 0;
}

// Function to log events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Log file not opened\n");
    }
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");

    // Close sockets
    if (server_fd != -1) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Turn off relay
    gpioWrite(config.gpio_pin, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        program_running = 0;
    }
}

