#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD_LOW 5.0
#define FLOW_THRESHOLD_HIGH 10.0
#define START_MEASUREMENT_CMD 0x3608
#define READ_COMMAND_CMD 0x0000
#define DATA_LENGTH 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr);
int write_i2c_command(int handle, uint16_t command);
int read_i2c_data(int handle, uint8_t *data);
int verify_crc(uint8_t data[], int len);
float convert_flow_rate(int16_t raw_flow);
void control_relay(float flow1, float flow2);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
} sensor_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C handle
int open_i2c_handle(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to write a command to the I2C device
int write_i2c_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command 0x%04X: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int read_i2c_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to verify the CRC-8 checksum
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0xFF);
}

// Function to convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / 1500.0;
}

// Function to control the relay based on flow rates
void control_relay(float flow1, float flow2) {
    static int relay_state = 0; // 0 = de-energized, 1 = energized
    if (flow1 < FLOW_THRESHOLD_LOW || flow2 < FLOW_THRESHOLD_LOW) {
        relay_state = 1; // Energize the relay
    } else if (flow1 > FLOW_THRESHOLD_HIGH && flow2 > FLOW_THRESHOLD_HIGH) {
        relay_state = 0; // De-energize the relay
    }
    gpioWrite(RELAY_GPIO, relay_state);
}

