            continue; // Skip to the next iteration
        }
        if (read_i2c_data(i2c_handle2, data2) != 0) {
            fprintf(stderr, "Failed to read data from sensor 2\n");
            continue; // Skip to the next iteration
        }

        // Verify CRC
        if (!verify_crc(data1, DATA_LENGTH) || !verify_crc(data2, DATA_LENGTH)) {
            fprintf(stderr, "CRC check failed for sensor 1 or sensor 2\n");
            continue; // Skip to the next iteration
        }

