#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define DRY_TO_WET_THRESHOLD 3
#define DRY_WINDOW_TIME 600 // 600 ms = 0.6 seconds
#define MOTOR_RUN_TIME 5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int enable);
int check_dry_window();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    log_message(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Control the DC motor
int control_motor(int enable) {
    if (enable) {
        gpioWrite(MOTOR_ENA_PIN, 1);
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_message(LOG_INFO, "Motor enabled");
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Convert seconds to microseconds
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_message(LOG_INFO, "Motor stopped");
    } else {
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_message(LOG_INFO, "Motor disabled");
    }
    return 0;
}

// Check if the window is dry for DRY_WINDOW_TIME
int check_dry_window() {
    int dry_count = 0;
    for (int i = 0; i < DRY_WINDOW_TIME; i++) {
        if (read_rain_sensor() == 0) { // Assuming 0 means dry
            dry_count++;
        }
        gpioDelay(200000); // 200 ms delay
    }
    return (dry_count == DRY_WINDOW_TIME) ? 1 : 0;
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_message(LOG_INFO, "Rain-activated window controller started");

    int dry_window_active = 0;
    int rain_detected = 0;

    while (program_running) {
        int rain_detected_local = read_rain_sensor();

        if (rain_detected_local == 0) { // Rain detected (LOW signal)
            rain_detected = 1;
            log_message(LOG_INFO, "Rain detected");
        } else {
            rain_detected = 0;
        }

        if (rain_detected && !dry_window_active) {
            log_message(LOG_INFO, "Dry window active, triggering motor");
            if (check_dry_window()) {
                log_message(LOG_INFO, "Dry window confirmed, initiating motor");
                control_motor(1); // Enable motor
                dry_window_active = 1;
            }
        }

        if (rain_detected && dry_window_active) {
            log_message(LOG_INFO, "Rain persisted, suppressing motor trigger");
            dry_window_active = 0;
        }

        gpioDelay(200000); // 200 ms delay
    }

    // Stop the motor
    control_motor(0);

    // Terminate pigpio
    gpioTerminate();

    log_message(LOG_INFO, "Rain-activated window controller stopped");

    return 0;
}

