    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_pressed = read_lock_button();
        int unlock_pressed = read_unlock_button();

        // Debouncing and button press logic
        if (lock_pressed && !unlock_pressed) {
            lock_servo();
            gpioDelay(500000); // Debounce delay (0.5 seconds)
        }
        if (!lock_pressed && unlock_pressed) {
            unlock_servo();
            gpioDelay(500000); // Debounce delay (0.5 seconds)
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms delay
    }

    // Clean up and exit
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    return 0;
}

