#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_DURATION 60 // seconds
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, const char *timestamp);
int get_iso8601_timestamp(char *timestamp_str, size_t size);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int pir_pin;
    int led_pin;
    int led_on_duration;
    char *log_file_name;
} Config;

Config config = {PIR_SENSOR_PIN, LED_PIN, LED_ON_DURATION, LOG_FILE};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        // If motion is detected
        if (motion_detected) {
            // Activate LED
            if (control_led(1) == 0) {
                // Log event
                if (log_event("Motion Detected", NULL) != 0) {
                    fprintf(stderr, "Failed to log motion detected event.\n");
                }
            } else {
                fprintf(stderr, "Failed to activate LED.\n");
            }

            // Wait for LED on duration
            gpioDelay(config.led_on_duration * 1000000); // Convert seconds to microseconds

            // Deactivate LED
            if (control_led(0) != 0) {
                fprintf(stderr, "Failed to deactivate LED.\n");
            }

            // Log event
            if (log_event("LED Deactivated", NULL) != 0) {
                fprintf(stderr, "Failed to log LED deactivated event.\n");
            }
        }

        // Poll every 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

// Initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Control LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Log event to file
int log_event(const char *event_type, const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s,%s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Get ISO 8601 timestamp
int get_iso8601_timestamp(char *timestamp_str, size_t size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    if (strftime(timestamp_str, size, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return 1;
    }
    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

