#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 200

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_BASELINE_FILTER_CONFIG 0x5C
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFT_RESET 0x80

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status();
void toggle_relay(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize the MPR121 sensor
int mpr121_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, MPR121_SOFT_RESET);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121: %d\n", status);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Baseline Filtering
    status = i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTER_CONFIG, 0x00); // MHD
    if (status < 0) {
        fprintf(stderr, "Error: Failed to configure baseline filter: %d\n", status);
        return -1;
    }

    // Configure FFI/SFI/CDT
    status = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C); // Enable all electrodes
    if (status < 0) {
        fprintf(stderr, "Error: Failed to configure FFI/SFI/CDT: %d\n", status);
        return -1;
    }

    return 0;
}

// Read the touch status from the MPR121
int read_touch_status() {
    char buf[2];
    int status = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read touch status: %d\n", status);
        return -1;
    }

    return ((int)buf[1] << 8) | (int)buf[0];
}

// Toggle the relay state
void toggle_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121-controlled relay program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check if electrode 0 is touched (bit 0 of the first 12 bits)
        if (touch_status & 0x01) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read touch status after debounce
            touch_status = read_touch_status();
            if (touch_status < 0) {
                fprintf(stderr, "Error reading touch status after debounce, retrying...\n");
                gpioDelay(100); // Wait before retrying
                continue;
            }

            // Toggle relay state
            toggle_relay(1); // Turn relay ON
            gpioDelay(500);   // Keep relay ON for 500ms
            toggle_relay(0); // Turn relay OFF
            gpioDelay(500);   // Keep relay OFF for 500ms
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

