#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <stdarg.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define PWM_DUTY_CYCLE_US (PWM_PERIOD_US / 2)
#define PIR_THRESHOLD 500 // Adjust this value based on your PIR sensor

// Global variables for graceful shutdown
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int setup_socket();
void handle_client(int client_fd);
void send_response(int client_fd, const char *response);
void log_message(int priority, const char *message, ...);
void cleanup();
void signal_handler(int signum);

// Function to initialize GPIO using libgpiod
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to set up the TCP server socket
int setup_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }
    log_message(LOG_INFO, "Server listening on port 5000");
    return 0;
}

// Function to handle client connection
void handle_client(int client_fd) {
    char buffer[1024] = {0};
    int valread;

    valread = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        log_message(LOG_ERR, "Error receiving data");
        return;
    }
    buffer[valread] = '\0';
    log_message(LOG_INFO, "Received: %s", buffer);

    if (strcmp(buffer, "SERVO") == 0) {
        int angle;
        if (sscanf(buffer, "SERVO %d", &angle) == 1) {
            if (angle >= 0 && angle <= 180) {
                gpioServo(SERVO_GPIO, angle * 1000 / 180 + PWM_DUTY_CYCLE_US);
                char response[100];
                snprintf(response, sizeof(response), "SERVO %d", angle);
                send_response(client_fd, response);
            } else {
                log_message(LOG_ERR, "Invalid servo angle: %d", angle);
                send_response(client_fd, "Invalid servo angle");
            }
        } else {
            log_message(LOG_ERR, "Invalid SERVO command");
            send_response(client_fd, "Invalid SERVO command");
        }
    } else if (strcmp(buffer, "PIR") == 0) {
        int pir_state = gpioRead(PIR_GPIO);
        char response[100];
        snprintf(response, sizeof(response), "PIR: %d", pir_state);
        send_response(client_fd, response);
    } else {
        log_message(LOG_ERR, "Unknown command: %s", buffer);
        send_response(client_fd, "Unknown command");
    }
}

// Function to send a response to the client
void send_response(int client_fd, const char *response) {
    char buffer[1024] = {0};
    snprintf(buffer, sizeof(buffer), "%s\n", response);
    send(client_fd, buffer, strlen(buffer), 0);
}

// Function to log messages using syslog and file
void log_message(int priority, const char *message, ...) {
    va_list args;
    va_start(args, message);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s [%s] ", timestamp, message);
    vsyslog(priority, log_entry, args);

    // Also log to file
    fprintf(log_file, "%s [%s] ", timestamp, message);
    va_end(args);
}

// Function to perform cleanup before exiting
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");

    if (server_fd != -1) {
        close(server_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    log_message(LOG_INFO, "Cleanup complete");
    closelog();
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d", signum);

    if (signum == SIGINT || signum == SIGTERM) {
        log_message(LOG_INFO, "Shutting down...");
        cleanup();
        exit(0);
    }
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed");
        closelog();
        return 1;
    }

    // Set up socket
    if (setup_socket() != 0) {
        log_message(LOG_ERR, "Socket setup failed");
        cleanup();
        closelog();
        return 1;
    }

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file");
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Security system started");

    // Main loop to accept connections
    while (1) {
        struct sockaddr_in client_address;
        int client_fd, *new_sock;
        socklen_t client_len = sizeof(client_address);

        new_sock = (struct sockaddr *)&client_address;

        client_fd = accept(server_fd, new_sock, &client_len);
        if (client_fd < 0) {
            log_message(LOG_ERR, "Accept failed");
            continue; // Continue accepting connections
        }

        log_message(LOG_INFO, "Connection accepted");

        handle_client(client_fd);
    }

    return 0;
}

