#define I2C_BUS "/dev/i2c-1"
#define HX711_ADDR 0x40
#define SOLENOID_PIN 25
#define WEIGHT_THRESHOLD 1000.0
#define WEIGHT_SCALE 1.0
#define WEIGHT_OFFSET 0.0
#define POLLING_INTERVAL_MS 500
#define MAX_RETRIES 3
#define TARE_READINGS 10

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_hx711(int fd, int *raw_value);
float calculate_weight(int raw_value, float scale, float offset);
void control_solenoid(int pin, int state, int duration_ms);
void log_message(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        terminate = 1;
    }
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HX711_ADDR) < 0) {
        log_message(LOG_ERR, "Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    log_message(LOG_INFO, "I2C initialized successfully");
    return 0;
}

// Read data from HX711
int read_hx711(int fd, int *raw_value) {
    unsigned char data[3];
    int retries = 0;

    // Set HX711 to Channel A, Gain 128
    while (retries < MAX_RETRIES) {
        if (write(fd, "A", 1) != 1) {
            log_message(LOG_ERR, "Failed to set HX711 channel");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }
        if (write(fd, "128", 3) != 3) {
            log_message(LOG_ERR, "Failed to set HX711 gain");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }
        break; // Exit retry loop if successful
    }

    if (retries == MAX_RETRIES) {
        log_message(LOG_ERR, "Max retries reached for HX711 configuration");
        return -1;
    }

    // Wait for data ready (DOUT low)
    int timeout_start = time(NULL);
    while (1) {
        int count = 0;
        while (read(fd, &data[count], 1) == 1) {
            count++;
            if (count > 2) break; // Check for 3 bytes read
        }
        if (count == 3) break; // Data ready
        usleep(1000); // Wait 1ms
        if (time(NULL) - timeout_start > 1) {
            log_message(LOG_ERR, "Timeout waiting for HX711 data ready");
            return -1;
        }
    }

    *raw_value = ((data[0] << 8) | data[1]) >> 1; // MSB-first, right-shift by 1

    return 0;
}

// Calculate weight
float calculate_weight(int raw_value, float scale, float offset) {
    return (raw_value - offset) / scale;
}

// Control solenoid
void control_solenoid(int pin, int state, int duration_ms) {
    gpioWrite(pin, state);
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
    gpioWrite(pin, 0); // Ensure solenoid is off after delay
}

// Log message
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

// Cleanup resources
void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
    close(i2c_fd);
    closelog();
}

