    float threshold = WEIGHT_THRESHOLD;
    float scale = WEIGHT_SCALE;
    int duration_ms = POLLING_INTERVAL_MS;
    int raw_value, average_raw, tare_sum = 0;
    int tare_count = 0;
    int i2c_retries = 0;

    // Parse command-line arguments
    while (1) {
        if (argc > 1) {
            threshold = atof(argv[1]);
        }
        if (argc > 2) {
            scale = atof(argv[2]);
        }
        if (argc > 3) {
            duration_ms = atoi(argv[3]);
        }
        if (argc > 4) {
            i2c_retries = atoi(argv[4]);
        }
        break; // Exit loop after parsing arguments
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    log_message(LOG_INFO, "Starting tare...");
    tare_sum = 0;
    tare_count = 0;
    while (tare_count < TARE_READINGS && !terminate) {
        if (read_hx711(i2c_fd, &raw_value) == 0) {
            tare_sum += raw_value;
            tare_count++;
        } else {
