            i2c_retries++;
            if (i2c_retries > MAX_RETRIES) {
                log_message(LOG_ERR, "Max tare retries reached, exiting");
                cleanup();
                return 1;
            }
            usleep(10000); // Wait 10ms before retrying
        }
        usleep(10000); // Wait 10ms
    }
    float tare_average = (float)tare_sum / tare_count;
    log_message(LOG_INFO, "Tare average: %f", tare_average);

    // Main loop
    while (!terminate) {
        log_message(LOG_INFO, "Starting weight measurement...");
        tare_sum = 0;
        tare_count = 0;
        for (int i = 0; i < 5; i++) {
            if (read_hx711(i2c_fd, &raw_value) == 0) {
                tare_sum += raw_value;
                tare_count++;
            } else {
