                usleep(10000); // Wait 10ms before retrying
            }
            usleep(10000); // Wait 10ms
        }
        float average_raw = (float)tare_sum / tare_count;
        float weight = calculate_weight(average_raw, scale, tare_average);

        log_message(LOG_INFO, "Raw: %d, Average: %f, Weight: %f", average_raw, average_raw, weight);

        if (weight > threshold) {
            log_message(LOG_INFO, "Weight exceeds threshold!");
            control_solenoid(SOLENOID_PIN, 1, duration_ms);
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Wait for next poll
    }

