#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <time.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define QOS 0

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set relay to OFF initially
    return 0;
}

// Function to set the relay state
void set_relay_state(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Function to handle MQTT connection
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, QOS);
    } else {
        char *connack_string = mosquitto_connack_string(result);
        log_message(LOG_ERR, connack_string);
        free(connack_string);
    }
}

// Function to handle MQTT disconnection
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    log_message(LOG_INFO, "Disconnected from MQTT broker");
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    running = 0; // Exit the main loop
    exit(0);
}

// Function to handle MQTT message arrival
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    char *payload = message->payload;
    int payload_len = message->payloadlen;

    if (payload == NULL || payload_len == 0) {
        log_message(LOG_ERR, "Invalid payload received");
        return;
    }

    if (strcmp(payload, "ON") == 0) {
        set_relay_state(1); // Turn relay ON
    } else if (strcmp(payload, "OFF") == 0) {
        set_relay_state(0); // Turn relay OFF
    } else {
        log_message(LOG_ERR, "Invalid command received");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    log_message(LOG_INFO, "Received SIGINT, shutting down...");
    running = 0;
}

// Signal handler for SIGTERM (Terminate process)
void sigterm_handler(int sig) {
    log_message(LOG_INFO, "Received SIGTERM, shutting down...");
    running = 0;
}

int main() {
    // Open syslog
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        closelog();
        return 1;
    }

    // Initialize mosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Start the mosquitto loop in a separate thread
    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

