#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_A_PWM 13
#define MOTOR_A_ENCODER_A_PHASE 4
#define MOTOR_A_ENCODER_B_PHASE 5

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define MOTOR_B_PWM 19
#define MOTOR_B_ENCODER_A_PHASE 6
#define MOTOR_B_ENCODER_B_PHASE 12

#define TARGET_RPM 50.0
#define PWM_FREQUENCY 10000 // 10 kHz
#define SAMPLE_PERIOD_MS 100
#define STALL_TIMEOUT_S 2

// Global variables
volatile int motor_a_ticks = 0;
volatile int motor_b_ticks = 0;
volatile int motor_a_encoder_count = 0;
volatile int motor_b_encoder_count = 0;
volatile int running = 1;

// Function prototypes
void motor_a_forward();
void motor_a_backward();
void motor_a_stop();
void motor_b_forward();
void motor_b_backward();
void motor_b_stop();
void motor_a_set_speed(int speed);
void motor_b_set_speed(int speed);
void motor_a_set_direction(int direction);
void motor_b_set_direction(int direction);
void encoder_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double calculate_integral(double current_integral, double previous_integral, double dt);
double calculate_proportional(double error, double kp);
double calculate_pwm(double proportional, double integral, double dt);
void signal_handler(int signal);

// Motor control functions
void motor_a_forward() {
    gpioWrite(MOTOR_A_IN1, 1);
    gpioWrite(MOTOR_A_IN2, 0);
}

void motor_a_backward() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 1);
}

void motor_a_stop() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
}

void motor_b_forward() {
    gpioWrite(MOTOR_B_IN3, 1);
    gpioWrite(MOTOR_B_IN4, 0);
}

void motor_b_backward() {
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 1);
}

void motor_b_stop() {
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
}

// Speed control functions
void motor_a_set_speed(int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;
    int pwm_duty = (int)(speed * 2.55); // Scale to 0-255
    gpioPWM(MOTOR_A_PWM, pwm_duty);
}

void motor_b_set_speed(int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;
    int pwm_duty = (int)(speed * 2.55); // Scale to 0-255
    gpioPWM(MOTOR_B_PWM, pwm_duty);
}

// Direction control functions
void motor_a_set_direction(int direction) {
    if (direction == 1) {
        gpioWrite(MOTOR_A_IN2, 1);
    } else {
        gpioWrite(MOTOR_A_IN2, 0);
    }
}

void motor_b_set_direction(int direction) {
    if (direction == 1) {
        gpioWrite(MOTOR_B_IN4, 1);
    } else {
        gpioWrite(MOTOR_B_IN4, 0);
    }
}

// Encoder ISR function
void encoder_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    int delta = current_tick - last_tick;

    if (delta > 0) {
        motor_a_ticks += delta;
        motor_b_ticks += delta;

        if (gpio == MOTOR_A_ENCODER_A_PHASE) {
            motor_a_encoder_count += delta;
        } else if (gpio == MOTOR_A_ENCODER_B_PHASE) {
            motor_a_encoder_count -= delta;
        } else if (gpio == MOTOR_B_ENCODER_A_PHASE) {
            motor_b_encoder_count += delta;
        } else if (gpio == MOTOR_B_ENCODER_B_PHASE) {
            motor_b_encoder_count -= delta;
        }

        last_tick = current_tick;
    }
}

// RPM calculation function
double calculate_rpm(int ticks) {
    double rpm = (double)ticks / (double)(SAMPLE_PERIOD_MS * 1000.0) * 60.0;
    return rpm;
}

// PI controller functions
double calculate_integral(double current_integral, double previous_integral, double dt) {
    return current_integral + (dt * (previous_integral - current_integral));
}

double calculate_proportional(double error, double kp) {
    return kp * error;
}

double calculate_pwm(double proportional, double integral, double dt) {
    double error = TARGET_RPM - calculate_rpm(motor_a_encoder_count);
    double integral_value = calculate_integral(integral, 0, dt);
    return proportional + integral_value;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    motor_a_stop();
    motor_b_stop();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Set ISR for encoder A
    gpioSetISRFuncEx(MOTOR_A_ENCODER_A_PHASE, RISING_EDGE, 0, encoder_isr, NULL);
    gpioSetISRFuncEx(MOTOR_A_ENCODER_B_PHASE, RISING_EDGE, 0, encoder_isr, NULL);

    // Set ISR for encoder B
    gpioSetISRFuncEx(MOTOR_B_ENCODER_A_PHASE, RISING_EDGE, 0, encoder_isr, NULL);
    gpioSetISRFuncEx(MOTOR_B_ENCODER_B_PHASE, RISING_EDGE, 0, encoder_isr, NULL);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    double dt = 0.01; // 10 ms
    double integral_a = 0;
    double integral_b = 0;
    double previous_error_a = 0;
    double previous_error_b = 0;
    double last_pwm_a = 0;
    double last_pwm_b = 0;
    double last_rpm_a = 0;
    double last_rpm_b = 0;
    double last_stall_time_a = 0;
    double last_stall_time_b = 0;
    int last_stall_a = 0;
    int last_stall_b = 0;
    int stall_a = 0;
    int stall_b = 0;

    while (running) {
        // Calculate RPM
        double rpm_a = calculate_rpm(motor_a_ticks);
        double rpm_b = calculate_rpm(motor_b_ticks);

        // Calculate errors
        double error_a = TARGET_RPM - rpm_a;
        double error_b = TARGET_RPM - rpm_b;

        // Calculate integrals
        integral_a = calculate_integral(integral_a, previous_error_a, dt);
        integral_b = calculate_integral(integral_b, previous_error_b, dt);

        // Calculate proportional gains
        double proportional_a = calculate_proportional(error_a, 0.5);
        double proportional_b = calculate_proportional(error_b, 0.5);

        // Calculate PWM duty cycles
        double pwm_a = calculate_pwm(proportional_a, integral_a, dt);
        double pwm_b = calculate_pwm(proportional_b, integral_b, dt);

        // Clamp PWM duty cycles
        pwm_a = fmin(pwm_a, 255);
        pwm_a = fmax(pwm_a, 0);
        pwm_b = fmin(pwm_b, 255);
        pwm_b = fmax(pwm_b, 0);

        // Set motor directions and speeds
        motor_a_set_speed(pwm_a);
        motor_a_set_direction(stall_a ? 1 : 0);
        motor_a_set_direction(stall_a ? 1 : 0);
        previous_error_a = error_a;
        last_pwm_a = pwm_a;
        last_rpm_a = rpm_a;

        motor_b_set_speed(pwm_b);
        motor_b_set_direction(stall_b ? 1 : 0);
        motor_b_set_direction(stall_b ? 1 : 0);
        previous_error_b = error_b;
        last_pwm_b = pwm_b;
        last_rpm_b = rpm_b;

        // Stall detection
        if (stall_a) {
            stall_time_a += dt;
            if (stall_time_a > STALL_TIMEOUT_S) {
                printf("Motor A Stall Detected!\n");
                stall_a = 0;
            }
        } else {
            stall_time_a = 0;
        }

        if (stall_b) {
            stall_time_b += dt;
            if (stall_time_b > STALL_TIMEOUT_S) {
                printf("Motor B Stall Detected!\n");
                stall_b = 0;
            }
        } else {
            stall_time_b = 0;
        }

        // Print RPM and PWM duty cycle
        printf("Motor A: RPM = %.2f, PWM = %d, Motor B: RPM = %.2f, PWM = %d\n", rpm_a, pwm_a, rpm_b, pwm_b);

        // Sleep for the sample period
        gpioDelay(SAMPLE_PERIOD_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    motor_a_stop();
    motor_b_stop();
    gpioTerminate();

    return 0;
}

