#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LED_GPIO 17
#define DUSK_LUX 50
#define DAWN_LUX 200
#define HYSTERESIS 50
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
float read_lux();
void control_relay(float lux);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int led_gpio;
    int dusk_lux;
    int dawn_lux;
    int hysteresis;
    char log_file[64];
} config_t;

config_t config = {
    I2C_BUS,
    BH1750_ADDR,
    LED_GPIO,
    DUSK_LUX,
    DAWN_LUX,
    HYSTERESIS,
    LOG_FILE
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value. Retrying in 5 seconds.\n");
            log_data(-1, -1); // Log error
            sleep(5);
            continue;
        }

        control_relay(lux);
        log_data(lux, gpioRead(LED_GPIO));

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    char command[1] = {0x21}; // One-Time High-Resolution Mode 2
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, command, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        log_data(-1, -1); // Log error
        return -1.0;
    }

    gpioDelay(180); // Wait 180 ms

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        log_data(-1, -1); // Log error
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Control the relay based on lux value
void control_relay(float lux) {
    static int relay_state = 0; // 0 = OFF, 1 = ON
    static time_t last_change_time = 0;

    if (lux < config.dusk_lux && relay_state == 0) {
        // Turn on relay
        gpioWrite(LED_GPIO, 1);
        relay_state = 1;
        last_change_time = time(NULL);
        log_data(lux, relay_state);
    } else if (lux > config.dawn_lux && relay_state == 1) {
        // Turn off relay
        gpioWrite(LED_GPIO, 0);
        relay_state = 0;
        last_change_time = time(NULL);
        log_data(lux, relay_state);
    } else if (difftime(time(NULL), last_change_time) > 60) {
        // Hysteresis: Turn off relay if no change for 60 seconds
        gpioWrite(LED_GPIO, 0);
        relay_state = 0;
        last_change_time = time(NULL);
        log_data(lux, relay_state);
    }
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED on exit
    gpioTerminate();
}

