#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 50

volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function to handle signals (Ctrl+C, etc.)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_GPIO, 0); // Turn off the relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int touch_detected = 0;
    int i;

    // Read the sensor value
    int current_value = gpioRead(TOUCH_SENSOR_GPIO);

    // Debounce the sensor
    for (i = 0; i < 5; i++) {
        if (gpioRead(TOUCH_SENSOR_GPIO) == current_value) {
            touch_detected = 1;
            break;
        }
        gpioDelay(1000); // 1 ms delay
    }

    return touch_detected;
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state; // Toggle the state
    gpioWrite(RELAY_GPIO, relay_state); // Write the new state to the relay
    printf("Relay toggled to: %s\n", relay_state ? "ON" : "OFF");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as input
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 17 as output
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_GPIO, 0);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read the touch sensor
        if (read_touch_sensor()) {
            // Toggle the relay if the sensor is HIGH
            toggle_relay();
        }

        // Sleep for 10 ms
        gpioDelay(10000); // 10 ms
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    gpioTerminate();
    return 0;
}

