#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define VALVE_GPIO 27
#define PULSES_PER_LITER 450.0
#define THRESHOLD_HIGH 5.0
#define THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT_US 1000000 // 1 second
#define SAMPLE_INTERVAL_S 1

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
bool solenoid_state = false; // 0 = open, 1 = closed
FILE *log_file = NULL;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulse_count);
void control_valve(double lpm);
void log_data(double lpm, bool valve_state);
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    // Reopen the solenoid valve
    gpioWrite(VALVE_GPIO, 1); // Open the valve
    pthread_mutex_lock(&pulse_mutex);
    solenoid_state = true;
    pthread_mutex_unlock(&pulse_mutex);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Interrupt service routine (ISR) for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_valve(double lpm) {
    if (lpm > THRESHOLD_HIGH && !solenoid_state) {
        gpioWrite(VALVE_GPIO, 0); // Close the valve
        solenoid_state = true;
        printf("Valve closed (LPM: %.2f)\n", lpm);
    } else if (lpm < THRESHOLD_LOW && solenoid_state) {
        gpioWrite(VALVE_GPIO, 1); // Open the valve
        solenoid_state = false;
        printf("Valve opened (LPM: %.2f)\n", lpm);
    }
}

// Function to log data to file
void log_data(double lpm, bool valve_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Valve: %s\n", timestamp, lpm, valve_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set initial valve state to open
    gpioWrite(VALVE_GPIO, 1);
    solenoid_state = true;

    // Set ISR for flow sensor GPIO
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor GPIO\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Wait for the sample interval
        sleep(SAMPLE_INTERVAL_S);

        // Reset pulse count
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
