#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"

// Default values
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_CALIBRATION_FACTOR 100.0

// HX711 GPIO pins
#define HX711_DATA_PIN 23
#define HX711_CLOCK_PIN 24

// Servo GPIO pin
#define SERVO_PIN 18

// Calibration factor
double calibration_factor = DEFAULT_CALIBRATION_FACTOR;

// Server IP and port
char server_ip[20] = DEFAULT_SERVER_IP;
int server_port = DEFAULT_SERVER_PORT;

// Target weight
double target_weight = 0.0;

// Servo pulse width range
int servo_min_pulsewidth = 1000;
int servo_max_pulsewidth = 2000;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int sockfd = -1;
FILE *log_file = NULL;

// Function prototypes
int read_config();
int initialize_gpio();
double read_hx711();
double calibrate_weight(double raw_value);
int set_servo_pulsewidth(int pulsewidth);
int send_data(double target_weight, double actual_weight);
int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
void cleanup();

// Function to read the configuration from the INI file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        // Trim whitespace from key and value
        while (*key == ' ') key++;
        while (*value == ' ') value++;
        while (value[strlen(value) - 1] == ' ') value[strlen(value) - 1] = 0;

        if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        } else if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "servo_min_pulsewidth") == 0) {
            servo_min_pulsewidth = atoi(value);
        } else if (strcmp(key, "servo_max_pulsewidth") == 0) {
            servo_max_pulsewidth = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    return 0;
}

// Function to read data from the HX711
double read_hx711() {
    int i;
    long value = 0;

    // Wait for DATA pin to go low
    int timeout = 1000; // Timeout after 1000 attempts
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 us
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1.0; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain setting (Channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (value & 0x800000) {
        value |= ~0xffffff;
    }

    return (double)value;
}

// Function to calibrate the raw HX711 reading to grams
double calibrate_weight(double raw_value) {
    return raw_value / calibration_factor;
}

// Function to set the servo pulse width
int set_servo_pulsewidth(int pulsewidth) {
    if (pulsewidth < servo_min_pulsewidth || pulsewidth > servo_max_pulsewidth) {
        fprintf(stderr, "Invalid servo pulsewidth: %d\n", pulsewidth);
        return -1;
    }
    gpioServo(SERVO_PIN, pulsewidth);
    return 0;
}

// Function to send data to the client
int send_data(double target_weight, double actual_weight) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "Target: %.2f, Actual: %.2f", target_weight, actual_weight);
    if (send(sockfd, buffer, strlen(buffer), 0) < 0) {
        perror("Error sending data");
        return -1;
    }
    return 0;
}

// Function to log the dispensing event
int log_event(double target_weight, double actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message);
    fflush(log_file);
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (sockfd != -1) {
        close(sockfd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Read configuration from file
    if (read_config() != 0) {
        fprintf(stderr, "Failed to read configuration file, using defaults.\n");
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(server_port);

    if (bind(sockfd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(sockfd, 1) < 0) {
        perror("Error listening on socket");
        cleanup();
        return 1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    // Accept connection and read data
    while (!terminate) {
        int client_sockfd = accept(sockfd, NULL, NULL);
        if (client_sockfd < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        char buffer[256];
        ssize_t bytes_received = recv(client_sockfd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Error receiving data");
            close(client_sockfd);
            continue; // Continue listening for other connections
        }
        buffer[bytes_received] = '\0';

        printf("Received: %s\n", buffer);

        // Parse target weight
        if (sscanf(buffer, "Target: %lf\n", &target_weight) != 1) {
            fprintf(stderr, "Invalid target weight format\n");
            log_event(target_weight, 0.0, "Invalid target weight format");
            close(client_sockfd);
            continue;
        }

        // Calibrate and dispense
        double raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading HX711, retrying...\n");
            log_event(target_weight, 0.0, "Error reading HX711");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }
        double actual_weight = calibrate_weight(raw_value);

        // Set servo pulse width
        if (set_servo_pulsewidth(round(actual_weight / 100.0 * (servo_max_pulsewidth - servo_min_pulsewidth) + servo_min_pulsewidth)) != 0) {
            fprintf(stderr, "Error setting servo pulse width\n");
            log_event(target_weight, actual_weight, "Error setting servo pulse width");
            continue;
        }

        // Wait for stabilization
        gpioDelay(1000); // Wait 1 second

        // Send data back to client
        if (send_data(target_weight, actual_weight) != 0) {
            fprintf(stderr, "Error sending data back to client\n");
            log_event(target_weight, actual_weight, "Error sending data back to client");
        }

        // Log the event
        log_event(target_weight, actual_weight, "None");

        // Close the connection
        close(client_sockfd);
    }

    // Clean up and exit
    cleanup();
    return 0;
}

