int read_touch_sensor();
int toggle_relay(int current_state);
int log_relay_state(int state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int touch_detected = 0;
    int i;

    // Read the sensor multiple times to debounce
    for (i = 0; i < 5; i++) {
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            touch_detected = 1;
            break;
        }
        gpioDelay(1); // Small delay for debouncing
    }

    return touch_detected;
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    int new_state = !current_state;
    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_PIN);
        return 1;
    }
    return new_state;
}

// Function to log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);

    // Release pigpio resources
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[]) {
    int touch_state;
    int relay_state = 0;

    // Parse command-line argument for debounce time
    if (argc > 1) {
        char *endptr;
        long debounce_milliseconds = strtol(argv[1], &endptr, 10);

        if (*endptr != '\0' || debounce_milliseconds <= 0) {
            fprintf(stderr, "Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
            debounce_time = DEFAULT_DEBOUNCE_TIME;
        } else {
            debounce_time = (int)debounce_milliseconds;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-controlled desk lamp started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        touch_state = read_touch_sensor();

        if (touch_state) {
            // Touch detected
            relay_state = toggle_relay(relay_state);
            log_relay_state(relay_state);
            gpioDelay(debounce_time); // Debounce delay
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

