#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US 20000 // 50 Hz (20 ms period)
#define MIN_PULSE_WIDTH_US 500
#define MAX_PULSE_WIDTH_US 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile int running = 1;
static int gpio_initialized = 0;
static int termfd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

int set_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d - %d)\n", MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    int pulse_width_us = MIN_PULSE_WIDTH_US + (int)(((float)(angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US));

    if (pulse_width_us < MIN_PULSE_WIDTH_US) {
        pulse_width_us = MIN_PULSE_WIDTH_US;
    } else if (pulse_width_us > MAX_PULSE_WIDTH_US) {
        pulse_width_us = MAX_PULSE_WIDTH_US;
    }

    int result = gpioServo(GPIO_PIN, pulse_width_us);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set angle %d to pulse width %d us (pigpio error: %d)\n", angle, pulse_width_us, result);
        return -1;
    }

    printf("Angle: %d, Pulse Width: %d us\n", angle, pulse_width_us);
    return 0;
}

int main() {
    struct termios old_termios;
    int fd;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    // Set up terminal for raw input
    fd = fileno(stdin);
    tcgetattr(fd, &old_termios);
    cfsetispeed(&old_termios, B115200);
    cfsetospeed(&old_termios, B115200);
    old_termios.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    old_termios.c_cc[VMIN] = 0;
    old_termios.c_cc[VTIME] = 5; // 0.5 seconds read timeout
    tcsetattr(fd, TCSANOW, &old_termios);

    // Open GPIO pin for PWM output
    fd = open("/dev/gpioPWM", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open /dev/gpioPWM: %s\n", strerror(errno));
        if (gpio_initialized) {
            gpioTerminate();
        }
        return 1;
    }

    // Set GPIO pin to PWM output mode
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", GPIO_PIN);
        close(fd);
        if (gpio_initialized) {
            gpioTerminate();
        }
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        close(fd);
        if (gpio_initialized) {
            gpioTerminate();
        }
        return 1;
    }

    // Main loop
    int angle = 90;
    char input;
    while (running) {
        printf("> ");
        if (fgets(&input, sizeof(input), stdin) == NULL) {
            if (running) {
                printf("Exiting...\n");
                running = 0;
            }
            break;
        }

        if (input == '+') {
            angle += 10;
        } else if (input == '-') {
            angle -= 10;
        } else if (input == 'q') {
            running = 0;
        } else {
            fprintf(stderr, "Error: Invalid input\n");
            running = 0; // Exit on invalid input
        }

        if (set_angle(angle) != 0) {
            running = 0; // Exit on error
        }
    }

    // Stop PWM and cleanup
    if (gpio_initialized) {
        gpioPWM(GPIO_PIN, 0); // Stop PWM
        gpioTerminate();
    }

    // Restore terminal settings
    if (termfd != -1) {
        tcsetattr(termfd, TCSANOW, &old_termios);
    }

    close(fd);
    if (termfd != -1) {
        close(termfd);
    }

    return 0;
}

