#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <math.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "motor_rpm.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int gpio_line;
    int debounce_ms;
    int sample_interval_sec;
    char *log_file_path;
} program_state_t;

// Function prototypes
int initialize_gpio(int gpio_pin, int debounce_ms);
int read_gpio(int gpio_line);
double calculate_rpm(int pulse_count, double sample_interval_sec);
void log_rpm(double rpm, const char *log_file_path);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio(int gpio_pin, int debounce_ms) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP); // Enable pull-up resistor

    int line = gpiod_chip_open(0); // Open GPIO chip
    if (line < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    int gpio_line = gpiod_chip_get_line(line, gpio_pin);
    if (gpio_line < 0) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", gpio_pin, strerror(errno));
        gpiod_chip_close(line);
        gpioTerminate();
        return -1;
    }

    int flags = gpiod_line_request_input_flags(gpio_line, PI_FLAGS_EDGE_BOTH);
    if (flags < 0) {
        fprintf(stderr, "Failed to request GPIO line %d flags: %s\n", gpio_pin, strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(line);
        gpioTerminate();
        return -1;
    }

    if (gpiod_line_request(gpio_line, "motor_sensor", flags) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", gpio_pin, strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(line);
        gpioTerminate();
        return -1;
    }

    return gpio_line;
}

// Read GPIO value with debouncing
int read_gpio(int gpio_line) {
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Calculate RPM
double calculate_rpm(int pulse_count, double sample_interval_sec) {
    return (double)pulse_count / sample_interval_sec * 60.0;
}

// Log RPM to file
void log_rpm(double rpm, const char *log_file_path) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    program_state_t state = {GPIO_PIN, DEBOUNCE_MS, SAMPLE_INTERVAL_SEC, LOG_FILE};

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    int gpio_line = initialize_gpio(state.gpio_pin, state.debounce_ms);
    if (gpio_line < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(state.log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int pulse_count = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Main loop
    while (running) {
        int value = read_gpio(state.gpio_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO, exiting.\n");
            break;
        }

        if (value == 1) {
            pulse_count++;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time >= state.sample_interval_sec) {
            double rpm = calculate_rpm(pulse_count, state.sample_interval_sec);
            log_rpm(rpm, state.log_file_path);
            pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        usleep(1000); // Sleep for 1 ms to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

