    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        handle_touch_event();
        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Relay control program exited cleanly.\n");
    return 0;
}

