#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PWM_FREQUENCY 1000  // Hz
#define PULSES_PER_LITER 450
#define Kp 1.0
#define LOG_FILE "flow_log.csv"

// Global variables
volatile int pulse_count = 0;
int running = 1;

// Function prototypes
void signal_handler(int signal);
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count, double time_interval);
double calculate_duty_cycle(double flow_rate, double target_flow_rate);
void log_data(double timestamp_ms, double flow_rate, int duty_cycle);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Interrupt service routine for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count, double time_interval) {
    return (double)pulse_count / PULSES_PER_LITER / (time_interval / 1000.0);
}

// Function to calculate PWM duty cycle using proportional control
double calculate_duty_cycle(double flow_rate, double target_flow_rate) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = Kp * error;
    // Clamp duty cycle to [0, 255]
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }
    return duty_cycle;
}

// Function to log data to a CSV file
void log_data(double timestamp_ms, double flow_rate, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp_ms,flow_rate,duty_cycle\n");
    }

    fprintf(fp, "%.0f,%.2f,%d\n", timestamp_ms, flow_rate, duty_cycle);
    fclose(fp);
}

// Cleanup function to release resources
void cleanup() {
    // Disable the valve
    gpioWrite(VALVE_ENABLE_PIN, 0);

    // Set PWM to 0
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close the log file
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp != NULL) {
        fclose(fp);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    // Parse the command-line argument
    double target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0) {
        fprintf(stderr, "Error: Invalid target flow rate. Must be a positive number.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(VALVE_PWM_PIN, 255);

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set up interrupt for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec start, end;
    double time_interval;
    int duty_cycle;
    double flow_rate;
    int pulse_count_prev = 0;

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        // Sample the flow rate
        clock_gettime(CLOCK_MONOTONIC, &end);
        time_interval = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        pulse_count = pulse_count_prev; // Reset pulse count for the next interval
        pulse_count_prev = pulse_count;

        flow_rate = calculate_flow_rate(pulse_count, time_interval);

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(flow_rate, target_flow_rate);

        // Set PWM duty cycle
        gpioPWM(VALVE_PWM_PIN, (int)duty_cycle);

        // Log data
        log_data((int)(time_interval * 1000), flow_rate, duty_cycle);

        // Sleep for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

