#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Configuration
#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz
#define RFID_READ_TIMEOUT 100 // ms
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
int server_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_rfid(unsigned char *rfid_data, int max_bytes);
int authenticate(const unsigned char *rfid_data, const unsigned char *tag);
int button_pressed(int gpio);
int log_event(const char *event_type, const char *message);
int send_access_request(const char *timestamp, const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read RFID data from SPI
int spi_read_rfid(unsigned char *rfid_data, int max_bytes) {
    int bytes_read = 0;
    int timeout_start = gpioTick();

    while (bytes_read < max_bytes && (gpioTick() - timeout_start) < RFID_READ_TIMEOUT * 1000) {
        int result = spiXfer(spi_handle, rfid_data, rfid_data, max_bytes);
        if (result == max_bytes) {
            bytes_read = max_bytes;
        } else {
            // Handle SPI transfer error (e.g., retry or log)
            log_event("ERROR", "SPI transfer error");
            return -1; // Indicate failure
        }
        gpioDelay(1000); // Small delay to avoid busy-waiting
    }

    if (bytes_read != max_bytes) {
        log_event("ERROR", "RFID read timeout");
        return -1; // Indicate failure
    }

    return 0; // Success
}

// Function to authenticate the RFID tag
int authenticate(const unsigned char *rfid_data, const unsigned char *tag) {
    if (memcmp(rfid_data, tag, 10) == 0) {
        return 1; // Authentication successful
    } else {
        return 0; // Authentication failed
    }
}

// Function to detect button press
int button_pressed(int gpio) {
    int button_state = gpioRead(gpio);
    gpioDelay(50000); // Debounce delay (50 ms)
    return button_state;
}

// Function to log events to a file
int log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%s,%s\n", timestamp, event_type, message);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Function to send access request to the server
int send_access_request(const char *timestamp, const char *event_type, const char *message) {
    struct sockaddr_in server_addr;
    char server_message[256];

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("inet_pton failed");
        log_event("ERROR", "Invalid server IP address");
        return -1;
    }

    snprintf(server_message, sizeof(server_message), "%s,%s,%s", timestamp, event_type, message);

    if (sendto(server_socket, server_message, strlen(server_message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("sendto failed");
        log_event("ERROR", "Failed to send access request to server");
        return -1;
    }

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_GPIO_1, PI_OUTPUT);
    gpioSetMode(LOCK_GPIO_2, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char rfid_data[10];
