#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>
#include <math.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPMs
#define TARGET_RPM_1 60.0
#define TARGET_RPM_2 60.0

// Sample Time (in milliseconds)
#define SAMPLE_TIME 100

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
volatile int encoder1_last_count = 0;
volatile int encoder2_last_count = 0;

// Mutexes
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void *encoder_thread(void *arg);
double calculate_pid(double target_rpm, double actual_rpm, double *integral, double *previous_error, double dt);
void set_motor_speed(int motor_num, double speed);
void log_data(double motor1_rpm, double motor2_rpm, double pid_p, double pid_i, double pid_d, double pid_output, double integral1, double previous_error1, double integral2, double previous_error2);
void signal_handler(int signal);

// Structure to hold motor parameters
typedef struct {
    int ena_pin;
    int in1_pin;
    int in2_pin;
    double target_rpm;
} MotorParams;

// Structure to hold encoder parameters
typedef struct {
    int a_pin;
    int b_pin;
    volatile int *count;
    volatile int last_count;
    pthread_mutex_t mutex;
} EncoderParams;

// Global encoder parameters
EncoderParams encoder1_params = {ENCODER1_A, ENCODER1_B, &encoder1_count, encoder1_last_count, PTHREAD_MUTEX_INITIALIZER};
EncoderParams encoder2_params = {ENCODER2_A, ENCODER2_B, &encoder2_count, encoder2_last_count, PTHREAD_MUTEX_INITIALIZER};

MotorParams motor1_params = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, TARGET_RPM_1};
MotorParams motor2_params = {MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4, TARGET_RPM_2};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Request lines for motor control
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Request lines for motor control
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);

    // Set PWM frequency (100 Hz)
    gpioSetPWMfrequency(MOTOR1_ENA, 100);
    gpioSetPWMfrequency(MOTOR2_ENB, 100);

    // Initialize encoder counts
    encoder1_count = 0;
    encoder2_count = 0;

    // Initialize mutexes
    pthread_mutex_init(&encoder1_mutex, NULL);
    pthread_mutex_init(&encoder2_mutex, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        pthread_mutex_destroy(&encoder1_mutex);
        pthread_mutex_destroy(&encoder2_mutex);
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID_P,PID_I,PID_D,PID_Output,Integral1,Previous_Error1,Integral2,Previous_Error2\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create encoder thread
    pthread_t encoder_thread_id;
    if (pthread_create(&encoder_thread_id, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder thread!\n");
        fclose(log_file);
        gpioTerminate();
        pthread_mutex_destroy(&encoder1_mutex);
        pthread_mutex_destroy(&encoder2_mutex);
        return 1;
    }

    // Main control loop
    double dt = (double)SAMPLE_TIME / 1000.0; // Convert ms to s
    double integral1 = 0.0;
    double previous_error1 = 0.0;
    double integral2 = 0.0;
    double previous_error2 = 0.0;
    double pid_output1 = 0.0;
    double pid_output2 = 0.0;

    while (1) {
        // Read encoder counts
        int encoder1_new_count = encoder1_count;
        int encoder2_new_count = encoder2_count;

        // Debounce encoder readings
        if (encoder1_new_count != encoder1_last_count) {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_last_count = encoder1_new_count;
            pthread_mutex_unlock(&encoder1_mutex);
        }

        if (encoder2_new_count != encoder2_last_count) {
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_last_count = encoder2_new_count;
            pthread_mutex_unlock(&encoder2_mutex);
        }

        // Calculate RPMs
        double motor1_rpm = (double)(encoder1_new_count - encoder1_last_count) * 60.0 / dt;
        double motor2_rpm = (double)(encoder2_new_count - encoder2_last_count) * 60.0 / dt;

        // Calculate PID outputs
        pid_output1 = calculate_pid(motor1_params.target_rpm, motor1_rpm, &integral1, &previous_error1, dt);
        pid_output2 = calculate_pid(motor2_params.target_rpm, motor2_rpm, &integral2, &previous_error2, dt);

        // Set motor speeds
        set_motor_speed(1, pid_output1);
        set_motor_speed(2, pid_output2);

        // Log data
        log_data(motor1_rpm, motor2_rpm, pid_output1, integral1, previous_error1, pid_output2, integral2, previous_error2);

        // Sleep for a short period
        gpioDelay(1000); // 1 ms
    }

    return 0;
}

// Encoder thread function
void *encoder_thread(void *arg) {
    while (1) {
        // Read encoder 1
        int encoder1_a_val = gpioRead(encoder1_params.a_pin);
        int encoder1_b_val = gpioRead(encoder1_params.b_pin);

        if (encoder1_a_val == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading encoder 1 A pin!\n");
        } else if (encoder1_b_val == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading encoder 1 B pin!\n");
        } else {
            if (encoder1_a_val == 1) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count++;
                pthread_mutex_unlock(&encoder1_mutex);
            } else {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count--;
                pthread_mutex_unlock(&encoder1_mutex);
            }
        }

        // Read encoder 2
        int encoder2_a_val = gpioRead(encoder2_params.a_pin);
        int encoder2_b_val = gpioRead(encoder2_params.b_pin);

        if (encoder2_a_val == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading encoder 2 A pin!\n");
        } else if (encoder2_b_val == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading encoder 2 B pin!\n");
        } else {
            if (encoder2_a_val == 1) {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count++;
                pthread_mutex_unlock(&encoder2_mutex);
            } else {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count--;
                pthread_mutex_unlock(&encoder2_mutex);
            }
        }
    }
    return NULL;
}

// PID calculation function
double calculate_pid(double target_rpm, double actual_rpm, double *integral, double *previous_error, double dt) {
    double error = target_rpm - actual_rpm;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Motor control function
void set_motor_speed(int motor_num, double speed) {
    int ena_pin, in1_pin, in2_pin;

    if (motor_num == 1) {
        ena_pin = motor1_params.ena_pin;
        in1_pin = motor1_params.in1_pin;
        in2_pin = motor1_params.in2_pin;
    } else {
        ena_pin = motor2_params.ena_pin;
        in1_pin = motor2_params.in1_pin;
        in2_pin = motor2_params.in2_pin;
    }

    // Calculate PWM duty cycle (0-255)
    int duty_cycle = (int)(speed * 255.0); // Assuming 0-100% speed maps to 0-255 duty cycle

    // Set ENA pin
    gpioWrite(ena_pin, 1); // Enable motor
    gpioPWM(ena_pin, duty_cycle);

    // Set IN1 and IN2 pins
    if (motor_num == 1) {
        gpioWrite(in1_pin, 0); // Motor direction control (example)
        gpioWrite(in2_pin, 0);
    } else {
        gpioWrite(in1_pin, 0); // Motor direction control (example)
        gpioWrite(in2_pin, 0);
    }
}

// Data logging function
void log_data(double motor1_rpm, double motor2_rpm, double pid_p, double pid_i, double pid_d, double pid_output, double integral1, double previous_error1, double integral2, double previous_error2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, motor1_rpm, motor2_rpm, pid_p, pid_i, pid_d, pid_output, integral1, previous_error1, integral2, previous_error2);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop motors
    set_motor_speed(1, 0.0);
    set_motor_speed(2, 0.0);

    // Release GPIO lines
    gpioWrite(MOTOR1_ENA, 0);
    gpioWrite(MOTOR2_ENB, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close pigpio
    gpioTerminate();

    // Destroy mutexes
    pthread_mutex_destroy(&encoder1_mutex);
    pthread_mutex_destroy(&encoder2_mutex);

    exit(0);
}

