#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_TOUCHTH_L 0x41
#define MPR121_TOUCHTH_H 0x42
#define MPR121_RELEASETH_L 0x43
#define MPR121_RELEASETH_H 0x44
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

// GPIO pin for relay control
#define RELAY_PIN 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status();
void relay_on();
void relay_off();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, shutting down...\n");
        relay_off();
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_L, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write filter threshold low byte\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write filter threshold high byte\n");
        return -1;
    }

    // Configure baseline
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_L, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write baseline low byte\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_H, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write baseline high byte\n");
        return -1;
    }

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_L + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to write touch threshold low byte for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_H + 2 * i, 0x20) < 0) {
            fprintf(stderr, "Error: Failed to write touch threshold high byte for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_L + 2 * i, 0x05) < 0) {
            fprintf(stderr, "Error: Failed to write release threshold low byte for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_H + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to write release threshold high byte for electrode %d\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to enable run mode\n");
        return -1;
    }

    return 0;
}

// Read the touch status from the MPR121
int read_touch_status() {
    int touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Failed to read touch status low byte\n");
        return -1;
    }
    int touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status high byte\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Turn the relay on
void relay_on() {
    gpioWrite(RELAY_PIN, 1);
}

// Turn the relay off
void relay_off() {
    gpioWrite(RELAY_PIN, 0);
}

// Log the relay state to a file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        int any_touched = (touch_status > 0);

        if (any_touched && !relay_is_on()) {
            relay_on();
            log_relay_state(1);
        } else if (!any_touched && relay_is_on()) {
            relay_off();
            log_relay_state(0);
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    relay_off();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

