#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define GPIO line names
#define VALVE1_LINE "GPIO17"
#define VALVE2_LINE "GPIO18"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Define schedule intervals (in seconds)
#define VALVE1_INTERVAL 5
#define VALVE2_INTERVAL 10

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int activate_valve(int gpio_line);
int deactivate_valve(int gpio_line);
int log_event(const char *message);
void cleanup(int signal);

// Signal handler for SIGINT and SIGTERM
void cleanup(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Exit program
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get GPIO line for Valve 1
    valve1_line = gpiod_chip_get_line(chip, VALVE1_LINE);
    if (!valve1_line) {
        fprintf(stderr, "Error getting GPIO line for Valve 1: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO line direction to output
    ret = gpiod_line_request_output(valve1_line, "greenhouse_valve1", 0); // Initial state: OFF
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for Valve 1 as output: %s\n", strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for Valve 2
    valve2_line = gpiod_chip_get_line(chip, VALVE2_LINE);
    if (!valve2_line) {
        fprintf(stderr, "Error getting GPIO line for Valve 2: %s\n", strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO line direction to output
    ret = gpiod_line_request_output(valve2_line, "greenhouse_valve2", 0); // Initial state: OFF
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for Valve 2 as output: %s\n", strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Activate a valve
int activate_valve(int gpio_line) {
    int ret;
    struct timespec sleep_time;

    // Set GPIO line to HIGH
    ret = gpiod_line_set_value(gpio_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line to HIGH: %s\n", strerror(errno));
        return -1;
    }

    // Calculate sleep time
    sleep_time.tv_sec = 0;
