// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status();
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 Initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error writing to MPR121 (Stop Mode)\n");
        return -1;
    }
    gpioDelay(1);

    // Touch threshold configuration
    if (i2cWriteByteData(i2c_handle, 0x41, 0x10) < 0) {
        fprintf(stderr, "Error writing to MPR121 (Touch Threshold)\n");
        return -1;
    }
    gpioDelay(1);

    // Release threshold configuration
    if (i2cWriteByteData(i2c_handle, 0x42, 0x0A) < 0) {
        fprintf(stderr, "Error writing to MPR121 (Release Threshold)\n");
        return -1;
    }
    gpioDelay(1);

    // Filter/Charge time configuration
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        fprintf(stderr, "Error writing to MPR121 (Filter/Charge Time)\n");
        return -1;
    }
    gpioDelay(1);

    // Electrode current configuration
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) {
        fprintf(stderr, "Error writing to MPR121 (Electrode Current)\n");
        return -1;
    }
    gpioDelay(1);

    // Enter Run Mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x20) < 0) {
        fprintf(stderr, "Error writing to MPR121 (Run Mode)\n");
        return -1;
    }
    gpioDelay(1);

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status() {
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error reading touch status low byte\n");
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error reading touch status high byte\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to toggle the relay
void toggle_relay() {
    int current_relay_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_relay_state);
    printf("Relay toggled to: %d\n", !current_relay_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (touch_status > 0) {
            toggle_relay();
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    gpioTerminate();

    return 0;
}

