#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MOTION_SENSOR_1 17
#define MOTION_SENSOR_2 22
#define MOTION_SENSOR_3 23
#define RELAY_PIN 18

// Define rate limiting parameters
#define RATE_LIMIT_INTERVAL 2000 // 2 seconds in milliseconds
#define RATE_LIMIT_THRESHOLD 5000 // 5000 milliseconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_motion_sensor(int gpio_pin);
void control_relay(int state);
void log_event(int gpio_pin, const char *event_type);
void rate_limit_check(int gpio_pin);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int last_motion_time;
} sensor_data_t;

sensor_data_t sensor_data[3];

// Initialize sensor data
void initialize_sensor_data() {
    sensor_data[0].gpio_pin = MOTION_SENSOR_1;
    sensor_data[0].last_motion_time = 0;

    sensor_data[1].gpio_pin = MOTION_SENSOR_2;
    sensor_data[1].last_motion_time = 0;

    sensor_data[2].gpio_pin = MOTION_SENSOR_3;
    sensor_data[2].last_motion_time = 0;
}

int main() {
    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize sensor data
    initialize_sensor_data();

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read motion sensors
        if (read_motion_sensor(MOTION_SENSOR_1) == 1) {
            log_event(MOTION_SENSOR_1, "Motion Detected");
            control_relay(1); // Activate relay
            gpioDelay(500); // Keep relay active for 500ms
            rate_limit_check(MOTION_SENSOR_1);
        }
        if (read_motion_sensor(MOTION_SENSOR_2) == 1) {
            log_event(MOTION_SENSOR_2, "Motion Detected");
            control_relay(1); // Activate relay
            gpioDelay(500); // Keep relay active for 500ms
            rate_limit_check(MOTION_SENSOR_2);
        }
        if (read_motion_sensor(MOTION_SENSOR_3) == 1) {
            log_event(MOTION_SENSOR_3, "Motion Detected");
            control_relay(1); // Activate relay
            gpioDelay(500); // Keep relay active for 500ms
            rate_limit_check(MOTION_SENSOR_3);
        }

        gpioDelay(50); // Check sensors every 50ms
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTION_SENSOR_1, PI_INPUT);
    gpioSetMode(MOTION_SENSOR_2, PI_INPUT);
    gpioSetMode(MOTION_SENSOR_3, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(MOTION_SENSOR_1, PI_PUD_DOWN);
    gpioSetPullUpDown(MOTION_SENSOR_2, PI_PUD_DOWN);
    gpioSetPullUpDown(MOTION_SENSOR_3, PI_PUD_DOWN);

    // Set initial relay state to off
    control_relay(0);

    return 0;
}

// Read motion sensor value
int read_motion_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Control relay state
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Log event to file
void log_event(int gpio_pin, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - GPIO %d - %s\n", timestamp, gpio_pin, event_type);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Rate limiting check
void rate_limit_check(int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (gpio_pin == MOTION_SENSOR_1) {
        if (difftime(time(NULL), sensor_data[0].last_motion_time) >= RATE_LIMIT_INTERVAL) {
            sensor_data[0].last_motion_time = time(NULL);
        }
    } else if (gpio_pin == MOTION_SENSOR_2) {
        if (difftime(time(NULL), sensor_data[1].last_motion_time) >= RATE_LIMIT_INTERVAL) {
            sensor_data[1].last_motion_time = time(NULL);
