void control_relay(int state);
void log_event(int gpio_pin, const char *event_type);
void rate_limit_check(int gpio_pin);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int last_motion_time;
} sensor_data_t;

sensor_data_t sensor_data[3];

// Initialize sensor data
void initialize_sensor_data() {
    sensor_data[0].gpio_pin = MOTION_SENSOR_1;
    sensor_data[0].last_motion_time = 0;

    sensor_data[1].gpio_pin = MOTION_SENSOR_2;
    sensor_data[1].last_motion_time = 0;

    sensor_data[2].gpio_pin = MOTION_SENSOR_3;
    sensor_data[2].last_motion_time = 0;
}

int main() {
    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize sensor data
    initialize_sensor_data();

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
