#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define minimum and maximum durations (ms)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define minimum and maximum duty cycle values
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE PWM_RANGE

// Global variables
volatile sig_atomic_t shutdown_flag = 0;

// Structure to hold motor parameters
typedef struct {
    int pin;
    int duty_cycle;
    int duration;
} MotorStep;

// Function prototypes
int initialize_gpio();
void generate_pattern(MotorStep *pattern, int pattern_size);
void play_pattern(MotorStep *pattern, int pattern_size);
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE);

    return 0;
}

// Function to generate a random haptic feedback pattern
void generate_pattern(MotorStep *pattern, int pattern_size) {
    srand(time(NULL)); // Seed the random number generator

    // Ensure pattern size is within bounds
    if (pattern_size < 5 || pattern_size > 15) {
        fprintf(stderr, "Invalid pattern size: %d\n", pattern_size);
        return;
    }

    // Generate random duty cycles and durations for each step
    for (int i = 0; i < pattern_size; i++) {
        pattern[i].duty_cycle = rand() % (MAX_DUTY_CYCLE + 1);
        pattern[i].duration = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
    }
}

// Function to play a haptic feedback pattern
void play_pattern(MotorStep *pattern, int pattern_size) {
    for (int i = 0; i < pattern_size; i++) {
        // Set PWM duty cycle for motor 1
        gpioPWM(MOTOR1_PIN, pattern[i].duty_cycle);
        // Set PWM duty cycle for motor 2
        gpioPWM(MOTOR2_PIN, pattern[i].duty_cycle);

        // Delay for the specified duration
        gpioDelay(pattern[i].duration * 1000); // Convert ms to microseconds
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Stop PWM output
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, shutting down...\n");
        shutdown_flag = 1;
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (!shutdown_flag) {
        MotorStep pattern[15]; // Assuming a maximum pattern size of 15 steps
        generate_pattern(pattern, rand() % 15 + 5); // Generate a random pattern size between 5 and 15
        play_pattern(pattern, rand() % 15 + 5); // Play the generated pattern

        // Small delay to prevent excessive CPU usage
        gpioDelay(10000); // 10ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Exiting cleanly.\n");
    return 0;
}

