#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SOLENOID_PIN 27
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define THRESHOLD 10.0 // kg
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_TIMEOUT_MS 500

// Global variables
static volatile int running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int read_calibration_data(const char *filename);
int calibrate_sensor(int data_pin, int clock_pin, double *scale_factor, double *offset);
double read_hx711(int data_pin, int clock_pin);
double convert_to_weight(double raw_value, double scale_factor, double offset);
void control_solenoid(int solenoid_pin, int state);
void log_data(double weight);
void signal_handler(int signal);

// Function to read calibration data from file
int read_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening calibration file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    char *token = strtok(line, " ");
    if (token == NULL) {
        fclose(fp);
        return -1;
    }

    scale_factor = atof(token);

    token = strtok(NULL, " ");
    if (token == NULL) {
        fclose(fp);
        return -1;
    }

    offset = atof(token);

    fclose(fp);
    return 0;
}

// Function to calibrate the sensor
int calibrate_sensor(int data_pin, int clock_pin, double *scale_factor, double *offset) {
    double sum = 0.0;
    int num_readings = 0;
    int i;

    printf("Calibrating sensor... Please ensure no weight is applied.\n");
    gpioDelay(1000); // Wait 1 second

    for (i = 0; i < 100; i++) {
        sum += read_hx711(data_pin, clock_pin);
        gpioDelay(10); // Small delay between readings
        num_readings++;
    }

    *offset = sum / num_readings;
    *scale_factor = 1.0; // Initialize scale factor to 1.0

    printf("Calibration complete. Offset: %lf, Scale Factor: %lf\n", *offset, *scale_factor);
    return 0;
}

// Function to read raw data from HX711
double read_hx711(int data_pin, int clock_pin) {
    int i;
    long value = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(data_pin) == 1 && timeout < READ_TIMEOUT_MS) {
        gpioDelay(1); // Wait 1 ms
        timeout++;
    }

    if (timeout >= READ_TIMEOUT_MS) {
        fprintf(stderr, "HX711 read timeout\n");
        return -1.0; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Short clock pulse
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Short clock pulse
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    value = value ^ 0x800000; // Convert to signed 2's complement

    return (double)value;
}

// Function to convert raw value to weight
double convert_to_weight(double raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(int solenoid_pin, int state) {
    gpioWrite(solenoid_pin, state);
}

// Function to log data to file
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    control_solenoid(SOLENOID_PIN, 0); // Release solenoid
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    control_solenoid(SOLENOID_PIN, 0); // Ensure solenoid is initially unlocked

    // Read calibration data
    if (read_calibration_data(CALIBRATION_FILE) != 0) {
        fprintf(stderr, "Failed to read calibration data. Using defaults.\n");
        printf("Enter scale factor (e.g., 1.0): ");
        if (scanf("%lf", &scale_factor) != 1) {
            fprintf(stderr, "Invalid input. Using default scale factor.\n");
            scale_factor = 1.0;
        }
        printf("Enter offset (e.g., 0.0): ");
        if (scanf("%lf", &offset) != 1) {
            fprintf(stderr, "Invalid input. Using default offset.\n");
            offset = 0.0;
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Calibrate the sensor
    calibrate_sensor(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset);

    // Main loop
    while (running) {
        double raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading HX711, skipping iteration.\n");
            gpioDelay(500); // Wait before retrying
            continue;
        }

        double weight = convert_to_weight(raw_value, scale_factor, offset);
        log_data(weight);

        if (weight > THRESHOLD) {
            control_solenoid(SOLENOID_PIN, 1); // Lock
        } else {
            control_solenoid(SOLENOID_PIN, 0); // Unlock
        }

        gpioDelay(500); // Read every 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

