    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        gpioDelay(DEBOUNCE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (readings[i] == 0) {
            low_count++;
        }
    }

    return (low_count >= RAIN_DETECT_THRESHOLD) ? 1 : 0;
}

