    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("GPIO initialized successfully");

    // Main loop
    while (running) {
        if (read_rain_sensor()) {
            log_event("Rain detected, closing window");
            close_window();
            window_closed = 1; // Set the window_closed flag
            log_event("Window closed");
        } else {
            window_closed = 0; // Reset the window_closed flag if no rain
            log_event("No rain detected, window is open");
        }

        gpioDelay(60000000); // Wait 60 seconds (60000000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_window();
    gpioTerminate();
    log_event("GPIO resources released");

    return 0;
}

