float calculate_weight(int raw_value);
void control_solenoid(int activate);
void log_event(const char *message);
void signal_handler(int signal);

// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    // Wait for DOUT pin to go low
    int timeout_counter = 0;
    while (gpioRead(DT_PIN) == 1 && timeout_counter < HX711_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= HX711_TIMEOUT) {
        log_event("HX711 timeout");
        return -1; // Indicate timeout
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(DT_PIN)) {
            data++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse to set the gain to 128
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

