#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration file
#define CALIBRATION_FILE "calibration.txt"

// Define log file
#define SECURITY_LOG_FILE "security.log"

// Define timeout duration (100ms)
#define TIMEOUT_DURATION 100

// Define solenoid activation duration (5 seconds)
#define SOLENOID_DURATION 5

// Global variables
double calibration_factor = 1.0; // Initial calibration factor
FILE *calibration_file = NULL;
FILE *security_log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_kg(int raw_value);
int calibrate_load_cell();
int log_event(double weight);
void control_solenoid(int lock);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_DURATION) {
        fprintf(stderr, "Error: HX711 data pin timeout.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    data = data ^ 0x800000; // Convert to signed

    return data;
}

// Function to convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to calibrate the load cell
int calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kilograms): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1;
    }

    printf("Reading raw value...\n");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration.\n");
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    // Save calibration factor to file
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1;
    }
    fprintf(calibration_file, "%lf\n", calibration_factor);
    fclose(calibration_file);

    printf("Calibration complete.\n");
    return 0;
}

// Function to log security events
int log_event(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    security_log_file = fopen(SECURITY_LOG_FILE, "a");
    if (security_log_file == NULL) {
        fprintf(stderr, "Error: Could not open security log file for writing.\n");
        return -1;
    }

    fprintf(security_log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
    fclose(security_log_file);

    printf("Event logged: %s - Weight: %.2f kg\n", timestamp, weight);
    return 0;
}

// Function to control the solenoid lock
void control_solenoid(int lock) {
    gpioWrite(SOLENOID_PIN, lock);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Unlock the solenoid
    control_solenoid(0);

    // Terminate pigpio
    gpioTerminate();

    // Close files
    if (calibration_file != NULL) {
        fclose(calibration_file);
