#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(int sensor_pin, int relay_pin);
int read_sensor(int sensor_pin);
int toggle_relay(int relay_pin);
int log_event(const char *relay_state);
void cleanup_gpio(int sensor_pin, int relay_pin);
void signal_handler(int signal);

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(SENSOR_PIN, RELAY_PIN) != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor(SENSOR_PIN);

        if (sensor_value == 0) { // Obstacle detected (sensor output is active-low)
            if (toggle_relay(RELAY_PIN) != 0) {
                fprintf(stderr, "Failed to toggle relay. Continuing.\n");
            }
            log_event("ON");
        } else if (sensor_value > 0) {
            // No obstacle detected
            log_event("OFF");
        } else {
            fprintf(stderr, "Error reading sensor. Continuing.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio(SENSOR_PIN, RELAY_PIN);

    printf("Relay control program stopped.\n");
    return 0;
}

// Initializes the specified GPIO pins using pigpio.
int initialize_gpio(int sensor_pin, int relay_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(sensor_pin, PI_INPUT);
    gpioSetMode(relay_pin, PI_OUTPUT);

    return 0;
}

// Reads the sensor value from the specified GPIO pin.
int read_sensor(int sensor_pin) {
    return gpioRead(sensor_pin);
}

// Toggles the relay state (ON/OFF) on the specified GPIO pin.
int toggle_relay(int relay_pin) {
    int current_state = gpioRead(relay_pin);
    gpioWrite(relay_pin, !current_state);
    return 0;
}

// Logs the relay state change to the specified log file.
int log_event(const char *relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s Relay is %s\n", timestamp, relay_state);
    fclose(fp);
    return 0;
}

// Releases the GPIO lines and closes the pigpio connection.
void cleanup_gpio(int sensor_pin, int relay_pin) {
    gpioWrite(relay_pin, 0); // Ensure relay is OFF
    gpioSetMode(relay_pin, PI_INPUT); // Set back to input
    gpioSetMode(sensor_pin, PI_INPUT); // Set back to input
    gpioTerminate();
}

// Signal handler to catch SIGINT and SIGTERM signals.
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

