#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define LOG_FILE "watering.log"

volatile sig_atomic_t program_running = 1;

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char *duration_str = strtok(line, "=");
    if (duration_str == NULL) {
        fprintf(stderr, "Error parsing config file: missing duration value\n");
        fclose(fp);
        return -1;
    }

    char *endptr;
    *duration = strtol(duration_str, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error parsing config file: invalid duration value\n");
        fclose(fp);
        return -1;
    }

    if (*duration <= 0 || *duration > 3600) {
        fprintf(stderr, "Error parsing config file: duration must be between 1 and 3600 seconds\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to log messages to a file
void log_message(const char *message) {
