#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_A_PWM 22
#define MOTOR_B_PWM 23
#define MOTOR_C_PWM 24
#define MOTOR_D_PWM 25

// Define constants
#define BASE_SPEED 150
#define HALF_SPEED 85
#define PWM_FREQUENCY 1000

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int control_motor(int motor_a_pwm, int motor_b_pwm, int motor_c_pwm, int motor_d_pwm, int speed);
int log_data(int left_sensor_state, int middle_sensor_state, int right_sensor_state, int left_motor_speed, int right_motor_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control motor speeds
int control_motor(int motor_a_pwm, int motor_b_pwm, int motor_c_pwm, int motor_d_pwm, int speed) {
    if (speed < 0 || speed > 255) {
        fprintf(stderr, "Error: Invalid motor speed. Must be between 0 and 255.\n");
        return -1;
    }

    if (gpioWrite(motor_a_pwm, speed) < 0) {
        fprintf(stderr, "Error: Failed to write to motor A PWM pin.\n");
        return -1;
    }
    if (gpioWrite(motor_b_pwm, speed) < 0) {
        fprintf(stderr, "Error: Failed to write to motor B PWM pin.\n");
        return -1;
    }
    if (gpioWrite(motor_c_pwm, speed) < 0) {
        fprintf(stderr, "Error: Failed to write to motor C PWM pin.\n");
        return -1;
    }
    if (gpioWrite(motor_d_pwm, speed) < 0) {
        fprintf(stderr, "Error: Failed to write to motor D PWM pin.\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(int left_sensor_state, int middle_sensor_state, int right_sensor_state, int left_motor_speed, int right_motor_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor_state, middle_sensor_state, right_sensor_state, left_motor_speed, right_motor_speed);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;

    // Stop motors
    control_motor(MOTOR_A_PWM, MOTOR_B_PWM, MOTOR_C_PWM, MOTOR_D_PWM, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_C_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_D_PWM, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_C_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_D_PWM, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int left_sensor_state = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor_state = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor_state = read_sensor(RIGHT_SENSOR_PIN);

        // Control motor speeds based on sensor readings
        int left_motor_speed = BASE_SPEED;
        int right_motor_speed = BASE_SPEED;

        if (middle_sensor_state == 0) {
            // Middle sensor low, drive straight
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED;
        } else if (left_sensor_state == 0) {
            // Left sensor low, turn right
            left_motor_speed = HALF_SPEED;
            right_motor_speed = BASE_SPEED;
        } else if (right_sensor_state == 0) {
            // Right sensor low, turn left
            left_motor_speed = BASE_SPEED;
            right_motor_speed = HALF_SPEED;
        } else {
            // No sensor low, stop
            left_motor_speed = 0;
            right_motor_speed = 0;
        }

        // Control motors
        if (control_motor(MOTOR_A_PWM, MOTOR_B_PWM, MOTOR_C_PWM, MOTOR_D_PWM, left_motor_speed) < 0) {
            running = 0; // Exit loop on error
        }
        if (control_motor(MOTOR_A_PWM, MOTOR_B_PWM, MOTOR_C_PWM, MOTOR_D_PWM, right_motor_speed) < 0) {
            running = 0; // Exit loop on error
        }

        // Log data
        if (log_data(left_sensor_state, middle_sensor_state, right_sensor_state, left_motor_speed, right_motor_speed) < 0) {
            running = 0; // Exit loop on error
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

