// Function to read lux value from BH1750 sensor
float read_lux() {
    char buf[2];
    int result;
    uint16_t raw_value;
    float lux;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1.0; // Indicate error
    }

    // Delay for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read two bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to lux
    lux = (float)raw_value / 1.2;

    return lux;
}

// Function to control the relay
void control_relay(float lux) {
    static int relay_state = 0; // 0 = off, 1 = on

    if (lux < LUX_THRESHOLD && relay_state == 0) {
        gpioWrite(RELAY_GPIO, 1); // Turn on relay
        relay_state = 1;
        printf("Relay turned ON (Lux: %.2f)\n", lux);
    } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
        gpioWrite(RELAY_GPIO, 0); // Turn off relay
        relay_state = 0;
        printf("Relay turned OFF (Lux: %.2f)\n", lux);
    }
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    float lux;
    int relay_state;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for relay
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        lux = read_lux();
        if (lux >= 0) {
            control_relay(lux);
            relay_state = gpioRead(RELAY_GPIO); // Read relay state
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Error reading lux value. Retrying...\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

