#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_GPIO 21
#define UNLOCK_BUTTON_GPIO 22
#define SERVO_GPIO 18

// Define servo limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the servo pulse width
void set_servo_pulse_width(int gpio, int pulse_width_us) {
    if (pulse_width_us < SERVO_MIN_PULSE_WIDTH || pulse_width_us > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d us).  Must be between %d and %d.\n", pulse_width_us, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return;
    }

    gpioServo(gpio, pulse_width_us);
}

// Function to lock the door
void lock_door() {
    set_servo_pulse_width(SERVO_GPIO, SERVO_MIN_PULSE_WIDTH); // Lock position
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
}

// Function to unlock the door
void unlock_door() {
    set_servo_pulse_width(SERVO_GPIO, SERVO_MAX_PULSE_WIDTH); // Unlock position
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(UNLOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (gpioRead(LOCK_BUTTON_GPIO) == 0) { // Button is pressed (active low)
            lock_door();
        }

        // Check for unlock button press
        if (gpioRead(UNLOCK_BUTTON_GPIO) == 0) { // Button is pressed (active low)
            unlock_door();
        }

        gpioDelay(50 * 1000); // Small delay to prevent busy-waiting
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

