#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the duration of the pulses (in milliseconds)
#define PULSE_DURATION_MS 200
#define MOTOR2_DURATION_MS 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGINT, stopping motors and exiting...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGTERM, stopping motors and exiting...\n");
}

// Function to initialize the GPIO pins
int initialize_gpio()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Request GPIO17 and GPIO27 as outputs
    if (gpiod_line_request_output(MOTOR1_GPIO, "motor1", 0) < 0)
    {
        fprintf(stderr, "Failed to request GPIO%d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpiod_line_request_output(MOTOR2_GPIO, "motor2", 0) < 0)
    {
        fprintf(stderr, "Failed to request GPIO%d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to stop the motors
void stop_motors()
{
    // Set both GPIO pins to LOW
    if (gpiod_line_set_value(MOTOR1_GPIO, 0) < 0)
    {
        fprintf(stderr, "Failed to set GPIO%d to LOW\n", MOTOR1_GPIO);
    }
    if (gpiod_line_set_value(MOTOR2_GPIO, 0) < 0)
    {
        fprintf(stderr, "Failed to set GPIO%d to LOW\n", MOTOR2_GPIO);
    }
}

// Function to pulse the motors
void pulse_motors()
{
    // Turn on motor 1
    if (gpiod_line_set_value(MOTOR1_GPIO, 1) < 0)
    {
        fprintf(stderr, "Failed to turn on motor 1\n");
    }

    // Wait for the specified duration
    gpioDelay(PULSE_DURATION_MS * 1000); // Convert ms to microseconds

    // Turn off motor 1
    if (gpiod_line_set_value(MOTOR1_GPIO, 0) < 0)
    {
        fprintf(stderr, "Failed to turn off motor 1\n");
    }

    // Turn on motor 2
    if (gpiod_line_set_value(MOTOR2_GPIO, 1) < 0)
    {
        fprintf(stderr, "Failed to turn on motor 2\n");
    }

    // Wait for the specified duration
    gpioDelay(MOTOR2_DURATION_MS * 1000); // Convert ms to microseconds

    // Turn off motor 2
    if (gpiod_line_set_value(MOTOR2_GPIO, 0) < 0)
    {
        fprintf(stderr, "Failed to turn off motor 2\n");
    }
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() < 0)
    {
        return 1;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop to continuously pulse the motors
    while (program_running)
    {
        pulse_motors();
    }

    // Stop the motors before exiting
    stop_motors();

    // Release the GPIO lines
    gpiod_line_release(MOTOR1_GPIO);
    gpiod_line_release(MOTOR2_GPIO);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

