#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <pigpio.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ALARM_DURATION_MS 1000

static volatile int running = 1;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;

void signal_handler(int sig) {
    running = 0;
    printf("Signal received, exiting gracefully...\n");
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_LED_GPIO, 0); // Ensure LED is off initially

    return 0;
}

int initialize_zmq() {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "ZMQ context creation failed: %s\n", zmq_strerror(errno));
        return -1;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "ZMQ publisher socket creation failed: %s\n", zmq_strerror(errno));
        return -1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "ZMQ subscriber socket creation failed: %s\n", zmq_strerror(errno));
        return -1;
    }

    int rc = zmq_bind(subscriber, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "ZMQ bind failed: %s\n", zmq_strerror(errno));
        return -1;
    }

    return 0;
}

int publish_sound_alert() {
    char message[100];
    snprintf(message, sizeof(message), "SOUND_DETECTED");

    int rc = zmq_send(publisher, message, strlen(message), 0);
    if (rc == -1) {
        fprintf(stderr, "ZMQ send failed: %s\n", zmq_strerror(errno));
        return -1;
    }

    return 0;
}

int subscribe_sound_alerts() {
    int rc = zmq_connect(subscriber, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "ZMQ connect failed: %s\n", zmq_strerror(errno));
        return -1;
    }

    while (running) {
        zmq_msg_t message;
        rc = zmq_msg_recv(&message, subscriber, 0);
        if (rc == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "ZMQ message receive failed: %s\n", zmq_strerror(errno));
            continue; // Or exit, depending on error handling strategy
        }

        char *data = (char *)zmq_msg_data(&message);
        int data_len = zmq_msg_size(&message);

        if (data_len > 0 && data[data_len - 1] == '\0') {
            printf("Received: %s\n", data);
            if (strcmp(data, "SOUND_DETECTED") == 0) {
                printf("Sound detected! Activating alarm.\n");
                gpioWrite(ALARM_LED_GPIO, 1); // Turn on LED
                gpioDelay(ALARM_DURATION_MS * 1000); // Delay for 1 second
                gpioWrite(ALARM_LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Invalid message format: %s\n", data);
        }

        zmq_msg_close(&message);
    }

    return 0;
}

int cleanup() {
    printf("Cleaning up...\n");

    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }

    gpioWrite(ALARM_LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor or alarm_node\n");
        return 1;
    }

    const char *mode = argv[1];

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_zmq() != 0) {
        cleanup();
        return 1;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Sound sensor mode started\n");
        while (running) {
            if (gpioRead(SOUND_SENSOR_GPIO) == 0) { // Active low
                if (publish_sound_alert() != 0) {
                    fprintf(stderr, "Error publishing sound alert\n");
                }
            }
            gpioDelay(10); // Check every 10 ms
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        printf("Alarm node mode started\n");
        if (subscribe_sound_alerts() != 0) {
            fprintf(stderr, "Error subscribing to sound alerts\n");
        }
    } else {
        fprintf(stderr, "Invalid mode specified\n");
        return 1;
    }

    cleanup();
    return 0;
}

