#include <time.h>
#include <math.h>

// Configuration
#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder_2024"
#define NEC_HEADER_MARK_US 9000
#define NEC_HEADER_SPACE_US 4500
#define NEC_BIT_MARK_US 560
#define NEC_SPACE_US 1690
#define NEC_CHECKSUM_US 450
#define NEC_MAX_PULSES 100
#define NEC_MAX_PULSE_GAP_US 10000 // 10ms

// Global variables
static volatile int pulse_count = 0;
static volatile unsigned int pulse_times[NEC_MAX_PULSES];
static volatile int pulse_index = 0;
static volatile int nec_address = 0;
static volatile int nec_command = 0;
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
void ir_callback(int gpio, int level, uint32_t tick, void *user);
int decode_nec(unsigned int *pulses, int pulse_count, unsigned int *address, unsigned int *command);
int validate_checksum(unsigned int address, unsigned int command);
int publish_mqtt(unsigned int address, unsigned int command);
void signal_handler(int signal);

// NEC decoding functions
int decode_nec(unsigned int *pulses, int pulse_count, unsigned int *address, unsigned int *command) {
    if (pulse_count < 68) return -1; // Not enough pulses

    unsigned int address_raw = 0;
    unsigned int command_raw = 0;

    for (int i = 0; i < 32; i++) {
        if (pulses[2 * i] < NEC_HEADER_MARK_US || pulses[2 * i + 1] > NEC_HEADER_SPACE_US) return -1; // Invalid header
        if (pulses[2 * i + 1] < NEC_BIT_MARK_US || pulses[2 * i + 1] > NEC_SPACE_US) return -1; // Invalid bit/space

        if (pulses[2 * i + 1] > NEC_SPACE_US) {
            address_raw = (address_raw << 1) | 1;
        } else {
            address_raw = (address_raw << 1) | 0;
        }
    }

    for (int i = 0; i < 32; i++) {
        if (pulses[32 + 2 * i] < NEC_HEADER_MARK_US || pulses[32 + 2 * i + 1] > NEC_HEADER_SPACE_US) return -1; // Invalid header
        if (pulses[32 + 2 * i + 1] < NEC_BIT_MARK_US || pulses[32 + 2 * i + 1] > NEC_SPACE_US) return -1; // Invalid bit/space

        if (pulses[32 + 2 * i + 1] > NEC_SPACE_US) {
            command_raw = (command_raw << 1) | 1;
        } else {
            command_raw = (command_raw << 1) | 0;
        }
    }

    if ((address_raw != address) || (command_raw != command)) return -1; // Checksum failure

    *address = address_raw;
    *command = command_raw;

    return 0;
}

int validate_checksum(unsigned int address, unsigned int command) {
    unsigned int calculated_checksum = 0;
    unsigned int address_inv = ~address;

    for (int i = 0; i < 32; i++) {
        if ((address & (1 << i)) != 0) {
            calculated_checksum += 1;
        } else {
            calculated_checksum += 0;
        }
    }

    for (int i = 0; i < 32; i++) {
        if ((command & (1 << i)) != 0) {
            calculated_checksum += 1;
        } else {
            calculated_checksum += 0;
        }
    }

    return (calculated_checksum == address_inv);
}

// Callback function for IR receiver
void ir_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t pulse_length;

    if (level == FALLING_EDGE) {
        pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < NEC_MAX_PULSES) {
            pulse_times[pulse_count++] = pulse_length;
        } else {
            pulse_count = 0; // Reset if buffer overflows
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// MQTT publishing function
int publish_mqtt(unsigned int address, unsigned int command) {
    int rc;
    char payload[100];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"address\": %u, \"command\": %u}", timestamp, address, command);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

int main() {
    openlog("ir_decoder", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO mode and pull-up/down resistor
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);
    mosquitto_subscribe_callback_set(mosq, NULL);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for IR receiver
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

    unsigned int pulses[NEC_MAX_PULSES];
    unsigned int address, command;

    while (running) {
        // Decode NEC IR signal
        if (decode_nec(pulses, pulse_count, &address, &command) == 0) {
            // Validate checksum
            if (validate_checksum(address, command)) {
                // Log decoded data
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

                syslog(LOG_INFO, "Decoded: Address = 0x%02X, Command = 0x%02X", address, command);

                // Publish to MQTT
                if (publish_mqtt(address, command) != 0) {
                    syslog(LOG_ERR, "Failed to publish MQTT message");
                }
            } else {
                syslog(LOG_ERR, "Checksum validation failed");
            }
        } else {
            syslog(LOG_ERR, "NEC decoding failed");
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

