#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define UDP_IP "239.255.255.250"
#define UDP_PORT 5005
#define SENSOR_ID_OFFSET 1
#define LUX_OFFSET 0

// Structure to hold sensor data
typedef struct {
    int fd;
    int address;
    float lux;
} sensor_t;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to open an I2C device
int open_i2c_device(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a command to an I2C device
int write_i2c_command(int fd, unsigned char command) {
    unsigned char buf[2];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from an I2C device
int read_i2c_data(int fd, unsigned char command, unsigned char *data, int count) {
    if (ioctl(fd, I2C_SLAVE, command) < 0) {
        perror("Error setting I2C slave address for read");
        return -1;
    }

    if (read(fd, data, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to convert raw data to lux
float convert_to_lux(unsigned char data[2]) {
    unsigned int raw_value = ((unsigned int)data[0] << 8) | data[1];
    return (float)raw_value / 1.2;
}

// Function to read a sensor
int read_sensor(sensor_t *sensor) {
    unsigned char command = 0x20; // One-Time High-Resolution mode
    unsigned char data[2];
    int retries = 3;

    while (retries > 0) {
        if (write_i2c_command(sensor->fd, command) == 0) {
            if (read_i2c_data(sensor->fd, 0, data, 2) == 0) {
                sensor->lux = convert_to_lux(data);
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading sensor data, retrying...\n");
                retries--;
                usleep(100000); // Wait 100ms before retrying
            }
        } else {
            fprintf(stderr, "Error writing to sensor, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to format sensor data into a string
char* format_sensor_data(sensor_t *sensor) {
    char *data = (char*)malloc(100 * sizeof(char)); // Allocate memory for the string
    if (data == NULL) {
        perror("Failed to allocate memory for sensor data");
        return NULL;
    }
    snprintf(data, 100, "%d,%.2f", sensor->address, sensor->lux);
    return data;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1; // Time-to-live for multicast packets

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket() failed");
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt() failed");
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_IP);
    addr.sin_port = htons(UDP_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto() failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sensor addresses
    int sensor_addresses[] = {0x23, 0x24, 0x25, 0x26};
    sensor_t sensors[NUM_SENSORS];

    // Initialize sensors
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].address = sensor_addresses[i];
        sensors[i].fd = open_i2c_device(sensors[i].address);
        if (sensors[i].fd < 0) {
            fprintf(stderr, "Failed to open sensor at address 0x%02x\n", sensors[i].address);
            // Continue to the next sensor, but log the error
        }
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (sensors[i].fd >= 0) {
                if (read_sensor(&sensors[i]) == 0) {
                    char *data = format_sensor_data(&sensors[i]);
                    if (data != NULL) {
                        printf("Sensor %d: %s\n", sensors[i].address, data);
                        send_udp_multicast(data);
                        free(data);
                    } else {
                        fprintf(stderr, "Failed to format data for sensor %d\n", sensors[i].address);
                    }
                } else {
                    fprintf(stderr, "Failed to read sensor %d\n", sensors[i].address);
                    sensors[i].lux = NAN; // Mark as failed
                }
            } else {
                fprintf(stderr, "Sensor at address 0x%02x not initialized\n", sensors[i].address);
                sensors[i].lux = NAN; // Mark as failed
            }
        }
        sleep(1); // Read sensors every second
    }

    // Cleanup
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].fd >= 0) {
            close(sensors[i].fd);
        }
    }

    return 0;
}

