#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SLEEP_MS 1000

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int read_i2c_data(int fd, unsigned char *data, int count) {
    if (count > 1) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (write(fd, NULL, 0) == count) {
                if (read(fd, data, count) == count) {
                    return 0; // Success
                } else {
                    perror("Error reading I2C data");
                    retries++;
                    usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
                }
            } else {
                perror("Error writing to I2C device");
                retries++;
                usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            }
        }
        fprintf(stderr, "Failed to read I2C data after %d retries\n", MAX_RETRIES);
        return -1; // Failure
    } else {
        fprintf(stderr, "Invalid data count for read_i2c_data\n");
        return -1; // Invalid count
    }
}

// Function to convert raw data to SLPM
float convert_to_slpm(unsigned short raw_data) {
    return (float)(raw_data - 3277) * 0.1;
}

// Function to log the data to a file
int log_data(FILE *log_file, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, flow_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (set_i2c_address(i2c_fd, I2C_ADDRESS) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    unsigned char data[2];
    unsigned short raw_flow;
    float flow_rate;

    // Main loop
    while (1) {
        // Read data from I2C
        if (read_i2c_data(i2c_fd, data, 2) == 0) {
            // Convert raw data to SLPM
            raw_flow = (data[0] << 8) | data[1];
            flow_rate = convert_to_slpm(raw_flow);

            // Log the data
            if (log_data(log_file, flow_rate) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading I2C data\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // This part will not be reached unless there's an error or the program is interrupted.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

