#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define AS7341_ADDR 0x39

// Define register addresses
#define WHO_AM_I 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x02
#define F1_DATA 0x60
#define F8_DATA 0x73

// Define spectral channels
#define F1_DATA_REG 0x60
#define F2_DATA_REG 0x62
#define F3_DATA_REG 0x64
#define F4_DATA_REG 0x66
#define F5_DATA_REG 0x68
#define F6_DATA_REG 0x6A
#define F7_DATA_REG 0x6C
#define F8_DATA_REG 0x6E
#define CLEAR_DATA_REG 0x70
#define NIR_DATA_REG 0x72

// Define log file path
#define LOG_FILE "spectral_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1;
    uint16_t f2;
    uint16_t f3;
    uint16_t f4;
    uint16_t f5;
    uint16_t f6;
    uint16_t f7;
    uint16_t f8;
    uint16_t clear;
    uint16_t nir;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int sensor_init(int fd);
int sensor_read_spectral_data(int fd, sensor_data_t *data);
float calculate_lux(const sensor_data_t *data);
int log_data(const sensor_data_t *data, float lux);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Sensor initialization function
int sensor_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x19\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_reg(fd, ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error powering on sensor\n");
        return -1;
    }

    // Configure SMUX for spectral readings
    if (i2c_write_reg(fd, CFG6, 0x03) < 0) {
        fprintf(stderr, "Error configuring SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_reg(fd, SP_EN, 0x01) < 0) {
        fprintf(stderr, "Error enabling spectral measurement\n");
        return -1;
    }

    return 0;
}

// Sensor read spectral data function
int sensor_read_spectral_data(int fd, sensor_data_t *data) {
    data->f1 = i2c_read_reg(fd, F1_DATA);
    data->f2 = i2c_read_reg(fd, F2_DATA);
    data->f3 = i2c_read_reg(fd, F3_DATA);
    data->f4 = i2c_read_reg(fd, F4_DATA);
    data->f5 = i2c_read_reg(fd, F5_DATA);
    data->f6 = i2c_read_reg(fd, F6_DATA);
    data->f7 = i2c_read_reg(fd, F7_DATA);
    data->f8 = i2c_read_reg(fd, F8_DATA);
    data->clear = i2c_read_reg(fd, CLEAR_DATA_REG);
    data->nir = i2c_read_reg(fd, NIR_DATA_REG);

    if (data->f1 < 0 || data->f2 < 0 || data->f3 < 0 || data->f4 < 0 ||
        data->f5 < 0 || data->f6 < 0 || data->f7 < 0 || data->f8 < 0 ||
        data->clear < 0 || data->nir < 0) {
        fprintf(stderr, "Error reading spectral data\n");
        return -1;
    }

    return 0;
}

// Calculate lux approximation function
float calculate_lux(const sensor_data_t *data) {
    // This is a placeholder.  A real implementation would use a more
    // sophisticated calibration and calculation based on the AS7341's
    // datasheet and application notes.
    // For example, you might use a lookup table or a polynomial fit.
    // This example just returns a constant value.
    return 100.0; // Placeholder: 100 lux
}

// Log data function
int log_data(const sensor_data_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
            timestamp, data->f1, data->f2, data->f3, data->f4, data->f5, data->f6, data->f7, data->f8, data->clear, data->nir);

    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        stop_flag = 1;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_setup(I2C_BUS, AS7341_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize sensor
    if (sensor_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    float lux;
    while (!stop_flag) {
        // Read spectral data
        if (sensor_read_spectral_data(i2c_fd, &sensor_data) == 0) {
            // Calculate lux
            lux = calculate_lux(&sensor_data);

            // Log data
            log_data(&sensor_data, lux);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

