#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int interval = DEFAULT_INTERVAL;
char *output_file = DEFAULT_OUTPUT_FILE;

// Function prototypes
int read_sensor_data(int i2c_handle, short *x, short *y, short *z);
float convert_to_g(short raw_value);
int log_data(float x, float y, float z, const char *filename);
int log_error(const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, short *x, short *y, short *z) {
    unsigned char buffer[6];
    int retries = 0;
    int bytes_read;

    while (retries < 3) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, 0x28, (char *)buffer, 6);
        if (bytes_read == 6) {
            // Success
            *x = (short)((buffer[1] << 8) | buffer[0]);
            *y = (short)((buffer[3] << 8) | buffer[2]);
            *z = (short)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            // Error or transient failure
            log_error("I2C read error, retrying...");
            gpioDelay(10000); // 10 ms delay
            retries++;
        }
    }

    // All retries failed
    log_error("I2C read failed after multiple retries.");
    return -1; // Failure
}

// Function to convert raw data to g
float convert_to_g(short raw_value) {
    return (float)raw_value * 0.000244;
}

// Function to log data to a CSV file
int log_data(float x, float y, float z, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        log_error("Failed to open log file.");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fclose(fp);
    return 0;
}

// Function to log errors to a file
int log_error(const char *message) {
    FILE *fp = fopen("seismic_error.log", "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (output_file != NULL) {
        fclose(fopen(output_file, "a"));
    }
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = strtol(optarg, NULL, 0);
                if (interval <= 0) {
                    fprintf(stderr, "Invalid interval value. Using default: %d\n", DEFAULT_INTERVAL);
                    interval = DEFAULT_INTERVAL;
                }
                break;
            case 'f':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f output_file]\n", argv[0]);
                return -1;
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device.");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    short x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;

    while (1) {
        if (read_sensor_data(i2c_handle, &x_raw, &y_raw, &z_raw) == 0) {
            x_g = convert_to_g(x_raw);
            y_g = convert_to_g(y_raw);
            z_g = convert_to_g(z_raw);

            if (log_data(x_g, y_g, z_g, output_file) != 0) {
                log_error("Failed to log data.");
            }
        } else {
            log_error("Failed to read sensor data.");
        }

        gpioDelay(interval * 1000000); // Delay in microseconds
    }

    // This point should not be reached due to the signal handler
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

