#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the BH1750 sensor
int init_bh1750() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Power on the sensor
    if (write(fd, &CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read the ambient light value from the BH1750 sensor
int read_bh1750(int fd, unsigned int *raw_value) {
    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert the raw value to lux
float convert_to_lux(unsigned int raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_MULTICAST_PORT);

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "Lux: %.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the BH1750 sensor
    int fd = init_bh1750();
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Exiting.\n");
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        close(fd);
        return 1;
    }

    // Set TTL for multicast
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        close(fd);
        return 1;
    }

    unsigned int raw_value;
    float lux_value;

    // Main loop
    while (1) {
        // Read the ambient light value
        if (read_bh1750(fd, &raw_value) == 0) {
            // Convert the raw value to lux
            lux_value = convert_to_lux(raw_value);

            // Send the lux value over UDP multicast
            if (send_udp_multicast(lux_value) != 0) {
                fprintf(stderr, "Failed to send UDP multicast. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor. Continuing.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop.
    close(fd);
    close(udp_socket);
    return 0;
}

