    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_MULTICAST_PORT);

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "Lux: %.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

