#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 2048 // Maximum frame size in bytes
#define MAX_OBJECTS 100      // Maximum number of objects to detect

// TLV Types (Example - adjust based on AWR1642 documentation)
#define TLV_TYPE_ANOMALY 1
#define TLV_TYPE_TARGET 2

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    float range;
    float velocity;
} RadarData;

// Function prototypes
int initialize_uart();
int read_magic_word(unsigned char *magic_word);
int validate_tlv_payload(unsigned char *payload, int payload_len);
int detect_objects(unsigned char *payload, int payload_len, RadarData *radar_data, int *num_objects);
int write_to_csv(RadarData *radar_data, int num_objects);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

// Read magic word
int read_magic_word(unsigned char *magic_word) {
    int bytes_read = serRead(uart_handle, magic_word, MAGIC_WORD_SIZE);
    if (bytes_read != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error reading magic word, read %d bytes\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate TLV payload
int validate_tlv_payload(unsigned char *payload, int payload_len) {
    // Example validation: Check for a specific TLV type (e.g., TLV_TYPE_TARGET)
    if (payload_len < 4) { // Minimum size for TLV_TYPE_TARGET is 4 bytes
        fprintf(stderr, "Error: Invalid payload length: %d\n", payload_len);
        return -1;
    }

    unsigned short tlv_type = *((unsigned short *)payload);
    if (tlv_type != TLV_TYPE_TARGET) {
        fprintf(stderr, "Error: Invalid TLV type: %d\n", tlv_type);
        return -1;
    }

    // Add more validation based on AWR1642 documentation
    return 0;
}

// Detect objects
int detect_objects(unsigned char *payload, int payload_len, RadarData *radar_data, int *num_objects) {
    // Example: Assuming the payload contains range and velocity data
    // in a specific format (adjust based on AWR1642 documentation)
    // For simplicity, let's assume range is in the first 4 bytes and velocity in the next 4 bytes
    if (payload_len < 8) {
        fprintf(stderr, "Error: Insufficient data for object detection\n");
        return -1;
    }

    radar_data[*num_objects] = (RadarData){.range = *((float *)payload), .velocity = *((float *)(payload + 4))};
    (*num_objects)++;

    return 0;
}

// Write to CSV file
int write_to_csv(RadarData *radar_data, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, i, radar_data[i].range, radar_data[i].velocity);
    }
    fflush(csv_file);
    return 0;
}

