void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
        printf("UART closed\n");
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        printf("CSV file closed\n");
    }
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    unsigned char magic_word[MAGIC_WORD_SIZE];
    unsigned char payload[MAX_FRAME_SIZE];
    int payload_len = 0;
    RadarData radar_data[MAX_OBJECTS];
    int num_objects = 0;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read magic word
        if (read_magic_word(magic_word) == 0) {
            // Validate magic word
            if (validate_tlv_payload(payload, payload_len) == 0) {
                // Detect objects
                if (detect_objects(payload, payload_len, radar_data, &num_objects) == 0) {
                    // Write to CSV
                    write_to_csv(radar_data, num_objects);
                }
            }
        } else {
            // Handle magic word read error
            fprintf(stderr, "Error reading magic word, retrying...\n");
        }

        // Read data from UART
        int bytes_read = serRead(uart_handle, payload, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            payload_len += bytes_read;
            if (payload_len > MAX_FRAME_SIZE) {
                fprintf(stderr, "Error: Frame too large, truncating\n");
                payload_len = MAX_FRAME_SIZE;
            }
        } else {
            // Handle UART read error
            fprintf(stderr, "Error reading from UART, retrying...\n");
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

