#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define MAX_LINE_LENGTH 256
#define MAX_BUFFER_SIZE 1024

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD; // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 0; // Read doesn't block

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        }
        return (int)bytes_read;
    }
}

int parse_line(const char *line, float *timestamp, float *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the string for strtok
    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid line format: %s\n", line);
        free(line_copy);
        return -1;
    }
    *timestamp = strtof(token, NULL);

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid line format: %s\n", line);
        free(line_copy);
        return -1;
    }
    *range = strtof(token, NULL);

    free(line_copy);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[MAX_BUFFER_SIZE];
    float timestamp, range;
    int bytes_read;

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, buffer, MAX_BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer

            // Check for newline character
            if (strstr(buffer, "\n") != NULL) {
                if (parse_line(buffer, &timestamp, &range) == 0) {
                    printf("Timestamp: %ld-%02ld-%02d %02d:%02d:%02d, Range: %.2f meters\n",
                           timestamp, (int)(timestamp - (int)timestamp),
                           (int)(timestamp - (int)timestamp),
                           (int)(timestamp % 1),
                           (int)(timestamp / 1),
                           (int)(range));
                } else {
                    fprintf(stderr, "Error parsing line: %s\n", buffer);
                }
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, but continue running
            fprintf(stderr, "Error reading from UART, continuing...\n");
        } else {
            // No data available, check for sensor-absent or bus-error
            // In a real application, you might want to log this or take other actions
            // For now, just continue running
            fprintf(stderr, "No data available, continuing...\n");
        }
    }

    close(uart_fd);
    printf("UART closed. Exiting.\n");
    return EXIT_SUCCESS;
}

